function normalizeSearchText(value) {
  return normalizeImportCell(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function extensionCategoryKey(category) {
  const normalized = normalizeSearchText(category);
  if (normalized.includes("appel groupe") || normalized.includes("group")) return "grouped-call";
  if (normalized.includes("interne") || normalized.includes("internal")) return "internal";
  if (normalized.includes("panic") || normalized.includes("panique")) return "panic";
  if (normalized.includes("appel") || normalized.includes("call")) return "call";
  if (normalized.includes("flash")) return "flash";
  if (normalized.includes("fixed") || normalized.includes("fixe")) return "fixed";
  if (normalized.includes("mobile")) return "mobile";
  return "other";
}

function isGroupedCallExtension(row) {
  const searchableText = [
    row?.category,
    row?.label,
    row?.labelFr,
    row?.labelNl,
    row?.labelEn,
    row?.item,
    row?.usage,
    row?.model
  ].map(normalizeSearchText).join(" ");
  return searchableText.includes("appel groupe")
    || searchableText.includes("appel group")
    || searchableText.includes("grouped call")
    || searchableText.includes("group call")
    || searchableText.includes("call group")
    || searchableText.includes("groepsoproep")
    || searchableText.includes("groep oproep")
    || searchableText.includes("groep op");
}

function extensionDisplayCategoryKey(row) {
  return isGroupedCallExtension(row) ? "grouped-call" : extensionCategoryKey(row?.category);
}

function extensionDisplayCategoryLabel(row) {
  return isGroupedCallExtension(row) ? groupedCallExtensionCategoryLabel : normalizeImportCell(row?.category || "Extension");
}

function compareExtensionRowsForCatalog(left, right, language = "fr") {
  const leftCategory = extensionDisplayCategoryLabel(left);
  const rightCategory = extensionDisplayCategoryLabel(right);
  const categoryCompare = leftCategory.localeCompare(rightCategory, "fr", { sensitivity: "base" });
  if (categoryCompare) {
    return categoryCompare;
  }

  const leftNumber = normalizeImportCell(left?.number);
  const rightNumber = normalizeImportCell(right?.number);
  const leftLabel = getExtensionPreferredLabel(left, language).toLowerCase();
  const rightLabel = getExtensionPreferredLabel(right, language).toLowerCase();
  if (extensionCategoryKey(leftCategory) === "mobile") {
    return leftLabel.localeCompare(rightLabel, "fr", { sensitivity: "base" })
      || leftNumber.localeCompare(rightNumber, "fr", { numeric: true, sensitivity: "base" });
  }

  return leftNumber.localeCompare(rightNumber, "fr", { numeric: true, sensitivity: "base" })
    || leftLabel.localeCompare(rightLabel, "fr", { sensitivity: "base" });
}

function groupedCallExtensionNumbers() {
  return new Set(
    extensionCatalogRows
      .filter(isGroupedCallExtension)
      .map((row) => normalizeExtensionNumber(row.number))
      .filter(Boolean)
  );
}

function isGroupedCallExtensionNumber(value) {
  const number = normalizeExtensionNumber(String(value || "").split(" - ")[0]);
  return Boolean(number) && groupedCallExtensionNumbers().has(number);
}

function isInternalExtension(row) {
  const searchableText = [
    row?.category,
    row?.usage,
    row?.item,
    row?.model
  ].map(normalizeSearchText).join(" ");
  return extensionCategoryKey(row?.category) === "internal"
    || searchableText.includes("interne")
    || searchableText.includes("internal")
    || searchableText.includes("niet selecteerbaar")
    || searchableText.includes("non selectionnable")
    || searchableText.includes("ne pas choisir");
}

function isSelectableExtensionRow(row) {
  return !isInternalExtension(row) && !isGroupedCallExtension(row) && !isGroupedCallExtensionNumber(row?.number);
}

function selectableExtensionCatalogRows() {
  return extensionCatalogRows.filter(isSelectableExtensionRow);
}

function extensionRowsForCategory(categoryFilter = "") {
  const targetKey = extensionCategoryKey(categoryFilter);
  return extensionCatalogRows
    .filter((row) => {
      const rowKey = extensionDisplayCategoryKey(row);
      if (!categoryFilter) return true;
      if (targetKey === "grouped-call") return rowKey === "grouped-call";
      if (rowKey === "grouped-call") return false;
      if (targetKey === "fixed" || targetKey === "mobile") return rowKey === "fixed" || rowKey === "mobile";
      if (targetKey === "flash") return rowKey === "flash";
      if (targetKey === "call") return rowKey === "call";
      if (targetKey === "panic") return rowKey === "panic";
      return true;
    })
    .slice()
    .sort((left, right) => {
      const leftLabel = getExtensionPreferredLabel(left, "fr").toLowerCase();
      const rightLabel = getExtensionPreferredLabel(right, "fr").toLowerCase();
      const leftNumber = normalizeImportCell(left.number);
      const rightNumber = normalizeImportCell(right.number);
      if (targetKey === "fixed" || targetKey === "mobile") {
        return leftLabel.localeCompare(rightLabel, "fr", { sensitivity: "base" })
          || leftNumber.localeCompare(rightNumber, "fr", { numeric: true, sensitivity: "base" });
      }
      return leftNumber.localeCompare(rightNumber, "fr", { numeric: true, sensitivity: "base" })
        || leftLabel.localeCompare(rightLabel, "fr", { sensitivity: "base" });
    });
}

function normalizeLanguageCode(value) {
  const normalized = normalizeImportCell(value).toLowerCase();
  if (normalized.startsWith("nl")) return "nl";
  if (normalized.startsWith("en") || normalized.startsWith("ang")) return "en";
  return "fr";
}

function normalizeExtensionNumber(value) {
  const normalized = normalizeImportCell(value);
  return /^\d+\.0$/.test(normalized) ? normalized.slice(0, -2) : normalized;
}

function getExtensionPreferredLabel(row, language = "fr") {
  const normalizedLanguage = normalizeLanguageCode(language);
  const labelFr = normalizeImportCell(row?.labelFr || row?.label_fr || row?.labelFR || row?.label);
  const labelNl = normalizeImportCell(row?.labelNl || row?.label_nl || row?.labelNL || row?.label);
  const labelEn = normalizeImportCell(row?.labelEn || row?.label_en || row?.labelEN || row?.label);
  if (normalizedLanguage === "nl") {
    return labelNl || labelFr || labelEn || "";
  }
  if (normalizedLanguage === "en") {
    return labelEn || labelFr || labelNl || "";
  }
  return labelFr || labelNl || labelEn || "";
}

function extensionReferenceText(row, language = "fr") {
  const number = normalizeImportCell(row?.number);
  const label = getExtensionPreferredLabel(row, language);
  if (!number && !label) {
    return "";
  }
  return label ? `${number} - ${label}` : number;
}

function extensionReferenceMultilingualText(row) {
  const number = normalizeImportCell(row?.number);
  const labels = ["fr", "nl", "en"]
    .map((language) => getExtensionPreferredLabel(row, language))
    .filter(Boolean);
  const uniqueLabels = [...new Set(labels)];
  if (!number && !uniqueLabels.length) {
    return "";
  }
  const label = uniqueLabels.join(" / ");
  return label ? `${number} - ${label}` : number;
}

function availableExtensionReferenceOptions(categoryFilter = "", language = "fr") {
  const targetKey = extensionCategoryKey(categoryFilter);
  const importedOptions = extensionRowsForCategory(categoryFilter)
    .filter(isSelectableExtensionRow)
    .slice()
    .sort((left, right) => {
      const leftLabel = getExtensionPreferredLabel(left, language).toLowerCase();
      const rightLabel = getExtensionPreferredLabel(right, language).toLowerCase();
      const leftNumber = normalizeImportCell(left.number);
      const rightNumber = normalizeImportCell(right.number);
      if (targetKey === "fixed" || targetKey === "mobile") {
        return leftLabel.localeCompare(rightLabel, "fr", { sensitivity: "base" })
          || leftNumber.localeCompare(rightNumber, "fr", { numeric: true, sensitivity: "base" });
      }
      return leftNumber.localeCompare(rightNumber, "fr", { numeric: true, sensitivity: "base" })
        || leftLabel.localeCompare(rightLabel, "fr", { sensitivity: "base" });
    })
    .map((row) => extensionReferenceMultilingualText(row))
    .filter(Boolean);

  return importedOptions.length ? importedOptions : extensionReferenceOptions;
}

const notApplicableExtensionOption = "NVT - Non applicable / Niet van toepassing / Not applicable";
const defaultPanicButtonExtensions = {
  1: "922 - Front-end évacuation (Panic)",
  2: "923 - Coffre (Panic)"
};
const defaultFlashLightExtensions = {
  1: "932 - Coffre (Flashlight)",
  2: "930 - Brico Service (Flashlight)",
  3: "933 - Local SAV (usage de compresseurs lors de l'entretien des tondeuses)",
  4: "934 - Réception (pour certains magasins où la réception est très bruyante)"
};
const flashLightExtensionOptions = Object.values(defaultFlashLightExtensions);
const panicButtonExtensionOptions = Object.values(defaultPanicButtonExtensions);

function defaultNetworkExtensionForRow(row = {}) {
  const match = String(row.id || row.slotLabel || "").match(/(\d+)$/);
  const index = match ? Number(match[1]) : 0;
  if (row.category === "Panic button") {
    return defaultPanicButtonExtensions[index] || "";
  }
  if (row.category === "Flash light") {
    return defaultFlashLightExtensions[index] || "";
  }
  return "";
}

function networkRowPositionKey(row = {}) {
  const match = String(row.id || row.slotLabel || "").match(/(\d+)$/);
  return `${normalizeImportCell(row.category)}:${match ? Number(match[1]) : normalizeImportCell(row.slotLabel)}`;
}

function networkExtensionOptionsForCategory(categoryFilter = "", language = "fr") {
  const category = normalizeImportCell(categoryFilter).toLowerCase();
  if (category === "flash light") {
    return [notApplicableExtensionOption, ...flashLightExtensionOptions];
  }
  if (category === "panic button") {
    return [notApplicableExtensionOption, ...panicButtonExtensionOptions];
  }
  const cacheKey = `${category}|${normalizeLanguageCode(language)}`;
  if (extensionCatalogRenderCache.optionsByCategory.has(cacheKey)) {
    return extensionCatalogRenderCache.optionsByCategory.get(cacheKey);
  }
  const options = [...new Set([notApplicableExtensionOption, ...availableExtensionReferenceOptions(categoryFilter, language)])];
  extensionCatalogRenderCache.optionsByCategory.set(cacheKey, options);
  return options;
}

function bigFixProgrammingOptions(language = "fr") {
  return extensionCatalogRows
    .filter((row) => !isInternalExtension(row))
    .map((row) => extensionReferenceMultilingualText(row) || extensionReferenceText(row, language))
    .filter(Boolean)
    .filter((value, index, values) => values.indexOf(value) === index);
}

const bigFixScreenKeyCount = 28;
const bigFixTotalKeyCount = 84;

function normalizeBigFixKeys(keys = []) {
  const existing = new Map((Array.isArray(keys) ? keys : [])
    .map((entry, index) => [Number(entry?.key) || index + 1, entry]));
  return Array.from({ length: bigFixTotalKeyCount }, (_, index) => {
    const key = index + 1;
    const entry = existing.get(key) || {};
    return {
      key,
      extensionLabel: normalizeImportCell(entry.extensionLabel || entry.extension || "")
    };
  });
}

function bigFixExtensionNumber(value = "") {
  return normalizeExtensionNumber(String(value).split(" - ")[0]);
}

function bigFixCatalogLabel(number, language = "fr") {
  const catalogRow = extensionCatalogRows.find((row) => normalizeExtensionNumber(row.number) === normalizeExtensionNumber(number));
  return catalogRow
    ? (extensionReferenceMultilingualText(catalogRow) || extensionReferenceText(catalogRow, language))
    : "";
}

function bigFixUniqueLabels(labels = []) {
  const seen = new Set();
  return labels.filter((label) => {
    const number = bigFixExtensionNumber(label);
    const key = number || normalizeImportCell(label).toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function bigFixManagerGroupLabels(store, language = "fr") {
  const note = ensureStoreWorkflowData(store).callGroupsNote || "";
  const numbers = String(note).split(/\r?\n/)
    .map((line) => line.match(/^\s*(?:(?:groupe|groep|group)\s*)?(\d{3})\s*(?=[:=\-])/i)?.[1] || "")
    .map((number) => normalizeExtensionNumber(number))
    .filter(Boolean);
  return bigFixUniqueLabels(numbers.map((number) => bigFixCatalogLabel(number, language) || `${number} - Groupe d appel`));
}

function bigFixInferredGroupLabels(candidateLabels = [], language = "fr") {
  const definitions = [
    ["peinture", "611"], ["decor", "612"], ["quincailler", "621"], ["rangement", "622"],
    ["electric", "631"], ["luminaire", "632"], ["sanitaire tech", "641"], ["sanitaire deco", "642"],
    ["outillage elect", "652"], ["outillage", "651"], ["batiment", "661"], ["bois", "662"],
    ["carrelage", "663"], ["garden", "671"], ["jardin", "671"], ["pepiniere", "673"]
  ];
  const normalized = candidateLabels.map((label) => normalizeSearchText(label));
  const result = [];
  const usedNumbers = new Set();
  definitions.forEach(([keyword, groupNumber]) => {
    if (usedNumbers.has(groupNumber)) return;
    const count = normalized.filter((label) => label.includes(normalizeSearchText(keyword))).length;
    if (count < 2) return;
    const groupLabel = bigFixCatalogLabel(groupNumber, language);
    if (groupLabel) {
      result.push(groupLabel);
      usedNumbers.add(groupNumber);
    }
  });
  return result;
}

function bigFixPackCategories(categories = [], capacity = 28) {
  const packed = [];
  categories.map((category) => bigFixUniqueLabels(category)).filter((category) => category.length).forEach((category) => {
    if (packed.length && packed.length < capacity) packed.push("", "");
    category.forEach((label) => {
      if (packed.length < capacity) packed.push(label);
    });
  });
  return packed.slice(0, capacity);
}

function isCedricManagedStore(store) {
  const workflow = ensureStoreWorkflowData(store);
  const manager = normalizeSearchText(workflow.regionalManager || "");
  return manager.includes("cedric") && manager.includes("desaive");
}

function proposedBigFixKeys(row, store) {
  const language = state.language || store.language || "fr";
  const existing = normalizeBigFixKeys(row.bigFixKeys);
  // Les magasins suivis par Cedric sont programmes manuellement : aucune
  // proposition automatique ne doit reapparaitre dans une case encore vide.
  if (isCedricManagedStore(store)) {
    return existing;
  }
  const currentLabels = getNetworkConfigRows(store)
    .filter((entry) => !["flash", "panic", "call-button", "pager"].includes(networkConfigurationGuideStage(entry.category)))
    .map((entry) => normalizeImportCell(entry.extensionLabel))
    .filter(Boolean);
  currentLabels.unshift(normalizeImportCell(row.extensionLabel));
  const existingScreensWithChoices = Array.from({ length: 3 }, (_, screen) => {
    const start = screen * bigFixScreenKeyCount;
    const entries = existing.slice(start, start + bigFixScreenKeyCount);
    return entries.some((entry) => Boolean(entry.extensionLabel)) ? entries : [];
  });
  const preservedNumbers = new Set(existingScreensWithChoices.flat().map((entry) => bigFixExtensionNumber(entry.extensionLabel)).filter(Boolean));
  const candidates = bigFixUniqueLabels(currentLabels)
    .filter((label) => !["444", "920"].includes(bigFixExtensionNumber(label)))
    .filter((label) => !preservedNumbers.has(bigFixExtensionNumber(label)));
  const byNumber = new Map(candidates.map((label) => [bigFixExtensionNumber(label), label]));
  const take = (numbers) => numbers.map((number) => byNumber.get(number)).filter(Boolean);
  const service = take(["200", "555", "803", "804", "501", "802"]);
  const cash = take(["201", "202", "222"]);
  const cdr = candidates.filter((label) => /\bcdr\b/i.test(label) || /^7(?:2[1-9]|[3-9]\d)$/.test(bigFixExtensionNumber(label)));
  const manager = take(["700"]);
  const departments = candidates.filter((label) => /^3\d{2}$/.test(bigFixExtensionNumber(label)));
  const allocated = new Set([...service, ...cash, ...cdr, ...manager, ...departments].map(bigFixExtensionNumber));
  const other = candidates.filter((label) => !allocated.has(bigFixExtensionNumber(label)));
  const generated = normalizeBigFixKeys([]);
  const set = (key, label) => {
    if (key >= 1 && key <= bigFixTotalKeyCount && label) generated[key - 1].extensionLabel = label;
  };
  service.slice(0, 6).forEach((label, index) => set(1 + index, label));
  cash.slice(0, 3).forEach((label, index) => set(9 + index, label));
  set(14, bigFixCatalogLabel("444", language) || "444 - Urgences");
  cdr.slice(0, 5).forEach((label, index) => set(15 + index, label));
  manager.slice(0, 1).forEach((label) => set(22, label));
  set(28, bigFixCatalogLabel("920", language) || "920 - Micro");
  const screen2Labels = bigFixPackCategories([departments, other, service.slice(6), cash.slice(3), cdr.slice(5)]);
  screen2Labels.slice(0, 28).forEach((label, index) => set(29 + index, label));
  const groups = bigFixUniqueLabels([
    ...bigFixManagerGroupLabels(store, language),
    ...bigFixInferredGroupLabels(candidates, language)
  ]);
  groups.slice(0, 28).forEach((label, index) => set(57 + index, label));

  for (let screen = 0; screen < 3; screen += 1) {
    const start = screen * bigFixScreenKeyCount;
    const currentScreen = existing.slice(start, start + bigFixScreenKeyCount);
    const hasExistingChoice = currentScreen.some((entry) => Boolean(entry.extensionLabel));
    if (hasExistingChoice) {
      currentScreen.forEach((entry, index) => {
        generated[start + index] = { ...entry };
      });
    }
  }
  return generated;
}

const extensionCatalogRenderCache = {
  exact: new Map(),
  selectableByNumber: new Map(),
  optionsByCategory: new Map()
};

function rebuildExtensionCatalogRenderCache() {
  extensionCatalogRenderCache.exact.clear();
  extensionCatalogRenderCache.selectableByNumber.clear();
  extensionCatalogRenderCache.optionsByCategory.clear();
  extensionCatalogRows.forEach((row) => {
    [
      extensionReferenceMultilingualText(row),
      extensionReferenceText(row, "fr"),
      extensionReferenceText(row, "nl"),
      extensionReferenceText(row, "en")
    ].forEach((label) => {
      const key = normalizeImportCell(label);
      if (key && !extensionCatalogRenderCache.exact.has(key)) {
        extensionCatalogRenderCache.exact.set(key, row);
      }
    });
    const number = normalizeExtensionNumber(row.number);
    if (number && isSelectableExtensionRow(row) && !extensionCatalogRenderCache.selectableByNumber.has(number)) {
      extensionCatalogRenderCache.selectableByNumber.set(number, row);
    }
  });
}

function extensionOptionDisplayLabel(option, language = state.language) {
  const value = normalizeImportCell(option);
  if (!value || value === notApplicableExtensionOption) {
    return value;
  }
  const valueNumber = normalizeExtensionNumber(value.split(" - ")[0]);
  const exactMatch = extensionCatalogRenderCache.exact.get(value);
  if (exactMatch && isSelectableExtensionRow(exactMatch)) {
    return extensionReferenceMultilingualText(exactMatch);
  }
  if (exactMatch && !isSelectableExtensionRow(exactMatch)) {
    return value;
  }
  const match = valueNumber ? extensionCatalogRenderCache.selectableByNumber.get(valueNumber) : null;
  return match ? extensionReferenceMultilingualText(match) : value;
}

function extensionOptionDisplayHtml(option, language = state.language) {
  const label = extensionOptionDisplayLabel(option, language);
  const separatorIndex = label.indexOf(" - ");
  if (separatorIndex < 0) {
    return escapeHtml(label || "-");
  }
  const number = label.slice(0, separatorIndex);
  const text = label.slice(separatorIndex + 3);
  return `
    <span class="extension-display">
      <span class="extension-number">${escapeHtml(number)}</span>
      <span class="extension-label">${escapeHtml(text)}</span>
    </span>
  `;
}

function repairExtensionCatalogEncoding(value = "") {
  const text = String(value ?? "");
  if (!/[ÃÂ]/.test(text)) {
    return text;
  }
  const windows1252Bytes = {
    0x20AC: 0x80, 0x201A: 0x82, 0x0192: 0x83, 0x201E: 0x84,
    0x2026: 0x85, 0x2020: 0x86, 0x2021: 0x87, 0x02C6: 0x88,
    0x2030: 0x89, 0x0160: 0x8A, 0x2039: 0x8B, 0x0152: 0x8C,
    0x017D: 0x8E, 0x2018: 0x91, 0x2019: 0x92, 0x201C: 0x93,
    0x201D: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
    0x02DC: 0x98, 0x2122: 0x99, 0x0161: 0x9A, 0x203A: 0x9B,
    0x0153: 0x9C, 0x017E: 0x9E, 0x0178: 0x9F
  };
  try {
    const bytes = Uint8Array.from([...text].map((character) => {
      const code = character.charCodeAt(0);
      return windows1252Bytes[code] ?? code;
    }));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return text;
  }
}

function repairImportedTextEncoding(value = "") {
  return repairExtensionCatalogEncoding(value);
}

function normalizeExtensionCatalogRow(row, index = 0) {
  const clean = (value) => normalizeImportCell(repairExtensionCatalogEncoding(value));
  const category = clean(
    row.category
    || row.Category
    || row.Categorie
    || row.categorie
    || row.type
    || row.Type
    || "Extension"
  );
  const originalNumber = normalizeExtensionNumber(
    row.number
    || row.Number
    || row.Numero
    || row.numero
    || row.extension
    || row["NEW NUMBER"]
    || row["Extension*OLD"]
    || `EXT-${index + 1}`
  );
  const internalRenumbering = { "901": "961", "902": "962", "903": "963", "910": "965", "920": "970" };
  const number = normalizeImportCell(category).toUpperCase() === "INTERNE"
    ? (internalRenumbering[originalNumber] || originalNumber)
    : originalNumber;
  const fallbackLabel = clean(
    row.label
    || row.libelle
    || row.lieu
    || row["Last name*"]
    || row.Departement
    || ""
  );
  return {
    category,
    model: clean(row.model || row.modele || row.Model || row.Modele || ""),
    number,
    label: fallbackLabel,
    labelFr: clean(
      row.labelFr
      || row.label_fr
      || row["Libelle FR"]
      || row["label fr"]
      || row["Label FR"]
      || row["libelle fr"]
      || row["libelle fr_be"]
      || row["FR"]
      || ""
    ),
    labelNl: clean(
      row.labelNl
      || row.label_nl
      || row["Libelle NL"]
      || row["label nl"]
      || row["Label NL"]
      || row["libelle nl"]
      || row["NL"]
      || ""
    ),
    labelEn: clean(
      row.labelEn
      || row.label_en
      || row["Libelle EN"]
      || row["label en"]
      || row["Label EN"]
      || row["libelle en"]
      || row["EN"]
      || ""
    ),
    oldNumber: clean(
      row.oldNumber
      || row.old_number
      || row["ancien numero"]
      || row.ancien_numero
      || row["ancien numÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©ro"]
      || row["Extension*OLD"]
      || ""
    ),
    language: clean(row.language || row.langue || row.Language || ""),
    item: clean(row.item || row.Item || ""),
    activation: clean(
      row.activation
      || row["Activation or Port-in type"]
      || row["Activation / Port-in"]
      || ""
    ),
    usage: clean(
      row.usage
      || row.Departement
      || row["Fixed phone type"]
      || row["External direct number"]
      || ""
    )
  };
}

function extensionCatalogMergeKey(row = {}) {
  const normalized = normalizeExtensionCatalogRow(row);
  const category = extensionDisplayCategoryKey(normalized);
  const number = normalizeExtensionNumber(normalized.number);
  if (number) {
    return `${category}:${number}`;
  }
  return [
    category,
    normalizeImportCell(normalized.labelFr || normalized.label || "").toLowerCase(),
    normalizeImportCell(normalized.labelNl || "").toLowerCase(),
    normalizeImportCell(normalized.labelEn || "").toLowerCase(),
    normalizeImportCell(normalized.item || "").toLowerCase()
  ].join(":");
}

function mergeExtensionCatalogRows(localRows = [], remoteRows = []) {
  const mergedByKey = new Map();
  const pushRows = (rows, overwrite = true) => {
    (Array.isArray(rows) ? rows : []).forEach((row, index) => {
      const normalized = normalizeExtensionCatalogRow(row, index);
      const key = extensionCatalogMergeKey(normalized);
      if (overwrite || !mergedByKey.has(key)) {
        mergedByKey.set(key, normalized);
      }
    });
  };

  pushRows(localRows, true);
  pushRows(remoteRows, true);
  pushRows(localRows, false);
  return [...mergedByKey.values()];
}

function publicExtensionCatalogRow(row, index = 0) {
  const normalized = normalizeExtensionCatalogRow(row, index);
  return {
    category: normalized.category,
    number: normalized.number,
    labelFr: normalized.labelFr,
    labelNl: normalized.labelNl,
    labelEn: normalized.labelEn
  };
}

