function isOperationalIntervenant(person) {
  const role = canonicalRoleKey(person?.role);
  const globalOperationalRoles = ["twem", "brico"];
  return Boolean(
    person
    && normalizeImportCell(person.name)
    && (isIntervenantRole(role) || globalOperationalRoles.includes(role))
  );
}

function intervenantPeopleForSelection(selectedNames = []) {
  const selectedSet = new Set((selectedNames || []).map((name) => normalizeImportCell(name).toLowerCase()).filter(Boolean));
  return [...(state.people || [])]
    .filter((person) => isOperationalIntervenant(person) || selectedSet.has(normalizeImportCell(person?.name).toLowerCase()))
    .sort((left, right) => normalizeImportCell(left.name).localeCompare(normalizeImportCell(right.name), "fr", { sensitivity: "base" }));
}

function savPersonOptions(store = null, selectedNames = []) {
  const selectedSet = new Set((selectedNames || []).map((name) => normalizeImportCell(name).toLowerCase()).filter(Boolean));
  const dispatchCorePeople = (state.people || []).filter((person) => {
    const normalizedName = normalizeImportCell(person?.name).toLowerCase();
    return ["emir", "valou"].includes(normalizedName) || selectedSet.has(normalizedName);
  });
  const people = [...dispatchCorePeople, ...intervenantPeopleForSelection(selectedNames)];
  const seen = new Set();
  return people
    .filter((person) => {
      const name = normalizeImportCell(person.name);
      if (!name || seen.has(name.toLowerCase())) {
        return false;
      }
      seen.add(name.toLowerCase());
      return true;
    })
    .map((person) => {
      const role = roleLabel(person.role || "");
      const storeCode = normalizeImportCell(person.storeCode);
      const details = [role, storeCode && store?.code !== storeCode ? storeCode : ""].filter(Boolean).join(" - ");
      return {
        value: person.name,
        label: details ? `${person.name} (${details})` : person.name
      };
    });
}

function ticketTargetPeople(ticket = {}) {
  const rawPeople = Array.isArray(ticket.targetPeople)
    ? ticket.targetPeople
    : Array.isArray(ticket.targetPersonNames)
      ? ticket.targetPersonNames
      : [];
  const people = rawPeople
    .map((value) => normalizeImportCell(value))
    .filter(Boolean);
  if (people.length) {
    return [...new Set(people)];
  }
  const legacyTarget = normalizeImportCell(ticket.targetService);
  if (!legacyTarget) {
    return [];
  }
  return legacyTarget
    .split(/[,;|]/)
    .map((value) => normalizeImportCell(value))
    .filter(Boolean);
}

function ticketTargetLabel(ticket = {}) {
  return ticketTargetPeople(ticket).join(", ")
    || normalizeImportCell(ticket.targetService)
    || (["new", "dispatch"].includes(ticket.status) ? "TWEM a dispatcher" : "Personne a definir");
}

function normalizedPersonName(value = "") {
  return normalizeImportCell(value).toLowerCase();
}

function actionCenterDismissKey(user = currentUser()) {
  const name = normalizedPersonName(user?.name || state.activeUserName || "user").replace(/[^a-z0-9_-]+/g, "-") || "user";
  const todayKey = new Date().toISOString().slice(0, 10);
  return `${storageKey}-action-center-${todayKey}-${name}`;
}

function isActionCenterDismissed(user = currentUser()) {
  try {
    return window.sessionStorage.getItem(actionCenterDismissKey(user)) === "1";
  } catch (error) {
    return false;
  }
}

function dismissActionCenterForSession(user = currentUser()) {
  try {
    window.sessionStorage.setItem(actionCenterDismissKey(user), "1");
  } catch (error) {
    // Ignore private-mode storage failures.
  }
}

function isStoreVisibleForActionCenter(store, user = currentUser()) {
  if (!store) return false;
  if (!user || canSeeAllStores(user)) return true;
  const storeCodes = allowedStoresForUser(user);
  return storeCodes.includes("*") || storeCodes.includes(store.code);
}

function actionCenterStoreForTicket(ticket = {}) {
  return state.stores.find((store) => String(store.id) === String(ticket.storeId))
    || state.stores.find((store) => store.code === ticket.storeCode || store.name === ticket.storeName)
    || null;
}

function actionCenterItems(user = currentUser()) {
  if (!user || !state.pinValidated) {
    return [];
  }
  const userName = normalizedPersonName(user.name || state.activeUserName);
  const items = [];
  const now = new Date();
  const today = new Date(now);
  today.setHours(0, 0, 0, 0);
  const inFourteenDays = new Date(today);
  inFourteenDays.setDate(inFourteenDays.getDate() + 14);

  (state.tickets || []).forEach((ticket) => {
    if (!ticket || ticket.status === "closed") return;
    const store = actionCenterStoreForTicket(ticket);
    if (!isStoreVisibleForActionCenter(store, user)) return;
    const targets = ticketTargetPeople(ticket).map(normalizedPersonName);
    const waitingForDispatch = canDispatchSav(user) && (ticket.dispatchStatus === "pending_twem" || ["new", "dispatch", "open"].includes(ticket.status));
    const assignedToUser = targets.includes(userName);
    if (!waitingForDispatch && !assignedToUser) return;
    items.push({
      id: `sav-${ticket.id}`,
      kind: waitingForDispatch ? "SAV a dispatcher" : "SAV assigne",
      priority: waitingForDispatch ? 1 : 2,
      storeId: store.id,
      section: "sav",
      tab: "stores",
      title: `${store.code || ticket.storeCode || "-"} - ${store.name || ticket.storeName || "-"}`,
      detail: `${ticket.concern || ticket.requestKind || "SAV"} - ${ticketStatusLabel(ticket.status)}`,
      meta: waitingForDispatch ? "Dispatch TWEM attendu" : `Assigne a ${ticketTargetLabel(ticket)}`,
      date: ticket.updatedAt || ticket.dispatchedAt || ticket.createdAt || ""
    });
  });

  (state.stores || []).forEach((store) => {
    if (!isStoreVisibleForActionCenter(store, user)) return;
    (store.appointments || []).forEach((appointment) => {
      const appointmentDate = normalizeDateOnly(appointment.datetime);
      if (!appointmentDate || appointmentDate < today || appointmentDate > inFourteenDays) return;
      const people = (appointment.people || []).map(normalizedPersonName);
      if (!people.includes(userName)) return;
      items.push({
        id: `appointment-${store.id}-${appointment.id || appointment.datetime}`,
        kind: "Rendez-vous",
        priority: 3,
        storeId: store.id,
        section: "appointments",
        tab: "stores",
        title: `${store.code || "-"} - ${store.name || "-"}`,
        detail: `${formatDateTime(appointment.datetime)} - ${appointment.status || "-"}`,
        meta: appointment.note || peopleLabel(appointment.people || []),
        date: appointment.datetime || ""
      });
    });
  });

  return items
    .sort((left, right) =>
      left.priority - right.priority
      || new Date(left.date || 0) - new Date(right.date || 0)
      || String(left.title).localeCompare(String(right.title), "fr", { numeric: true })
    )
    .slice(0, 12);
}

function actionCenterOpenItem(itemId) {
  const item = actionCenterItems().find((entry) => entry.id === itemId);
  if (!item) return;
  const store = state.stores.find((entry) => String(entry.id) === String(item.storeId));
  if (!store) return;
  resetWorkspaceFilters();
  state.filters.search = normalizeImportCell(store.code || store.shopNumber || store.name).toLowerCase();
  state.activeAdminTab = item.tab || "stores";
  state.expandedStoreIds = new Set([store.id]);
  state.pendingStoreDetailFocusId = String(store.id);
  state.pendingStoreSectionFocus = item.section || "";
  closeActionCenterModal();
  saveState();
  render();
}

function actionCenterHtml(items = actionCenterItems(), options = {}) {
  const compact = Boolean(options.compact);
  if (!items.length) {
    return `
      <div class="action-center-empty">
        <strong>Rien a verifier pour le moment.</strong>
        <span>Les actions assignees apparaitront ici a l'ouverture.</span>
      </div>
    `;
  }
  return `
    <div class="action-center-list ${compact ? "is-compact" : ""}">
      ${items.map((item) => `
        <article class="action-center-item">
          <div>
            <span class="status-pill neutral">${escapeHtml(item.kind)}</span>
            <strong>${escapeHtml(item.title)}</strong>
            <p>${escapeHtml(item.detail)}</p>
            ${item.meta ? `<small>${escapeHtml(item.meta)}</small>` : ""}
          </div>
          <button type="button" class="mini-button" data-action-center-open="${escapeHtml(item.id)}">Ouvrir</button>
        </article>
      `).join("")}
    </div>
  `;
}

function closeActionCenterModal() {
  document.querySelector("[data-action-center-modal]")?.remove();
}

function attachActionCenterHandlers(root = document) {
  root.querySelectorAll("[data-action-center-open]").forEach((button) => {
    button.addEventListener("click", () => {
      actionCenterOpenItem(button.getAttribute("data-action-center-open") || "");
    });
  });
  root.querySelectorAll("[data-action-center-close]").forEach((button) => {
    button.addEventListener("click", () => {
      dismissActionCenterForSession();
      closeActionCenterModal();
      renderActionCenter();
    });
  });
  root.querySelectorAll("[data-action-center-show]").forEach((button) => {
    button.addEventListener("click", () => {
      try {
        window.sessionStorage.removeItem(actionCenterDismissKey(currentUser()));
      } catch (error) {
        // Ignore private-mode storage failures.
      }
      closeActionCenterModal();
      renderActionCenter();
    });
  });
}

function renderActionCenter() {
  const user = currentUser();
  const items = actionCenterItems(user);
  const dismissed = isActionCenterDismissed(user);
  if (actionCenterPanel) {
    if (items.length && activeMainWorkspaceTab() === "dashboard") {
      actionCenterPanel.classList.remove("hidden-panel");
      actionCenterPanel.classList.toggle("is-muted", dismissed);
      actionCenterPanel.innerHTML = `
        <div class="action-center-head">
          <div>
            <h3>Actions a verifier</h3>
            <p>${items.length} action(s) liee(s) a ton profil. Cette zone reste visible sans bloquer la navigation.</p>
          </div>
          ${dismissed
            ? '<button type="button" class="secondary-button" data-action-center-show>Afficher les actions</button>'
            : '<button type="button" class="secondary-button" data-action-center-close>Masquer pour cette session</button>'}
        </div>
        ${actionCenterHtml(items, { compact: true })}
      `;
      attachActionCenterHandlers(actionCenterPanel);
    } else {
      actionCenterPanel.classList.remove("is-muted");
      actionCenterPanel.classList.add("hidden-panel");
      actionCenterPanel.innerHTML = "";
    }
  }

  closeActionCenterModal();
}

function renderSavPersonCheckboxes(store) {
  const options = savPersonOptions(store);
  if (!options.length) {
    return '<div class="empty-state sav-empty">Aucune personne disponible dans les contacts.</div>';
  }
  return options.map((option, index) => {
    const optionId = `new-ticket-person-${index}`;
    return `
    <div class="sav-person-option">
      <input id="${escapeHtml(optionId)}" type="checkbox" name="new_ticket_people" value="${escapeHtml(option.value)}">
      <label for="${escapeHtml(optionId)}">${escapeHtml(option.label)}</label>
    </div>
  `;
  }).join("");
}

function renderSavDispatchCheckboxes(store, selectedNames = [], inputName = "sav_dispatch_people") {
  const selectedSet = new Set((selectedNames || []).map((name) => normalizeImportCell(name).toLowerCase()).filter(Boolean));
  const options = savPersonOptions(store, selectedNames);
  if (!options.length) {
    return '<div class="empty-state sav-empty">Aucune personne disponible dans les contacts.</div>';
  }
  return options.map((option, index) => {
    const checked = selectedSet.has(normalizeImportCell(option.value).toLowerCase()) ? "checked" : "";
    const optionId = `${inputName}-${index}`;
    return `
      <div class="sav-person-option">
        <input id="${escapeHtml(optionId)}" type="checkbox" name="${escapeHtml(inputName)}" value="${escapeHtml(option.value)}" ${checked}>
        <label for="${escapeHtml(optionId)}">${escapeHtml(option.label)}</label>
      </div>
    `;
  }).join("");
}

