function hydrateAccessProfile(person) {
  const normalizedPerson = normalizeCoreRole(person);
  const defaults = defaultPinProfiles[person.id] || {};
  return {
    pin: "",
    allowedStoreCodes: normalizedPerson.storeCode ? [normalizedPerson.storeCode] : ["*"],
    accessibleTabs: defaultTabsForRole(normalizedPerson.role).includes("*") ? ["*"] : defaultTabsForRole(normalizedPerson.role),
    accessibleBlocks: ["appointments", "problem_notes"],
    pinStatus: "active",
    pinCreatedAt: "2026-05-06T00:00:00Z",
    pinExpiresAt: "",
    loginHistory: [],
    ...normalizedPerson,
    ...defaults,
    allowedStoreCodes: Array.isArray(normalizedPerson.allowedStoreCodes) ? normalizedPerson.allowedStoreCodes : (defaults.allowedStoreCodes || (normalizedPerson.storeCode ? [normalizedPerson.storeCode] : ["*"])),
    accessibleTabs: Array.isArray(normalizedPerson.accessibleTabs) ? normalizedPerson.accessibleTabs : (defaults.accessibleTabs || (defaultTabsForRole(normalizedPerson.role).includes("*") ? ["*"] : defaultTabsForRole(normalizedPerson.role))),
    accessibleBlocks: Array.isArray(normalizedPerson.accessibleBlocks) ? normalizedPerson.accessibleBlocks : (defaults.accessibleBlocks || ["appointments", "problem_notes"]),
    loginHistory: Array.isArray(normalizedPerson.loginHistory) ? normalizedPerson.loginHistory : []
  };
}

function shouldMarkLegacyWelcomeSent(person = {}) {
  if (!person?.id || person.welcomeEmailSentAt || normalizePin(person.pin).length !== 6) {
    return false;
  }
  const createdAt = new Date(person.pinCreatedAt || person.createdAt || person.updatedAt || "2026-05-06T00:00:00Z");
  return Number.isNaN(createdAt.getTime()) || createdAt < legacyWelcomeCutoffAt;
}

function markLegacyWelcomeMailsSent(people = state.people) {
  const changed = [];
  (people || []).forEach((person) => {
    if (!shouldMarkLegacyWelcomeSent(person)) {
      return;
    }
    person.welcomeEmailSentAt = legacyWelcomeSentAt;
    person.welcomeEmailQueuedAt = "";
    person.manualWelcomeEmailSentAt = legacyWelcomeSentAt;
    person.manualWelcomeEmailSentBy = person.manualWelcomeEmailSentBy || "Migration TWEM";
    changed.push(person);
  });
  return changed;
}

function stripKnownTestPeople(people = []) {
  return (people || []).filter((person) => !knownTestPeopleNames.includes(person?.name));
}

function normalizeSpecialPeople(people = []) {
  const entries = people || [];
  const canonicalValou = entries.find((person) => (
    person
    && person.name === "Valou"
    && normalizeImportCell(person.phone) === "0488231773"
    && normalizeImportCell(person.email).toLowerCase() === "backoffice@twem.be"
  )) || entries.find((person) => {
    if (!person || person.name !== "Valou") {
      return false;
    }
    const email = normalizeImportCell(person.email).toLowerCase();
    const phone = normalizeImportCell(person.phone);
    return email === "backoffice@twem.be" || phone === "0488231773";
  });

  return entries.map((person) => {
    if (!person) {
      return person;
    }
    const email = normalizeImportCell(person.email).toLowerCase();
    const phone = normalizeImportCell(person.phone);
    const shouldRenameLegacyValou = person.name === "Valou"
      && canonicalValou
      && canonicalValou.id !== person.id
      && (email === "valou@twem.be" || phone === "0470 00 00 02");

    if (shouldRenameLegacyValou) {
      return hydrateAccessProfile({
        ...person,
        name: "Georgette Larix",
        role: "intervenant",
        accessibleTabs: ["dashboard", "timeline", "stores", "sav", "extensions", "reports"],
        accessibleBlocks: ["appointments", "sav_ticket", "problem_notes"]
      });
    }
    if (person.name === "Valou" && email === "valou@twem.be") {
      return hydrateAccessProfile({
        ...person,
        email: "backoffice@twem.be"
      });
    }
    return person;
  });
}

function stripKnownTestTickets(tickets = []) {
  return (tickets || []).filter((ticket) => {
    const concern = normalizeImportCell(ticket?.concern).toLowerCase();
    const note = normalizeImportCell(ticket?.initialNote).toLowerCase();
    return !knownTestSavNotes.includes(concern) && !knownTestSavNotes.includes(note);
  });
}

function ticketDedupeKey(ticket = {}) {
  return [
    normalizeImportCell(ticket.id),
    normalizeImportCell(ticket.storeCode || ticket.storeId || ticket.storeName).toLowerCase()
  ].join("|");
}

function ticketCompletenessScore(ticket = {}) {
  const updatesScore = Array.isArray(ticket.updates) ? ticket.updates.length * 3 : 0;
  const assignedScore = Array.isArray(ticket.targetPeople) && ticket.targetPeople.length ? 20 : 0;
  const statusScore = ["assigned", "in_progress", "closed"].includes(String(ticket.status || "").toLowerCase()) ? 10 : 0;
  const dateScore = Date.parse(ticket.updatedAt || ticket.dispatchedAt || ticket.closedAt || ticket.createdAt || "") || 0;
  return assignedScore + statusScore + updatesScore + Math.min(dateScore / 100000000000, 10);
}

function mergeTicketUpdates(...updateGroups) {
  const byKey = new Map();
  updateGroups.flat().filter(Boolean).forEach((update) => {
    const key = normalizeImportCell(update.id)
      || [normalizeImportCell(update.createdAt), normalizeImportCell(update.authorName), normalizeImportCell(update.note)].join("|");
    if (!byKey.has(key)) {
      byKey.set(key, update);
    }
  });
  return [...byKey.values()].sort((left, right) =>
    new Date(left.createdAt || 0) - new Date(right.createdAt || 0)
  );
}

function mergeSavTicketDuplicates(tickets = []) {
  const byKey = new Map();
  (tickets || []).filter(Boolean).forEach((ticket) => {
    const key = ticketDedupeKey(ticket);
    if (!normalizeImportCell(ticket.id) || !key.trim()) {
      return;
    }
    const current = byKey.get(key);
    if (!current) {
      byKey.set(key, {
        ...ticket,
        updates: Array.isArray(ticket.updates) ? [...ticket.updates] : []
      });
      return;
    }
    const primary = ticketCompletenessScore(ticket) > ticketCompletenessScore(current) ? ticket : current;
    const secondary = primary === ticket ? current : ticket;
    byKey.set(key, {
      ...secondary,
      ...primary,
      targetPeople: Array.isArray(primary.targetPeople) && primary.targetPeople.length
        ? [...new Set(primary.targetPeople)]
        : [...new Set(secondary.targetPeople || [])],
      targetService: primary.targetService || secondary.targetService || "",
      updates: mergeTicketUpdates(current.updates || [], ticket.updates || []),
      updatedAt: primary.updatedAt || secondary.updatedAt || current.updatedAt || ""
    });
  });
  return [...byKey.values()];
}

function demoPinPeople() {
  const hasCanonicalValou = (state.people || []).some((person) => (
    person
    && person.name === "Valou"
    && normalizeImportCell(person.email).toLowerCase() === "backoffice@twem.be"
    && normalizeImportCell(person.phone) === "0488231773"
  ));
  return clone(initialPeople)
    .filter((person) => !knownTestPeopleNames.includes(person.name))
    .filter((person) => !(hasCanonicalValou && person.id === "p2"))
    .map(hydrateAccessProfile);
}

function mergePeopleWithPinFallback(people = []) {
  const byKey = new Map();
  const sourcePeople = [
    ...demoPinPeople(),
    ...people.map(hydrateAccessProfile)
  ];

  sourcePeople.forEach((person) => {
    const key = (person.id || person.email || person.name || "").toLowerCase();
    if (!key) {
      return;
    }
    const existing = byKey.get(key);
    if (!existing) {
      byKey.set(key, hydrateAccessProfile(person));
      return;
    }

    const merged = hydrateAccessProfile({
      ...existing,
      ...person,
      pin: normalizePin(person.pin).length === 6 ? person.pin : existing.pin,
      allowedStoreCodes: Array.isArray(person.allowedStoreCodes) && person.allowedStoreCodes.length
        ? person.allowedStoreCodes
        : existing.allowedStoreCodes,
      accessibleTabs: Array.isArray(person.accessibleTabs) && person.accessibleTabs.length
        ? person.accessibleTabs
        : existing.accessibleTabs,
      accessibleBlocks: Array.isArray(person.accessibleBlocks) && person.accessibleBlocks.length
        ? person.accessibleBlocks
        : existing.accessibleBlocks,
      loginHistory: Array.isArray(person.loginHistory) && person.loginHistory.length
        ? person.loginHistory
        : existing.loginHistory,
      pinStatus: person.pinStatus || existing.pinStatus,
      pinCreatedAt: person.pinCreatedAt || existing.pinCreatedAt,
      pinExpiresAt: person.pinExpiresAt || existing.pinExpiresAt
    });

    byKey.set(key, merged);
  });

  return normalizeSpecialPeople(stripKnownTestPeople([...byKey.values()]));
}

function hasRemoteData() {
  return isSupabaseMode || hasAppwriteDataConfig;
}

function safeDocumentId(prefix, value) {
  const normalized = String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9._-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 24);
  return `${prefix}-${normalized || "item"}`.slice(0, 36);
}

function storeCodeFromShopNumber(shopNumber, fallbackCode = "") {
  const rawShopNumber = normalizeImportCell(shopNumber).toUpperCase();
  if (!rawShopNumber) {
    return normalizeImportCell(fallbackCode).toUpperCase();
  }
  return rawShopNumber.startsWith("BRI-") ? rawShopNumber : `BRI-${rawShopNumber}`;
}

function replaceStoreCodeReference(value, oldCode, newCode) {
  return normalizeImportCell(value) === oldCode ? newCode : value;
}

function updateStoreCodeReferences(oldCode, newCode, store) {
  if (!oldCode || !newCode || oldCode === newCode) {
    return { people: [], tickets: [], activities: [] };
  }

  const touchedPeople = [];
  const touchedTickets = [];
  const touchedActivities = [];

  state.people.forEach((person) => {
    let touched = false;
    if (person.storeCode === oldCode) {
      person.storeCode = newCode;
      touched = true;
    }
    if (Array.isArray(person.allowedStoreCodes)) {
      const nextCodes = person.allowedStoreCodes.map((code) => replaceStoreCodeReference(code, oldCode, newCode));
      if (nextCodes.join("|") !== person.allowedStoreCodes.join("|")) {
        person.allowedStoreCodes = [...new Set(nextCodes)];
        touched = true;
      }
    }
    if (touched) {
      touchedPeople.push(person);
    }
  });

  (state.tickets || []).forEach((ticket) => {
    if (ticket.storeCode === oldCode) {
      ticket.storeCode = newCode;
      ticket.storeName = store?.name || ticket.storeName || "";
      touchedTickets.push(ticket);
    }
  });

  (state.activities || []).forEach((activity) => {
    if (activity.storeCode === oldCode) {
      activity.storeCode = newCode;
      activity.storeName = store?.name || activity.storeName || "";
      touchedActivities.push(activity);
    }
  });

  return { people: touchedPeople, tickets: touchedTickets, activities: touchedActivities };
}

function parseJsonField(value, fallback) {
  if (!value) {
    return fallback;
  }
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

function normalizedSupportRequests(list) {
  return (Array.isArray(list) ? list : [])
    .map((request) => ({
      requestId: normalizeImportCell(request?.requestId),
      appId: normalizeImportCell(request?.appId),
      appName: normalizeImportCell(request?.appName || techSupportAppName),
      clientName: normalizeImportCell(request?.clientName || techSupportClientName),
      subject: normalizeImportCell(request?.subject),
      priority: request?.priority === "urgent" ? "urgent" : "normal",
      sourceUrl: normalizeImportCell(request?.sourceUrl),
      status: request?.status === "closed" ? "closed" : "open",
      createdAt: request?.createdAt || new Date().toISOString(),
      updatedAt: request?.updatedAt || request?.createdAt || new Date().toISOString()
    }))
    .filter((request) => request.requestId && request.appId);
}

function normalizedSupportAccessLog(list) {
  return (Array.isArray(list) ? list : [])
    .map((entry) => ({
      id: normalizeImportCell(entry?.id) || `support-log-${Date.now()}`,
      createdAt: entry?.createdAt || new Date().toISOString(),
      appId: normalizeImportCell(entry?.appId),
      clientName: normalizeImportCell(entry?.clientName || techSupportClientName),
      supportRequestId: normalizeImportCell(entry?.supportRequestId),
      supportUser: normalizeImportCell(entry?.supportUser || techSupportUserName)
    }))
    .filter((entry) => entry.appId && entry.supportRequestId);
}

function sanitizeStoreForRemote(store) {
  const sanitized = clone(store);
  const workflow = sanitized.workflow || {};
  if (workflow.planPdfDataUrl) {
    workflow.planPdfDataUrl = "";
  }
  if (Array.isArray(workflow.planFiles)) {
    workflow.planFiles = workflow.planFiles.map((plan) => ({
      ...plan,
      dataUrl: plan.fileId ? "" : plan.dataUrl
    }));
  }
  sanitized.workflow = workflow;
  return sanitized;
}

