function userIsScopedToStore(user, store) {
  if (!user || !store) {
    return false;
  }
  const allowed = allowedStoresForUser(user);
  if (!allowed.length || allowed.includes("*")) {
    return false;
  }
  const storeCodes = [
    store.code,
    store.shopNumber,
    store.id
  ].map((value) => normalizeImportStoreCode(value)).filter(Boolean);
  return allowed
    .map((value) => normalizeImportStoreCode(value))
    .some((value) => storeCodes.includes(value));
}

function userCanAccessStore(user, store) {
  if (!user || !store) {
    return false;
  }
  if (canSeeAllStores(user)) {
    return true;
  }
  const allowed = allowedStoresForUser(user);
  if (allowed.includes("*")) {
    return true;
  }
  const storeCodes = [store.code, store.shopNumber, store.id]
    .map((value) => normalizeImportStoreCode(value))
    .filter(Boolean);
  return allowed
    .map((value) => normalizeImportStoreCode(value))
    .some((value) => storeCodes.includes(value));
}

