let visibilitySyncQueue = Promise.resolve();

function saveVisibilityState() {
  window.localStorage.setItem(storageKey, JSON.stringify(localUiState()));
  if (!hasRemoteData()) {
    return visibilitySyncQueue;
  }
  // Rights changes must reach Appwrite in the same order as the clicks made in
  // the editor. Parallel full-settings writes could previously restore an older
  // checkbox/radio value when their responses arrived out of order.
  visibilitySyncQueue = visibilitySyncQueue
    .catch(() => undefined)
    .then(() => syncRoleSettingsToRemote());
  void visibilitySyncQueue.catch((error) => console.error("Visibility sync error", error));
  return visibilitySyncQueue;
}

