function rememberPinSession(person) {
  if (!person) {
    state.pinSession = null;
    return;
  }
  state.pinSession = {
    id: person.id || "",
    name: person.name || "",
    email: person.email || "",
    at: new Date().toISOString()
  };
}

function restoreRememberedPinSession() {
  let session = state.pinSession;
  if (!session && state.activeUserName) {
    const legacyPerson = state.people.find((entry) => entry.name === state.activeUserName);
    if (legacyPerson && ["manager", "magasin"].includes(canonicalRoleKey(legacyPerson.role)) && loginAllowedForPerson(legacyPerson)) {
      rememberPinSession(legacyPerson);
      session = state.pinSession;
    }
  }
  if (!session?.name && !session?.id && !session?.email) {
    return false;
  }
  const startedAt = session.at ? new Date(session.at).getTime() : 0;
  if (!startedAt || Date.now() - startedAt > pinSessionMaxAgeMs) {
    state.pinSession = null;
    state.pinValidated = false;
    return false;
  }
  const normalizedEmail = normalizeImportCell(session.email).toLowerCase();
  const person = state.people.find((entry) =>
    (session.id && String(entry.id) === String(session.id))
    || (session.name && entry.name === session.name)
    || (normalizedEmail && normalizeImportCell(entry.email).toLowerCase() === normalizedEmail)
  );
  if (!person || !loginAllowedForPerson(person)) {
    state.pinSession = null;
    state.pinValidated = false;
    return false;
  }
  state.activeUserName = person.name;
  state.pinValidated = true;
  rememberPinSession(person);
  if (!canAccessTab(state.activeAdminTab, person)) {
    state.activeAdminTab = firstAccessibleTabForUser(person);
  }
  return true;
}

