function updateFocusFromQuery() {
  const params = new URLSearchParams(window.location.search);
  const rawStore = normalizeImportCell(params.get("store"));
  const rawFocus = normalizeImportCell(params.get("focus"));
  const rawTicket = normalizeImportCell(params.get("ticket"));
  const rawAppointment = normalizeImportCell(params.get("appointment"));
  const rawScope = normalizeImportCell(params.get("scope"));
  const rawTab = normalizeImportCell(params.get("tab"));
  const isMailReply = params.get("mailReply") === "1";
  if (!rawStore && !rawFocus && !rawTicket && !rawAppointment) {
    return false;
  }

  const store = state.stores.find((entry) =>
    String(entry.code || "").toLowerCase() === rawStore.toLowerCase()
    || String(entry.id || "") === rawStore
  ) || state.stores.find((entry) =>
    (state.activities || []).some((activity) =>
      activity.id === rawFocus
      && activity.storeName === entry.name
    )
  ) || state.stores.find((entry) =>
    rawTicket && (state.tickets || []).some((ticket) =>
      ticket.id === rawTicket
      && (String(ticket.storeId || "") === String(entry.id) || ticket.storeCode === entry.code)
    )
  ) || state.stores.find((entry) =>
    rawAppointment && (entry.appointments || []).some((appointment) => appointment.id === rawAppointment)
  );
  if (!store) {
    return false;
  }

  const activity = rawFocus
    ? (state.activities || []).find((entry) => entry.id === rawFocus)
    : null;
  state.focusedUpdate = {
    storeId: store.id,
    storeCode: store.code,
    activityId: rawFocus,
    message: activity?.comment || normalizeImportCell(params.get("message")) || (isMailReply ? "Reponse mail a traiter dans l'application" : "Nouvelle information a consulter"),
    createdAt: activity?.createdAt || ""
  };
  const normalizedRequestedTab = rawTab === "preparation" ? "configuration" : rawTab;
  const requestedTab = mainWorkspaceTabs.includes(normalizedRequestedTab) && canAccessTab(normalizedRequestedTab) ? normalizedRequestedTab : "";
  state.activeAdminTab = requestedTab || (canAccessTab("stores") ? "stores" : "dashboard");
  state.filters = { search: "", status: "all", owner: "all", stage: "all", type: "all", city: "all", date: "all", invoice: "all", invoiceSearch: "", configStatus: "all" };
  state.filters.search = normalizeImportCell(store.code || store.shopNumber || store.name || "").toLowerCase();
  state.expandedStoreIds = new Set([store.id]);
  const effectiveScope = rawScope || (requestedTab === "configuration" ? "configuration" : requestedTab === "preparation" ? "preparation" : "");
  if (effectiveScope) {
    const sectionByScope = {
      sav: "sav",
      configuration: "configuration",
      preparation: "preparation",
      appointment: "appointments",
      appointments: "appointments",
      previsit: "previsit",
      "pre-visite": "previsit",
      previsite: "previsit",
      installation: "closing"
    };
    state.pendingStoreSectionFocus = sectionByScope[effectiveScope.toLowerCase()] || effectiveScope.toLowerCase();
  } else if (rawTicket) {
    state.pendingStoreSectionFocus = "sav";
  }
  return true;
}

