async function loadSnapshotState(fallbackState) {
  if (!isSnapshotMode) {
    return fallbackState;
  }
  const response = await fetch(`${appConfig.snapshotUrl || "snapshot/current.json"}?t=${Date.now()}`, {
    cache: "no-store"
  });
  if (!response.ok) {
    throw new Error(`Snapshot local indisponible (${response.status})`);
  }
  const snapshot = await response.json();
  return {
    ...fallbackState,
    stores: Array.isArray(snapshot.stores) ? snapshot.stores : [],
    activities: Array.isArray(snapshot.activities) ? snapshot.activities : [],
    tickets: Array.isArray(snapshot.tickets) ? snapshot.tickets : [],
    people: Array.isArray(snapshot.people) ? snapshot.people : [],
    accessOverrides: Array.isArray(snapshot.accessOverrides) ? snapshot.accessOverrides : [],
    roleOptions: Array.isArray(snapshot.roleOptions) ? snapshot.roleOptions : fallbackState.roleOptions,
    roleVisibilityConfig: snapshot.roleVisibilityConfig || {},
    visibilityEditorRole: snapshot.visibilityEditorRole || "supadmin_twem",
    activeUserName: snapshot.activeUserName || fallbackState.activeUserName,
    activeAdminTab: "dashboard"
  };
}

