function isRestrictedImportExportTab(tab) {
  return ["field-imports", "import-export"].includes(tab);
}

function isRetiredTab(tab) {
  return ["timeline", "migration", "finished-stores", "stores-fos", "stores-fosdos-group", "quantity-bulk", "preparation", "visibility", "pin-access", "import-export"].includes(tab);
}

function filterDisabledTabs(tabs = []) {
  return tabs.filter((tab) => (
    (ENABLE_LEGAL_TABS || !isLegalTab(tab))
    && !isRestrictedContactAccessTab(tab)
    && !isRestrictedImportExportTab(tab)
    && !isRetiredTab(tab)
  ));
}

