function accessibleTabsForUser(user = currentUser()) {
  if (!user) {
    return ["dashboard"];
  }
  // A store manager must always be able to reach the three workspaces needed
  // for their own store: the store sheet, installation preparation and SAV.
  // Keep this explicit so legacy person-level permissions cannot expose TWEM's
  // private tools or dashboard areas.
  if (canonicalRoleKey(user.role) === "magasin") {
    return ["stores", "configuration", "sav"];
  }
  if (isMobileConsultationViewport()) {
    return ["stores"];
  }
  if (user.accessibleTabs?.includes("*") || isSupAdmin(user)) {
    return ["*"];
  }
  const managerScopedRole = ["manager", "magasin"].includes(canonicalRoleKey(user.role));
  const roleConfig = state.roleVisibilityConfig?.[canonicalRoleKey(user.role)];
  const configuredTabs = roleConfig?.tabs && typeof roleConfig.tabs === "object"
    ? Object.entries(roleConfig.tabs).filter(([, visible]) => visible).map(([tabKey]) => tabKey)
    : null;
  const roleDefaults = configuredTabs || defaultTabsForRole(user.role) || ["dashboard"];
  const savedTabs = Array.isArray(user.accessibleTabs)
    ? filterDisabledTabs(user.accessibleTabs.filter(Boolean).map((tab) => tab === "preparation" ? "configuration" : tab))
    : [];
  // Once a role has a central matrix, it is the source of truth. Legacy rights
  // stored on a person must not silently re-enable a tab disabled in Tools.
  let mergedTabs = [...new Set(configuredTabs ? roleDefaults : [...roleDefaults, ...savedTabs])];
  // Brico Technique receives only the preparation workspace entry point. The
  // editable area remains restricted to the dedicated technical_cabling zone.
  if (isBricoTechnicalUser(user)) {
    mergedTabs.push("configuration");
  }
  if (managerScopedRole) {
    const scopedListTabs = [...new Set(getRoleScopedStores(user).map(storePrimaryListTab))];
    const genericStoreTabs = new Set(["finished-stores", "migration", "stores", "stores-fos", "stores-fosdos-group"]);
    mergedTabs = mergedTabs.filter((tab) => !genericStoreTabs.has(tab));
    mergedTabs.push(...(scopedListTabs.length ? scopedListTabs : ["stores"]));
    mergedTabs.push("configuration");
  }
  if (!managerScopedRole && (mergedTabs.includes("finished-stores") || mergedTabs.includes("stores"))) {
    mergedTabs.push("migration");
  }
  if (!managerScopedRole && mergedTabs.includes("stores")) {
    mergedTabs.push("stores-fos", "stores-fosdos-group");
  }
  if (ENABLE_LEGAL_TABS && mergedTabs.includes("tuto")) {
    mergedTabs.push("legal-documents", "legal-acceptances");
  }
  if (canManageContactsAndPins(user)) {
    mergedTabs.push("pin-access");
  }
  if (canManageImportsAndExports(user)) {
    mergedTabs.push("import-export");
  }
  const enabledTabs = [...new Set(filterDisabledTabs(mergedTabs))];
  return enabledTabs.length ? enabledTabs : ["dashboard"];
}

function canAccessTab(tab, user = currentUser()) {
  if (isRetiredTab(tab)) {
    return false;
  }
  if (!ENABLE_LEGAL_TABS && isLegalTab(tab)) {
    return false;
  }
  if (tab === "contacts") {
    return false;
  }
  if (tab === "pin-access") {
    return canManageContactsAndPins(user);
  }
  if (tab === "field-imports") {
    return false;
  }
  if (tab === "import-export") {
    return canManageImportsAndExports(user);
  }
  if (isMobileConsultationViewport()) {
    return tab === "stores";
  }
  if (tab === "visibility") {
    return isSupAdmin(user);
  }
  if (tab === "quantity-bulk") {
    return canUseQuantityBulk(user);
  }
  const tabs = accessibleTabsForUser(user);
  return tabs.includes("*") || tabs.includes(tab);
}

