function isBricoTechnicalUser(user = currentUser()) {
  const email = normalizeImportCell(user?.email || "").toLowerCase();
  const name = normalizeSearchText(user?.name || "");
  return user?.bricoTechnicalAccess === true
    || user?.accessibleBlocks?.includes("technical_cabling")
    || bricoTechnicalAccessEmails.has(email)
    || bricoTechnicalAccessNames.has(name);
}

function configuredVisibilityModeForZone(user, zone) {
  if (!user || !zone || canonicalRoleKey(user.role) === "magasin") {
    return null;
  }
  const matrixPath = visibilityZoneMatrixMap[zone];
  if (!matrixPath) {
    return null;
  }
  const [tabKey, blockKey] = matrixPath;
  const config = state.roleVisibilityConfig?.[canonicalRoleKey(user.role)];
  if (!config || config.tabs?.[tabKey] === false) {
    return config ? "hide" : null;
  }
  const mode = config.blocks?.[tabKey]?.[blockKey];
  return ["hide", "view", "edit"].includes(mode) ? mode : null;
}

function canEditZone(store, zone) {
  const user = currentUser();
  if (!user || !zone) {
    return false;
  }
  if (zone === "sav_ticket") {
    return true;
  }
  if (zone === "call_button_merchandising" && isCallButtonMerchandisingUser(user)) {
    return true;
  }
  if (zone === "technical_cabling" && isBricoTechnicalUser(user)) {
    return userCanAccessStore(user, store);
  }
  const configuredMode = configuredVisibilityModeForZone(user, zone);
  if (configuredMode) {
    return configuredMode === "edit";
  }
  const allowedZones = editableZonesForRole(user.role);
  if (zone === "alarm" && allowedZones.includes("external_prep")) {
    return true;
  }
  if (zone === "technical_cabling" && allowedZones.includes("external_prep")) {
    return true;
  }
  if (allowedZones.includes("all") || allowedZones.includes(zone)) {
    return true;
  }
  return state.accessOverrides.some((override) =>
    String(override.storeId) === String(store.id)
    && override.personId === user.id
    && override.zone === zone
    && override.level === "edit"
    && isOverrideActive(override)
  );
}

function isNetworkConfigLockedForUser(store) {
  const user = currentUser();
  const workflow = ensureStoreWorkflowData(store);
  return Boolean(user && ["manager", "magasin"].includes(user.role) && workflow.networkConfigConfirmed);
}

function getRoleScopedStores() {
  const user = currentUser();
  if (!user) {
    return state.stores;
  }

  if (canSeeAllStores(user)) {
    return state.stores;
  }

  const storeCodes = allowedStoresForUser(user);
  return state.stores.filter((store) => storeCodes.includes(store.code));
}

function visibleActivitiesForUser(user = currentUser()) {
  if (!user || canSeeAllStores(user)) {
    return state.activities;
  }
  const allowedCodes = allowedStoresForUser(user);
  if (allowedCodes.includes("*")) {
    return state.activities;
  }
  const storesByName = new Map(state.stores.map((store) => [normalizeImportCell(store.name).toLowerCase(), store]));
  const allowedSet = new Set(allowedCodes);
  return state.activities.filter((activity) => {
    const store = storesByName.get(normalizeImportCell(activity.storeName).toLowerCase());
    return Boolean(store && allowedSet.has(store.code));
  });
}

function stepFor(store, actorType) {
  store.steps ||= [];
  let step = store.steps.find((entry) => entry.actorType === actorType);
  if (!step) {
    const fallbackLabels = {
      store_manager: "Magasin",
      installer: "Telephonie",
      electrician: "Electricien"
    };
    step = { actorType, label: fallbackLabels[actorType] || actorType, status: "planned", note: "" };
    store.steps.push(step);
  }
  return step;
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function formatDateTime(dateString) {
  if (!dateString) {
    return "-";
  }

  return new Intl.DateTimeFormat("fr-BE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit"
  }).format(new Date(dateString));
}

function todayLocalDateKey() {
  const date = new Date();
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function formatDailyTodoDateLabel(dateKey = todayLocalDateKey()) {
  const [year, month, day] = String(dateKey).split("-").map(Number);
  if (!year || !month || !day) {
    return dateKey || "Aujourd hui";
  }
  return new Intl.DateTimeFormat("fr-BE", {
    weekday: "long",
    day: "2-digit",
    month: "2-digit",
    year: "numeric"
  }).format(new Date(year, month - 1, day));
}

function formatDateOnlyLabel(dateString) {
  const normalized = normalizeDateOnly(dateString);
  if (!normalized) {
    return "";
  }
  return new Intl.DateTimeFormat("fr-BE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric"
  }).format(normalized);
}

function formatDateTimeLocal(dateString) {
  if (!dateString) {
    return "";
  }

  const date = new Date(dateString);
  if (Number.isNaN(date.getTime())) {
    return "";
  }

  const pad = (value) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function isSameLocalDay(dateA, dateB) {
  return dateA.getFullYear() === dateB.getFullYear()
    && dateA.getMonth() === dateB.getMonth()
    && dateA.getDate() === dateB.getDate();
}

function peopleLabel(people = []) {
  return Array.isArray(people) ? people.join(", ") : String(people || "");
}

function generateUniquePin() {
  const existingPins = new Set(
    state.people
      .map((person) => normalizePin(person.pin))
      .filter((pin) => pin.length === 6)
  );
  let candidate = "";
  do {
    candidate = String(Math.floor(100000 + Math.random() * 900000));
  } while (existingPins.has(candidate));
  return candidate;
}

function roleLabel(role) {
  const normalizedRole = canonicalRoleKey(role);
  const labels = {
    supadmin_twem: "SupAdmin TWEM",
    admin_twem: "Admin TWEM",
    direction_brico: "Direction Brico",
    twem: "TWEM",
    brico: "Brico",
    brico_corrector: "Correcteur Brico",
    supmanager: "SupManager",
    manager: "Manager magasin",
    magasin: "Magasin",
    telephonie_destiny: "Telephonie / Destiny",
    pm_dstny: "PM dstny",
    uc_pm_fr_nl_dstny: "uc pm fr & nl dstny",
    uc_tech_fr_nl_dstny: "uc tech fr & nl dstny",
    logistic_coord_dstny: "logistic coord dstny",
    it: "IT",
    infra: "Infra",
    intervenant: "Autre intervenant"
  };
  return labels[normalizedRole] || String(role || "").replace(/_/g, " ");
}

function normalizeRoleKey(value = "") {
  return normalizeImportCell(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function canonicalRoleKey(value = "") {
  const normalized = normalizeRoleKey(value);
  const aliases = {
    direction: "direction_brico",
    directory: "direction_brico",
    directory_brico: "direction_brico",
    direction_brico: "direction_brico",
    uc_pm_fr_nl_dstny: "uc_pm_fr_nl_dstny",
    uc_pm_fr_and_nl_dstny: "uc_pm_fr_nl_dstny",
    uc_tech_fr_nl_dstny: "uc_tech_fr_nl_dstny",
    uc_tech_fr_and_nl_dstny: "uc_tech_fr_nl_dstny",
    logistic_coord_dstny: "logistic_coord_dstny"
  };
  return aliases[normalized] || normalized;
}

function isIntervenantRole(role) {
  const normalized = String(role || "");
  return defaultIntervenantRoleOptions.includes(normalized)
    || ((state.roleOptions || []).includes(normalized) && !defaultRoleOptions.includes(normalized));
}

function intervenantRoleOptions() {
  return [...new Set([
    ...defaultIntervenantRoleOptions,
    ...(state.roleOptions || []).filter((role) => isIntervenantRole(role))
  ])];
}

function renderIntervenantRoleOptions(selectedValue) {
  return renderOptions(
    intervenantRoleOptions().map((role) => ({ value: role, label: roleLabel(role) })),
    selectedValue
  );
}

function defaultVisibilityModesForRole(role) {
  const visibleTabs = defaultTabsForRole(role).includes("*")
    ? activeVisibilityTabCatalog().map((tab) => tab.key)
    : defaultTabsForRole(role).filter((tab) => activeVisibilityTabCatalog().some((entry) => entry.key === tab));
  const editableZones = editableZonesForRole(role);
  const tabs = {};
  const blocks = {};
  visibleTabs.forEach((tabKey) => {
    tabs[tabKey] = true;
    const catalog = activeVisibilityTabCatalog().find((entry) => entry.key === tabKey);
    if (!catalog) return;
    blocks[tabKey] = {};
    catalog.blocks.forEach((block) => {
      const editable = editableZones.includes("all")
        || editableZones.includes(block.key)
        || editableZones.includes(tabKey)
        || (block.key === "alarm" && editableZones.includes("external_prep"))
        || (tabKey === "stores" && editableZones.includes("sav_ticket") && block.key === "store_sav");
      blocks[tabKey][block.key] = editable ? "edit" : "view";
    });
  });
  return { tabs, blocks };
}

function ensureRoleVisibilityConfig(role) {
  if (!role) {
    return { tabs: {}, blocks: {} };
  }
  const defaultConfig = defaultVisibilityModesForRole(role);
  if (!state.roleVisibilityConfig[role]) {
    state.roleVisibilityConfig[role] = defaultConfig;
  }
  state.roleVisibilityConfig[role].tabs ||= {};
  state.roleVisibilityConfig[role].blocks ||= {};
  Object.entries(defaultConfig.tabs || {}).forEach(([tabKey, visible]) => {
    if (!(tabKey in state.roleVisibilityConfig[role].tabs)) {
      state.roleVisibilityConfig[role].tabs[tabKey] = visible;
    }
  });
  Object.entries(defaultConfig.blocks || {}).forEach(([tabKey, blocks]) => {
    state.roleVisibilityConfig[role].blocks[tabKey] ||= {};
    Object.entries(blocks || {}).forEach(([blockKey, mode]) => {
      if (!(blockKey in state.roleVisibilityConfig[role].blocks[tabKey])) {
        state.roleVisibilityConfig[role].blocks[tabKey][blockKey] = mode;
      }
    });
  });
  return state.roleVisibilityConfig[role];
}

function summarizeRoleVisibility(role) {
  const config = ensureRoleVisibilityConfig(role);
  const visibleTabs = activeVisibilityTabCatalog().filter((tab) => config.tabs[tab.key]);
  const editableBlocks = [];
  visibleTabs.forEach((tab) => {
    tab.blocks.forEach((block) => {
      const mode = config.blocks?.[tab.key]?.[block.key];
      if (mode === "edit") {
        editableBlocks.push(`${tab.label} : ${block.label}`);
      }
    });
  });
  return { visibleTabs, editableBlocks };
}

function renderVisibilityEditor() {
  if (!visibilityRoleSelect || !visibilityTabsEditor || !visibilityZonesEditor || !visibilityRoleSummary || !visibilityRoleDirectory) {
    return;
  }

  const availableRoles = [...new Set([...(state.roleOptions || []), ...defaultRoleOptions])]
    .filter((role) => isSupAdmin() || role !== "supadmin_twem");
  if (!availableRoles.includes(state.visibilityEditorRole)) {
    state.visibilityEditorRole = availableRoles[0] || "admin_twem";
  }
  const role = state.visibilityEditorRole;
  const config = ensureRoleVisibilityConfig(role);
  const modeLabels = {
    hide: "Cacher",
    view: "Consulter",
    edit: "Encoder / modifier"
  };

  visibilityRoleSelect.innerHTML = availableRoles
    .map((entry) => `<option value="${escapeHtml(entry)}" ${entry === role ? "selected" : ""}>${escapeHtml(roleLabel(entry))}</option>`)
    .join("");

  const summary = summarizeRoleVisibility(role);
  visibilityRoleMeta.innerHTML = `
    <span class="info-chip">${escapeHtml(roleLabel(role))}</span>
    <span class="info-chip">${summary.visibleTabs.length} onglet(s) visibles</span>
    <span class="info-chip">${summary.editableBlocks.length} bloc(s) modifiable(s)</span>
  `;

  visibilityTabsEditor.innerHTML = activeVisibilityTabCatalog()
    .map((tab) => `
      <label class="visibility-tab-pill">
        <input type="checkbox" data-visibility-tab="${escapeHtml(tab.key)}" ${config.tabs[tab.key] ? "checked" : ""}>
        <span>${escapeHtml(tab.label)}</span>
      </label>
    `)
    .join("");

  const visibleTabCards = activeVisibilityTabCatalog()
    .filter((tab) => config.tabs[tab.key])
      .map((tab) => {
        const blockRows = tab.blocks.map((block) => {
          const currentMode = config.blocks?.[tab.key]?.[block.key] || "view";
          return `
            <div class="visibility-zone-row">
              <div class="visibility-zone-label">
                <strong>${escapeHtml(block.label)}</strong>
                <span>${escapeHtml(block.hint)}</span>
              </div>
              <label>
                <span>${modeLabels.hide}</span>
                <input type="radio" name="visibility-${escapeHtml(role)}-${escapeHtml(tab.key)}-${escapeHtml(block.key)}" value="hide" data-visibility-mode="${escapeHtml(tab.key)}::${escapeHtml(block.key)}" ${currentMode === "hide" ? "checked" : ""}>
              </label>
              <label>
                <span>${modeLabels.view}</span>
                <input type="radio" name="visibility-${escapeHtml(role)}-${escapeHtml(tab.key)}-${escapeHtml(block.key)}" value="view" data-visibility-mode="${escapeHtml(tab.key)}::${escapeHtml(block.key)}" ${currentMode === "view" ? "checked" : ""}>
              </label>
              <label>
                <span>${modeLabels.edit}</span>
                <input type="radio" name="visibility-${escapeHtml(role)}-${escapeHtml(tab.key)}-${escapeHtml(block.key)}" value="edit" data-visibility-mode="${escapeHtml(tab.key)}::${escapeHtml(block.key)}" ${currentMode === "edit" ? "checked" : ""}>
              </label>
          </div>
        `;
      }).join("");
      return `
        <article class="visibility-zone-card">
          <h5>${escapeHtml(tab.label)}</h5>
          <div class="visibility-zone-list">${blockRows}</div>
        </article>
      `;
    })
    .join("");

  visibilityZonesEditor.innerHTML = visibleTabCards || '<div class="visibility-zone-empty">Aucun onglet visible pour ce role.</div>';

  const visibleTabChips = summary.visibleTabs.length
    ? summary.visibleTabs.map((tab) => `<span class="visibility-chip">${escapeHtml(tab.label)}</span>`).join("")
    : '<div class="empty-state">Aucun onglet visible.</div>';
    const editableBlockChips = summary.editableBlocks.length
      ? summary.editableBlocks.map((block) => `<span class="visibility-chip">${escapeHtml(block)}</span>`).join("")
      : '<div class="empty-state">Tout est en lecture seule.</div>';
    const hiddenBlocks = [];
    summary.visibleTabs.forEach((tab) => {
      tab.blocks.forEach((block) => {
        const mode = config.blocks?.[tab.key]?.[block.key];
        if (mode === "hide") {
          hiddenBlocks.push(`${tab.label} : ${block.label}`);
        }
      });
    });
    const hiddenBlockChips = hiddenBlocks.length
      ? hiddenBlocks.map((block) => `<span class="visibility-chip">${escapeHtml(block)}</span>`).join("")
      : '<div class="empty-state">Aucun bloc masque.</div>';

    visibilityRoleSummary.innerHTML = `
      <article class="visibility-summary-card">
        <h5>Onglets visibles</h5>
        <div class="visibility-zone-list">
        <div class="visibility-chip-list">${visibleTabChips}</div>
      </div>
    </article>
      <article class="visibility-summary-card">
        <h5>Blocs modifiables</h5>
        <div class="visibility-zone-list">
          <div class="visibility-chip-list">${editableBlockChips}</div>
        </div>
      </article>
      <article class="visibility-summary-card">
        <h5>Blocs masques</h5>
        <div class="visibility-zone-list">
          <div class="visibility-chip-list">${hiddenBlockChips}</div>
        </div>
      </article>
    `;

  visibilityRoleDirectory.innerHTML = availableRoles.map((entry) => {
    const roleSummary = summarizeRoleVisibility(entry);
    const visibleText = roleSummary.visibleTabs.map((tab) => tab.label).join(", ") || "Aucun onglet";
    const editableText = roleSummary.editableBlocks.slice(0, 3).join(" | ") || "Lecture seule";
    return `
      <article class="visibility-role-compact ${entry === role ? "is-active" : ""}">
        <div class="visibility-role-compact-head">
          <strong>${escapeHtml(roleLabel(entry))}</strong>
          <button type="button" class="mini-button" data-visibility-edit-role="${escapeHtml(entry)}">Configurer</button>
        </div>
        <p>${escapeHtml(visibleText)}</p>
        <p class="cell-note">${escapeHtml(editableText)}</p>
      </article>
    `;
  }).join("");

  visibilityTabsEditor.querySelectorAll("[data-visibility-tab]").forEach((checkbox) => {
    checkbox.addEventListener("change", () => {
      const tabKey = checkbox.getAttribute("data-visibility-tab");
      config.tabs[tabKey] = checkbox.checked;
      const catalog = activeVisibilityTabCatalog().find((entry) => entry.key === tabKey);
      if (checkbox.checked && catalog) {
        config.blocks[tabKey] ||= {};
        catalog.blocks.forEach((block) => {
          config.blocks[tabKey][block.key] ||= "view";
        });
      }
      saveVisibilityState();
      renderVisibilityEditor();
    });
  });

  visibilityZonesEditor.querySelectorAll("[data-visibility-mode]").forEach((input) => {
    input.addEventListener("change", () => {
      const [tabKey, blockKey] = input.getAttribute("data-visibility-mode").split("::");
      config.blocks[tabKey] ||= {};
      config.blocks[tabKey][blockKey] = input.value;
      saveVisibilityState();
      renderVisibilityEditor();
    });
  });

  visibilityRoleDirectory.querySelectorAll("[data-visibility-edit-role]").forEach((button) => {
    button.addEventListener("click", () => {
      state.visibilityEditorRole = button.getAttribute("data-visibility-edit-role") || state.visibilityEditorRole;
      saveState();
      renderVisibilityEditor();
    });
  });
}

function renderOptions(options, selectedValue) {
  return options.map((option) => {
    const value = typeof option === "string" ? option : option.value;
    const label = typeof option === "string" ? option : option.label;
    const selected = value === selectedValue ? "selected" : "";
    return `<option value="${escapeHtml(value)}" ${selected}>${escapeHtml(label)}</option>`;
  }).join("");
}

function renderUiOptions(options, selectedValue) {
  return options.map((option) => {
    const value = typeof option === "string" ? option : option.value;
    const label = typeof option === "string" ? option : option.label;
    const selected = value === selectedValue ? "selected" : "";
    return `<option value="${escapeHtml(value)}" ${selected}>${escapeUi(label)}</option>`;
  }).join("");
}

function renderRoleOptions(selectedValue) {
  return renderOptions(
    state.roleOptions.map((role) => ({ value: role, label: roleLabel(role) })),
    selectedValue
  );
}

function renderStoreCodeOptions(selectedValue = "") {
  const storeOptions = [
    { value: "", label: "-" },
    ...state.stores.map((store) => ({
      value: store.code,
      label: `${store.name} (${store.code})`
    }))
  ];

  return renderOptions(storeOptions, selectedValue);
}

function renderStorePeopleOptions(store, selectedValues = []) {
  const candidates = intervenantPeopleForSelection(selectedValues);

  return candidates.map((person) => {
    const selected = selectedValues.includes(person.name) ? "selected" : "";
    return `<option value="${escapeHtml(person.name)}" ${selected}>${escapeHtml(person.name)} - ${escapeHtml(roleLabel(person.role))}</option>`;
  }).join("");
}

function normalizeRemotePerson(person) {
  return hydrateAccessProfile({
    id: String(person.id),
    name: person.name || "",
    role: person.role || "manager",
    phone: person.phone || "",
    email: person.email || "",
    storeCode: person.store_code || "",
    language: person.language || "fr"
  });
}

function mapStoreRowToState(storeRow, stepRows = [], appointmentRows = []) {
  const stepsByActor = Object.fromEntries(stepRows.map((step) => [step.actor_type, step]));
  const buildStep = (actorType, fallbackLabel) => ({
    actorType,
    label: fallbackLabel,
    status: stepsByActor[actorType]?.status === "issue" ? "blocked" : (stepsByActor[actorType]?.status || "planned"),
    note: stepsByActor[actorType]?.note || ""
  });

  return {
    id: Number(storeRow.id),
    code: storeRow.code,
    name: storeRow.name,
    city: storeRow.city,
    owner: storeRow.owner_name || "",
    manager: storeRow.manager_name || "",
    status: storeRow.status || "planned",
    health: storeRow.health || "",
    updatedAt: storeRow.updated_at || storeRow.last_update_at || new Date().toISOString(),
    steps: [
      buildStep("store_manager", "Magasin"),
      buildStep("installer", "Telephonie"),
      buildStep("electrician", "Electricien")
    ],
    appointments: appointmentRows.map((appointment) => ({
      id: String(appointment.id),
      datetime: appointment.scheduled_at,
      status: appointment.status || "Propose",
      people: appointment.people ? JSON.parse(appointment.people) : [],
      note: appointment.note || ""
    }))
  };
}

function roleValueFromSession(session) {
  const email = session?.user?.email?.toLowerCase();
  if (!email) {
    return null;
  }
  return state.people.find((person) => person.email.toLowerCase() === email) || null;
}

function badgeClass(status) {
  if (status === "done" || status === "ok" || status === "Confirme") {
    return "badge badge-done";
  }

  if (status === "in_progress" || status === "Propose") {
    return "badge badge-in_progress";
  }

  if (status === "blocked" || status === "issue") {
    return "badge badge-blocked";
  }

  return "badge badge-planned";
}

function activePhonePlatformBadge(store) {
  const workflow = ensureStoreWorkflowData(store);
  if (workflow.destinyInstallDone !== "Oui") {
    return "";
  }
  const isMigrationStore = normalizeRoleKey(workflow.dstnyDoneClassification || "") === "migration";
  const installDate = formatDateOnlyLabel(workflow.destinyInstallDate);
  const badgeLabel = isMigrationStore ? "Fuzer actif" : "Telepo actif";
  const badgeClassName = isMigrationStore ? "badge-fuzer" : "badge-telepo";
  return `
    <span class="active-platform-stack">
      <span class="badge ${badgeClassName}">${escapeUi(badgeLabel)}</span>
      ${installDate ? `<span class="active-platform-date ${isMigrationStore ? "is-fuzer" : "is-telepo"}">${escapeUi(`Finalise le ${installDate}`)}</span>` : ""}
    </span>
  `;
}

function sortedAppointments(store) {
  syncDstnyInstallationAppointments(store);
  return [...store.appointments].sort((a, b) => new Date(a.datetime) - new Date(b.datetime));
}

function appointmentDateKey(value) {
  const date = normalizeDateOnly(value);
  if (!date) {
    return "";
  }
  return [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0")
  ].join("-");
}

function addDaysToDate(date, days) {
  const nextDate = new Date(date);
  nextDate.setDate(nextDate.getDate() + days);
  return nextDate;
}

function canEditClosedStoreBigFix(store) {
  return Boolean(isCedricManagedStore(store) && canEditZone(store, "network_config"));
}

function installReminderDateKey(store) {
  return appointmentDateKey(ensureStoreWorkflowData(store).destinyInstallDate);
}

function installReminderPlannedAt(store) {
  const installDate = normalizeDateOnly(ensureStoreWorkflowData(store).destinyInstallDate);
  if (!installDate) {
    return "";
  }
  const plannedAt = addDaysToDate(installDate, -2);
  plannedAt.setHours(9, 0, 0, 0);
  return plannedAt.toISOString();
}

function networkConfigReminderPlannedAt(store, reminderDays = 14) {
  const installDate = normalizeDateOnly(ensureStoreWorkflowData(store).destinyInstallDate);
  if (!installDate) {
    return "";
  }
  const plannedAt = addDaysToDate(installDate, -Math.abs(Number(reminderDays) || 14));
  plannedAt.setHours(9, 0, 0, 0);
  return plannedAt.toISOString();
}

function installationReportFollowupPlannedAt(report = {}) {
  const createdAt = report?.createdAt ? new Date(report.createdAt) : null;
  if (!(createdAt instanceof Date) || Number.isNaN(createdAt.getTime())) {
    return "";
  }
  const plannedAt = addDaysToDate(createdAt, 3);
  plannedAt.setHours(9, 0, 0, 0);
  return plannedAt.toISOString();
}

function installationReportFollowupDateKey(report = {}) {
  const createdAt = report?.createdAt ? new Date(report.createdAt) : null;
  if (!(createdAt instanceof Date) || Number.isNaN(createdAt.getTime())) {
    return "";
  }
  return [
    createdAt.getFullYear(),
    String(createdAt.getMonth() + 1).padStart(2, "0"),
    String(createdAt.getDate()).padStart(2, "0")
  ].join("-");
}

function isPlannedEmailDue(plannedAt) {
  if (!plannedAt) {
    return true;
  }
  const plannedDate = new Date(plannedAt);
  return !Number.isNaN(plannedDate.getTime()) && plannedDate.getTime() <= Date.now();
}

function installDateKnownMailKey(store) {
  const dateKey = installReminderDateKey(store);
  return dateKey ? `${store?.code || store?.id || "store"}:${dateKey}` : "";
}
function isDstnyInstallationAppointment(appointment = {}) {
  const haystack = normalizeSearchText([
    appointment.id || "",
    appointment.note || "",
    appointment.source || ""
  ].join(" "));
  const mentionsDstny = haystack.includes("dstny") || haystack.includes("destiny");
  return mentionsDstny && (
    haystack.includes("installation")
    || haystack.includes("planning mail")
    || haystack.includes("dstny install")
    || haystack.includes("destiny install")
  );
}

function syncDstnyInstallationAppointments(store) {
  if (!store) {
    return false;
  }
  const workflow = ensureStoreWorkflowData(store);
  const installDate = appointmentDateKey(workflow.destinyInstallDate);
  store.appointments = Array.isArray(store.appointments) ? store.appointments : [];
  const dstnyAppointments = store.appointments.filter(isDstnyInstallationAppointment);
  const otherAppointments = store.appointments.filter((appointment) => !isDstnyInstallationAppointment(appointment));
  if (!installDate) {
    return false;
  }
  const matching = dstnyAppointments.find((appointment) => appointmentDateKey(appointment.datetime) === installDate);
  const source = matching || dstnyAppointments[0] || {};
  const sourceTime = String(source.datetime || "").match(/T(\d{2}:\d{2})/)?.[1] || "09:00";
  const syncedAppointment = {
    id: source.id || `dstny-install-${store.id}-${installDate}-${Date.now()}`,
    datetime: `${installDate}T${sourceTime}`,
    status: source.status || "Confirme",
    people: Array.isArray(source.people) && source.people.length ? source.people : ["Dstny"],
    note: source.note || "Installation Dstny importee depuis planning mail"
  };
  const nextAppointments = [...otherAppointments, syncedAppointment];
  const changed = store.appointments.length !== nextAppointments.length
    || dstnyAppointments.some((appointment) => appointmentDateKey(appointment.datetime) !== installDate)
    || !matching;
  store.appointments = nextAppointments;
  return changed;
}

function syncDestinyInstallDateFromAppointments(store) {
  if (!store) {
    return false;
  }
  const workflow = ensureStoreWorkflowData(store);
  const dstnyAppointments = (store.appointments || [])
    .filter((appointment) => isDstnyInstallationAppointment(appointment) && appointmentDateKey(appointment.datetime))
    .sort((left, right) => new Date(left.datetime) - new Date(right.datetime));
  if (!dstnyAppointments.length) {
    return false;
  }
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const nextAppointment = dstnyAppointments.find((appointment) => {
    const date = normalizeDateOnly(appointment.datetime);
    return date && date >= today;
  }) || dstnyAppointments[dstnyAppointments.length - 1];
  const nextDate = appointmentDateKey(nextAppointment.datetime);
  if (!nextDate || appointmentDateKey(workflow.destinyInstallDate) === nextDate) {
    return false;
  }
  workflow.destinyInstallDate = nextDate;
  return true;
}

function reconcileDstnyInstallationAppointments(stores = state.stores || []) {
  const changedStores = [];
  (stores || []).forEach((store) => {
    if (syncDstnyInstallationAppointments(store)) {
      store.updatedAt = new Date().toISOString();
      changedStores.push(store);
    }
  });
  return changedStores;
}

function computeProgress(store) {
  const map = { planned: 0, in_progress: 50, done: 100 };
  const values = store.steps.map((step) => map[step.status] ?? 0);
  const average = values.length ? Math.round(values.reduce((sum, value) => sum + value, 0) / values.length) : 0;
  return store.status === "done" ? 100 : average;
}

function renderProgressCircle(store) {
  const progress = computeProgress(store);
  return `
    <div class="progress-wrap">
      <div class="progress-circle" style="--progress:${progress}%">
        <span>${progress}%</span>
      </div>
    </div>
  `;
}

function buildTimeline(store) {
  const appointments = sortedAppointments(store);
  if (!appointments.length) {
    return '<div class="empty-state">Aucun rendez-vous programme.</div>';
  }

  const dates = appointments.map((appointment) => new Date(appointment.datetime));
  const minDate = new Date(Math.min(...dates));
  const maxDate = new Date(Math.max(...dates));
  const start = new Date(minDate);
  start.setDate(start.getDate() - ((start.getDay() + 6) % 7));
  const end = new Date(maxDate);
  end.setDate(end.getDate() + (6 - ((end.getDay() + 6) % 7)));
  const weekCount = Math.max(1, Math.round((end - start) / (7 * 24 * 60 * 60 * 1000)) + 1);
  const weeks = Array.from({ length: weekCount }, (_, index) => {
    const weekDate = new Date(start);
    weekDate.setDate(start.getDate() + index * 7);
    return weekDate;
  });
  const gridStyle = `grid-template-columns: 1.3fr repeat(${weekCount}, minmax(56px, 1fr));`;

  return `
    <div class="gantt-shell">
      <div class="gantt-header" style="${gridStyle}">
        <div class="gantt-label">Planning</div>
        ${weeks.map((weekDate, index) => `<div class="gantt-week">S${index + 1}<br>${weekDate.toLocaleDateString("fr-BE", { day: "2-digit", month: "2-digit" })}</div>`).join("")}
      </div>
      ${appointments.map((appointment) => {
        const appointmentDate = new Date(appointment.datetime);
        const weekIndex = Math.max(0, Math.floor((appointmentDate - start) / (7 * 24 * 60 * 60 * 1000)));
        return `
          <div class="gantt-row" style="${gridStyle}">
            <div class="gantt-label">${escapeHtml(appointment.status)}<br>${escapeHtml(peopleLabel(appointment.people))}</div>
            <div class="gantt-track" style="grid-column: 2 / span ${weekCount}; --weeks:${weekCount};">
              <div class="gantt-bar ${appointment.status === "Propose" ? "proposed" : ""}" style="grid-column:${weekIndex + 1}">
                ${escapeHtml(formatDateTime(appointment.datetime))}
              </div>
            </div>
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function normalizeDateOnly(dateLike) {
  if (!dateLike) {
    return null;
  }
  if (dateLike instanceof Date && !Number.isNaN(dateLike.getTime())) {
    const parsedDate = new Date(dateLike);
    parsedDate.setHours(0, 0, 0, 0);
    return parsedDate;
  }
  const raw = String(dateLike).trim();
  const isoMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    const [, year, month, day] = isoMatch;
    const parsedIso = new Date(Number(year), Number(month) - 1, Number(day));
    parsedIso.setHours(0, 0, 0, 0);
    return Number.isNaN(parsedIso.getTime()) ? null : parsedIso;
  }
  const localMatch = raw.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})(?:\s+.*)?$/);
  if (localMatch) {
    let [, day, month, year] = localMatch;
    if (year.length === 2) {
      year = Number(year) >= 70 ? `19${year}` : `20${year}`;
    }
    const parsedLocal = new Date(Number(year), Number(month) - 1, Number(day));
    parsedLocal.setHours(0, 0, 0, 0);
    return Number.isNaN(parsedLocal.getTime()) ? null : parsedLocal;
  }
  const parsed = new Date(dateLike);
  if (Number.isNaN(parsed.getTime())) {
    return null;
  }
  parsed.setHours(0, 0, 0, 0);
  return parsed;
}

function localDateInputValue(dateLike) {
  const date = normalizeDateOnly(dateLike);
  if (!date) {
    return "";
  }
  const pad = (value) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function extractInstallationReportDate(reports = []) {
  const reportText = (Array.isArray(reports) ? reports : [])
    .map((report) => [
      report?.date,
      report?.createdAt,
      report?.updatedAt,
      report?.text,
      report?.body,
      report?.content,
      report?.report
    ].filter(Boolean).join(" "))
    .join(" ");
  const match = reportText.match(/(?:Date d(?:'|â€™)installation|Date d(?:'|â€™)intervention|Dates d(?:'|â€™)intervention)\s*:?\s*(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/i)
    || reportText.match(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})\b/);
  if (!match) {
    return "";
  }
  const year = match[3].length === 2 ? `20${match[3]}` : match[3];
  return `${year}-${String(match[2]).padStart(2, "0")}-${String(match[1]).padStart(2, "0")}`;
}

function installationReportOpenActionSection(text = "") {
  const reportText = String(text || "").replace(/\r/g, "");
  const headingPattern = /^\s*(?:\d+\.\s*)?(?:points? d.?attention(?:\s+et\s+actions? restantes?)?|actions? restantes?|points? de vigilance(?:\s+et\s+actions? restantes?)?|openstaande actiepunten)\s*:?\s*$/gim;
  const headings = [...reportText.matchAll(headingPattern)];
  if (!headings.length) return "";
  const heading = headings.at(-1);
  const afterHeading = reportText.slice((heading.index || 0) + heading[0].length).replace(/^\s*\n?/, "");
  const end = afterHeading.search(/^\s*(?:\d+\.\s*)?(?:conclusion|conclusie)\b.*$/im);
  return (end >= 0 ? afterHeading.slice(0, end) : afterHeading).trim();
}

function installationReportHasOpenActions(text = "") {
  const reportText = String(text || "").replace(/\r/g, "");
  if (normalizeImportCell(installationReportOpenActionSection(reportText)).length > 3) {
    return true;
  }
  return /(?:fnp[-\s]?document|document\s+fnp)/i.test(reportText)
    && /(?:definitieve\s+nummerportering|portabilit[eé]\s+d[eé]finitive|nummerportering[^\n]*(?:nog\s+niet|inplannen|uitvoeren))/i.test(reportText);
}

function syncStoreDoneFromInstallationReports(store) {
  if (!store) {
    return false;
  }
  const workflow = ensureStoreWorkflowData(store);
  const reports = Array.isArray(workflow.installationReports) ? workflow.installationReports : [];
  if (!reports.length) {
    return false;
  }
  const reportDate = extractInstallationReportDate(reports);
  const finalDate = reportDate || localDateInputValue(workflow.destinyInstallDate || workflow.currentPhoneDate);
  const explicitlyIncomplete = reports.some((report) => (
    report?.completed === false
    || ["partial", "in_progress", "incomplete"].includes(normalizeImportCell(report?.status).toLowerCase())
    || installationReportHasOpenActions(report?.text || report?.body || report?.content || report?.report || "")
  ));
  if (explicitlyIncomplete) {
    workflow.destinyInstallDone = "Non";
    workflow.dstnyDoneClassification = "";
    workflow.migrationRequired = false;
    workflow.targetPlatform = "Telepo (Dstny)";
    if (finalDate) {
      workflow.destinyInstallDate = finalDate;
    }
    if (store.status === "done") {
      store.status = "in_progress";
    }
    return false;
  }
  const classification = finalDate && finalDate < "2025-09-01" ? "migration" : "magasin fini";

  workflow.destinyInstallDone = "Oui";
  workflow.dstnyDoneClassification = classification;
  workflow.migrationRequired = classification === "migration";
  workflow.currentPlatform = classification === "migration" ? "Fuzer" : "Telepo (Dstny)";
  workflow.targetPlatform = "Telepo (Dstny)";
  if (finalDate) {
    workflow.destinyInstallDate = finalDate;
    workflow.currentPhoneDate = finalDate;
  }
  store.status = "done";
  return true;
}

function nextRelevantDate(store) {
  const appointments = sortedAppointments(store);
  if (appointments[0]?.datetime) {
    return normalizeDateOnly(appointments[0].datetime);
  }
  const workflow = ensureStoreWorkflowData(store);
  return normalizeDateOnly(workflow.destinyInstallDate || store.updatedAt);
}

function matchesDateScope(store) {
  if (state.filters.date === "all") {
    return true;
  }

  const date = nextRelevantDate(store);
  if (!date) {
    return state.filters.date !== "today" && state.filters.date !== "week";
  }

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const diffDays = Math.round((date - today) / 86400000);

  if (state.filters.date === "today") {
    return diffDays === 0;
  }
  if (state.filters.date === "week") {
    return diffDays >= 0 && diffDays <= 7;
  }
  if (state.filters.date === "late") {
    return diffDays < 0;
  }
  if (state.filters.date === "future") {
    return diffDays > 7;
  }
  return true;
}

function hasPlannedIntervention(store) {
  if (store.status === "done") {
    return false;
  }
  const workflow = ensureStoreWorkflowData(store);
  return sortedAppointments(store).some((appointment) => Boolean(normalizeDateOnly(appointment.datetime)))
    || Boolean(normalizeDateOnly(workflow.destinyInstallDate));
}

function hasActiveSav(store) {
  return ticketsForStore(store.id).some((ticket) => ticket.status !== "closed");
}

function isPlannedInterventionListView() {
  return state.filters.search === "intervention prevue";
}

function interventionDateLabel(store) {
  const workflow = ensureStoreWorkflowData(store);
  if (workflow.destinyInstallDate) {
    return workflow.destinyInstallDate;
  }
  const appointments = sortedAppointments(store).filter((appointment) => normalizeDateOnly(appointment.datetime));
  if (appointments[0]?.datetime) {
    return formatDateTime(appointments[0].datetime);
  }
  return "";
}

function compareStoresByInterventionDate(left, right) {
  const fallbackDate = new Date(8640000000000000);
  const leftDate = normalizeDateOnly(interventionDateLabel(left)) || fallbackDate;
  const rightDate = normalizeDateOnly(interventionDateLabel(right)) || fallbackDate;
  return leftDate - rightDate
    || normalizeImportCell(left.code).localeCompare(normalizeImportCell(right.code), "fr", { numeric: true });
}

function missingValidationLabels(store) {
  const workflow = ensureStoreWorkflowData(store);
  const missing = [];
  if (!isNetworkConfigurationOk(store)) missing.push("Config magasin");
  if (!isVlan22Ok(workflow)) missing.push("VLAN22");
  if (externalPrepStatusLabel(workflow) !== "Termine") missing.push("Pre-visite");
  if (workflow.destinyInstallDone !== "Oui") missing.push("Installation Destiny");
  return missing;
}

function isVlan22Ok(workflow = {}) {
  return workflow.vlan22Activated === "Oui"
    || workflow.vlan22Activated === "OK"
    || Boolean(normalizeImportCell(workflow.vlan22Date));
}

function isNetworkConfigurationOk(store) {
  const workflow = ensureStoreWorkflowData(store);
  const networkRows = getNetworkConfigRows(store);
  const requiredRows = isVocovoActive(store)
    ? networkRows.filter((row) => networkConfigurationGuideStage(row.category) !== "call-button")
    : networkRows;
  return Boolean(workflow.networkConfigConfirmed)
    || (requiredRows.length > 0 && requiredRows.every((row) => normalizeImportCell(row.extensionLabel)));
}

function configurationWatchTechnicalStatuses(store) {
  const workflow = ensureStoreWorkflowData(store);
  return [
    { label: "Configuration reseau", icon: "assets/status-icons/network-config-clear.svg", ok: isNetworkConfigurationOk(store) },
    { label: "VLAN22", icon: "assets/status-icons/vlan22-clear.svg", ok: isVlan22Ok(workflow) },
    { label: "Switch", icon: "assets/status-icons/switch-clear.svg", ok: technicalChecklistStageState(store, "network_switches").done },
    { label: "Cable", icon: "assets/status-icons/cable-clear.svg", ok: technicalChecklistStageState(store, "cabling").done }
  ];
}

function configurationWatchTechnicalIcons(store) {
  const statuses = configurationWatchTechnicalStatuses(store);
  return `<span class="configuration-watch-technical-statuses">${statuses.map((status) => `
    <span class="configuration-watch-technical-status ${status.ok ? "is-ok" : "is-incomplete"}"
      title="${escapeHtml(`${status.label} : ${status.ok ? "OK" : "pas OK"}`)}"
      aria-label="${escapeHtml(`${status.label} : ${status.ok ? "OK" : "pas OK"}`)}">
      <img src="${escapeHtml(status.icon)}" alt="">
    </span>`).join("")}${hammerRedScreenIndicator(store)}</span>`;
}

function hammerRedScreenIndicator(store) {
  const workflow = ensureStoreWorkflowData(store);
  const count = Math.max(0, Number(workflow.hammerRedScreenCount) || 0);
  const total = Math.max(0, Number(getStoreQuantityPlan(store).mobileCount) || 0);
  const history = Array.isArray(workflow.hammerRedScreenHistory) ? workflow.hammerRedScreenHistory : [];
  const latest = history.at(-1);
  const title = latest ? `Ecrans rouges cumules : ${count}/${total || "?"} - derniere modification ${formatDateTime(latest.at)}` : `Ecrans rouges cumules : ${count}/${total || "?"}`;
  return `<button type="button" class="hammer-red-screen-indicator ${count > 0 ? "is-active" : ""}" data-hammer-red-screen-count="${escapeHtml(String(store.id))}" title="${escapeHtml(title)}">HAMMER ${count}/${total || "?"}</button>`;
}

function installationFinishGaugeTitle(text = "") {
  const raw = normalizeImportCell(text);
  const normalized = raw.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  if (/\bfnp\b/.test(normalized)) return "FNP";
  if (/nummerport|numeroport|portage|portabilit|portering/.test(normalized)) return "Portage";
  if (/call\s*flow|callflow|keuzemenu|menu de choix|menu vocal/.test(normalized)) return "Callflow";
  if (/algo|audio alerter|geluidssysteem|systeme (?:audio|sonore)/.test(normalized)) return "Algo";
  if (/call\s*button|bouton(?:s)? d.?appel/.test(normalized)) return "Call buttons";
  if (/panic\s*button|bouton(?:s)? panique/.test(normalized)) return "Panic buttons";
  if (/bekabeling|cablage/.test(normalized)) return "Cablage";
  if (/materiaal|materiel/.test(normalized)) return "Materiel";
  const heading = raw.split(/\s+[\u2014-]\s+|[:.;]/)[0].trim();
  return heading.length > 28 ? `${heading.slice(0, 25).trim()}...` : (heading || "Finition");
}

function installationFinishGaugeStatuses(store) {
  const workflow = ensureStoreWorkflowData(store);
  const reports = Array.isArray(workflow.installationReports) ? workflow.installationReports : [];
  if (!reports.length) return [];
  const grouped = new Map();
  syncStoreFinishItems(store).forEach((item) => {
    const label = installationFinishGaugeTitle(item.text);
    const current = grouped.get(label) || { label, done: true, details: [] };
    current.done = current.done && Boolean(item.done);
    current.details.push(normalizeImportCell(item.text));
    grouped.set(label, current);
  });
  const orderedFinishStatuses = [...grouped.values()].sort((left, right) => {
    const order = { FNP: 0, Portage: 1, Callflow: 2, Algo: 3 };
    return (order[left.label] ?? 4) - (order[right.label] ?? 4);
  });
  return [
    { label: "Installation", done: true, details: ["Rapport d installation disponible"] },
    ...orderedFinishStatuses
  ];
}

function installationFinishGauge(store) {
  const statuses = installationFinishGaugeStatuses(store);
  if (!statuses.length) return "";
  const workflow = ensureStoreWorkflowData(store);
  const closureDocuments = Array.isArray(workflow.signedClosureDocuments) ? workflow.signedClosureDocuments : [];
  const closureReceived = closureDocuments.some((document) => document?.fileId || document?.dataUrl || document?.externalUrl);
  const closureClass = closureReceived ? "is-closure-received" : (workflow.closureMailSentAt ? "is-closure-sent" : "is-closure-waiting");
  const closureTitle = closureReceived ? "Rapport de cloture signe recu" : (workflow.closureMailSentAt ? "Rapport de cloture envoye, retour attendu" : "Rapport de cloture pas encore envoye");
  return `<span class="installation-finish-gauge" aria-label="Etat de l installation et des finitions">
    ${statuses.map((status) => `<span class="installation-finish-step ${status.done ? "is-ok" : "is-pending"}"
      title="${escapeHtml(`${status.label} : ${status.done ? "termine" : "a traiter"}${status.details.length ? ` - ${status.details.join(" | ")}` : ""}`)}">
      <span class="installation-finish-dot" aria-hidden="true"></span>${escapeHtml(status.label)}
    </span>`).join("")}
    <span class="installation-finish-step ${closureClass}" title="${escapeHtml(closureTitle)}"><span class="installation-finish-dot" aria-hidden="true"></span>Clôture</span>
    ${hammerRedScreenIndicator(store)}
  </span>`;
}

function testStoreInstallationFinishGauge() {
  const labels = ["Installation", "FNP", "Portage", "Callflow", "Algo", "Remarques"];
  return `<span class="installation-finish-gauge installation-finish-gauge-demo" aria-label="Exemple du suivi après installation">
    ${labels.map((label) => `<span class="installation-finish-step is-pending" title="${escapeHtml(`${label} : exemple à traiter`)}">
      <span class="installation-finish-dot" aria-hidden="true"></span>${escapeHtml(label)}
    </span>`).join("")}
  </span>`;
}

function configurationWatchReportText(report = {}) {
  return normalizeImportCell([report.text, report.content, report.reportText, report.rawText].filter(Boolean).join("\n"));
}

function configurationWatchExtractReportValue(text, labels = []) {
  const source = String(text || "");
  for (const label of labels) {
    const match = source.match(new RegExp(`(?:^|\\n)\\s*(?:${label})\\s*[:\\-]\\s*([^\\n\\r]+)`, "i"));
    if (match?.[1]) return normalizeImportCell(match[1]);
  }
  return "";
}

function configurationWatchDstnyIntervenants(store) {
  const workflow = ensureStoreWorkflowData(store);
  const reports = Array.isArray(workflow.installationReports) ? workflow.installationReports : [];
  const latestReport = [...reports].sort((left, right) => String(right.createdAt || right.date || "").localeCompare(String(left.createdAt || left.date || "")))[0] || {};
  const reportText = configurationWatchReportText(latestReport);
  const installer = configurationWatchExtractReportValue(reportText, ["Technieker", "Installateur", "Technicien installation", "Installation technician"])
    || normalizeImportCell(workflow.destinyInstallerName || workflow.installationInstaller || workflow.destinyPmName);
  const technician = configurationWatchExtractReportValue(reportText, ["UC Consultant", "Consultant UC", "Technicien Dstny", "Dstny technician"])
    || normalizeImportCell(workflow.destinyTechnicianName || workflow.installationTechnician);
  return { installer, technician };
}

function exportConfigurationWatchToXlsx(stores = []) {
  if (!xlsxAvailable()) throw new Error("Bibliotheque XLSX indisponible.");
  const installedLabels = ["Installation", "FNP", "Portage", "Callflow", "Algo"];
  stores.forEach((store) => installationFinishGaugeStatuses(store).forEach((status) => {
    if (!installedLabels.includes(status.label)) installedLabels.push(status.label);
  }));
  const preparationLabels = ["Configuration reseau", "VLAN22", "Switch", "Cable"];
  const headers = ["N° magasin", "Ville", "Date d'installation", "Responsable Brico", "Installateur Dstny", "Technicien Dstny", "Situation", ...installedLabels, ...preparationLabels];
  const rows = stores.map((store) => {
    const workflow = ensureStoreWorkflowData(store);
    const installationStatuses = installationFinishGaugeStatuses(store);
    const installed = installationStatuses.length > 0;
    const installationMap = new Map(installationStatuses.map((status) => [status.label, status.done]));
    const preparationMap = new Map(configurationWatchTechnicalStatuses(store).map((status) => [status.label, status.ok]));
    const intervenants = configurationWatchDstnyIntervenants(store);
    return [
      normalizeImportCell(store.code), normalizeImportCell(store.city || store.name),
      formatDateOnlyLabel(workflow.destinyInstallDate) || normalizeImportCell(workflow.destinyInstallDate),
      normalizeImportCell(workflow.regionalManager), intervenants.installer, intervenants.technician,
      installed ? "Installe - finitions en cours" : "Installation a venir",
      ...installedLabels.map((label, index) => installed
        ? (installationMap.get(label) === true ? "VERT - OK" : (index < 5 ? "ORANGE - A traiter" : (installationMap.has(label) ? "ORANGE - A traiter" : "")))
        : ""),
      ...preparationLabels.map((label) => !installed ? (preparationMap.get(label) ? "VERT - OK" : "ORANGE - A traiter") : "")
    ];
  });
  const worksheet = window.XLSX.utils.aoa_to_sheet([headers, ...rows]);
  worksheet["!cols"] = headers.map((header, index) => ({ wch: index === 0 ? 14 : index === 2 ? 18 : index >= 7 ? 22 : 25 }));
  worksheet["!autofilter"] = { ref: worksheet["!ref"] };
  worksheet["!freeze"] = { xSplit: 0, ySplit: 1, topLeftCell: "A2", activePane: "bottomLeft", state: "frozen" };
  worksheet["!margins"] = { left: 0.25, right: 0.25, top: 0.5, bottom: 0.5, header: 0.2, footer: 0.2 };
  worksheet["!pageSetup"] = { orientation: "landscape", fitToWidth: 1, fitToHeight: 0 };
  const range = window.XLSX.utils.decode_range(worksheet["!ref"]);
  for (let column = range.s.c; column <= range.e.c; column += 1) {
    const cell = worksheet[window.XLSX.utils.encode_cell({ r: 0, c: column })];
    if (cell) cell.s = { font: { bold: true }, fill: { fgColor: { rgb: "FFE066" } } };
  }
  for (let row = 1; row <= range.e.r; row += 1) {
    for (let column = 7; column <= range.e.c; column += 1) {
      const cell = worksheet[window.XLSX.utils.encode_cell({ r: row, c: column })];
      if (!cell?.v) continue;
      if (String(cell.v).startsWith("VERT")) cell.s = { fill: { fgColor: { rgb: "DFF2D7" } } };
      if (String(cell.v).startsWith("ORANGE")) cell.s = { fill: { fgColor: { rgb: "FFE7C2" } } };
    }
  }
  const workbook = window.XLSX.utils.book_new();
  window.XLSX.utils.book_append_sheet(workbook, worksheet, "Planning installations");
  window.XLSX.writeFile(workbook, `planning-installations-prive-${new Date().toISOString().slice(0, 10)}.xlsx`, { cellStyles: true });
}

function scheduledStoresForConfigurationWatch(stores = state.stores || []) {
  const rolloutStartDate = normalizeDateOnly("2026-05-01");
  return (stores || [])
    .filter((store) => {
      const workflow = ensureStoreWorkflowData(store);
      const installDate = normalizeDateOnly(workflow.destinyInstallDate);
      const installationReports = Array.isArray(workflow.installationReports) ? workflow.installationReports : [];
      const hasPendingFinish = installationReports.length > 0 && storeHasPendingFinishItems(store);
      return ["DOS", "FOSDOS"].includes(normalizeShopTypeValue(store.shopType))
        && Boolean(installDate)
        && installDate >= rolloutStartDate
        && (installationReports.length === 0 || hasPendingFinish);
    })
    .sort((left, right) => {
      const leftDate = normalizeDateOnly(ensureStoreWorkflowData(left).destinyInstallDate);
      const rightDate = normalizeDateOnly(ensureStoreWorkflowData(right).destinyInstallDate);
      return (leftDate?.getTime?.() || 0) - (rightDate?.getTime?.() || 0)
        || String(left.name || left.code || "").localeCompare(String(right.name || right.code || ""));
    });
}

function scheduledStoresAwaitingNetworkConfiguration(stores = state.stores || []) {
  return scheduledStoresForConfigurationWatch(stores)
    .filter((store) => !isNetworkConfigurationOk(store));
}

function networkConfigurationWatchDays(store) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const installDate = normalizeDateOnly(ensureStoreWorkflowData(store).destinyInstallDate);
  return installDate ? Math.ceil((installDate.getTime() - today.getTime()) / 86400000) : null;
}

function hasStorePlan(store) {
  const workflow = ensureStoreWorkflowData(store);
  return getStorePlanFilesFromWorkflow(workflow).length > 0;
}

function planFileIsZip(plan = {}) {
  return /\.zip$/i.test(plan.name || plan.fileName || "") || plan.fileType === "application/zip";
}

function planFileIsImage(plan = {}) {
  return /^image\//i.test(plan.fileType || "") || /\.(png|jpe?g|webp|heic)$/i.test(plan.name || plan.fileName || "");
}

function planFileKindLabel(plan = {}) {
  if (planFileIsZip(plan)) return "ZIP";
  if (planFileIsImage(plan)) return "IMAGE";
  return "PDF";
}

function planFileMergeKey(plan = {}) {
  return [
    normalizeImportCell(plan.name || plan.fileName || "").toLowerCase(),
    String(plan.fileSize || plan.planFileSize || "")
  ].join("::");
}

function normalizeStorePlanFile(plan = {}, index = 0) {
  const name = normalizeImportCell(plan.name || plan.fileName || plan.planPdfName || "");
  const fileId = normalizeImportCell(plan.fileId || plan.planFileId || "");
  const dataUrl = plan.dataUrl || plan.planPdfDataUrl || "";
  return {
    id: normalizeImportCell(plan.id || "") || safeDocumentId("plan-doc", `${name || "document"}-${fileId || index}`),
    name,
    fileType: plan.fileType || plan.planFileType || (/\.zip$/i.test(name) ? "application/zip" : /\.(png|jpe?g|webp|heic)$/i.test(name) ? "image/*" : "application/pdf"),
    fileSize: String(plan.fileSize || plan.planFileSize || ""),
    fileId,
    bucketId: normalizeImportCell(plan.bucketId || plan.planFileBucketId || "") || appwritePlansBucketId,
    dataUrl,
    updatedAt: plan.updatedAt || plan.planPdfUpdatedAt || new Date().toISOString()
  };
}

function getStorePlanFilesFromWorkflow(workflow = {}) {
  const files = Array.isArray(workflow.planFiles)
    ? workflow.planFiles.map((plan, index) => normalizeStorePlanFile(plan, index))
    : [];
  if (!files.length && (workflow.planFileId || workflow.planPdfDataUrl || workflow.planPdfName)) {
    files.push(normalizeStorePlanFile({
      id: "legacy-plan",
      name: workflow.planPdfName || "Plan magasin",
      fileType: workflow.planFileType || "",
      fileSize: workflow.planFileSize || "",
      fileId: workflow.planFileId || "",
      bucketId: workflow.planFileBucketId || appwritePlansBucketId,
      dataUrl: workflow.planPdfDataUrl || "",
      updatedAt: workflow.planPdfUpdatedAt || ""
    }));
  }
  return files.filter((plan) => plan.name || plan.fileId || plan.dataUrl);
}

function syncLegacyPlanFieldsFromList(workflow = {}) {
  const files = getStorePlanFilesFromWorkflow(workflow);
  workflow.planFiles = files;
  const latest = files[files.length - 1] || null;
  workflow.planPdfName = latest?.name || "";
  workflow.planFileType = latest?.fileType || "";
  workflow.planFileId = latest?.fileId || "";
  workflow.planFileBucketId = latest?.bucketId || "";
  workflow.planFileSize = latest?.fileSize || "";
  workflow.planPdfDataUrl = latest?.dataUrl || "";
  workflow.planPdfUpdatedAt = latest?.updatedAt || "";
  return files;
}

function storeValidationItems(store) {
  const workflow = ensureStoreWorkflowData(store);
  const installationReports = Array.isArray(workflow.installationReports)
    ? workflow.installationReports.filter((report) => report && typeof report === "object")
    : [];
  return [
    {
      label: "Config",
      okLabel: "Config OK",
      issueLabel: "Config a faire",
      ok: isNetworkConfigurationOk(store)
    },
    {
      label: "VLAN22",
      okLabel: "VLAN22 OK",
      issueLabel: "VLAN22 a valider",
      ok: isVlan22Ok(workflow)
    },
    {
      label: "Pre-visite",
      okLabel: "Pre-visite OK",
      issueLabel: "Pre-visite a faire",
      ok: externalPrepStatusLabel(workflow) === "Termine"
    },
    {
      label: "Plan",
      okLabel: "Plan OK",
      issueLabel: "Plan a charger",
      ok: hasStorePlan(store)
    },
    {
      label: "Installation",
      okLabel: "Installation OK",
      issueLabel: "Installation a faire",
      ok: workflow.destinyInstallDone === "Oui" || installationReports.length > 0
    }
  ];
}

function effectiveStoreStatus(store) {
  const currentStatus = store?.status || "planned";
  if (currentStatus !== "planned") return currentStatus;
  const workflow = ensureStoreWorkflowData(store || {});
  const installationReports = Array.isArray(workflow.installationReports)
    ? workflow.installationReports.filter((report) => report && typeof report === "object")
    : [];
  return installationReports.length > 0 ? "in_progress" : currentStatus;
}

function renderStoreValidationSignals(store, options = {}) {
  if (options.compact) {
    const status = configControlStatus(store);
    const compactItems = [
      {
        ok: status.networkConfigOk,
        okLabel: "Config OK",
        issueLabel: "Config a verifier"
      },
      {
        ok: status.vlanOk,
        okLabel: "VLAN22 OK",
        issueLabel: "VLAN22 a verifier"
      }
    ];
    return `
      <div class="store-validation-signals is-compact">
        ${store.status === "blocked" ? `<span class="validation-signal signal-issue">${escapeUi("Blocage")}</span>` : ""}
        ${compactItems.map((item) => `
          <span class="validation-signal ${item.ok ? "signal-ok" : "signal-issue"}">
            ${escapeUi(item.ok ? item.okLabel : item.issueLabel)}
          </span>
        `).join("")}
      </div>
    `;
  }
  const items = storeValidationItems(store);
  const visibleItems = items;
  return `
    <div class="store-validation-signals">
      ${store.status === "blocked" ? `<span class="validation-signal signal-issue">${escapeUi("Blocage")}</span>` : ""}
      ${visibleItems.map((item) => `
        <span class="validation-signal ${item.ok ? "signal-ok" : "signal-issue"}">
          ${escapeUi(item.ok ? item.okLabel : item.issueLabel)}
        </span>
      `).join("")}
    </div>
  `;
}

function configControlStatus(store) {
  const workflow = ensureStoreWorkflowData(store);
  return {
    vlanOk: isVlan22Ok(workflow),
    networkConfigOk: isNetworkConfigurationOk(store),
    previsitOk: externalPrepStatusLabel(workflow) === "Termine",
    cablingOk: workflow.cablingStatus === "OK",
    switchOk: workflow.ltSwitchStatus === "Basculee" || workflow.ltSwitchStatus === "OK"
  };
}

function configStatusCards(visibleStores, total) {
  const countOk = (key) => visibleStores.filter((store) => configControlStatus(store)[key]).length;
  const cardPair = (label, key, okNote = "OK", koNote = "A traiter", filterKey = key) => {
    const okCount = countOk(key);
    const koCount = visibleStores.length - okCount;
    return [
      { label: `${label} OK`, value: okCount, note: okNote, portion: Math.round((okCount / total) * 100), filter: { reset: true, key: "configStatus", value: `${filterKey}:ok`, tab: "configuration" } },
      { label: `${label} pas OK`, value: koCount, note: koNote, portion: Math.round((koCount / total) * 100), filter: { reset: true, key: "configStatus", value: `${filterKey}:ko`, tab: "configuration" } }
    ];
  };
  return [
    ...cardPair("VLAN22", "vlanOk", "VLAN valide", "VLAN a valider", "vlanOk"),
    ...cardPair("Config reseau", "networkConfigOk", "Configuration complete", "Configuration incomplete", "networkConfigOk"),
    ...cardPair("Previsite", "previsitOk", "Previsite OK", "Previsite a suivre", "previsitOk"),
    ...cardPair("Cablage", "cablingOk", "Cablage OK", "Cablage a suivre", "cablingOk"),
    ...cardPair("Switch", "switchOk", "Switch effectue", "Switch a faire", "switchOk")
  ];
}

function matchesConfigStatusScope(store) {
  const scope = state.filters.configStatus || "all";
  if (scope === "all") {
    return true;
  }
  const [key, expected] = scope.split(":");
  const status = configControlStatus(store);
  if (!(key in status)) {
    return true;
  }
  return expected === "ok" ? Boolean(status[key]) : !status[key];
}

function getFilteredStores() {
  const finishedStoresOnly = activeMainWorkspaceTab() === "finished-stores";
  const migrationStoresOnly = activeMainWorkspaceTab() === "migration";
  const timelineStoresOnly = activeMainWorkspaceTab() === "timeline";
  const fosStoresOnly = activeMainWorkspaceTab() === "stores-fos";
  const fosdosGroupStoresOnly = activeMainWorkspaceTab() === "stores-fosdos-group";
  const activeStoresOnly = activeMainWorkspaceTab() === "stores";
  const scopedStores = getRoleScopedStores();
  const user = currentUser();
  const forceScopedUserStores = user && !canSeeAllStores(user);
  const filteredStores = scopedStores.filter((store) => {
    const searchTerm = normalizeImportCell(state.filters.search).toLowerCase();
    const normalizedSearch = normalizeImportStoreCode(searchTerm);
    const normalizedCode = normalizeImportStoreCode(store.code);
    const normalizedShopNumber = normalizeImportStoreCode(store.shopNumber);
    const exactCodeSearch = Boolean(searchTerm)
      && (
        normalizedSearch === normalizedCode
        || normalizedSearch === normalizedShopNumber
        || searchTerm === normalizeImportCell(store.code).toLowerCase()
        || searchTerm === normalizeImportCell(store.shopNumber).toLowerCase()
      );
    const appointments = sortedAppointments(store);
    const nextAction = appointments[0]?.note || store.health || "";
    const stage = currentWorkflowStage(store);
    const workflow = ensureStoreWorkflowData(store);
    const appointmentHaystack = appointments.map((appointment) => [
      appointment.status || "",
      appointment.note || "",
      peopleLabel(appointment.people || []),
      formatDateTime(appointment.datetime || "")
    ].join(" ")).join(" ");
    const plannedInstallKeywords = appointments.length || workflow.destinyInstallDate
      ? "installation prevue installation planifiee rendez-vous planifie"
      : "";
    const interventionKeywords = hasPlannedIntervention(store)
      ? "intervention prevue intervention planifiee"
      : "";
    const savKeywords = hasActiveSav(store)
      ? "sav actif sav ouvert sav en cours"
      : "";
    const invoiceHaystack = [
      store.poLicences,
      store.poHpDesk,
      store.poPm,
      store.poRentingHw,
      ...invoiceTicketsForStore(store).map((ticket) => [
        ticket.requestKind,
        ticket.materialLabel,
        ticket.concern,
        ticket.orderWorkflowStatus,
        ticket.invoiceOrderStatus,
        ticket.orderApproved,
        invoiceOrderReference(ticket),
        invoiceOrderDeliveredDate(ticket)
      ].join(" "))
    ].join(" ");
    const haystack = `${store.code} ${store.shopNumber || ""} ${store.cnsNumber || ""} ${store.name} ${store.city} ${store.manager} ${store.shopType || ""} ${store.status} ${store.owner} ${nextAction} ${stage} ${appointmentHaystack} ${workflow.destinyInstallDate || ""} ${workflow.currentPhoneDate || ""} ${plannedInstallKeywords} ${interventionKeywords} ${savKeywords} ${invoiceHaystack}`.toLowerCase();
    const matchesSearch = haystack.includes(searchTerm);
    const classification = normalizeRoleKey(workflow.dstnyDoneClassification || "");
    const normalizedType = normalizeShopTypeValue(store.shopType);
    const isFosType = normalizedType === "FOS";
    const isFosdosOrUndefinedType = normalizedType === "FOSDOS" || isUndefinedShopType(store.shopType);
    const isSpecialTypeTabStore = isFosType || isFosdosOrUndefinedType;
    const selectedUnifiedCategory = state.storeCategoryFilter || "all";
    const matchesUnifiedCategory = !activeStoresOnly
      || selectedUnifiedCategory === "all"
      || unifiedStoreCategory(store) === selectedUnifiedCategory;
    const matchesFinishedScope = !finishedStoresOnly || (store.status === "done" && classification !== "migration" && !isSpecialTypeTabStore);
    const matchesMigrationScope = !migrationStoresOnly || (classification === "migration" && !isSpecialTypeTabStore);
    const matchesFosScope = !fosStoresOnly || isFosType;
    const matchesFosdosGroupScope = !fosdosGroupStoresOnly || isFosdosOrUndefinedType;
    const matchesActiveStoresScope = matchesUnifiedCategory;
    const matchesTimelineScope = !timelineStoresOnly || classification === "migration" || (store.status !== "done" && hasPlannedIntervention(store));
    const matchesStatus = finishedStoresOnly || migrationStoresOnly || state.filters.status === "all" || store.status === state.filters.status;
    const matchesOwner = state.filters.owner === "all" || storeProvenance(store) === state.filters.owner;
    const matchesStage = state.filters.stage === "all" || stage === state.filters.stage;
    const matchesType = state.filters.type === "all"
      || (state.filters.type === "TO_DEFINE" ? isUndefinedShopType(store.shopType) : normalizeShopTypeValue(store.shopType || "") === state.filters.type);
    const matchesCity = state.filters.city === "all" || store.city === state.filters.city;
    const matchesDate = matchesDateScope(store);
    const matchesInvoice = matchesInvoiceScope(store);
    const matchesConfigStatus = matchesConfigStatusScope(store);
    if (forceScopedUserStores) {
      return searchTerm ? matchesSearch : true;
    }
    const matchesWorkspaceScope = matchesFinishedScope
      && matchesMigrationScope
      && matchesFosScope
      && matchesFosdosGroupScope
      && matchesActiveStoresScope
      && matchesTimelineScope;
    if (exactCodeSearch) {
      return matchesSearch && matchesWorkspaceScope;
    }
    if (searchTerm) {
      return matchesSearch && matchesWorkspaceScope;
    }
    return matchesWorkspaceScope && matchesSearch && matchesStatus && matchesOwner && matchesStage && matchesType && matchesCity && matchesDate && matchesInvoice && matchesConfigStatus;
  });

  if (isPlannedInterventionListView()) {
    return filteredStores.slice().sort(compareStoresByInterventionDate);
  }
  return filteredStores;
}

function renderSummary() {
  const visibleStores = getRoleScopedStores();
  const total = visibleStores.length || 1;
  const doneCount = visibleStores.filter((store) => store.status === "done").length;
  const blockedCount = visibleStores.filter((store) => store.status === "blocked").length;
  const noRdvCount = visibleStores.filter((store) => !hasPlannedIntervention(store)).length;
  const migrationCount = visibleStores.filter((store) => normalizeRoleKey(ensureStoreWorkflowData(store).dstnyDoneClassification || "") === "migration").length;
  const deploymentCount = visibleStores.filter(hasPlannedIntervention).length;
  const visibleStoreIds = new Set(visibleStores.map((store) => String(store.id)));
  const visibleSavTickets = (state.tickets || [])
    .filter(Boolean)
    .filter((ticket) => visibleStoreIds.has(String(ticket.storeId)));
  const activeSavCount = visibleSavTickets
    .filter((ticket) => String(ticket.status || "").toLowerCase() !== "closed")
    .length;
  const savTotal = visibleSavTickets.length || 1;
  const dosCount = visibleStores.filter((store) => normalizeShopTypeValue(store.shopType) === "DOS").length;
  const fosCount = visibleStores.filter((store) => normalizeShopTypeValue(store.shopType) === "FOS").length;
  const fosdosCount = visibleStores.filter((store) => normalizeShopTypeValue(store.shopType) === "FOSDOS").length;
  const undefinedTypeCount = visibleStores.filter((store) => isUndefinedShopType(store.shopType)).length;
  const validationItCount = visibleStores.filter((store) => !isVlan22Ok(ensureStoreWorkflowData(store))).length;
  const riskCount = visibleStores.filter((store) => {
    const workflow = ensureStoreWorkflowData(store);
    return store.status === "blocked" || externalPrepStatusLabel(workflow) !== "Termine";
  }).length;
  const mainTab = activeMainWorkspaceTab();
  const cardsByTab = {
    dashboard: [
      { label: "Total magasins", value: visibleStores.length, note: "Vision globale parc", portion: 100, filter: null },
      { label: "DOS", value: dosCount, note: "Type magasin DOS", portion: Math.round((dosCount / total) * 100), filter: { key: "type", value: "DOS", tab: "stores" } },
      { label: "FOS", value: fosCount, note: "Type magasin FOS", portion: Math.round((fosCount / total) * 100), filter: { reset: true, key: "type", value: "FOS", tab: "stores-fos" } },
      { label: "FOSDOS", value: fosdosCount, note: "Type magasin FOSDOS", portion: Math.round((fosdosCount / total) * 100), filter: { reset: true, key: "type", value: "FOSDOS", tab: "stores-fosdos-group" } },
      { label: "A definir", value: undefinedTypeCount, note: "Type magasin a definir", portion: Math.round((undefinedTypeCount / total) * 100), filter: { reset: true, key: "type", value: "TO_DEFINE", tab: "stores-fosdos-group" } },
      { label: "En deploiement", value: deploymentCount, note: "Interventions prevues", portion: Math.round((deploymentCount / total) * 100), filter: { reset: true, key: "search", value: "intervention prevue", tab: "stores" } },
      { label: "Helpdesk on", value: activeSavCount, note: "SAV non clotures", portion: Math.round((activeSavCount / savTotal) * 100), filter: { reset: true, tab: "sav" } },
      { label: "Clotures", value: doneCount, note: "Projets finalises", portion: Math.round((doneCount / total) * 100), filter: { key: "status", value: "done", tab: "stores" } },
      { label: "Bloques", value: blockedCount, note: "Dossiers a debloquer", portion: Math.round((blockedCount / total) * 100), filter: { key: "status", value: "blocked", tab: "stores" } }
    ],
    timeline: [
      { label: "Interventions planifiees", value: visibleStores.filter((store) => sortedAppointments(store).length).length, note: "Chronologie magasins", portion: Math.round((visibleStores.filter((store) => sortedAppointments(store).length).length / total) * 100), filter: null },
      { label: "Validation VLAN22", value: validationItCount, note: "VLAN22 a valider", portion: Math.round((validationItCount / total) * 100), filter: { key: "stage", value: "Validation VLAN22", tab: "timeline" } },
      { label: "Installations a risque", value: riskCount, note: "Points sensibles a traiter", portion: Math.round((riskCount / total) * 100), filter: { key: "status", value: "blocked", tab: "timeline" } }
    ],
    sav: [
      { label: "Tickets ouverts", value: getFilteredTickets().filter((ticket) => ticket.status === "open").length, note: "Demandes a traiter", portion: Math.min(100, getFilteredTickets().filter((ticket) => ticket.status === "open").length * 20), filter: { key: "status", value: "in_progress", tab: "sav" } },
      { label: "En cours", value: getFilteredTickets().filter((ticket) => ticket.status === "in_progress").length, note: "Suivis en traitement", portion: Math.min(100, getFilteredTickets().filter((ticket) => ticket.status === "in_progress").length * 20), filter: { key: "status", value: "in_progress", tab: "sav" } },
      { label: "Clotures", value: getFilteredTickets().filter((ticket) => ticket.status === "closed").length, note: "Historique conserve", portion: Math.min(100, getFilteredTickets().filter((ticket) => ticket.status === "closed").length * 20), filter: { key: "status", value: "done", tab: "sav" } },
      { label: "A surveiller", value: getFilteredTickets().filter((ticket) => ticket.status !== "closed").length, note: "Tickets encore actifs", portion: Math.min(100, getFilteredTickets().filter((ticket) => ticket.status !== "closed").length * 20), filter: null }
    ],
    extensions: [
      { label: "Reference extensions", value: extensionCatalogRows.length, note: "Liste commune magasin / IT", portion: 100, filter: null },
      { label: "Postes fixes", value: visibleStores.reduce((sum, store) => sum + getStoreQuantityPlan(store).fixCount, 0), note: "Quota total fixe", portion: 100, filter: null },
      { label: "Mobiles", value: visibleStores.reduce((sum, store) => sum + getStoreQuantityPlan(store).mobileCount, 0), note: "Quota total mobile", portion: 100, filter: null },
      { label: "Call / Panic", value: visibleStores.reduce((sum, store) => sum + getStoreQuantityPlan(store).callButtonCount + getStoreQuantityPlan(store).panicCount, 0), note: "Lignes specifiques", portion: 100, filter: null }
    ],
    invoice: [
      { label: "Magasins", value: visibleStores.length, note: "Suivi facturation", portion: 100, filter: null },
      { label: "PO manquants", value: visibleStores.filter(hasMissingInvoicePo).length, note: "Au moins un PO absent", portion: Math.round((visibleStores.filter(hasMissingInvoicePo).length / total) * 100), filter: { reset: true, key: "invoice", value: "missing_po", tab: "invoice" } },
      { label: "A facturer", value: visibleStores.reduce((sum, store) => sum + invoiceTicketsForStore(store, "billable").length, 0), note: "Commandes supplementaires", portion: 100, filter: { reset: true, key: "invoice", value: "billable", tab: "invoice" } },
      { label: "Remplacements", value: visibleStores.reduce((sum, store) => sum + invoiceTicketsForStore(store, "replacement").length, 0), note: "Materiel casse / remplace", portion: 100, filter: { reset: true, key: "invoice", value: "replacement", tab: "invoice" } }
    ],
    stores: [
      { label: t("summaryStores"), value: visibleStores.length, note: t("summaryStoresNote"), portion: 100 },
      { label: t("summaryDone"), value: doneCount, note: t("summaryDoneNote"), portion: Math.round((doneCount / total) * 100) },
      { label: t("summaryBlocked"), value: blockedCount, note: t("summaryBlockedNote"), portion: Math.round((blockedCount / total) * 100) },
      { label: "Migration", value: migrationCount, note: "A reprendre en migration", portion: Math.round((migrationCount / total) * 100), filter: { reset: true, tab: "migration" } }
    ],
    configuration: configStatusCards(visibleStores, total)
  };
  const cards = cardsByTab[mainTab] || cardsByTab.dashboard;

  summaryGrid.innerHTML = "";
  cards.forEach((card) => {
    const article = document.createElement("article");
    article.innerHTML = `
      <button type="button" class="dashboard-kpi-button" ${card.filter ? `data-kpi-filter='${escapeHtml(JSON.stringify(card.filter))}'` : ""}>
        <div class="panel summary-card">
          <div class="summary-card-layout">
            <div class="summary-copy">
              <span class="mini-label">${escapeUi(card.label)}</span>
              <strong>${card.value}</strong>
              <span class="summary-note">${escapeUi(card.note)}</span>
            </div>
            <div class="mini-donut" style="--portion:${card.portion}%">
              <span>${card.portion}%</span>
            </div>
          </div>
        </div>
      </button>
    `;
    summaryGrid.append(article);
  });

  summaryGrid.querySelectorAll("[data-kpi-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      const filter = JSON.parse(button.getAttribute("data-kpi-filter"));
      if (filter?.tab) {
        state.activeAdminTab = openUnifiedStoresFromLegacyTab(filter.tab);
      }
      if (filter?.reset) {
        resetWorkspaceFilters();
      }
      if (filter?.key) {
        state.filters[filter.key] = filter.value;
      }
      saveState();
      render();
    });
  });

  renderDashboardExtra(mainTab, visibleStores);
}

function renderDashboardExtra(mainTab, visibleStores) {
  if (!dashboardExtra) {
    return;
  }

  if (mainTab === "dashboard") {
    const canSeeConfigurationWatch = canSeeConfigurationWatchDashboard();
    const scheduledConfigurationStores = canSeeConfigurationWatch
      ? scheduledStoresForConfigurationWatch(visibleStores)
      : [];
    const pendingConfigurationStores = scheduledConfigurationStores
      .filter((store) => {
        const workflow = ensureStoreWorkflowData(store);
        const reports = Array.isArray(workflow.installationReports) ? workflow.installationReports : [];
        return reports.length ? storeHasPendingFinishItems(store) : !isNetworkConfigurationOk(store);
      });
    dashboardExtra.classList.remove("hidden-panel");
    dashboardExtra.innerHTML = `
      <div class="dashboard-card-grid">
        <article class="dashboard-card">
          <h3>${escapeUi("Statut projets")}</h3>
          <div class="dashboard-chip-grid">
            ${[
              { label: "A lancer", value: visibleStores.filter((store) => store.status === "planned").length, note: "Dossiers a demarrer", filter: { key: "status", value: "planned", tab: "stores" } },
              { label: "En attente infos", value: visibleStores.filter((store) => !isNetworkConfigurationOk(store)).length, note: "Config magasin attendue", filter: { key: "stage", value: "Validation manager config", tab: "stores" } },
              { label: "Validation VLAN22", value: visibleStores.filter((store) => !isVlan22Ok(ensureStoreWorkflowData(store))).length, note: "VLAN22 a valider", filter: { key: "stage", value: "Validation VLAN22", tab: "timeline" } },
              { label: "En cours", value: visibleStores.filter(hasPlannedIntervention).length, note: "Interventions prevues", filter: { reset: true, key: "search", value: "intervention prevue", tab: "stores" } },
              { label: "RUN", value: visibleStores.filter(hasActiveSav).length, note: "Magasins avec SAV", filter: { reset: true, key: "search", value: "sav actif", tab: "stores" } },
              { label: "PO attente", value: visibleStores.filter((store) => !store.poLicences).length, note: "Commandes a relancer", filter: { key: "status", value: "blocked", tab: "stores" } },
              { label: "Tickets urgents", value: visibleStores.filter((store) => store.status === "blocked").length, note: "SAV prioritaire", filter: { key: "status", value: "blocked", tab: "sav" } }
            ].map((chip) => `
              <button type="button" class="dashboard-chip" data-kpi-filter='${escapeHtml(JSON.stringify(chip.filter))}'>
                <span class="mini-label">${escapeUi(chip.label)}</span>
                <strong>${chip.value}</strong>
                <small>${escapeUi(chip.note)}</small>
              </button>
            `).join("")}
          </div>
        </article>
        ${canSeeConfigurationWatch ? `
          <article class="dashboard-card configuration-watch-card">
            <div class="configuration-watch-heading">
              <div>
                <span class="mini-label">${escapeUi("Suivi privé Emir / Valou")}</span>
                <h3>${escapeUi("Installations programmées — suivi des configurations et finitions")}</h3>
                <p>${escapeUi("Après installation, les magasins restent visibles tant qu une finition du Statut global est ouverte.")}</p>
              </div>
              <div class="configuration-watch-counts">
                <button type="button" class="configuration-watch-export" data-configuration-watch-export>${escapeUi("Exporter en Excel")}</button>
                <span><strong>${scheduledConfigurationStores.length}</strong><small>${escapeUi("suivis")}</small></span>
                <span class="${pendingConfigurationStores.length ? "has-pending" : "is-complete"}"><strong>${pendingConfigurationStores.length}</strong><small>${escapeUi("à traiter")}</small></span>
              </div>
            </div>
            ${scheduledConfigurationStores.length ? `
              <div class="configuration-watch-list">
                ${scheduledConfigurationStores.map((store) => {
                  const workflow = ensureStoreWorkflowData(store);
                  const installationReports = Array.isArray(workflow.installationReports) ? workflow.installationReports : [];
                  const installed = installationReports.length > 0;
                  const isTestStore = normalizeImportCell(store.code).toUpperCase() === "BRI-TEST";
                  const days = networkConfigurationWatchDays(store);
                  const urgencyClass = days <= 10 ? "is-urgent" : days <= 14 ? "is-warning" : "is-future";
                  const configurationOk = isNetworkConfigurationOk(store);
                  const sostelActive = workflow.sostelActive === true;
                  return `
                    <div class="configuration-watch-row ${configurationOk ? "is-config-complete" : "is-config-pending"} ${isTestStore ? "is-test-store" : ""}">
                      <span class="configuration-watch-store">
                        <strong>${escapeHtml(store.code || "")} — ${escapeHtml(store.name || "")}</strong>
                        <small>${escapeHtml(store.city || "")}</small>
                      </span>
                      <span class="configuration-watch-date">${escapeHtml(formatDateOnlyLabel(workflow.destinyInstallDate) || workflow.destinyInstallDate || "")}</span>
                      <span class="configuration-watch-urgency ${installed ? "is-installed" : urgencyClass}">${installed ? "Installé" : days === 0 ? "Aujourd’hui" : days > 0 ? `J-${days}` : `+${Math.abs(days)}J`}</span>
                      ${installed ? installationFinishGauge(store) : configurationWatchTechnicalIcons(store)}
                      ${installed ? "" : canToggleSostel()
                        ? `<button type="button" class="sostel-indicator ${sostelActive ? "is-active" : ""}" data-sostel-toggle="${escapeHtml(String(store.id))}" aria-pressed="${sostelActive ? "true" : "false"}">SOSTEL</button>`
                        : `<span class="sostel-indicator ${sostelActive ? "is-active" : ""}">SOSTEL</span>`}
                      <button type="button" class="configuration-watch-action" data-configuration-watch-store="${escapeHtml(String(store.id))}">${escapeUi(installed ? "Ouvrir la fiche" : "Ouvrir la configuration")}</button>
                      ${isTestStore && !installed ? testStoreInstallationFinishGauge() : ""}
                    </div>
                  `;
                }).join("")}
              </div>
            ` : `<div class="empty-state">${escapeUi("Aucun magasin DOS installe depuis mai 2026 n attend son rapport d installation.")}</div>`}
          </article>
        ` : ""}
      </div>
    `;
    dashboardExtra.querySelectorAll("[data-kpi-filter]").forEach((button) => {
      button.addEventListener("click", () => {
        const filter = JSON.parse(button.getAttribute("data-kpi-filter"));
        if (filter?.tab) {
          state.activeAdminTab = openUnifiedStoresFromLegacyTab(filter.tab);
        }
        if (filter?.reset) {
          resetWorkspaceFilters();
        }
        if (filter?.key) {
          state.filters[filter.key] = filter.value;
        }
        saveState();
        render();
      });
    });
    dashboardExtra.querySelectorAll("[data-configuration-watch-store]").forEach((button) => {
      button.addEventListener("click", () => {
        openStoreConfigurationById(Number(button.getAttribute("data-configuration-watch-store")));
      });
    });
    dashboardExtra.querySelector("[data-configuration-watch-export]")?.addEventListener("click", () => {
      try {
        exportConfigurationWatchToXlsx(scheduledConfigurationStores);
      } catch (error) {
        window.alert(error?.message || "L export Excel n a pas pu etre cree.");
      }
    });
    dashboardExtra.querySelectorAll("[data-sostel-toggle]").forEach((button) => {
      button.addEventListener("click", handleSostelToggle);
    });
    dashboardExtra.querySelectorAll("[data-hammer-red-screen-count]").forEach((button) => {
      button.addEventListener("click", handleHammerRedScreenCounter);
    });
    return;
  }

  if (mainTab === "invoice") {
    dashboardExtra.classList.remove("hidden-panel");
    dashboardExtra.innerHTML = `
      <div class="invoice-search-panel">
        <label>
          <span>Recherche Invoice</span>
          <input type="search" data-invoice-search value="${escapeHtml(state.filters.invoiceSearch || "")}" placeholder="Rechercher par PO, magasin, code, commande...">
        </label>
        ${state.filters.invoiceSearch ? '<button type="button" class="secondary-button" data-invoice-search-clear>Effacer</button>' : ""}
      </div>
    `;
    const searchInput = dashboardExtra.querySelector("[data-invoice-search]");
    searchInput?.addEventListener("input", () => {
      state.filters.invoiceSearch = normalizeImportCell(searchInput.value);
      saveState();
      renderStores();
    });
    dashboardExtra.querySelector("[data-invoice-search-clear]")?.addEventListener("click", () => {
      state.filters.invoiceSearch = "";
      saveState();
      render();
    });
    return;
  }

  dashboardExtra.classList.add("hidden-panel");
  dashboardExtra.innerHTML = "";
}

function syncSelectors() {
  if (languageSelect) {
    languageSelect.value = state.language;
    languageSelect.disabled = !canOverrideInterfaceLanguage();
  }
  if (languageSwitch) {
    languageSwitch.classList.toggle("hidden-panel", !canOverrideInterfaceLanguage());
  }
  const types = [...new Set(getRoleScopedStores().map((store) => isUndefinedShopType(store.shopType) ? "TO_DEFINE" : normalizeShopTypeValue(store.shopType)).filter(Boolean))].sort((a, b) => {
    const order = { DOS: 0, FOS: 1, FOSDOS: 2, TO_DEFINE: 3 };
    return (order[a] ?? 9) - (order[b] ?? 9) || a.localeCompare(b);
  });
  const cities = [...new Set(getRoleScopedStores().map((store) => store.city).filter(Boolean))].sort();
  const stages = [...new Set(getRoleScopedStores().map((store) => currentWorkflowStage(store)).filter(Boolean))].sort();
  ownerFilter.innerHTML = `<option value="all">${t("all")}</option>`;
  provenanceOptions.forEach((owner) => {
    const option = document.createElement("option");
    option.value = owner;
    option.textContent = owner;
    ownerFilter.append(option);
  });
  ownerFilter.value = state.filters.owner;

  typeFilter.innerHTML = `<option value="all">${t("all")}</option>${types.map((type) => `<option value="${escapeHtml(type)}">${escapeHtml(shopTypeLabel(type))}</option>`).join("")}`;
  typeFilter.value = state.filters.type;

  cityFilter.innerHTML = `<option value="all">${t("all")}</option>${cities.map((city) => `<option value="${escapeHtml(city)}">${escapeHtml(city)}</option>`).join("")}`;
  cityFilter.value = state.filters.city;

  stageFilter.innerHTML = `<option value="all">${state.language === "nl" ? "Alle" : "Toutes"}</option>${stages.map((stage) => `<option value="${escapeHtml(stage)}">${escapeHtml(stage)}</option>`).join("")}`;
  stageFilter.value = state.filters.stage;

  dateFilter.value = state.filters.date;

  activeUserSelect.innerHTML = state.people.map((person) => {
    const selected = person.name === state.activeUserName ? "selected" : "";
    return `<option value="${escapeHtml(person.name)}" ${selected}>${escapeHtml(person.name)} - ${escapeHtml(person.role)}</option>`;
  }).join("");

  storeOwnerSelect.innerHTML = provenanceOptions
    .map((value) => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`)
    .join("");
  if (storeEditSelect) {
    const selectedStoreId = storeEditSelect.value;
    storeEditSelect.innerHTML = [
      '<option value="">Nouveau magasin</option>',
      ...state.stores
        .slice()
        .sort((a, b) => String(a.code || "").localeCompare(String(b.code || ""), "fr", { numeric: true }))
        .map((store) => `<option value="${escapeHtml(String(store.id))}">${escapeHtml(`${store.code} - ${store.name}`)}</option>`)
    ].join("");
    if ([...storeEditSelect.options].some((option) => option.value === selectedStoreId)) {
      storeEditSelect.value = selectedStoreId;
    }
  }
  const fieldStoreOptions = state.stores
    .slice()
    .sort((a, b) => String(a.code || "").localeCompare(String(b.code || ""), "fr", { numeric: true }))
    .map((store) => `<option value="${escapeHtml(String(store.id))}">${escapeHtml(`${store.code} - ${store.name}`)}</option>`)
    .join("");
  if (fieldReportStoreSelect) {
    const selected = fieldReportStoreSelect.value;
    fieldReportStoreSelect.innerHTML = fieldStoreOptions;
    if ([...fieldReportStoreSelect.options].some((option) => option.value === selected)) fieldReportStoreSelect.value = selected;
  }
  if (fieldReportStoreOptions) {
    fieldReportStoreOptions.innerHTML = state.stores
      .slice()
      .sort((a, b) => storeOptionLabel(a).localeCompare(storeOptionLabel(b), "fr"))
      .map((store) => `<option value="${escapeHtml(storeOptionLabel(store))}">${escapeHtml([store.city, store.shopNumber].filter(Boolean).join(" - "))}</option>`)
      .join("");
  }
  if (fieldUsersStoreOptions) {
    fieldUsersStoreOptions.innerHTML = state.stores
      .slice()
      .sort((a, b) => storeOptionLabel(a).localeCompare(storeOptionLabel(b), "fr"))
      .map((store) => `<option value="${escapeHtml(storeOptionLabel(store))}">${escapeHtml([store.city, store.shopNumber].filter(Boolean).join(" - "))}</option>`)
      .join("");
  }
  if (fieldUsersStoreSelect) {
    const selected = fieldUsersStoreSelect.value;
    fieldUsersStoreSelect.innerHTML = fieldStoreOptions;
    if ([...fieldUsersStoreSelect.options].some((option) => option.value === selected)) fieldUsersStoreSelect.value = selected;
  }

  personRoleSelect.innerHTML = renderRoleOptions(personRoleSelect.value || "manager");
  personLanguageSelect.value = personLanguageSelect.value || "fr";
  personStoreCodeInput.innerHTML = renderStoreCodeOptions(personStoreCodeInput.value || "");
  peopleSearchInput.value = state.contactSearch;
  if (intervenantPersonSelect) {
    intervenantPersonSelect.innerHTML = state.people
      .slice()
      .sort((a, b) => a.name.localeCompare(b.name, "fr"))
      .map((person) => `<option value="${escapeHtml(person.id)}">${escapeHtml(person.name)}</option>`)
      .join("");
  }
  if (intervenantRoleSelect) {
    intervenantRoleSelect.innerHTML = renderIntervenantRoleOptions(intervenantRoleSelect.value || "intervenant");
  }

  if (pinRoleSelect) {
    pinRoleSelect.innerHTML = renderRoleOptions(pinRoleSelect.value || "manager");
  }
  if (pinPersonNameOptions) {
    pinPersonNameOptions.innerHTML = state.people
      .slice()
      .sort((a, b) => a.name.localeCompare(b.name, "fr"))
      .map((person) => `<option value="${escapeHtml(person.name)}">${escapeHtml(roleLabel(person.role))}</option>`)
      .join("");
  }
  if (pinStoreSearchOptions) {
    pinStoreSearchOptions.innerHTML = state.stores
      .slice()
      .sort((a, b) => a.name.localeCompare(b.name, "fr"))
      .map((store) => `<option value="${escapeHtml(`${store.name} (${store.code})`)}">${escapeHtml(store.city || "")}</option>`)
      .join("");
  }
  if (pinStoreMultiSelect) {
    pinStoreMultiSelect.innerHTML = state.stores
      .map((store) => `<option value="${escapeHtml(store.code)}">${escapeHtml(store.name)} (${escapeHtml(store.code)})</option>`)
      .join("");
  }
}

