  workflow.previsitAppointment.id ||= `previsit-${Date.now()}`;
  workflow.previsitAppointment.previsitDate ||= appointmentDateKey(workflow.previsitAppointment.datetime) || workflow.previsitDate || "";
  workflow.previsitAppointment.previsitTime ||= workflow.previsitAppointment.timeProvided ? String(workflow.previsitAppointment.datetime || "").match(/T(\d{2}:\d{2})/)?.[1] || "" : "";
  workflow.previsitAppointment.timeProvided = Boolean(workflow.previsitAppointment.previsitTime);
  workflow.previsitAppointment.people = [];
