function buildStoreDocumentsCard(store) {
  const workflow = ensureStoreWorkflowData(store);
  const planFiles = getStorePlanFilesFromWorkflow(workflow);
  const emptyLabel = "Aucun document importe";
  const importLabel = planFiles.length ? "Ajouter PDF / ZIP / image" : "Importer PDF / ZIP / image";
  const documentsHtml = planFiles.length
    ? `
      <div class="remark-history">
        ${planFiles.slice().reverse().map((plan) => {
          const isZipPlan = planFileIsZip(plan);
          const isImagePlan = planFileIsImage(plan);
          const planKindLabel = planFileKindLabel(plan);
          return `
            <div class="remark-entry">
              <div class="remark-meta">${escapeHtml(formatDateTime(plan.updatedAt))} - ${escapeHtml(planKindLabel)}</div>
              <div class="two-col align-end-grid">
                <div class="cell-stack">
                  <strong>${escapeHtml(plan.name || emptyLabel)}</strong>
                  <span class="cell-note">${escapeHtml(plan.fileSize ? `${Math.round(Number(plan.fileSize) / 1024)} Ko` : "Document magasin")}</span>
                </div>
                <div class="posts-skeleton-actions">
                  <button type="button" class="mini-button" data-plan-open="${store.id}" data-plan-doc-id="${escapeHtml(plan.id)}">${escapeUi(isZipPlan ? "Telecharger le ZIP" : isImagePlan ? "Ouvrir l'image" : "Ouvrir le PDF")}</button>
                  <button type="button" class="mini-button" data-plan-delete="${store.id}" data-plan-doc-id="${escapeHtml(plan.id)}">${escapeUi("Supprimer")}</button>
                </div>
              </div>
            </div>
          `;
        }).join("")}
      </div>
    `
    : `<div class="cell-note">${escapeUi("Ajoute ici les plans PDF, images de workflow ou ZIP contenant plusieurs plans.")}</div>`;
  const saveFeedback = state.storeSaveFeedback?.storeId === Number(store.id)
    ? state.storeSaveFeedback
    : null;

  return `
    <div class="editor-grid section-anchor" id="section-documents">
      <article class="editor-card full-span-card" data-access-zone="store_documents">
        <h3>${escapeUi("Documents / Plan magasin")}</h3>
        <div class="two-col align-end-grid">
          <div class="cell-stack">
            <strong>${escapeHtml(planFiles.length ? `${planFiles.length} document(s) importe(s)` : emptyLabel)}</strong>
            <span class="cell-note">${escapeHtml(planFiles.length ? "Plusieurs PDF / ZIP / images possibles pour ce magasin." : "Aucun plan charge pour ce magasin.")}</span>
          </div>
          <div class="posts-skeleton-actions">
            <input type="file" class="hidden-file-input" data-plan-file="${store.id}" accept="application/pdf,application/zip,image/png,image/jpeg,image/webp,.pdf,.zip,.png,.jpg,.jpeg,.webp" multiple>
            <button type="button" class="mini-button" data-plan-upload="${store.id}">${escapeUi(importLabel)}</button>
          </div>
        </div>
        ${documentsHtml}
        ${saveFeedback ? `<p class="validation-text is-${escapeHtml(saveFeedback.status)} document-feedback">${escapeHtml(saveFeedback.message)}</p>` : ""}
      </article>
    </div>
  `;
}

