function ensureStoreWorkflowData(store) {
  const { mobileCount } = getStoreQuantityPlan(store);
  if (!store.workflow) {
    store.workflow = {};
  }

  const defaults = {
    currentPlatform: "Destiny",
    targetPlatform: "TELEPO",
    configStatus: "Envoye",
    currentPhoneDate: "",
    orderStatus: "Transmise fournisseur",
    orderNote: "",
    currentContractClientNumber: "",
    currentContractMainNumber: "",
    currentContractOtherNumbers: "",
    collectDate: "",
    itValidationDate: "",
    previsitDate: "",
    previsitAppointment: null,
    transferDate: "",
    destinyInstallDate: "",
    destinyPmName: "",
    destinyPmEmail: "",
    destinyTicketRef: "",
    destinyCaseRef: "",
    destinyDistribution: "Emir; Valou; Charles Roux",
    networkSurveyStatus: "A planifier",
    mobileCoverage: "A verifier",
    firstVisitRemark: "",
    extensionRequestStatus: "A envoyer",
    extensionConfigStatus: "En attente",
    ivrNotes: "",
    greetingNotes: "",
    regionalManager: "",
    alarmHandledByIt: "A confirmer",
    vlan22Status: "A relancer",
    vlan22Date: "",
    vlan22Activated: "Non",
    vlan22Note: "",
    charlesRouxStatus: "A verifier",
    cablingStatus: "A verifier",
    cablingDate: "",
    cablingSwitchReference: "",
    mobileChargersSent: "Non",
    mobileChargerCount: String(Math.max(1, Math.ceil(mobileCount / 10))),
    planPdfName: "",
    planFileType: "",
    planFileId: "",
    planFileBucketId: "",
    planFileSize: "",
    planPdfDataUrl: "",
    planPdfUpdatedAt: "",
    planFiles: [],
    destinyInstallDone: "Non",
    destinyInstallRemark: "",
    bricoFinalMailStatus: "A envoyer",
    bricoFinalRemark: "",
    dstnyDoneClassification: "",
    dstnyDoneClassificationImportedAt: "",
    dstnyDoneClassificationSource: "",
    originalDstnyInstallDate: "",
    migrationRequired: false,
    ltSwitchStatus: "En attente",
    ltSwitchDate: "",
    switchNote: "",
    installSwitchDate: "",
    installCableDate: "",
    installAntennaDate: "",
    installCentralDate: "",
    externalPrepRemarks: [],
    installationRemarks: [],
    installationReports: [],
    managerJ3Report: "",
    managerJ3ReportSender: "",
    finishItems: [],
    finishManualRemarks: "",
    closureMailSentAt: "",
    closureMailRecipients: [],
    closureMailStatus: "",
    signedClosureDocuments: [],
    closureReviewRequired: false,
    closureReviewStatus: "",
    closureReviewNotificationSentAt: "",
    closurePortingVerified: false,
    closurePortingVerifiedAt: "",
    closurePortingSource: "",
    closurePortingNote: "",
    closureSummaryNote: "",
    closureConclusion: "",
    closureSummaryDocuments: [],
    closureReportRemarks: [],
    closureReportSignedDate: "",
    closurePackageSentAt: "",
    closurePackageRecipients: [],
    hammerRedScreenCount: 0,
    hammerRedScreenHistory: [],
    hammerRedScreenResponses: [],
    hammerBlueBagReplacements: [],
    hammerDstnyReplacements: [],
    postInstallSimInfo: {},
    postInstallSimInventory: [],
    postInstallExtensionDirectory: [],
    callButtonDisplayStatus: "A demander",
    callButtonDisplayDate: "",
    callButtonDisplayRemarks: [],
    callButtonStickerStatus: "A demander",
    callButtonStickerDate: "",
    callButtonStickerRemarks: [],
    networkConfigConfirmed: false,
    networkRows: defaultNetworkRowsForStore(store),
    gsmRows: defaultGsmRowsForStore(store),
    intervenantRows: defaultIntervenantRows(),
    openingHours: defaultStoreOpeningHours(),
    openingHoursNote: "",
    alarmType: "A confirmer",
    alarmCompany: "",
    alarmCentralPhone: "",
    alarmOther: "",
    callGroupsNote: "",
    cascadeNote: "",
    menuChoiceNote: ""
  };

  Object.entries(defaults).forEach(([key, value]) => {
    if (!store.workflow[key]) {
      store.workflow[key] = value;
    }
  });

  ["installationReports", "finishItems", "signedFnpDocuments", "portingConfirmationDocuments", "signedClosureDocuments", "closureSummaryDocuments", "closureReportRemarks", "hammerRedScreenHistory", "hammerRedScreenResponses", "hammerBlueBagReplacements", "hammerDstnyReplacements"].forEach((key) => {
    const value = store.workflow[key];
    if (value == null || value === "") store.workflow[key] = [];
    else if (!Array.isArray(value)) store.workflow[key] = [value];
  });

  if (store.workflow.currentPhoneDate === "1970-01-01") {
    store.workflow.currentPhoneDate = "";
  }

  if (store.workflow.vlan22Date === "1970-01-01") {
    store.workflow.vlan22Date = "";
  }

  ["externalPrepRemarks", "installationRemarks", "callButtonDisplayRemarks", "callButtonStickerRemarks"].forEach((key) => {
    store.workflow[key] = dedupeWorkflowRemarks(store.workflow[key]);
  });
  store.workflow.openingHours = isLegacyDefaultStoreOpeningHours(store.workflow.openingHours)
    ? defaultStoreOpeningHours()
    : normalizeStoreOpeningHours(store.workflow.openingHours);
  syncLegacyPlanFieldsFromList(store.workflow);

  return store.workflow;
}

