function buildClosureWorkflowCard(store, options = {}) {
  const workflow = ensureStoreWorkflowData(store);
  const includeBricoFeedback = options.includeBricoFeedback !== false;
  const installationReports = Array.isArray(workflow.installationReports) ? workflow.installationReports : [];
  const reportsContent = installationReports.length ? `
    <section class="installation-report-card">
      <h4>${escapeUi("Rapport d installation Dstny importe via Tools TWEM")}</h4>
      <p>${escapeUi("Le rapport importe dans Tools TWEM est rattache automatiquement a ce magasin et conserve ici pour lecture.")}</p>
      <div class="installation-report-list">
        ${installationReports.map((report) => `
          <article class="installation-report-item">
            <div class="installation-report-meta">
              <strong>${escapeHtml(formatDateTime(report.createdAt) || "Rapport installation")}</strong>
              <span>${escapeHtml(report.author || "TWEM")}</span>
            </div>
             <pre>${escapeHtml(report.text || "")}</pre>
             ${(report.sourceArchivePlanId || report.callflowPlanId) ? `<div class="installation-report-actions">
               ${report.sourceArchivePlanId ? `<button type="button" class="mini-button" data-installation-doc-open="${store.id}" data-installation-doc-id="${escapeHtml(report.sourceArchivePlanId)}">${escapeUi("Telecharger le ZIP complet")}</button>` : ""}
               ${report.callflowPlanId ? `<button type="button" class="mini-button" data-installation-doc-open="${store.id}" data-installation-doc-id="${escapeHtml(report.callflowPlanId)}">${escapeUi("Voir le Call Flow")}</button>` : ""}
             </div>` : ""}
           </article>
        `).join("")}
      </div>
    </section>
  ` : `
    <section class="installation-report-card">
      <h4>${escapeUi("Rapport d installation Dstny importe via Tools TWEM")}</h4>
      <div class="empty-state">${escapeUi("Aucun rapport d installation importe pour ce magasin.")}</div>
    </section>
  `;
  return `
    <div class="editor-grid closure-grid full-span-card">
      <article class="editor-card full-span-card" data-access-zone="destiny_closure">
        <h3>${escapeUi("Cloture installation Destiny")}</h3>
        <p>${escapeUi("Validation de fin d intervention, remarques de chantier et rapport importe depuis Tools TWEM.")}</p>
        <div class="two-col">
          <label>
            <span>${escapeUi("Installation Destiny terminee")}</span>
            <select name="destiny_install_done">
              ${renderUiOptions(["Non", "Oui", "Avec reserve"], workflow.destinyInstallDone)}
            </select>
          </label>
          <label>
            <span>${escapeUi("Mail de fin equipe Brico")}</span>
            <select name="brico_final_mail_status">
              ${renderUiOptions(["A envoyer", "Envoye", "Retour recu"], workflow.bricoFinalMailStatus)}
            </select>
          </label>
        </div>
        <label>
          <span>${escapeUi("Remarque installation Destiny")}</span>
          <textarea name="destiny_install_remark" rows="4" placeholder="${escapeUi("Probleme constate, element a corriger, reserve de fin")}">${escapeHtml(workflow.destinyInstallRemark)}</textarea>
        </label>
        ${reportsContent}
      </article>

      ${includeBricoFeedback ? `<article class="editor-card" data-access-zone="brico_feedback">
        <h3>${escapeUi("Retour Brico / bascule suite")}</h3>
        <p>${escapeUi("Remarques finales du magasin et eventuelle bascule vers la plateforme suivante.")}</p>
        <label>
          <span>${escapeUi("Remarques finales Brico")}</span>
          <textarea name="brico_final_remark" rows="4" placeholder="${escapeUi("Element qui pourrait encore ne pas fonctionner, remarque post-installation")}">${escapeHtml(workflow.bricoFinalRemark)}</textarea>
        </label>
        <label>
          <span>${escapeUi("Switch plateforme LT")}</span>
          <select name="lt_switch_status">
            ${renderUiOptions(["En attente", "A decider", "Basculee"], workflow.ltSwitchStatus)}
          </select>
        </label>
      </article>` : ""}
    </div>
  `;
}

