function buildStoreInstallationReportArchive(store) {
  const workflow = ensureStoreWorkflowData(store);
  const installationReports = Array.isArray(workflow.installationReports) ? workflow.installationReports : [];
  const storeCategory = unifiedStoreCategory(store);
  const installationDate = formatDateOnlyLabel(workflow.destinyInstallDate || "");
  const reportStatusMessage = storeCategory === "non-rollout"
    ? "Ce magasin n est pas dans le roll-out : aucun rapport d installation n est attendu."
    : installationDate
      ? `L installation est planifiee le ${installationDate}. Le rapport sera affiche ici apres son introduction dans le systeme.`
      : "La date d installation n a pas encore ete planifiee. Aucun rapport n est donc attendu pour le moment.";
  const reportStatusSummary = storeCategory === "non-rollout"
    ? "Magasin hors roll-out"
    : installationDate
      ? `Installation planifiee le ${installationDate}`
      : "Installation pas encore planifiee";
  return `
    <details class="store-config-archive store-mirror-archive section-anchor" id="section-closing">
      <summary>
        <span>${escapeUi("Cloture installation Destiny")}</span>
        <span>${escapeUi(installationReports.length ? `${installationReports.length} rapport(s) disponible(s)` : reportStatusSummary)}</span>
      </summary>
      <div class="store-config-archive-body">
        <details class="store-config-subsection">
          <summary>
            <span>${escapeUi("Rapport d installation Dstny")}</span>
            <span>${escapeUi(installationReports.length ? `${installationReports.length} rapport(s)` : reportStatusSummary)}</span>
          </summary>
          <div class="store-config-subsection-body">
            ${installationReports.length ? `
              <div class="installation-report-list">
                ${installationReports.map((report) => `
                  <article class="installation-report-item">
                    <div class="installation-report-meta">
                      <strong>${escapeHtml(formatDateTime(report.createdAt) || "Rapport installation")}</strong>
                      <span>${escapeHtml(report.author || "TWEM")}</span>
                    </div>
                     <pre>${escapeHtml(report.text || "")}</pre>
                     ${(report.sourceArchivePlanId || report.callflowPlanId) ? `<div class="installation-report-actions">
                       ${report.sourceArchivePlanId ? `<button type="button" class="mini-button" data-installation-doc-open="${store.id}" data-installation-doc-id="${escapeHtml(report.sourceArchivePlanId)}">${escapeUi("Telecharger le ZIP complet")}</button>` : ""}
                       ${report.callflowPlanId ? `<button type="button" class="mini-button" data-installation-doc-open="${store.id}" data-installation-doc-id="${escapeHtml(report.callflowPlanId)}">${escapeUi("Voir le Call Flow")}</button>` : ""}
                     </div>` : ""}
                   </article>
                `).join("")}
              </div>
            ` : `<div class="empty-state">${escapeUi(reportStatusMessage)}</div>`}
          </div>
        </details>

        <details class="store-config-subsection">
          <summary>
            <span>${escapeUi("Rapport J+3 du magasin")}</span>
            <span>${escapeUi(workflow.managerJ3Report ? "Rapport recu" : "En attente")}</span>
          </summary>
          <div class="store-config-subsection-body">
            <label>
              <span>${escapeUi("Envoye par")}</span>
              <input type="text" name="manager_j3_report_sender" value="${escapeHtml(workflow.managerJ3ReportSender || "")}">
            </label>
            <label>
              <span>${escapeUi("Mail / rapport J+3 du magasin")}</span>
              <textarea name="manager_j3_report" rows="7">${escapeHtml(workflow.managerJ3Report || "")}</textarea>
            </label>
          </div>
        </details>
      </div>
    </details>
  `;
}

function buildStoreManagerJ3Archive(store) {
  const workflow = ensureStoreWorkflowData(store);
  const storeCategory = unifiedStoreCategory(store);
  const installationDate = formatDateOnlyLabel(workflow.destinyInstallDate || "");
  const managerJ3Report = normalizeImportCell(workflow.managerJ3Report || "");
  const isFinishedStore = storeCategory === "finished";
  const waitingMessage = storeCategory === "non-rollout"
    ? "Ce magasin n est pas dans le roll-out : aucun retour manager J+3 n est attendu."
    : installationDate
      ? `L installation est planifiee le ${installationDate}. Le retour du manager sera introduit ici apres reception du mail J+3.`
      : "La date d installation n a pas encore ete planifiee. Aucun retour manager J+3 n est attendu pour le moment.";
  const summaryStatus = managerJ3Report
    ? "Retour manager J+3 enregistre"
    : isFinishedStore
      ? "Retour a introduire manuellement"
      : storeCategory === "non-rollout"
        ? "Magasin hors roll-out"
        : installationDate
          ? `Installation planifiee le ${installationDate}`
          : "Installation pas encore planifiee";
  return `
    <details class="store-config-archive store-mirror-archive section-anchor" id="section-problem-notes">
      <summary>
        <span>${escapeUi("Cloture finale")}</span>
        <span>${escapeUi(summaryStatus)}</span>
      </summary>
      <div class="store-config-archive-body">
        ${!managerJ3Report && !isFinishedStore ? `<div class="empty-state">${escapeUi(waitingMessage)}</div>` : ""}
        <article class="editor-card full-span-card" data-access-zone="problem_notes">
          <h3>${escapeUi("Retour manager J+3")}</h3>
          <p>${escapeUi(isFinishedStore
            ? "Pour les magasins finis, colle manuellement ici le mail du manager."
            : "Le mail recu du manager sera conserve ici dans la fiche du magasin.")}</p>
          <label>
            <span>${escapeUi("Mail / rapport J+3 du manager")}</span>
            <textarea name="manager_j3_report" rows="7">${escapeHtml(managerJ3Report)}</textarea>
          </label>
          <label>
            <span>${escapeUi("Envoye par")}</span>
            <input type="text" name="manager_j3_report_sender" value="${escapeHtml(workflow.managerJ3ReportSender || "")}">
          </label>
          <label>
            <span>${escapeUi("Note interne / probleme bloquant")}</span>
            <textarea name="health" rows="4">${escapeHtml(store.health || "")}</textarea>
          </label>
        </article>
      </div>
    </details>
  `;
}

