      <tbody>${switches.map((item) => `<tr><td>${escapeHtml(item.hostname || "-")}</td><td>${escapeHtml(item.assetId || "-")}</td><td>${escapeHtml(item.model || "-")}</td><td>${escapeHtml(item.ipAddress || "-")}</td><td>${escapeHtml(item.serialNumber || "-")}</td><td>${escapeHtml(item.location || "-")}</td><td>${escapeHtml(item.freePorts || "0")}</td><td>${escapeHtml([item.portDetails, item.comment].filter(Boolean).join(" — ") || "-")}</td></tr>`).join("")}</tbody>
