function populateSimInfoPanel(panel, info = {}) {
  panel.querySelectorAll("[data-sim-field]").forEach((field) => {
    const key = field.getAttribute("data-sim-field");
    if (key === "puk2" && field.dataset.puk2Revealed !== "1") {
      field.value = "";
      field.type = "password";
      field.placeholder = "Second PIN requis";
      return;
    }
    field.value = info[key] || "";
  });
  const meta = panel.querySelector("[data-sim-meta]");
  if (meta) {
    const pieces = [];
    if (info.updatedAt) {
      pieces.push(`Maj ${formatDateTime(info.updatedAt)}`);
    }
    if (info.updatedBy) {
      pieces.push(info.updatedBy);
    }
    if (info.source) {
      pieces.push(info.source);
    }
    meta.textContent = pieces.join(" - ");
  }
}

function handleSimPuk2Reveal(event) {
  const button = event.currentTarget;
  const storeId = Number(button.getAttribute("data-sim-puk2-reveal"));
  const rowId = button.getAttribute("data-sim-puk2-row") || "";
  const store = state.stores.find((item) => item.id === storeId);
  const row = getNetworkConfigRows(store || {}).find((entry) => String(entry.id || entry.slotLabel || "") === rowId);
  const panel = button.closest("[data-sim-row-editor]");
  const field = panel?.querySelector('[data-sim-field="puk2"]');
  if (!store || !row || !panel || !field) {
    return;
  }
  if (!canAccessSimInfoForStore(store)) {
    window.alert("PUK2 reserve au manager du magasin, a TWEM et aux utilisateurs autorises.");
    return;
  }
  if (!validatePinForPuk2Reveal()) {
    return;
  }
  const info = simInfoForNetworkRow(store, row);
  field.dataset.puk2Revealed = "1";
  field.type = "text";
  field.value = info.puk2 || "";
  field.readOnly = !canEditSimTechnicalInfo();
  field.placeholder = "";
}

function handleSimInfoToggle(event) {
  const button = event.currentTarget;
  const storeId = Number(button.getAttribute("data-sim-toggle"));
  const rowId = button.getAttribute("data-sim-row") || "";
  const store = state.stores.find((item) => item.id === storeId);
  const row = getNetworkConfigRows(store || {}).find((entry) => String(entry.id || entry.slotLabel || "") === rowId);
  if (!store || !row) {
    return;
  }
  const panelRow = projectTableBody.querySelector(`[data-sim-panel="${CSS.escape(String(storeId))}"][data-sim-row-panel="${CSS.escape(rowId)}"]`);
  if (!panelRow) {
    return;
  }
  if (!panelRow.classList.contains("hidden-panel")) {
    panelRow.classList.add("hidden-panel");
    return;
  }
  if (!validateCurrentPinForSimReveal(store)) {
    return;
  }
  const info = simInfoForNetworkRow(store, row);
  const panel = panelRow.querySelector("[data-sim-row-editor]");
  if (panel) {
    populateSimInfoPanel(panel, info);
  }
  panelRow.classList.remove("hidden-panel");
}

async function handleSostelToggle(event) {
  if (!canToggleSostel()) return;
  const button = event.currentTarget;
  const storeId = Number(button.getAttribute("data-sostel-toggle"));
  const store = state.stores.find((entry) => Number(entry.id) === storeId);
  if (!store) return;
  const workflow = ensureStoreWorkflowData(store);
  workflow.sostelActive = workflow.sostelActive !== true;
  workflow.sostelUpdatedAt = new Date().toISOString();
  workflow.sostelUpdatedBy = currentUser()?.name || state.activeUserName || "TWEM";
  store.updatedAt = workflow.sostelUpdatedAt;
  saveState();
  render();
  if (hasRemoteData()) {
    try {
      await syncStoreToRemote(store, workflow.sostelActive ? "SOSTEL active" : "SOSTEL desactive");
    } catch (error) {
      console.error("Erreur sauvegarde statut SOSTEL", error);
      alert("Le statut SOSTEL est garde localement, mais la sauvegarde Appwrite a echoue.");
    }
  }
}

async function handleHammerRedScreenCounter(event) {
  if (!canSeeConfigurationWatchDashboard()) return;
  const storeId = Number(event.currentTarget.getAttribute("data-hammer-red-screen-count"));
  const store = state.stores.find((entry) => Number(entry.id) === storeId);
  if (!store) return;
  const workflow = ensureStoreWorkflowData(store);
  const currentCount = Math.max(0, Number(workflow.hammerRedScreenCount) || 0);
  const total = Math.max(0, Number(getStoreQuantityPlan(store).mobileCount) || 0);
  const responses = Array.isArray(workflow.hammerRedScreenResponses) ? workflow.hammerRedScreenResponses : [];
  const archive = responses.length ? responses.map((item) => `${formatDateTime(item.receivedAt)} - ${item.result || "Retour reçu"}${item.devices ? ` - ${item.devices}` : ""}${item.comment ? ` - ${item.comment}` : ""}`).join("\n") : "Aucun retour magasin archivé.";
  const answer = window.prompt(`Nouveaux Hammer dont l'écran est devenu rouge pour ${store.code} — ${store.name}\n\nCompteur cumulé actuel : ${currentCount}\nTotal Hammer du magasin : ${total || "non renseigné"}\n\nRetours archivés :\n${archive}\n\nSaisis uniquement le nombre de nouveaux Hammer à ajouter au cumul :`, "0");
  if (answer === null) return;
  const addedCount = Number.parseInt(String(answer).trim(), 10);
  if (!Number.isInteger(addedCount) || addedCount < 0) {
    window.alert("Introduis un nombre entier positif ou zéro.");
    return;
  }
  if (addedCount === 0) return;
  const nextCount = currentCount + addedCount;
  const changeRemark = window.prompt(
    `Remarque liée à cet ajout pour ${store.code} — ${store.name}\n\n` +
    `Nouveaux Hammer rouges : ${addedCount}\nCompteur cumulé : ${currentCount} -> ${nextCount}\n\n` +
    "Indique le poste, le numéro de série ou toute information utile. Cette remarque et la date seront reprises dans le rapport :",
    ""
  );
  if (changeRemark === null) return;
  const at = new Date().toISOString();
  workflow.hammerRedScreenCount = nextCount;
  workflow.hammerRedScreenHistory = [...(Array.isArray(workflow.hammerRedScreenHistory) ? workflow.hammerRedScreenHistory : []), {
    id: `hammer-red-${Date.now()}`,
    previousCount: currentCount,
    count: nextCount,
    delta: addedCount,
    at,
    by: currentUser()?.name || state.activeUserName || "TWEM",
    note: normalizeImportCell(changeRemark) || `Ajout cumulatif : +${addedCount} (${currentCount} -> ${nextCount})`
  }];
  workflow.hammerRedScreenResponses = [...responses, {
    id: `hammer-red-response-${Date.now()}`,
    receivedAt: at,
    sender: currentUser()?.name || state.activeUserName || "TWEM",
    result: `${addedCount} appareil${addedCount > 1 ? "s" : ""} supplémentaire${addedCount > 1 ? "s" : ""}`,
    count: nextCount,
    devices: normalizeImportCell(changeRemark),
    serialNumbers: "",
    comment: `Compteur cumulé augmenté de ${addedCount} : ${currentCount} -> ${nextCount}`
  }];
  store.updatedAt = at;
  saveState();
  render();
  if (hasRemoteData()) {
    try {
      await syncStoreToRemote(store, `Compteur Hammer ecran rouge : ${currentCount} -> ${nextCount}`);
    } catch (error) {
      console.error("Erreur sauvegarde compteur Hammer ecran rouge", error);
      window.alert("Le compteur est gardé localement, mais la sauvegarde Appwrite a échoué.");
    }
  }
}

async function handleSimInfoSave(event) {
  const button = event.currentTarget;
  const storeId = Number(button.getAttribute("data-sim-save"));
  const rowId = button.getAttribute("data-sim-save-row") || "";
  const store = state.stores.find((item) => item.id === storeId);
  const row = getNetworkConfigRows(store || {}).find((entry) => String(entry.id || entry.slotLabel || "") === rowId);
  const panel = button.closest("[data-sim-row-editor]");
  if (!store || !row || !panel) {
    return;
  }
  const info = simInfoForNetworkRow(store, row);
  const canEditTechnical = canEditSimTechnicalInfo();
  panel.querySelectorAll("[data-sim-field]").forEach((field) => {
    const key = field.getAttribute("data-sim-field");
    if (key === "puk2" && field.dataset.puk2Revealed !== "1") {
      return;
    }
    if (key === "pin" || canEditTechnical) {
      info[key] = field.value.trim();
    }
  });
  if (isMobileNetworkRow(row)) {
    info.pin = info.pin || "1111";
  }
  info.updatedAt = new Date().toISOString();
  info.updatedBy = currentUser()?.name || state.activeUserName || "TWEM";
  store.updatedAt = info.updatedAt;
  setStoreSaveFeedback(storeId, "Sauvegarde infos SIM en cours...", "pending");
  saveState();
  if (hasRemoteData()) {
    try {
      await syncStoreToRemote(store, "Infos SIM post-installation");
      setStoreSaveFeedback(storeId, "Infos SIM sauvegardees.", "success");
    } catch (error) {
      console.error("Erreur sauvegarde infos SIM", error);
      setStoreSaveFeedback(storeId, "Infos SIM gardees localement, erreur Appwrite.", "error");
    }
  } else {
    setStoreSaveFeedback(storeId, "Infos SIM sauvegardees localement.", "success");
  }
  populateSimInfoPanel(panel, info);
}

function attachStoreInteractiveHandlers() {
  projectTableBody.querySelectorAll(".store-editor-nav").forEach((nav) => {
    nav.addEventListener("click", handleStoreEditorNavClick);
  });

  projectTableBody.querySelectorAll("[data-quantity-bulk-save]").forEach((button) => {
    button.addEventListener("click", handleQuantityBulkSave);
  });

  projectTableBody.querySelectorAll("[data-big-fix-export]").forEach((button) => {
    button.addEventListener("click", handleBigFixExport);
  });

  projectTableBody.querySelectorAll(".big-fix-key-row select").forEach((select) => {
    select.addEventListener("change", () => {
      select.closest(".big-fix-key-row")?.classList.toggle("is-empty", !normalizeImportCell(select.value));
    });
  });

  projectTableBody.querySelectorAll("[data-store-toggle]").forEach((button) => {
    button.addEventListener("click", () => {
      const storeId = Number(button.getAttribute("data-store-toggle"));
      if (state.expandedStoreIds.has(storeId)) {
        state.expandedStoreIds.delete(storeId);
      } else {
        state.expandedStoreIds = new Set([storeId]);
      }
      saveState();
      render();
    });
  });

  projectTableBody.querySelectorAll("[data-sim-toggle]").forEach((button) => {
    button.addEventListener("click", handleSimInfoToggle);
  });

  projectTableBody.querySelectorAll("[data-sim-save]").forEach((button) => {
    button.addEventListener("click", handleSimInfoSave);
  });

  projectTableBody.querySelectorAll("[data-sim-puk2-reveal]").forEach((button) => {
    button.addEventListener("click", handleSimPuk2Reveal);
  });

  projectTableBody.querySelectorAll("[data-remove-appointment]").forEach((button) => {
    button.addEventListener("click", handleRemoveAppointment);
  });

  projectTableBody.querySelectorAll("[data-appointment-mail]").forEach((button) => {
    button.addEventListener("click", handleAppointmentMail);
  });

  projectTableBody.querySelectorAll("[data-appointment-reply]").forEach((button) => {
    button.addEventListener("click", handleAppointmentReply);
  });

  projectTableBody.querySelectorAll("[data-previsit-mail]").forEach((button) => {
    button.addEventListener("click", handlePrevisitMail);
  });

  projectTableBody.querySelectorAll("[data-previsit-reply]").forEach((button) => {
    button.addEventListener("click", handlePrevisitReply);
  });

  projectTableBody.querySelectorAll("[data-big-fix-save]").forEach((button) => {
    button.addEventListener("click", handleBigFixProgrammingSave);
  });

  projectTableBody.querySelectorAll("[data-store-editor]").forEach((form) => {
    form.addEventListener("submit", handleStoreEditorSubmit);
    form.addEventListener("input", (event) => {
      if (event.target.closest('[name="destiny_install_remark"], [name="brico_final_remark"]')) {
        persistClosureDraftFromForm(form);
      }
      markStoreEditorDirty(form.getAttribute("data-store-editor"));
    });
    form.addEventListener("change", (event) => {
      if (event.target.closest('[name="destiny_install_done"], [name="brico_final_mail_status"], [name="lt_switch_status"], [name="destiny_install_remark"], [name="brico_final_remark"]')) {
        persistClosureDraftFromForm(form);
      }
      markStoreEditorDirty(form.getAttribute("data-store-editor"));
    });
    form.addEventListener("focusin", () => {
      markStoreEditorDirty(form.getAttribute("data-store-editor"));
    });
  });

  projectTableBody.querySelectorAll("[data-sav-create]").forEach((button) => {
    button.addEventListener("click", handleSavCreate);
  });

  projectTableBody.querySelectorAll("[data-sav-go-tab], [data-sav-open-ticket]").forEach((button) => {
    button.addEventListener("click", () => {
      const ticketId = button.getAttribute("data-sav-open-ticket") || "";
      const storeId = Number(button.getAttribute("data-sav-store") || button.getAttribute("data-sav-go-tab") || 0);
      const ticket = ticketId ? state.tickets.find((entry) => entry.id === ticketId) : null;
      const store = state.stores.find((entry) => Number(entry.id) === storeId);
      state.activeAdminTab = "sav";
      state.activeSavSubtab = "inbox";
      state.focusedSavTicketId = ticketId;
      state.filters.search = ticket ? "" : normalizeImportCell(store?.code || store?.name || "").toLowerCase();
      if (searchInput) {
        searchInput.value = state.filters.search;
      }
      saveState();
      render();
    });
  });

  projectTableBody.querySelectorAll("[data-appointment-go-tab]").forEach((button) => {
    button.addEventListener("click", () => {
      state.activeAdminTab = "sav";
      state.activeSavSubtab = "appointments";
      state.focusedAppointmentStoreId = Number(button.getAttribute("data-appointment-go-tab") || 0);
      state.filters.search = "";
      if (searchInput) {
        searchInput.value = "";
      }
      saveState();
      render();
    });
  });

  projectTableBody.querySelectorAll("[data-store-quick-action]").forEach((button) => {
    button.addEventListener("click", () => {
      const action = button.getAttribute("data-store-quick-action") || "sav";
      const storeId = Number(button.getAttribute("data-store-quick-id") || 0);
      state.activeAdminTab = "sav";
      state.focusedSavTicketId = "";
      state.filters.search = "";
      if (action === "appointments") {
        state.activeSavSubtab = "appointments";
        state.focusedAppointmentStoreId = storeId;
      } else {
        state.activeSavSubtab = ["sav", "info", "nvmat", "repmat"].includes(action) ? action : "sav";
        state.focusedSavRequestStoreId = storeId;
      }
      if (searchInput) {
        searchInput.value = "";
      }
      saveState();
      render();
    });
  });

  projectTableBody.querySelectorAll("[data-sav-update]").forEach((button) => {
    button.addEventListener("click", handleSavUpdate);
  });

  projectTableBody.querySelectorAll("[data-sav-status-control]").forEach((statusField) => {
    const updateButtonLabel = () => {
      const actions = statusField.closest(".sav-thread-actions");
      const saveButton = actions?.querySelector("[data-sav-update]");
      if (saveButton) {
        saveButton.textContent = statusField.value === "closed"
          ? "Enregistrer et cloturer"
          : "Enregistrer le suivi";
      }
    };
    statusField.addEventListener("change", updateButtonLabel);
    updateButtonLabel();
  });

  projectTableBody.querySelectorAll("[data-sav-dispatch]").forEach((button) => {
    button.addEventListener("click", handleSavDispatch);
  });

  projectTableBody.querySelectorAll("[data-sav-toggle-close]").forEach((button) => {
    button.addEventListener("click", handleSavToggleClose);
  });

  projectTableBody.querySelectorAll("[data-open-config-store]").forEach((button) => {
    button.addEventListener("click", () => {
      const storeId = Number(button.getAttribute("data-open-config-store"));
      state.activeAdminTab = "configuration";
      state.expandedStoreIds = new Set([storeId]);
      saveState();
      render();
      window.location.hash = "#section-configuration";
    });
  });

  projectTableBody.querySelectorAll("[data-store-sim-csv]").forEach((button) => {
    button.addEventListener("click", handleStoreSimCsvDownload);
  });

  projectTableBody.querySelectorAll("[data-plan-upload]").forEach((button) => {
    button.addEventListener("click", handleStorePlanUploadTrigger);
  });

  projectTableBody.querySelectorAll("[data-plan-open]").forEach((button) => {
    button.addEventListener("click", handleStorePlanOpen);
  });

  projectTableBody.querySelectorAll("[data-installation-doc-open]").forEach((button) => {
    button.addEventListener("click", handleInstallationDocumentOpen);
  });

  projectTableBody.querySelectorAll("[data-signed-fnp-upload]").forEach((button) => {
    button.addEventListener("click", handleSignedFnpUploadTrigger);
  });

  projectTableBody.querySelectorAll("[data-signed-fnp-file]").forEach((input) => {
    input.addEventListener("change", handleSignedFnpFileChange);
  });

  projectTableBody.querySelectorAll("[data-signed-fnp-open]").forEach((button) => {
    button.addEventListener("click", handleSignedFnpOpen);
  });

  projectTableBody.querySelectorAll("[data-porting-confirmation-open]").forEach((button) => {
    button.addEventListener("click", handlePortingConfirmationOpen);
  });

  projectTableBody.querySelectorAll("[data-plan-delete]").forEach((button) => {
    button.addEventListener("click", handleStorePlanDelete);
  });

  projectTableBody.querySelectorAll("[data-plan-file]").forEach((input) => {
    input.addEventListener("change", handleStorePlanFileChange);
  });
  projectTableBody.querySelectorAll("[data-previsit-photo-upload]").forEach((button) => {
    button.addEventListener("click", handlePrevisitPhotoUploadTrigger);
  });
  projectTableBody.querySelectorAll("[data-previsit-rack-photo-upload]").forEach((button) => {
    button.addEventListener("click", handlePrevisitRackPhotoUploadTrigger);
  });
  projectTableBody.querySelectorAll("[data-previsit-coverage-photo-upload]").forEach((button) => {
    button.addEventListener("click", handlePrevisitCoveragePhotoUploadTrigger);
  });
  projectTableBody.querySelectorAll('[name^="previsit_mobile_point_checked_"]').forEach((input) => {
    input.addEventListener("change", handleMobileCoveragePointToggle);
  });
  projectTableBody.querySelectorAll("[data-previsit-photo-open]").forEach((button) => {
    button.addEventListener("click", handlePrevisitPhotoOpen);
  });
  projectTableBody.querySelectorAll("[data-previsit-photo-delete]").forEach((button) => {
    button.addEventListener("click", handlePrevisitPhotoDelete);
  });
  projectTableBody.querySelectorAll("[data-previsit-photo-file]").forEach((input) => {
    input.addEventListener("change", handlePrevisitPhotoFileChange);
  });
  projectTableBody.querySelectorAll("[data-previsit-import-trigger]").forEach((button) => {
    button.addEventListener("click", handlePrevisitImportTrigger);
  });
  projectTableBody.querySelectorAll("[data-previsit-import-file]").forEach((input) => {
    input.addEventListener("change", handlePrevisitImportFileChange);
  });
  projectTableBody.querySelectorAll("[data-previsit-finalize-pdf]").forEach((button) => {
    button.addEventListener("click", handlePrevisitFinalizePdf);
  });

  projectTableBody.querySelectorAll("[data-config-prep-tab]").forEach((button) => {
    button.addEventListener("click", () => {
      const form = button.closest(".store-editor");
      const selectedTab = button.getAttribute("data-config-prep-tab");
      if (!form || !selectedTab) {
        return;
      }
      form.querySelectorAll("[data-config-prep-tab]").forEach((tabButton) => {
        const isSelected = tabButton === button;
        tabButton.classList.toggle("is-active", isSelected);
        tabButton.setAttribute("aria-selected", isSelected ? "true" : "false");
      });
      form.querySelectorAll("[data-config-prep-panel]").forEach((panel) => {
        panel.classList.toggle("is-active", panel.getAttribute("data-config-prep-panel") === selectedTab);
      });
    });
  });

  projectTableBody.querySelectorAll("[data-technical-pdf-download]").forEach((button) => {
    button.addEventListener("click", handleTechnicalPdfDownload);
  });

  projectTableBody.querySelectorAll("[data-store-print]").forEach((button) => {
    button.addEventListener("click", handleStorePrint);
  });

  projectTableBody.querySelectorAll("[data-checklist-print]").forEach((button) => {
    button.addEventListener("click", handleChecklistPrint);
  });
}

function renderStoreCards(stores, mode = "stores") {
  stores.forEach((store) => {
    const manager = stepFor(store, "store_manager");
    const installer = stepFor(store, "installer");
    const electrician = stepFor(store, "electrician");
    const appointments = sortedAppointments(store);
    const appointmentSummary = appointments.length
      ? appointments.map((appointment) => `
          <div class="cell-stack">
            <strong>${formatDateTime(appointment.datetime)}</strong>
            <span class="${badgeClass(appointment.status)}">${appointment.status}</span>
            <span class="cell-note">${escapeHtml(peopleLabel(appointment.people))}</span>
          </div>
        `).join("")
      : '<div class="cell-stack"><strong>-</strong><span class="badge badge-planned">A fixer</span><span class="cell-note">-</span></div>';
    const isExpanded = state.expandedStoreIds.has(store.id);

    const heroRow = document.createElement("tr");
    heroRow.className = "expanded-hero-row";
    heroRow.innerHTML = `
      <td colspan="9">
        <div class="details-panel hero-panel">
          ${buildStoreHero(store, manager, installer, electrician, isExpanded, mode)}
        </div>
      </td>
    `;
    projectTableBody.append(heroRow);

    if (isExpanded) {
      const detailRow = document.createElement("tr");
      detailRow.className = "details-row";
        detailRow.innerHTML = `
          <td colspan="9">
            ${buildStoreDetailForm(store, mode)}
        </td>
      `;
      projectTableBody.append(detailRow);
    }
  });

  attachStoreInteractiveHandlers();
}

function isMobileConsultationViewport() {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
    return false;
  }
  return window.matchMedia("(max-width: 700px)").matches
    && window.matchMedia("(pointer: coarse)").matches;
}

function mobileInfoItem(label, value) {
  return `
    <div class="mobile-info-item">
      <span>${escapeUi(label)}</span>
      <strong>${escapeHtml(value || "-")}</strong>
    </div>
  `;
}

function mobileCheckItem(label, value, date = "") {
  const normalized = normalizeImportCell(value || "");
  const done = ["ok", "oui", "termine", "basculee", "fait", "confirme"].includes(normalized.toLowerCase());
  const blocked = ["bloque", "probleme", "ko", "non"].includes(normalized.toLowerCase());
  const statusClass = blocked ? "is-blocked" : done ? "is-ok" : "is-pending";
  return `
    <div class="mobile-check ${statusClass}">
      <div>
        <span>${escapeUi(label)}</span>
        <strong>${escapeHtml(value || "A confirmer")}</strong>
      </div>
      ${date ? `<em>${escapeHtml(date)}</em>` : ""}
    </div>
  `;
}

function buildMobileNetworkSummary(store) {
  const rows = getNetworkConfigRows(store).filter((row) => row.extensionLabel || row.note || row.slotLabel);
  if (!rows.length) {
    return `<div class="empty-state">${escapeUi("Aucun choix extension confirme pour le moment.")}</div>`;
  }
  return `
    <div class="mobile-network-list">
      ${rows.map((row) => `
        <div class="mobile-network-row">
          <span>${escapeUi(extensionDisplayCategoryLabel(row))}</span>
          <strong>${row.extensionLabel ? extensionOptionDisplayHtml(row.extensionLabel, state.language) : escapeUi("A confirmer")}</strong>
          ${row.note ? `<em>${escapeHtml(row.note)}</em>` : ""}
        </div>
      `).join("")}
    </div>
  `;
}

function buildMobileAppointments(store) {
  const appointments = sortedAppointments(store);
  if (!appointments.length) {
    return `<div class="empty-state">${escapeUi("Aucun rendez-vous pour ce magasin.")}</div>`;
  }
  return appointments.slice(0, 4).map((appointment) => `
    <div class="mobile-list-line">
      <strong>${escapeHtml(formatDateTime(appointment.datetime))}</strong>
      <span>${escapeHtml(appointment.status || "-")}</span>
      <em>${escapeHtml(peopleLabel(appointment.people) || "-")}</em>
    </div>
  `).join("");
}

function buildMobileSavSummary(store) {
  const tickets = (state.tickets || []).filter((ticket) =>
    Number(ticket.storeId) === Number(store.id)
    || normalizeImportCell(ticket.storeCode) === normalizeImportCell(store.code)
  );
  const activeTickets = tickets.filter((ticket) => !["closed", "done"].includes(String(ticket.status || "").toLowerCase()));
  if (!activeTickets.length) {
    return `<div class="empty-state">${escapeUi("Aucun ticket SAV pour ce magasin pour le moment.")}</div>`;
  }
  return activeTickets.slice(0, 4).map((ticket) => `
    <div class="mobile-list-line">
      <strong>${escapeHtml(ticket.concern || ticketTargetLabel(ticket) || "SAV")}</strong>
      <span>${escapeHtml(ticketStatusLabel(ticket.status))}</span>
      <em>${escapeHtml(formatDateTime(ticket.createdAt))}</em>
    </div>
  `).join("");
}

function buildMobileStoreDetail(store) {
  const workflow = ensureStoreWorkflowData(store);
  const managerContact = managerContactForStore(store);
  const planFiles = getStorePlanFilesFromWorkflow(workflow);
  return `
    <section class="mobile-store-detail">
      ${migrationProgramNotice(store)}
      <div class="mobile-section">
        <h3>${escapeUi("Infos magasin")}</h3>
        <div class="mobile-info-grid">
          ${mobileInfoItem("Adresse", [store.address, store.city, store.country].filter(Boolean).join(" - "))}
          ${mobileInfoItem("Type", [displayShopTypeValue(store.shopType, ""), store.shopSize || store.shopType2].filter(Boolean).join(" / "))}
          ${mobileInfoItem("Responsable", managerContact.name || store.manager || "-")}
          ${mobileInfoItem("Telephone", managerContact.phone || "-")}
          ${mobileInfoItem("Mail", managerContact.email || "-")}
          ${mobileInfoItem("Mail general magasin", store.generalEmail || "-")}
          ${mobileInfoItem("PO", [store.poHpDesk, store.poPm].filter(Boolean).join(" / "))}
        </div>
      </div>

      <div class="mobile-section">
        <h3>${escapeUi("Configuration reseau")}</h3>
        ${buildMobileNetworkSummary(store)}
      </div>

      <div class="mobile-section">
        <h3>${escapeUi("Pre-visite / preparation")}</h3>
        <div class="mobile-check-grid">
          ${mobileCheckItem("VLAN22", workflow.vlan22Activated === "Oui" ? "OK" : workflow.vlan22Activated, workflow.vlan22Date)}
          ${mobileCheckItem("Cablage", workflow.cablingStatus, workflow.cablingDate)}
          ${mobileCheckItem("Switch", workflow.ltSwitchStatus, workflow.ltSwitchDate || workflow.transferDate)}
          ${mobileCheckItem("Couverture mobile", workflow.mobileCoverage)}
          ${mobileCheckItem("Installation", workflow.destinyInstallDone === "Oui" ? "OK" : "A confirmer", workflow.destinyInstallDate)}
        </div>
      </div>

      <div class="mobile-section">
        <h3>${escapeUi("Rendez-vous")}</h3>
        ${buildMobileAppointments(store)}
      </div>

      <div class="mobile-section">
        <h3>${escapeUi("SAV du magasin")}</h3>
        ${buildMobileSavSummary(store)}
      </div>

      <div class="mobile-section">
        <h3>${escapeUi("Documents / Plan magasin")}</h3>
        ${planFiles.length ? planFiles.slice().reverse().map((plan) => `
          <div class="mobile-document-line">
            <div>
              <strong>${escapeHtml(plan.name || "Document magasin")}</strong>
              <span>${escapeHtml(formatDateTime(plan.updatedAt))}</span>
            </div>
            <button type="button" class="mini-button" data-plan-open="${store.id}" data-plan-doc-id="${escapeHtml(plan.id)}">${escapeUi(planFileKindLabel(plan))}</button>
          </div>
        `).join("") : `<div class="cell-note">${escapeUi("Aucun document importe")}</div>`}
      </div>
    </section>
  `;
}

function renderMobileStoreConsultationRows(stores) {
  const projectTable = document.querySelector(".project-table");
  projectTable?.classList.add("mobile-store-table");
  setMainTableHeaders(["", "", "", "", "", "", "", "", ""]);
  projectTableBody.innerHTML = stores.map((store) => {
    const isExpanded = state.expandedStoreIds.has(store.id);
    return `
      <tr class="mobile-store-row" data-store-row="${store.id}">
        <td colspan="9">
          <article class="mobile-store-card ${isExpanded ? "is-open" : ""}">
            <div class="mobile-store-card-head">
              <div>
                <span>${escapeHtml(store.code || "-")}</span>
                ${storeSituationCapsule(store)}
                <h3>${escapeHtml(store.name || "-")}</h3>
                <p>${escapeHtml([store.city, displayShopTypeValue(store.shopType, "")].filter(Boolean).join(" - ") || "-")}</p>
              </div>
              <span class="${badgeClass(effectiveStoreStatus(store))}">${escapeHtml(statusLabel(effectiveStoreStatus(store)))}</span>
            </div>
            <div class="mobile-store-card-actions">
              <button type="button" class="mini-button" data-store-toggle="${store.id}">${escapeUi(isExpanded ? "Fermer fiche" : "Voir fiche")}</button>
              <button type="button" class="mini-button" data-store-print="${store.id}">${escapeUi("Imprimer")}</button>
            </div>
            ${isExpanded ? buildMobileStoreDetail(store) : ""}
          </article>
        </td>
      </tr>
    `;
  }).join("");
  attachStoreInteractiveHandlers();
}

function renderStoreOverviewRows(stores, mode = "stores") {
  projectTableBody.innerHTML = "";
  const plannedInterventionView = isPlannedInterventionListView();
  const displayStores = mode === "preparation"
    ? stores.slice().sort(compareStoresByInterventionDate)
    : stores;
  const fragment = document.createDocumentFragment();
  displayStores.forEach((store) => {
    try {
    const isExpanded = state.expandedStoreIds.has(store.id);
    const row = document.createElement("tr");
    row.dataset.storeRow = String(store.id);
    const managerContact = managerContactForStore(store);
    if (mode === "stores") {
      const addressBits = [store.address, store.city, store.country].filter(Boolean).join(" - ") || "-";
      const typeAndLicence = [
        displayShopTypeValue(store.shopType),
        store.poLicences ? `Licence ${store.poLicences}` : null
      ].filter(Boolean).join("\n");
      const poBits = [
        store.poHpDesk ? `PO HpDesk ${store.poHpDesk}` : null,
        store.poPm ? `PO PM ${store.poPm}` : null
      ].filter(Boolean).join("\n") || "-";
      row.innerHTML = `
        <td>
          <strong>${escapeHtml(store.code)}</strong>
          ${storeSituationCapsule(store)}
          <div class="cell-note">${escapeHtml(store.shopSize || store.shopType2 || "-")}</div>
          ${store.cnsNumber ? `<div class="cell-note">CNS ${escapeHtml(store.cnsNumber)}</div>` : ""}
        </td>
        <td>
          <strong>${escapeHtml(store.name)}</strong>
          <div class="cell-note">${escapeHtml(addressBits)}</div>
        </td>
        <td>
          ${typeAndLicence.split("\n").map((line, index) => index === 0 ? escapeHtml(line) : `<div class="cell-note">${escapeHtml(line)}</div>`).join("")}
        </td>
        <td>
          ${poBits.split("\n").map((line, index) => index === 0 ? escapeHtml(line) : `<div class="cell-note">${escapeHtml(line)}</div>`).join("")}
        </td>
        <td>
          <strong>${escapeHtml(managerContact.name || "-")}</strong>
          <div class="cell-note">${escapeHtml(managerContact.phone || "-")}</div>
          <div class="cell-note">${escapeHtml(managerContact.email || "-")}</div>
        </td>
        <td>${plannedInterventionView ? escapeHtml(interventionDateLabel(store) || "-") : "&nbsp;"}</td>
        <td><div class="status-badge-stack"><span class="${badgeClass(effectiveStoreStatus(store))}">${escapeHtml(statusLabel(effectiveStoreStatus(store)))}</span>${activePhonePlatformBadge(store)}</div></td>
        <td>${renderStoreValidationSignals(store, { showAll: plannedInterventionView })}</td>
        <td>
          <div class="store-row-actions">
            <button type="button" class="mini-button" data-store-toggle="${store.id}">${escapeUi(isExpanded ? "Fermer fiche" : "Voir fiche")}</button>
            <button type="button" class="mini-button" data-store-print="${store.id}">${escapeUi("Imprimer")}</button>
          </div>
        </td>
      `;
    } else {
      const addressBits = [store.address, store.city, store.country].filter(Boolean).join(" - ") || store.city || "-";
      row.innerHTML = `
        <td>${escapeHtml(store.code)}${store.cnsNumber ? `<div class="cell-note">CNS ${escapeHtml(store.cnsNumber)}</div>` : ""}</td>
        <td>
          <strong>${escapeHtml(store.name)}</strong>
          <div class="cell-note">${escapeHtml(addressBits)}</div>
        </td>
        <td>${escapeHtml(store.city || "-")}</td>
        <td>${escapeHtml(displayShopTypeValue(store.shopType))}</td>
        <td>
          <strong>${escapeHtml(managerContact.name || "-")}</strong>
          <div class="cell-note">${escapeHtml(managerContact.phone || "-")}</div>
          <div class="cell-note">${escapeHtml(managerContact.email || "-")}</div>
        </td>
        <td>${escapeHtml(interventionDateLabel(store) || "-")}</td>
        <td><div class="status-badge-stack"><span class="${badgeClass(effectiveStoreStatus(store))}">${escapeHtml(statusLabel(effectiveStoreStatus(store)))}</span>${activePhonePlatformBadge(store)}</div></td>
        <td>${renderStoreValidationSignals(store, { compact: mode === "configuration" })}</td>
        <td>
          <div class="store-row-actions">
            <button type="button" class="mini-button" data-store-toggle="${store.id}">${escapeUi(isExpanded ? "Fermer fiche" : "Voir fiche")}</button>
            <button type="button" class="mini-button" data-store-print="${store.id}">${escapeUi("Imprimer")}</button>
          </div>
        </td>
      `;
    }
    fragment.append(row);

    if (isExpanded) {
      const detailRow = document.createElement("tr");
      detailRow.className = "details-row";
      detailRow.dataset.storeDetailRow = String(store.id);
      try {
        detailRow.innerHTML = `
          <td colspan="9">
            ${buildStoreDetailForm(store, mode)}
          </td>
        `;
      } catch (error) {
        console.error("Erreur affichage fiche magasin", store.code, error);
        detailRow.innerHTML = `
          <td colspan="9">
            <div class="empty-state">La fiche ${escapeHtml(store.code || "magasin")} n'a pas pu s'ouvrir. La liste des magasins reste disponible.</div>
          </td>
        `;
      }
      fragment.append(detailRow);
    }
    } catch (error) {
      console.error("Erreur affichage ligne magasin", store?.code, error);
      const errorRow = document.createElement("tr");
      errorRow.dataset.storeRow = String(store?.id || "");
      errorRow.innerHTML = `
        <td colspan="9" class="empty-state">
          La ligne ${escapeHtml(store?.code || "magasin")} n'a pas pu s'afficher. Les autres magasins restent disponibles.
        </td>
      `;
      fragment.append(errorRow);
    }
  });
  projectTableBody.append(fragment);
  attachStoreInteractiveHandlers();
  renderMobileCoveragePdfPreviews(projectTableBody);
  setupMobileCoverageImagePreviews(projectTableBody);
}

function addUnifiedStoreSectionRows(groups) {
  groups.forEach((group) => {
    const firstStore = group.items[0];
    const firstRow = projectTableBody.querySelector(`[data-store-row="${CSS.escape(String(firstStore.id))}"]`);
    if (!firstRow) return;
    const sectionRow = document.createElement("tr");
    sectionRow.className = `unified-store-section section-${group.category}`;
    sectionRow.innerHTML = `
      <td colspan="9">
        <strong>${escapeHtml(group.label)}</strong>
        <span>${group.items.length} magasin${group.items.length > 1 ? "s" : ""}</span>
      </td>
    `;
    firstRow.before(sectionRow);
  });
}

function renderUnifiedStoreRows(stores) {
  const groups = groupedUnifiedStores(stores);
  const sortedStores = groups.flatMap((group) => group.items);
  if (isMobileConsultationViewport()) {
    renderMobileStoreConsultationRows(sortedStores);
  } else {
    renderStoreOverviewRows(sortedStores, "stores");
  }
  addUnifiedStoreSectionRows(groups);
}

const MAIN_TABLE_HEADER_IDS = ["thDetail", "thStore", "thTwem", "thManager", "thPhone", "thElectrician", "thAppointment", "thStatus", "thIssue"];

function resetMainTableHeaderStructure() {
  const headerRow = document.querySelector(".project-table thead tr");
  if (!headerRow) return;
  if (MAIN_TABLE_HEADER_IDS.every((id) => document.getElementById(id))) return;
  headerRow.innerHTML = MAIN_TABLE_HEADER_IDS
    .map((id) => `<th id="${id}"></th>`)
    .join("");
}

function setMainTableHeaders(headers) {
  resetMainTableHeaderStructure();
  const ids = MAIN_TABLE_HEADER_IDS;
  ids.forEach((id, index) => {
    const node = document.getElementById(id);
    if (node) {
      node.textContent = headers[index] || "";
    }
  });
}

function setInvoiceTableHeaders() {
  const headerRow = document.querySelector(".project-table thead tr");
  if (!headerRow) return;
  headerRow.innerHTML = `
    <th>N magasin</th>
    <th>Nom magasin</th>
    <th colspan="4">PO</th>
    <th>A facturer</th>
    <th>En remplacement</th>
    <th>Statut cde / livraison</th>
  `;
}

function storeQuickActions() {
  return '<div class="cell-stack"><span class="badge badge-done">Voir</span><span class="badge badge-planned">Relancer</span><span class="badge badge-progress">Valider</span></div>';
}

function nextActionForStore(store) {
  const workflow = ensureStoreWorkflowData(store);
  if (store.status === "blocked") return "Deblocage projet";
  if (!isNetworkConfigurationOk(store)) return "Validation manager config";
  if (!isVlan22Ok(workflow)) return "Validation VLAN22";
  if (workflow.destinyInstallDone !== "Oui") return "Installation Destiny";
  return workflow.ltSwitchStatus === "Basculee" ? "RUN / SAV" : "Bascule plateforme";
}

function currentWorkflowStage(store) {
  const workflow = ensureStoreWorkflowData(store);
  if (store.status === "blocked") return "Blocage chantier";
  if (!isNetworkConfigurationOk(store)) return "Collecte infos";
  if (!isVlan22Ok(workflow)) return "Validation VLAN22";
  if (externalPrepStatusLabel(workflow) !== "Termine") return "Pre-visite";
  if (workflow.destinyInstallDone !== "Oui") return "Installation";
  if (workflow.ltSwitchStatus === "Basculee") return "RUN";
  return "A lancer";
}

function renderCompactStoreRows(stores, mapper) {
  projectTableBody.innerHTML = stores.map((store, index) => {
    const cells = mapper(store, index);
    return `<tr>${cells.map((cell) => `<td>${cell}</td>`).join("")}</tr>`;
  }).join("");
}

function renderTimelineRows(stores) {
  setMainTableHeaders(["Code magasin", "Magasin", "Ville", "Type", "Plateforme actuelle", "Date telephonie", "Etape actuelle", "Date etape", "Statut"].map((label) => ui(label)));
  const sortTimelineStores = (items) => [...items].sort((left, right) => {
    const leftWorkflow = ensureStoreWorkflowData(left);
    const rightWorkflow = ensureStoreWorkflowData(right);
    const leftDate = normalizeDateOnly(leftWorkflow.destinyInstallDate);
    const rightDate = normalizeDateOnly(rightWorkflow.destinyInstallDate);
    if (!leftDate && !rightDate) {
      return String(left.code || "").localeCompare(String(right.code || ""), "fr", { numeric: true });
    }
    if (!leftDate) return 1;
    if (!rightDate) return -1;
    return new Date(leftDate) - new Date(rightDate)
      || String(left.code || "").localeCompare(String(right.code || ""), "fr", { numeric: true });
  });
  const timelineRowHtml = (store) => {
    const workflow = ensureStoreWorkflowData(store);
    const isMigrationStore = normalizeRoleKey(workflow.dstnyDoneClassification || "") === "migration";
    const timelineSteps = [
      {
        date: workflow.currentPhoneDate || "15/03/2021",
        label: "Telephonie actuelle",
        status: workflow.currentPhoneDate ? "done" : "planned",
        note: displayCurrentPhonePlatform(workflow.currentPlatform)
      },
      {
        date: workflow.collectDate || formatDateTime(store.updatedAt).split(" ")[0],
        label: "Collecte",
        status: store.status === "planned" ? "in_progress" : "done",
        note: "Collecte infos magasin"
      },
      {
        date: workflow.vlan22Date || workflow.itValidationDate || "",
        label: "IT",
        status: isVlan22Ok(workflow) ? "done" : (store.status === "blocked" ? "blocked" : "in_progress"),
        note: "Validation reseau / VLAN"
      },
      {
        date: workflow.previsitDate || "A confirmer",
        label: "Pre-visite",
        status: externalPrepStatusLabel(workflow) === "Termine" ? "done" : "planned",
        note: externalPrepStatusLabel(workflow)
      },
      {
        date: workflow.destinyInstallDate || "A confirmer",
        label: "Install",
        status: workflow.destinyInstallDone === "Oui" ? "done" : (store.status === "in_progress" ? "in_progress" : "planned"),
        note: workflow.destinyPmName || "Intervention prevue"
      },
      {
        date: workflow.transferDate || workflow.destinyInstallDate || "A confirmer",
        label: "Transfert",
        status: workflow.ltSwitchStatus === "Basculee" ? "done" : "planned",
        note: displayTargetPhonePlatform(workflow.targetPlatform)
      }
    ];

    return `
      <tr>
        <td colspan="9">
          <article class="timeline-store">
            <div class="timeline-store-head">
              <div>
                <h3>${escapeHtml(store.name)} - ${escapeHtml(store.code)} - ${escapeHtml(store.manager || store.owner || "-")}</h3>
                <div class="timeline-meta">
                  <span>${escapeHtml(store.city)}</span>
                  <span>${escapeHtml(displayShopTypeValue(store.shopType))}</span>
                  <span>${escapeUi("Actuelle")}: ${escapeHtml(displayCurrentPhonePlatform(workflow.currentPlatform))}</span>
                  <span>${escapeUi("Cible")}: ${escapeHtml(displayTargetPhonePlatform(workflow.targetPlatform))}</span>
                </div>
              </div>
              <div class="timeline-status-stack">
                <span class="${badgeClass(effectiveStoreStatus(store))}">${escapeHtml(statusLabel(effectiveStoreStatus(store)))}</span>
                ${activePhonePlatformBadge(store)}
                ${isMigrationStore ? '<span class="badge badge-migration">Migration</span>' : ""}
              </div>
            </div>
            <div class="timeline-strip">
              ${timelineSteps.map((step) => `
                <button type="button" class="timeline-step" data-timeline-open="${store.id}">
                  <div class="timeline-dot ${escapeHtml(step.status)}"></div>
                  <div class="timeline-step-date">${escapeUi(step.date || "A confirmer")}</div>
                  <div class="timeline-step-name">${escapeUi(step.label)}</div>
                  <div class="timeline-step-note">${escapeUi(step.note || "")}</div>
                </button>
              `).join("")}
            </div>
          </article>
        </td>
      </tr>
    `;
  };
  const visibleStores = stores.filter((store) => {
    const classification = normalizeRoleKey(ensureStoreWorkflowData(store).dstnyDoneClassification || "");
    return classification === "migration" || (store.status !== "done" && hasPlannedIntervention(store));
  });
  const regularStores = sortTimelineStores(visibleStores.filter((store) => normalizeRoleKey(ensureStoreWorkflowData(store).dstnyDoneClassification || "") !== "migration"));
  const migrationStores = sortTimelineStores(visibleStores.filter((store) => normalizeRoleKey(ensureStoreWorkflowData(store).dstnyDoneClassification || "") === "migration"));
  const sectionHtml = (title, items) => items.length
    ? `
      <tr class="timeline-section-row"><td colspan="9">${escapeHtml(title)} (${items.length})</td></tr>
      ${items.map(timelineRowHtml).join("")}
    `
    : "";
  const rows = [
    sectionHtml("Magasins", regularStores),
    sectionHtml("Migration", migrationStores)
  ].filter(Boolean).join("") || `<tr><td colspan="9" class="empty-state">${escapeUi("Aucun magasin ne correspond aux filtres.")}</td></tr>`;

  projectTableBody.innerHTML = rows;
  projectTableBody.querySelectorAll("[data-timeline-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const storeId = Number(button.getAttribute("data-timeline-open"));
      openStoreConfigurationById(storeId);
    });
  });
}
function renderDashboardRows(stores) {
  setMainTableHeaders([]);
  projectTableBody.innerHTML = "";
}

function googleDrivePreviewUrl(url = "") {
  const value = String(url || "").trim();
  if (!value) {
    return "";
  }
  const fileMatch = value.match(/drive\.google\.com\/file\/d\/([^/]+)/i);
  const idParamMatch = value.match(/[?&]id=([^&]+)/i);
  const fileId = fileMatch?.[1] || idParamMatch?.[1] || "";
  if (fileId) {
    return `https://drive.google.com/file/d/${encodeURIComponent(fileId)}/preview`;
  }
  return value;
}

function normalizedTutorialVideos(videos = []) {
  const byKey = new Map((videos || []).map((video) => [String(video?.key || ""), video]));
  return defaultTutorialVideos.map((base) => {
    const saved = byKey.get(base.key) || {};
    const savedBucketId = saved.storageBucketId || saved.bucketId || "";
    const baseBucketId = base.storageBucketId || base.bucketId || "";
    const savedFileId = normalizeImportCell(saved.storageFileId || "");
    const baseFileId = normalizeImportCell(base.storageFileId || "");
    const savedRawUrl = normalizeImportCell(saved.url || saved.videoUrl || "");
    const baseRawUrl = normalizeImportCell(base.url || "");
    const savedIsRealTutoStorage = savedBucketId === appwriteTutorialVideosBucketId && savedFileId.startsWith("tuto-video-");
    const savedUrlIsFakeStorage = savedRawUrl.includes("/storage/buckets/")
      && !savedIsRealTutoStorage;
    const savedStorageUrl = saved.storageFileId && savedBucketId ? appwriteStorageFileUrl(saved.storageFileId, "view", savedBucketId) : "";
    const storageUrl = base.storageFileId && baseBucketId ? appwriteStorageFileUrl(base.storageFileId, "view", baseBucketId) : "";
    const savedUrl = savedUrlIsFakeStorage ? "" : savedRawUrl;
    const url = normalizeImportCell(savedStorageUrl || savedUrl || storageUrl || baseRawUrl || "");
    const hasSavedFile = Boolean(savedFileId && (savedIsRealTutoStorage || savedUrl));
    const hasBaseFile = Boolean(base.storageFileId && (baseBucketId || base.url));
    return {
      ...base,
      storageFileId: hasSavedFile ? saved.storageFileId : (hasBaseFile ? base.storageFileId : ""),
      storageBucketId: hasSavedFile ? savedBucketId : (hasBaseFile ? baseBucketId : ""),
      url,
      embedUrl: ""
    };
  });
}

function tutorialVideosHaveUrl(videos = []) {
  return normalizedTutorialVideos(videos).some((video) => Boolean(video.url));
}

function mergeTutorialVideosPreservingUrls(currentVideos = [], incomingVideos = []) {
  const currentByKey = new Map(normalizedTutorialVideos(currentVideos).map((video) => [video.key, video]));
  return normalizedTutorialVideos(incomingVideos).map((incoming) => {
    const current = currentByKey.get(incoming.key) || {};
    const url = incoming.url || current.url || "";
    const storageFileId = incoming.storageFileId || current.storageFileId || "";
    const storageBucketId = incoming.storageBucketId || incoming.bucketId || current.storageBucketId || current.bucketId || "";
    return {
      ...incoming,
      storageFileId,
      storageBucketId,
      url,
      disabled: Boolean(incoming.disabled || current.disabled),
      embedUrl: ""
    };
  });

}

function selectTutorialVideosSettingsItem(toolItems = []) {
  const tutorialItems = (toolItems || []).filter((item) =>
    item?.id === tutorialVideosSettingsItemId || item?.kind === "tutorial_videos"
  );
  return tutorialItems.find((item) => tutorialVideosHaveUrl(item?.videos || [])) || tutorialItems[0] || null;
}

function normalizedTechnicalSheets(sheets = []) {
  const seen = new Set();
  const sourceSheets = [
    ...(Array.isArray(sheets) ? sheets : []),
    ...defaultTechnicalSheets
  ];
  return sourceSheets
    .map((sheet, index) => ({
      id: String(sheet?.id || `sheet-${Date.now()}-${index}`),
      title: normalizeImportCell(sheet?.title || ""),
      tag: normalizeImportCell(sheet?.tag || ""),
      summary: normalizeImportCell(sheet?.summary || ""),
      body: String(sheet?.body || sheet?.content || "").trim(),
      note: String(sheet?.note || "").trim(),
      url: normalizeImportCell(sheet?.url || sheet?.fileUrl || sheet?.href || ""),
      fileName: normalizeImportCell(sheet?.fileName || sheet?.attachmentName || ""),
      fileType: normalizeImportCell(sheet?.fileType || sheet?.contentType || ""),
      fileStorageFileId: normalizeImportCell(sheet?.fileStorageFileId || sheet?.storageFileId || ""),
      fileStorageBucketId: normalizeImportCell(sheet?.fileStorageBucketId || sheet?.storageBucketId || ""),
      videoUrl: normalizeImportCell(sheet?.videoUrl || sheet?.tutorialVideoUrl || ""),
      videoStorageFileId: normalizeImportCell(sheet?.videoStorageFileId || ""),
      videoStorageBucketId: normalizeImportCell(sheet?.videoStorageBucketId || ""),
      includeInInstallFollowup: Boolean(sheet?.includeInInstallFollowup || sheet?.installFollowup || sheet?.includeInJ3Mail),
      disabled: Boolean(sheet?.disabled || sheet?.inactive || sheet?.archived),
      updatedAt: sheet?.updatedAt || new Date().toISOString()
    }))
    .filter((sheet) => {
      if ((!sheet.title && !sheet.body) || seen.has(sheet.id)) {
        return false;
      }
      seen.add(sheet.id);
      return true;
    })
    .sort((left, right) =>
      normalizeImportCell(left.title || "").localeCompare(
        normalizeImportCell(right.title || ""),
        "fr",
        { sensitivity: "base" }
      )
    );
}

function technicalSheetDocumentId(sheetOrId) {
  const rawId = typeof sheetOrId === "object" ? sheetOrId?.id : sheetOrId;
  return safeDocumentId("technical-sheet", rawId || Date.now());
}

