function technicalSheetTranslation(sheet) {
  if (normalizeLanguageCode(state.language) !== "nl") {
    return null;
  }
  const title = normalizeSearchText(sheet?.title || "");
  if (nlTechnicalSheetTranslations[title]) return nlTechnicalSheetTranslations[title];
  if (title.includes("hammer")) return nlTechnicalSheetTranslations["telephone hammer 6 lte / telepo"];
  if (title.includes("appel") && title.includes("groupe")) return nlTechnicalSheetTranslations["appel groupe"];
  if (title.includes("cascade")) return nlTechnicalSheetTranslations.cascade;
  if (title.includes("panic")) return nlTechnicalSheetTranslations["panic button"];
  if (title.includes("call") && title.includes("button")) return nlTechnicalSheetTranslations["call button"];
  if (title.includes("flashlight")) return nlTechnicalSheetTranslations["flashlight button"];
  if (title.includes("transfert") || title.includes("transfer")) return nlTechnicalSheetTranslations["transfert d'appel"];
  if (title.includes("regle") && title.includes("telephonie")) return nlTechnicalSheetTranslations["regle importante telephonie"];
  return null;
}

function technicalSheetDisplayValue(sheet, field) {
  const translated = technicalSheetTranslation(sheet);
  return translated?.[field] ?? tutoDisplayText(sheet?.[field] || "");
}

function isDirectVideoUrl(url = "") {
  const value = normalizeImportCell(url).toLowerCase();
  return Boolean(value)
    && (
      /\/storage\/buckets\/[^/]+\/files\/[^/]+\/(view|download)/i.test(value)
      || /\.(mp4|webm|mov|m4v)(?:[?#].*)?$/i.test(value)
    );
}

function renderTutorialVideoMedia(video) {
  if (!video.url) {
    return `
      <div class="tuto-video-placeholder">
        <span>${escapeTuto("Video a ajouter")}</span>
      </div>
    `;
  }
  const safeUrl = escapeHtml(video.url);
  if (/drive\.google\.com/i.test(video.url)) {
    return `
      <iframe class="tuto-video-player" src="${escapeHtml(googleDrivePreviewUrl(video.url))}" allow="autoplay; fullscreen" allowfullscreen loading="lazy"></iframe>
    `;
  }
  if (isDirectVideoUrl(video.url)) {
    return `
      <video class="tuto-video-player" controls preload="metadata" playsinline>
        <source src="${safeUrl}">
        ${escapeTuto("Votre navigateur ne sait pas lire cette video.")}
      </video>
    `;
  }
  return `
    <div class="tuto-video-placeholder is-ready">
      <span>${escapeTuto("Video disponible")}</span>
    </div>
  `;
}

function buildAppointmentsSummaryCard(store) {
  const appointments = sortedAppointments(store);
  const rows = appointments.length
    ? appointments.map((appointment) => `
        <button type="button" class="appointment-summary-row" data-appointment-go-tab="${store.id}" data-appointment-focus="${escapeHtml(appointment.id || "")}">
          <span class="appointment-summary-ref">${escapeHtml(appointment.status || "Propose")}</span>
          <span class="appointment-summary-main">
            <strong>${escapeHtml(formatDateTime(appointment.datetime) || "-")}</strong>
            <small>${escapeHtml(appointment.note || "Rendez-vous")}</small>
          </span>
          <span class="${badgeClass(appointment.status)}">${escapeHtml(appointment.status || "Propose")}</span>
        </button>
      `).join("")
    : `<div class="empty-state">${escapeUi("Aucun rendez-vous pour ce magasin.")}</div>`;
  return `
    <article class="appointments-card full-span-card" data-access-zone="appointments">
      <div class="sav-store-summary-head">
        <div>
          <h3>${escapeUi("Rendez-vous du magasin")}</h3>
          <p>${escapeUi("Une ligne par rendez-vous. La creation et les modifications se font dans l onglet SAV / Tickets.")}</p>
        </div>
        <button type="button" class="mini-button" data-appointment-go-tab="${store.id}">${escapeUi("Gerer les rendez-vous")}</button>
      </div>
      <div class="sav-store-summary-list">
        ${rows}
      </div>
    </article>
  `;
}

function renderTechnicalSheetVideoMedia(sheet) {
  const video = { url: normalizeImportCell(sheet?.videoUrl || "") };
  return `
    <div class="technical-sheet-video-media">
      ${renderTutorialVideoMedia(video)}
      ${video.url ? `<a class="tuto-video-link" href="${escapeHtml(video.url)}" target="_blank" rel="noreferrer">${escapeTuto("Regarder la video")}</a>` : ""}
    </div>
  `;
}

function renderTutoVideoIndicator(hasVideo) {
  return hasVideo ? `<span class="tuto-camera-indicator" title="${escapeTuto("Video disponible")}">VIDEO</span>` : "";
}

function renderInstallFollowupIndicator(enabled) {
  return enabled ? `<span class="tuto-camera-indicator" title="${escapeTuto("Ajoute au mail J+3 apres installation")}">J+3</span>` : "";
}

function compareTutoEntriesByTitle(left, right) {
  return normalizeImportCell(left?.title || "").localeCompare(
    normalizeImportCell(right?.title || ""),
    "fr",
    { sensitivity: "base" }
  );
}

function renderTutorialVideoAccordion(video, canEditVideos) {
  const isDisabled = Boolean(video.disabled);
  return `
    <details class="tuto-accordion-card ${isDisabled ? "is-disabled" : ""}">
      <summary>
        <span>
          <strong>${escapeHtml(tutorialVideoDisplayValue(video, "title"))}</strong>
          <small>${escapeHtml(tutorialVideoDisplayValue(video, "description"))}</small>
        </span>
        ${renderTutoVideoIndicator(Boolean(video.url))}
      </summary>
      <div class="tuto-accordion-body">
        ${renderTutorialVideoMedia(video)}
        <h4>${escapeHtml(tutorialVideoDisplayValue(video, "title"))}</h4>
        <p>${escapeHtml(tutorialVideoDisplayValue(video, "description"))}</p>
        ${video.url ? `<a class="tuto-video-link" href="${escapeHtml(video.url)}" target="_blank" rel="noreferrer">${escapeTuto("Regarder la video")}</a>` : ""}
        ${canEditVideos ? `
          <form class="tuto-video-form" data-tutorial-key="${escapeHtml(video.key)}">
            <input type="url" name="tutorial_url" value="${escapeHtml(video.url || "")}" placeholder="${escapeTuto("Coller le lien video Appwrite / Drive")}">
            <button type="submit" class="mini-button">${escapeTuto("Enregistrer")}</button>
          </form>
          <div class="tuto-video-upload">
            <input type="file" class="hidden-file-input" data-tuto-video-file="${escapeHtml(video.key)}" accept="video/*,.mp4,.webm,.mov,.m4v">
            <button type="button" class="mini-button" data-tuto-video-upload="${escapeHtml(video.key)}">${escapeTuto("Envoyer video")}</button>
          </div>
          <div class="technical-sheet-card-actions">
            <button type="button" class="mini-button" data-tuto-video-disable="${escapeHtml(video.key)}" data-disabled="${isDisabled ? "false" : "true"}">${escapeTuto(isDisabled ? "Reactiver" : "Desactiver")}</button>
          </div>
        ` : ""}
      </div>
    </details>
  `;
}

