async function handleTutorialVideoSubmit(event) {
  event.preventDefault();
  if (!isAdminTwem()) {
    return;
  }
  const form = event.currentTarget;
  const key = form.getAttribute("data-tutorial-key");
  const url = form.querySelector('[name="tutorial_url"]')?.value.trim() || "";
  state.tutorialVideos = normalizedTutorialVideos(state.tutorialVideos).map((video) =>
    video.key === key ? { ...video, url, embedUrl: "" } : video
  );
  saveState();
  renderTutorialRows();
  if (hasRemoteData()) {
    try {
      await syncSettingsToRemote();
    } catch (error) {
      console.error("Impossible de synchroniser la video tuto.", error);
      window.alert("Lien video sauvegarde localement, mais la synchronisation distante a echoue.");
    }
  }
}

function handleTutorialVideoUploadTrigger(event) {
  const key = event.currentTarget.getAttribute("data-tuto-video-upload") || "";
  const input = projectTableBody.querySelector(`[data-tuto-video-file="${CSS.escape(key)}"]`);
  if (!input) {
    window.alert("Le champ d'envoi video n'est pas disponible. Recharge l'onglet TUTO.");
    return;
  }
  input.value = "";
  input.click();
}

async function handleTutorialVideoFileChange(event) {
  const input = event.currentTarget;
  const key = input.getAttribute("data-tuto-video-file") || "";
  const file = input.files?.[0];
  if (!key || !file) {
    return;
  }
  if (!isAdminTwem()) {
    input.value = "";
    return;
  }
  if (!hasRemoteData() || !appwriteStorage || !appwriteTutorialVideosBucketId) {
    window.alert("Storage Appwrite indisponible pour l'envoi de la video.");
    input.value = "";
    return;
  }
  try {
    const fileId = safeDocumentId("tuto-video", `${key}-${Date.now()}`);
    await createAppwriteStorageFile(appwriteTutorialVideosBucketId, fileId, file, ['read("any")']);
    const url = appwriteStorageFileUrl(fileId, "view", appwriteTutorialVideosBucketId);
    state.tutorialVideos = normalizedTutorialVideos(state.tutorialVideos).map((video) =>
      video.key === key ? { ...video, url, embedUrl: "", storageFileId: fileId, storageBucketId: appwriteTutorialVideosBucketId } : video
    );
    saveState();
    await syncSettingsToRemote();
    renderTutorialRows();
    window.alert("Video envoyee et lien TUTO mis a jour.");
  } catch (error) {
    console.error("Impossible d'envoyer la video tuto.", error);
    if (isAppwriteFileExtensionDenied(error)) {
      window.alert("Le Storage Appwrite refuse encore les fichiers video sur ce bucket. Mets la video dans un bucket Appwrite qui autorise mp4/webm/mov, puis colle son lien ici avec Enregistrer.");
    } else {
      window.alert(`Impossible d'envoyer la video pour le moment. ${syncErrorLabel(error)}`);
    }
  } finally {
    input.value = "";
  }
}

async function syncTechnicalSheetsAfterEdit(options = {}) {
  state.technicalSheets = normalizedTechnicalSheets(state.technicalSheets || []);
  saveState();
  renderTutorialRows();
  if (hasRemoteData()) {
    try {
      if (options.deletedId) {
        await deleteTechnicalSheetFromRemote(options.deletedId);
      }
      if (options.sheet) {
        await syncTechnicalSheetToRemote(options.sheet);
      }
    } catch (error) {
      console.error("Impossible de synchroniser les fiches techniques.", error);
      window.alert("Fiche sauvegardee localement, mais la synchronisation distante a echoue.");
    }
  }
}

async function handleTechnicalSheetSubmit(event) {
  event.preventDefault();
  if (!isAdminTwem()) {
    return;
  }
  const form = event.currentTarget;
  const editId = form.getAttribute("data-technical-sheet-edit") || "";
  const previousSheet = normalizedTechnicalSheets(state.technicalSheets || []).find((sheet) => sheet.id === editId) || null;
  const nextSheet = {
    id: editId || `sheet-${Date.now()}`,
    title: form.querySelector('[name="technical_title"]')?.value.trim() || "",
    tag: form.querySelector('[name="technical_tag"]')?.value.trim() || "",
    summary: form.querySelector('[name="technical_summary"]')?.value.trim() || "",
    body: form.querySelector('[name="technical_body"]')?.value.trim() || "",
    note: form.querySelector('[name="technical_note"]')?.value.trim() || "",
    url: form.querySelector('[name="technical_url"]')?.value.trim() || previousSheet?.url || "",
    fileName: previousSheet?.fileName || "",
    fileType: previousSheet?.fileType || "",
    fileStorageFileId: previousSheet?.fileStorageFileId || "",
    fileStorageBucketId: previousSheet?.fileStorageBucketId || "",
    videoUrl: previousSheet?.videoUrl || "",
    videoStorageFileId: previousSheet?.videoStorageFileId || "",
    videoStorageBucketId: previousSheet?.videoStorageBucketId || "",
    includeInInstallFollowup: Boolean(form.querySelector('[name="technical_install_followup"]')?.checked),
    disabled: previousSheet?.disabled || false,
    updatedAt: new Date().toISOString()
  };
  if (!nextSheet.title || !nextSheet.body) {
    window.alert("Indique au minimum un titre et le texte de la fiche.");
    return;
  }
  const sheets = normalizedTechnicalSheets(state.technicalSheets || []);
  state.technicalSheets = editId
    ? sheets.map((sheet) => (sheet.id === editId ? nextSheet : sheet))
    : [nextSheet, ...sheets];
  state.technicalSheetEditId = "";
  await syncTechnicalSheetsAfterEdit({ sheet: nextSheet });
}

function handleTechnicalSheetEdit(event) {
  state.technicalSheetEditId = event.currentTarget.getAttribute("data-technical-edit") || "";
  renderTutorialRows();
}

async function handleTechnicalSheetDelete(event) {
  const id = event.currentTarget.getAttribute("data-technical-delete") || "";
  if (!id || !window.confirm("Supprimer cette fiche technique ?")) {
    return;
  }
  state.technicalSheets = normalizedTechnicalSheets(state.technicalSheets || []).filter((sheet) => sheet.id !== id);
  if (state.technicalSheetEditId === id) {
    state.technicalSheetEditId = "";
  }
  await syncTechnicalSheetsAfterEdit({ deletedId: id });
}

function handleTechnicalSheetCancel() {
  state.technicalSheetEditId = "";
  renderTutorialRows();
}

async function updateTechnicalSheetVideo(sheetId, videoPatch) {
  const sheets = normalizedTechnicalSheets(state.technicalSheets || []);
  const targetSheet = sheets.find((sheet) => sheet.id === sheetId);
  if (!targetSheet) {
    window.alert("Fiche TUTO introuvable. Recharge l'onglet TUTO.");
    return;
  }
  const updatedSheet = {
    ...targetSheet,
    ...videoPatch,
    updatedAt: new Date().toISOString()
  };
  state.technicalSheets = sheets.map((sheet) => (sheet.id === sheetId ? updatedSheet : sheet));
  await syncTechnicalSheetsAfterEdit({ sheet: updatedSheet });
}

async function updateTechnicalSheetFile(sheetId, filePatch) {
  const sheets = normalizedTechnicalSheets(state.technicalSheets || []);
  const targetSheet = sheets.find((sheet) => sheet.id === sheetId);
  if (!targetSheet) {
    window.alert("Fiche TUTO introuvable. Recharge l'onglet TUTO.");
    return;
  }
  const updatedSheet = {
    ...targetSheet,
    ...filePatch,
    updatedAt: new Date().toISOString()
  };
  state.technicalSheets = sheets.map((sheet) => (sheet.id === sheetId ? updatedSheet : sheet));
  await syncTechnicalSheetsAfterEdit({ sheet: updatedSheet });
}

