async function handleTechnicalSheetFileChange(event) {
  const input = event.currentTarget;
  const sheetId = input.getAttribute("data-technical-file-file") || "";
  const file = input.files?.[0];
  if (!sheetId || !file) {
    return;
  }
  if (!isAdminTwem()) {
    input.value = "";
    return;
  }
  const allowed = /^(image\/|application\/pdf$)/i.test(file.type || "") || /\.(png|jpe?g|webp|pdf)$/i.test(file.name || "");
  if (!allowed) {
    window.alert("Utilise une image ou un PDF pour la fiche visuelle.");
    input.value = "";
    return;
  }
  if (!hasRemoteData() || !appwriteStorage || !appwritePlansBucketId) {
    window.alert("Storage Appwrite indisponible pour l'envoi de la fiche.");
    input.value = "";
    return;
  }
  try {
    const fileId = safeDocumentId("technical-sheet", `${sheetId}-${Date.now()}`);
    await createAppwriteStorageFile(appwritePlansBucketId, fileId, file, ['read("any")']);
    const url = appwriteStorageFileUrl(fileId, "view", appwritePlansBucketId);
    await updateTechnicalSheetFile(sheetId, {
      url,
      fileName: file.name || "fiche-visuelle",
      fileType: file.type || "application/octet-stream",
      fileStorageFileId: fileId,
      fileStorageBucketId: appwritePlansBucketId
    });
    window.alert("Fiche envoyee et lien TUTO mis a jour.");
  } catch (error) {
    console.error("Impossible d'envoyer la fiche visuelle.", error);
    if (isAppwriteFileExtensionDenied(error)) {
      window.alert("Le Storage Appwrite refuse ce type de fichier. Utilise PNG/JPG/WebP/PDF ou colle un lien.");
    } else {
      window.alert(`Impossible d'envoyer la fiche pour le moment. ${syncErrorLabel(error)}`);
    }
  } finally {
    input.value = "";
  }
}

