      `<span class="cell-note">${escapeHtml(store.health || "-")}</span>`,
      goNoGo ? '<span class="badge badge-done">GO</span>' : '<span class="badge badge-blocked">NO GO</span>',
      escapeHtml(nextActionForStore(store))
