function renderSavRows() {
  setMainTableHeaders([escapeUi("SAV / demandes"), "", "", "", "", "", "", "", ""]);
  const activeTab = savRequestConfigByKey(state.activeSavSubtab || "inbox");
  const filteredTickets = filteredTicketsBySavSubtab();
  const scopedStoreIds = new Set(getRoleScopedStores().map((store) => String(store.id)));
  const focusedTicket = state.focusedSavTicketId
    ? filteredTickets.find((ticket) => ticket.id === state.focusedSavTicketId)
      || (state.tickets || []).find((ticket) => ticket.id === state.focusedSavTicketId && scopedStoreIds.has(String(ticket.storeId)))
      || null
    : null;
  const focusedStore = focusedTicket
    ? state.stores.find((store) => String(store.id) === String(focusedTicket.storeId)) || { id: focusedTicket.storeId, code: focusedTicket.storeCode, name: focusedTicket.storeName }
    : null;
  projectTableBody.innerHTML = `
    <tr>
      <td colspan="9">
        <article class="sav-workspace">
          <div class="sav-subtabs">
            ${savRequestTabs.map((tab) => `<button type="button" class="sav-subtab ${tab.key === activeTab.key ? "is-active" : ""}" data-sav-subtab="${escapeHtml(tab.key)}">${escapeHtml(tab.label)}</button>`).join("")}
          </div>
          ${focusedTicket && focusedStore ? `
            <section class="sav-focused-ticket" data-store-editor="${focusedStore.id}">
              <div class="sav-focused-head">
                <strong>${escapeHtml("Dossier ouvert")}</strong>
                <button type="button" class="mini-button" data-sav-close-focused>${escapeUi("Refermer le dossier")}</button>
              </div>
              ${buildTicketThread(focusedStore, focusedTicket)}
            </section>
          ` : ""}
          ${activeTab.key === "inbox"
      ? renderSavInboxTable(filteredTickets)
      : activeTab.key === "appointments"
        ? renderAppointmentsWorkspacePanel()
        : renderSavRequestFormPanel(activeTab)}
        </article>
      </td>
    </tr>
  `;

  projectTableBody.querySelectorAll("[data-sav-subtab]").forEach((button) => {
    button.addEventListener("click", () => {
      state.activeSavSubtab = button.getAttribute("data-sav-subtab") || "inbox";
      state.focusedSavTicketId = "";
      saveState();
      renderStores();
    });
  });

  projectTableBody.querySelector("[data-sav-close-focused]")?.addEventListener("click", () => {
    state.focusedSavTicketId = "";
    saveState();
    renderStores();
  });

  projectTableBody.querySelectorAll("[data-sav-standalone-form]").forEach((form) => {
    const storeSelect = form.querySelector('[name="sav_store_id"]');
    const preview = form.querySelector('[name="sav_reference_preview"]');
    const updatePreview = () => {
      const store = state.stores.find((item) => String(item.id) === String(storeSelect?.value || ""));
      preview.value = store ? savBaseReference(store, activeTab) : "";
    };
    storeSelect?.addEventListener("change", updatePreview);
    form.querySelector("[data-sav-standalone-create]")?.addEventListener("click", handleSavCreate);
  });

  projectTableBody.querySelector("[data-appointment-store-select]")?.addEventListener("change", (event) => {
    state.focusedAppointmentStoreId = Number(event.currentTarget.value || 0);
    saveState();
    renderStores();
  });

  projectTableBody.querySelectorAll("[data-appointment-standalone-save]").forEach((button) => {
    button.addEventListener("click", handleAppointmentStandaloneSave);
  });

  projectTableBody.querySelectorAll("[data-sav-open-store]").forEach((button) => {
    button.addEventListener("click", () => {
      state.focusedSavTicketId = button.getAttribute("data-sav-focus-ticket") || "";
      state.activeAdminTab = "sav";
      state.activeSavSubtab = "inbox";
      state.filters.search = "";
      if (searchInput) {
        searchInput.value = "";
      }
      saveState();
      renderStores();
    });
  });

  projectTableBody.querySelectorAll("[data-sav-row-apply]").forEach((button) => {
    button.addEventListener("click", handleSavRowStatusUpdate);
  });
  attachStoreInteractiveHandlers();
}

