const ticketStatusOptions = [
  { value: "new", label: "Nouveau TWEM" },
  { value: "dispatch", label: "A dispatcher" },
  { value: "assigned", label: "Assigne" },
  { value: "open", label: "Ouvert" },
  { value: "in_progress", label: "En cours" },
  { value: "waiting", label: "En attente" },
  { value: "resolved", label: "Resolu" },
  { value: "closed", label: "Cloture" }
];

function ticketStatusLabel(status, language = state.language) {
  const isNl = normalizeLanguageCode(language) === "nl";
  const labels = isNl
    ? {
        new: "Nieuw TWEM",
        dispatch: "Te dispatchen",
        assigned: "Toegewezen",
        open: "Open",
        in_progress: "Bezig",
        waiting: "In afwachting",
        resolved: "Opgelost",
        closed: "Afgesloten"
      }
    : {
        new: "Nouveau TWEM",
        dispatch: "A dispatcher",
        assigned: "Assigne",
        open: "Ouvert",
        in_progress: "En cours",
        waiting: "En attente",
        resolved: "Resolu",
        closed: "Cloture"
      };
  return labels[status] || status;
}

function ticketBadgeClass(status) {
  const map = {
    new: "badge badge-planned",
    dispatch: "badge badge-planned",
    assigned: "badge badge-progress",
    open: "badge badge-planned",
    in_progress: "badge badge-progress",
    waiting: "badge badge-warning",
    resolved: "badge badge-done",
    closed: "badge badge-done"
  };
  return map[status] || "badge badge-planned";
}

function savRequestConfigByKey(key = "") {
  return savRequestTabs.find((tab) => tab.key === key) || savRequestTabs[0];
}

function savRequestConfigForTicket(ticket = {}) {
  const kind = normalizeImportCell(ticket.requestKind || "").toLowerCase();
  const id = normalizeImportCell(ticket.id || "").toUpperCase();
  if (kind.includes("info") || id.includes("-INFO")) return savRequestConfigByKey("info");
  if (kind.includes("supplementaire") || kind.includes("nouveau") || id.includes("-NVMAT")) return savRequestConfigByKey("nvmat");
  if (kind.includes("casse") || kind.includes("remplacement") || id.includes("-REMPMAT")) return savRequestConfigByKey("repmat");
  return savRequestConfigByKey("sav");
}

function savStoreReference(store = {}) {
  const rawCode = normalizeImportCell(store.shopNumber || store.code || "");
  const digitMatch = rawCode.match(/\d+/g);
  return digitMatch ? digitMatch.join("") : rawCode.replace(/^BRI[-\s]*/i, "") || rawCode || "MAG";
}

function savBaseReference(store = {}, config = savRequestConfigByKey("sav")) {
  return `BR-${savStoreReference(store)}-${config.suffix || "SAV"}`;
}

function savTicketDisplayReference(ticket = {}) {
  const store = state.stores.find((item) => String(item.id) === String(ticket.storeId))
    || state.stores.find((item) => item.code === ticket.storeCode)
    || { code: ticket.storeCode, shopNumber: ticket.shopNumber };
  const config = savRequestConfigForTicket(ticket);
  return ticket.reference || savBaseReference(store, config);
}

function filteredTicketsBySavSubtab() {
  const currentTab = savRequestConfigByKey(state.activeSavSubtab || "inbox");
  const tickets = getFilteredTickets()
    .slice()
    .sort((a, b) => {
      const rankDifference = savTicketDisplayRank(a) - savTicketDisplayRank(b);
      if (rankDifference) {
        return rankDifference;
      }
      const aDate = Date.parse(a.updatedAt || a.dispatchedAt || a.closedAt || a.createdAt || "") || 0;
      const bDate = Date.parse(b.updatedAt || b.dispatchedAt || b.closedAt || b.createdAt || "") || 0;
      return bDate - aDate;
    });
  if (currentTab.key === "inbox") {
    return tickets;
  }
  return tickets.filter((ticket) => savRequestConfigForTicket(ticket).key === currentTab.key);
}

function savTicketDisplayRank(ticket = {}) {
  const status = String(ticket.status || "").toLowerCase();
  if (status === "closed") {
    return 3;
  }
  if (["in_progress", "waiting", "resolved"].includes(status)) {
    return 2;
  }
  const isAssigned = status === "assigned"
    || ticket.dispatchStatus === "assigned"
    || ticketTargetPeople(ticket).length > 0;
  return isAssigned ? 1 : 0;
}

function ticketsForStore(storeId) {
  return (state.tickets || [])
    .filter(Boolean)
    .filter((ticket) => String(ticket.storeId) === String(storeId))
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
}

async function handleAddExtensionSubmit(event) {
  event.preventDefault();
  if (!canEditExtensionCatalog()) return;
  const form = event.currentTarget;
  const submitButton = form.querySelector('button[type="submit"]');
  const category = normalizeImportCell(form.querySelector('[name="category"]')?.value);
  const number = normalizeImportCell(form.querySelector('[name="number"]')?.value);
  const labelFr = normalizeImportCell(form.querySelector('[name="label_fr"]')?.value);
  const labelNl = normalizeImportCell(form.querySelector('[name="label_nl"]')?.value);
  const labelEn = normalizeImportCell(form.querySelector('[name="label_en"]')?.value);
  if (!category || !number) {
    window.alert("La categorie et le numero sont obligatoires.");
    return;
  }
  if (extensionCatalogRows.some((row) => normalizeExtensionNumber(row.number) === normalizeExtensionNumber(number))) {
    window.alert(`L'extension ${number} existe deja dans le catalogue.`);
    return;
  }
  const nextRows = [
    ...extensionCatalogRows,
    publicExtensionCatalogRow({ category, number, labelFr, labelNl, labelEn }, extensionCatalogRows.length)
  ];
  if (submitButton) {
    submitButton.disabled = true;
    submitButton.textContent = "Enregistrement...";
  }
  if (hasRemoteData()) {
    try {
      await syncExtensionCatalogToRemote(nextRows);
      extensionCatalogRows.splice(0, extensionCatalogRows.length, ...nextRows);
      saveState();
      refreshRemoteSyncShadow();
    } catch (error) {
      console.error("Impossible de synchroniser l extension ajoutee.", error);
      window.alert("Extension non ajoutee : la synchronisation Appwrite a echoue. Rien n'a ete garde seulement en local.");
      if (submitButton) {
        submitButton.disabled = false;
        submitButton.textContent = "Ajouter extension";
      }
      return;
    }
  } else {
    extensionCatalogRows.splice(0, extensionCatalogRows.length, ...nextRows);
    saveState();
  }
  render();
}

