function buildTicketThread(store, ticket) {
  const updates = [...(ticket.updates || [])].sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
  const outgoingMails = outgoingMailActivitiesForTicket(ticket);
  const selectedTargets = ticketTargetPeople(ticket);
  const isDispatcher = canDispatchSav();
  const currentName = normalizeImportCell(currentUser()?.name || state.activeUserName).toLowerCase();
  const canWorkOnTicket = isDispatcher
    || selectedTargets.some((name) => normalizeImportCell(name).toLowerCase() === currentName);
  const dispatchBlock = isDispatcher ? `
    <div class="sav-dispatch-box">
      <div class="sav-thread-label">Dispatch TWEM</div>
      <div class="sav-people-grid">
        ${renderSavDispatchCheckboxes(store, selectedTargets, `ticket_dispatch_people_${ticket.id}`)}
      </div>
      <label>
        <span>Message de transfert</span>
        <textarea name="ticket_dispatch_note_${ticket.id}" rows="3" placeholder="Explique ce qui est attendu avant de transferer le SAV."></textarea>
      </label>
      <span class="validation-text" data-sav-dispatch-feedback="${escapeHtml(ticket.id)}"></span>
      <button type="button" class="mini-button" data-sav-dispatch="${ticket.id}" data-sav-store="${store.id}">Transferer / assigner</button>
    </div>
  ` : "";
  const contextRows = [
    ticket.requestKind ? `<div><strong>Type</strong> ${escapeHtml(ticket.requestKind)}</div>` : "",
    `<div><strong>Assignation</strong> ${escapeHtml(ticketTargetLabel(ticket))}</div>`,
    ticket.materialLabel ? `<div><strong>Materiel</strong> ${escapeHtml(ticket.materialLabel)}</div>` : "",
    ticket.extensionLabel ? `<div><strong>Extension</strong> ${escapeHtml(ticket.extensionLabel)}</div>` : "",
    ticket.quantityRequested ? `<div><strong>Quantite</strong> ${escapeHtml(String(ticket.quantityRequested))}</div>` : "",
    ticket.orderWorkflowStatus ? `<div><strong>Workflow</strong> ${escapeHtml(ticket.orderWorkflowStatus)}</div>` : ""
  ].filter(Boolean).join("");
  const isClosed = ticket.status === "closed";
  return `
    <details class="sav-thread-card ${isClosed ? "is-closed" : "is-open"}" ${isClosed ? "" : "open"}>
      <summary class="sav-thread-head">
        <div>
          <strong>${escapeHtml(ticket.id)} - ${escapeHtml(ticket.concern || "Sans objet")}</strong>
          <div class="cell-note">Demande initiale par ${escapeHtml(ticket.requesterName || "-")} le ${escapeHtml(formatDateTime(ticket.createdAt))} - ${escapeHtml(ticketTargetLabel(ticket))}</div>
        </div>
        <span class="${ticketBadgeClass(ticket.status)}">${escapeHtml(ticketStatusLabel(ticket.status))}</span>
      </summary>

      <div class="sav-thread-body">
        <div class="sav-thread-request">
          <div class="sav-thread-label">Demande initiale</div>
          ${contextRows ? `<div class="sav-thread-context">${contextRows}</div>` : ""}
          <div class="sav-thread-box">${escapeHtml(ticket.initialNote || "-")}</div>
        </div>

        <div class="sav-thread-updates">
          <div class="sav-thread-label">Historique de traitement</div>
          ${updates.length ? updates.map((update) => `
            <div class="sav-update-item">
              <div class="sav-update-meta">${escapeHtml(update.authorName || "-")} - ${escapeHtml(formatDateTime(update.createdAt))}</div>
              <div class="sav-thread-box">${escapeHtml(update.note || "-")}</div>
            </div>
          `).join("") : '<div class="empty-state sav-empty">Aucun suivi ajoute pour le moment.</div>'}
        </div>

        ${renderOutgoingMailLog(outgoingMails, "Mails SAV envoyes")}

        ${dispatchBlock}

        <div class="sav-thread-actions">
          ${canWorkOnTicket ? `
            <label class="sav-thread-note">
              <span>Nouveau suivi</span>
              <textarea name="ticket_update_note_${ticket.id}" rows="3" placeholder="Ajoute ici le suivi, la reponse, la correction ou l etat d avancement"></textarea>
            </label>
            <div class="sav-thread-control">
              <label>
                <span>Statut du ticket</span>
                <select name="ticket_status_${ticket.id}" data-sav-status-control>
                  ${renderOptions(ticketStatusOptions, ticket.status)}
                </select>
              </label>
              <div class="sav-thread-buttons">
                <span class="validation-text" data-sav-update-feedback="${escapeHtml(ticket.id)}"></span>
                <button type="button" class="mini-button" data-sav-update="${ticket.id}" data-sav-store="${store.id}">Enregistrer le suivi</button>
              </div>
            </div>
          ` : '<div class="empty-state sav-empty">En attente du dispatch TWEM avant intervention.</div>'}
        </div>
      </div>
    </details>
  `;
}

const quantityBulkFields = [
  { key: "licenseCount", label: "Licences" },
  { key: "fixCount", label: "Postes fixes" },
  { key: "fixBigCount", label: "Fix big" },
  { key: "mobileCount", label: "Mobiles" },
  { key: "flashLightCount", label: "Flashlights" },
  { key: "callButtonCount", label: "Call buttons" },
  { key: "panicCount", label: "Panic buttons" }
];

function sortStoresForQuantityBulk(stores) {
  return stores.slice().sort((a, b) => {
    const regionOrder = storeLanguageForPrint(a) === "nl" ? 0 : 1;
    const otherRegionOrder = storeLanguageForPrint(b) === "nl" ? 0 : 1;
    if (regionOrder !== otherRegionOrder) {
      return regionOrder - otherRegionOrder;
    }
    const shopTypeOrder = quantityBulkShopTypeOrder(a);
    const otherShopTypeOrder = quantityBulkShopTypeOrder(b);
    if (shopTypeOrder !== otherShopTypeOrder) {
      return shopTypeOrder - otherShopTypeOrder;
    }
    return normalizeImportStoreCode(a.code).localeCompare(normalizeImportStoreCode(b.code), "fr", { numeric: true });
  });
}

function quantityBulkShopTypeOrder(store) {
  const order = { DOS: 0, FOSDOS: 1, FOS: 2 };
  return order[normalizeShopTypeValue(store.shopType || "")] ?? 9;
}

function quantityBulkShopTypeLabel(store) {
  return shopTypeLabel(normalizeShopTypeValue(store.shopType || "") || "TO_DEFINE");
}

function renderQuantityBulkShopTypeGroups(stores, rowHtml) {
  const groups = stores.reduce((accumulator, store) => {
    const label = quantityBulkShopTypeLabel(store);
    if (!accumulator.has(label)) {
      accumulator.set(label, []);
    }
    accumulator.get(label).push(store);
    return accumulator;
  }, new Map());

  return [...groups.entries()].map(([label, groupStores]) => `
    <tr class="quantity-bulk-subhead">
      <td colspan="${quantityBulkFields.length + 2}">
        <strong>${escapeHtml(label)}</strong>
        <span>${groupStores.length} magasin(s)</span>
      </td>
    </tr>
    ${groupStores.map(rowHtml).join("")}
  `).join("");
}

function renderQuantityBulkRows(stores, target = projectTableBody, { embedded = false } = {}) {
  if (!target) {
    return;
  }
  target.innerHTML = "";
  if (!canUseQuantityBulk()) {
    target.innerHTML = embedded
      ? '<div class="empty-state">Cet outil est reserve a Emir et Valou.</div>'
      : '<tr><td colspan="9" class="empty-state">Cet outil est reserve a Emir et Valou.</td></tr>';
    return;
  }

  const sortedStores = sortStoresForQuantityBulk(stores);
  const regionSections = [
    { title: "Region flamande", stores: sortedStores.filter((store) => storeLanguageForPrint(store) === "nl") },
    { title: "Region francophone", stores: sortedStores.filter((store) => storeLanguageForPrint(store) !== "nl") }
  ].filter((section) => section.stores.length);

  const rowHtml = (store) => {
    const quantityPlan = getStoreQuantityPlan(store);
    return `
      <tr data-quantity-row="${escapeHtml(String(store.id))}">
        <td class="bulk-store-code">${escapeHtml(store.code || "-")}</td>
        <td class="bulk-store-name">
          <strong>${escapeHtml(store.name || "-")}</strong>
          <span>${escapeHtml([store.city, displayShopTypeValue(store.shopType, "")].filter(Boolean).join(" - ") || "-")}</span>
        </td>
        ${quantityBulkFields.map((field) => `
          <td>
            <input class="bulk-quantity-input" type="number" min="0" step="1" data-quantity-field="${field.key}" value="${escapeHtml(String(quantityPlan[field.key] || 0))}">
          </td>
        `).join("")}
      </tr>
    `;
  };

  const sectionsHtml = regionSections.map((section) => `
    <section class="quantity-bulk-section">
      <div class="quantity-bulk-section-head">
        <h3>${escapeHtml(section.title)}</h3>
        <span>${section.stores.length} magasin(s)</span>
      </div>
      <div class="quantity-bulk-scroll">
        <table class="quantity-bulk-table">
          <thead>
            <tr>
              <th>Code</th>
              <th>Magasin</th>
              ${quantityBulkFields.map((field) => `<th>${escapeHtml(field.label)}</th>`).join("")}
            </tr>
          </thead>
          <tbody>
            ${renderQuantityBulkShopTypeGroups(section.stores, rowHtml)}
          </tbody>
        </table>
      </div>
    </section>
  `).join("");

  const panelHtml = `
    <div class="quantity-bulk-panel" data-quantity-bulk-root>
          <div class="quantity-bulk-actions">
            <div>
              <h3>Edition massive des quantites</h3>
              <p>Modifie uniquement les quantites necessaires, puis sauvegarde. Les lignes reseau sont recalculees sans effacer les choix deja encodes.</p>
            </div>
            <button type="button" class="secondary-button" data-quantity-bulk-save>Sauvegarder les quantites modifiees</button>
          </div>
          <div class="validation-text" data-quantity-bulk-feedback></div>
          ${sectionsHtml}
    </div>
  `;
  target.innerHTML = embedded
    ? panelHtml
    : `<tr><td colspan="9">${panelHtml}</td></tr>`;
  target.querySelectorAll("[data-quantity-bulk-save]").forEach((button) => {
    button.addEventListener("click", handleQuantityBulkSave);
  });
}

const quantityReportFields = [
  { key: "licenseCount", label: "Licences" },
  { key: "fixCount", label: "Postes fixes" },
  { key: "fixBigCount", label: "Big fix" },
  { key: "mobileCount", label: "Mobiles" },
  { key: "flashLightCount", label: "Flashlight" },
  { key: "callButtonCount", label: "Call buttons" },
  { key: "panicCount", label: "Panic button" }
];
const quantityReportDisplayFields = quantityReportFields.filter((field) => field.key !== "panicCount");

const quantityReportGroupOrder = ["DOS", "FOS", "FOSDOS", "TO_DEFINE"];

function quantityReportGroupKey(store) {
  const type = normalizeShopTypeValue(store.shopType || "");
  return type && type !== "TO_DEFINE" ? type : "TO_DEFINE";
}

function quantityReportGroupLabel(groupKey) {
  return groupKey === "TO_DEFINE" ? "A definir" : groupKey;
}

function quantityReportStoreSort(left, right) {
  const leftGroup = quantityReportGroupOrder.indexOf(quantityReportGroupKey(left));
  const rightGroup = quantityReportGroupOrder.indexOf(quantityReportGroupKey(right));
  if (leftGroup !== rightGroup) {
    return leftGroup - rightGroup;
  }
  return normalizeImportStoreCode(left.code).localeCompare(normalizeImportStoreCode(right.code), "fr", { numeric: true });
}

function buildQuantityReportGroups(stores = getRoleScopedStores()) {
  const groups = quantityReportGroupOrder.map((key) => ({
    key,
    label: quantityReportGroupLabel(key),
    stores: [],
    totals: Object.fromEntries(quantityReportFields.map((field) => [field.key, 0])),
    vocovo: { Oui: 0, Futur: 0, Non: 0 }
  }));
  const groupsByKey = new Map(groups.map((group) => [group.key, group]));

  stores
    .slice()
    .sort(quantityReportStoreSort)
    .forEach((store) => {
      const key = quantityReportGroupKey(store);
      const group = groupsByKey.get(key) || groupsByKey.get("TO_DEFINE");
      const plan = getStoreQuantityPlan(store);
      const vocovoStatus = normalizeVocovoStatus(ensureStoreWorkflowData(store).callButtonsVocovo);
      group.stores.push({ store, plan, vocovoStatus });
      quantityReportFields.forEach((field) => {
        group.totals[field.key] += Number(plan[field.key] || 0);
      });
      group.vocovo[vocovoStatus] = (group.vocovo[vocovoStatus] || 0) + 1;
    });

  return groups;
}

function quantityReportVocovoTotalLabel(vocovo = {}) {
  return `Oui: ${vocovo.Oui || 0} / Futur: ${vocovo.Futur || 0} / Non: ${vocovo.Non || 0}`;
}

function renderQuantityReport() {
  if (!quantityReportTable) {
    return;
  }
  const groups = buildQuantityReportGroups();
  const totalStores = groups.reduce((sum, group) => sum + group.stores.length, 0);
  if (!totalStores) {
    quantityReportTable.innerHTML = '<div class="empty-state">Aucun magasin disponible pour ce rapport.</div>';
    return;
  }

  quantityReportTable.innerHTML = `
    <div class="quantity-report-scroll">
      <table>
        <thead>
          <tr>
            <th>Categorie</th>
            <th>N magasin</th>
            <th>Nom magasin</th>
            ${quantityReportDisplayFields.map((field) => `<th>${escapeHtml(field.label)}</th>`).join("")}
            <th>Vocovo</th>
            <th>Panic button</th>
          </tr>
        </thead>
        <tbody>
          ${groups.map((group) => `
            <tr class="quantity-report-total">
              <td>${escapeHtml(group.label)}</td>
              <td>Total</td>
              <td>${group.stores.length} magasin(s)</td>
              ${quantityReportDisplayFields.map((field) => `<td>${group.totals[field.key]}</td>`).join("")}
              <td>${escapeHtml(quantityReportVocovoTotalLabel(group.vocovo))}</td>
              <td>${group.totals.panicCount}</td>
            </tr>
            ${group.stores.map(({ store, plan, vocovoStatus }) => `
              <tr>
                <td>${escapeHtml(group.label)}</td>
                <td class="bulk-store-code">${escapeHtml(store.code || "-")}</td>
                <td>
                  <strong>${escapeHtml(store.name || "-")}</strong>
                  <span class="cell-note">${escapeHtml(store.city || "-")}</span>
                </td>
                ${quantityReportDisplayFields.map((field) => `<td>${Number(plan[field.key] || 0)}</td>`).join("")}
                <td>${escapeHtml(vocovoStatus)}</td>
                <td>${Number(plan.panicCount || 0)}</td>
              </tr>
            `).join("")}
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

async function handleQuantityBulkSave(event) {
  if (!canUseQuantityBulk()) {
    return;
  }
  const container = event?.currentTarget?.closest("[data-quantity-bulk-root]") || projectTableBody;
  const feedback = container.querySelector("[data-quantity-bulk-feedback]");
  const rows = [...container.querySelectorAll("[data-quantity-row]")];
  const changedStores = [];

  rows.forEach((row) => {
    const storeId = row.getAttribute("data-quantity-row");
    const store = state.stores.find((entry) => String(entry.id) === storeId);
    if (!store) {
      return;
    }
    const currentPlan = getStoreQuantityPlan(store);
    let changed = false;
    quantityBulkFields.forEach((field) => {
      const input = row.querySelector(`[data-quantity-field="${field.key}"]`);
      const nextValue = Math.max(0, Number(input?.value || 0) || 0);
      if (nextValue !== currentPlan[field.key]) {
        store[field.key] = nextValue;
        changed = true;
      }
    });
    if (changed) {
      store.updatedAt = new Date().toISOString();
      reconcileNetworkRowsWithQuantities(store);
      reconcileGsmRowsWithQuantities(store);
      changedStores.push(store);
    }
  });

  if (!changedStores.length) {
    if (feedback) {
      feedback.textContent = "Aucune quantite modifiee.";
    }
    return;
  }

  if (feedback) {
    feedback.textContent = `Sauvegarde de ${changedStores.length} magasin(s)...`;
  }
  saveState();

  const failedStores = [];
  for (const store of changedStores) {
    try {
      await syncStoreToRemote(store, "");
    } catch (error) {
      console.error("Erreur sync quantites magasin", store.code, error);
      failedStores.push(store.code || store.name);
    }
  }

  saveState();
  if (feedback) {
    feedback.textContent = failedStores.length
      ? `Sauvegarde locale OK, mais sync Appwrite echouee pour: ${failedStores.join(", ")}.`
      : `${changedStores.length} magasin(s) sauvegarde(s).`;
  }
  renderStores();
}

function renderStores() {
  const stores = getFilteredStores();
  const unifiedStoresView = activeMainWorkspaceTab() === "stores";
  const invoiceView = activeMainWorkspaceTab() === "invoice";
  storeCategoryTools?.classList.toggle("hidden-panel", !unifiedStoresView);
  invoiceExportXlsxButton?.classList.toggle("hidden-panel", !invoiceView);
  if (storeCategoryFilter) {
    storeCategoryFilter.value = state.storeCategoryFilter || "all";
  }
  if (unifiedStoresView && printCurrentListButton) {
    printCurrentListButton.textContent = state.storeCategoryFilter === "all"
      ? "Imprimer les listes par catégorie"
      : "Imprimer cette catégorie";
  }
  projectTableBody.innerHTML = "";
  const projectTable = document.querySelector(".project-table");
  projectTable?.classList.remove("compact-rows-table");
  projectTable?.classList.remove("store-list-table");
  projectTable?.classList.remove("dashboard-summary-only");
  projectTable?.classList.remove("tuto-table");
  projectTable?.classList.remove("mobile-store-table");

  if (!stores.length) {
    projectTableBody.innerHTML = `<tr><td colspan="9" class="empty-state">${escapeUi("Aucun magasin ne correspond aux filtres.")}</td></tr>`;
    return;
  }

  switch (activeMainWorkspaceTab()) {
    case "timeline":
      projectTable?.classList.add("compact-rows-table");
      renderTimelineRows(stores);
      return;
    case "sav":
      projectTable?.classList.add("compact-rows-table");
      renderSavRows(stores);
      return;
    case "extensions":
      projectTable?.classList.add("compact-rows-table");
      renderExtensionsRowsV2(stores);
      return;
    case "invoice":
      projectTable?.classList.add("compact-rows-table");
      renderInvoiceRows(stores);
      return;
    case "tuto":
      projectTable?.classList.add("tuto-table");
      renderTutorialRows();
      return;
    case "dashboard":
      projectTable?.classList.add("dashboard-summary-only");
      renderDashboardRows(stores);
      return;
    case "configuration":
      projectTable?.classList.add("compact-rows-table");
      setMainTableHeaders(["Code", "Magasin", "Ville", "Type", "Responsable", "Intervention", "Statut", "Validations", "Actions"].map((label) => ui(label)));
      renderStoreOverviewRows(stores, "configuration");
      return;
    case "migration":
      projectTable?.classList.add("compact-rows-table");
      projectTable?.classList.add("store-list-table");
      if (isMobileConsultationViewport()) {
        renderMobileStoreConsultationRows(stores);
        return;
      }
      setMainTableHeaders(isPlannedInterventionListView()
        ? ["Code", "Magasin", "Type / licence", "PO / PM", "Responsable / tel", "Intervention", "Statut", "Validations manquantes", "Actions"].map((label) => ui(label))
        : ["Code", "Magasin", "Type / licence", "PO / PM", "Responsable / tel", "", "Statut", "Prochaine action", "Actions"].map((label) => ui(label)));
      renderStoreOverviewRows(stores, "stores");
      return;
    case "quantity-bulk":
      projectTable?.classList.add("compact-rows-table");
      setMainTableHeaders([ui("Quantites magasins"), "", "", "", "", "", "", "", ""]);
      renderQuantityBulkRows(stores);
      return;
    case "preparation":
      projectTable?.classList.add("compact-rows-table");
      setMainTableHeaders(["Code", "Magasin", "Ville", "Type", "Responsable", "Intervention", "Statut", "Validations", "Actions"].map((label) => ui(label)));
      renderStoreOverviewRows(stores, "preparation");
      return;
      case "stores":
      default:
        projectTable?.classList.add("compact-rows-table");
        projectTable?.classList.add("store-list-table");
        setMainTableHeaders(isPlannedInterventionListView()
          ? ["Code", "Magasin", "Type / licence", "PO / PM", "Responsable / tel", "Intervention", "Statut", "Validations manquantes", "Actions"].map((label) => ui(label))
          : ["Code", "Magasin", "Type / licence", "PO / PM", "Responsable / tel", "", "Statut", "Prochaine action", "Actions"].map((label) => ui(label)));
        renderUnifiedStoreRows(stores);
  }
}

let renderStoresTimer = null;
let renderStoresFrame = null;

function scheduleRenderStores(delay = 0) {
  if (renderStoresTimer) {
    window.clearTimeout(renderStoresTimer);
    renderStoresTimer = null;
  }
  if (renderStoresFrame) {
    window.cancelAnimationFrame(renderStoresFrame);
    renderStoresFrame = null;
  }
  const run = () => {
    renderStoresFrame = window.requestAnimationFrame(() => {
      renderStoresFrame = null;
      renderStores();
    });
  };
  if (delay > 0) {
    renderStoresTimer = window.setTimeout(() => {
      renderStoresTimer = null;
      run();
    }, delay);
    return;
  }
  run();
}

function renderActivities() {
  if (activityList) {
    activityList.innerHTML = "";
  }
  reportArchiveList.innerHTML = "";
  const storesByName = new Map(state.stores.map((store) => [normalizeImportCell(store.name).toLowerCase(), store]));
  const groupsByStore = new Map();
  visibleActivitiesForUser().forEach((activity) => {
    const store = storesByName.get(normalizeImportCell(activity.storeName).toLowerCase());
    const key = store?.code || normalizeImportCell(activity.storeName).toLowerCase();
    if (!groupsByStore.has(key)) {
      groupsByStore.set(key, {
        key,
        store,
        storeName: store?.name || activity.storeName || "Magasin",
        entries: []
      });
    }
    groupsByStore.get(key).entries.push(activity);
  });
  const groupedByStore = [...groupsByStore.values()]
    .map((group) => ({
      ...group,
      entries: group.entries.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    }))
    .sort((a, b) => new Date(b.entries[0]?.createdAt || 0) - new Date(a.entries[0]?.createdAt || 0));

  if (!groupedByStore.length) {
    reportArchiveList.innerHTML = '<div class="empty-state">Aucun rapport magasin disponible pour le moment.</div>';
    return;
  }

  groupedByStore.forEach((group) => {
    const details = document.createElement("details");
    const latestEntry = group.entries[0];
    details.className = `report-store ${latestEntry?.alertQueuedAt || isSameLocalDay(new Date(latestEntry?.createdAt || 0), new Date()) ? "has-new-update" : ""}`;
    details.innerHTML = `
      <summary>
        <span class="report-store-title">${escapeHtml(group.store?.code ? `${group.store.code} - ${group.storeName}` : group.storeName)}</span>
        <span class="report-store-meta">${group.entries.length} remontee(s)</span>
        <span class="report-store-latest">${escapeHtml(formatDateTime(latestEntry?.createdAt || ""))}</span>
        <button type="button" class="mini-button report-export-button" data-report-export="${escapeHtml(group.key)}">Exporter PDF</button>
      </summary>
      <div class="report-store-body">
        ${group.entries.map((entry) => `
          <article class="report-entry">
            <div class="report-entry-meta">
              <span class="${badgeClass(entry.result)}">${entry.result === "issue" ? "Probleme" : "OK"}</span>
              <span>${escapeHtml(formatDateTime(entry.createdAt))}</span>
            </div>
            <div class="report-entry-author">${escapeHtml(entry.confirmedBy)}</div>
            <div class="report-entry-text">${escapeHtml(entry.comment)}</div>
          </article>
        `).join("")}
      </div>
    `;
    reportArchiveList.append(details);
  });

  reportArchiveList.querySelectorAll("[data-report-export]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const storeKey = button.getAttribute("data-report-export");
      const group = groupedByStore.find((entry) => entry.key === storeKey);
      if (group) {
        exportStoreReportPdf(group);
      }
    });
  });
}

function automationCategoryLabel(category) {
  const isNl = state.language === "nl";
  const labels = {
    notifications: isNl ? "Notificaties" : "Notifications",
    access: isNl ? "Toegang" : "Acces utilisateurs",
    followup: isNl ? "Herinneringen / escalaties" : "Relances / escalades"
  };
  return labels[category] || category;
}

const automationEmailStatusOptions = [
  { value: "draft", label: "Brouillon" },
  { value: "ready", label: "A envoyer" },
  { value: "blocked", label: "Bloque premiere connexion" },
  { value: "sent", label: "Deja envoye" },
  { value: "error", label: "Erreur" }
];

function automationEmailStatusLabel(status) {
  return automationEmailStatusOptions.find((option) => option.value === status)?.label || status || "Brouillon";
}

function selectableAutomationEmailStatusOptions(email = {}) {
  return automationEmailStatusOptions.filter((option) => option.value !== "sent" || email.status === "sent");
}

function automationEmailStatusClass(status) {
  const normalized = status || "draft";
  if (normalized === "ready") return "automation-email-status status-ready";
  if (normalized === "sent") return "automation-email-status status-sent";
  if (normalized === "blocked") return "automation-email-status status-blocked";
  if (normalized === "error") return "automation-email-status status-error";
  return "automation-email-status status-draft";
}

function automationEmailStatusHelp(status) {
  const labels = {
    ready: "La fonction Appwrite peut envoyer ce mail au prochain passage.",
    sent: "Journal uniquement: ce statut indique que le mail est deja parti.",
    draft: "Brouillon: la fonction ne l'envoie pas.",
    blocked: "Bloque tant que la premiere connexion PIN n'est pas faite.",
    error: "Erreur d'envoi: repasser a A envoyer apres correction."
  };
  return labels[status] || "";
}

function personRecipientValue(person = {}) {
  return normalizeImportCell(person.email) || normalizeImportCell(person.name);
}

function launchMailEligiblePeople() {
  return (state.people || [])
    .filter((person) =>
      normalizeImportCell(person.email)
      && normalizePin(person.pin).length === 6
      && !["disabled", "expired"].includes(String(person.pinStatus || "").toLowerCase())
    );
}

function personMatchesStoreType(person, targetType) {
  const types = storesForPersonAccess(person).map((store) => normalizeShopTypeValue(store.shopType)).filter(Boolean);
  if (targetType === "FOS-FOSDOS") {
    return types.some((type) => type === "FOS" || type === "FOSDOS");
  }
  return types.includes(targetType);
}

function launchMailRecipientsFromForm(form) {
  if (!form) {
    return [];
  }
  const mode = form.querySelector('[name="launch_recipient_mode"]')?.value || "storeType";
  const storeType = form.querySelector('[name="launch_store_type"]')?.value || "DOS";
  const role = form.querySelector('[name="launch_role"]')?.value || "";
  const personId = form.querySelector('[name="launch_person"]')?.value || "";
  const seen = new Set();
  return launchMailEligiblePeople()
    .filter((person) => {
      if (mode === "storeType") {
        return personMatchesStoreType(person, storeType);
      }
      if (mode === "role") {
        return String(person.role || "") === role;
      }
      if (mode === "person") {
        return String(person.id || "") === personId;
      }
      return false;
    })
    .filter((person) => {
      const email = normalizeImportCell(person.email).toLowerCase();
      if (!email || seen.has(email)) {
        return false;
      }
      seen.add(email);
      return true;
    })
    .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "fr", { sensitivity: "base" }));
}

function digestNameKey(value = "") {
  return normalizeImportCell(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/gi, "")
    .toLowerCase();
}

function digestPersonHaystack(person = {}) {
  return digestNameKey([person.name, person.email, person.role].filter(Boolean).join(" "));
}

function digestPersonMatchesRecipient(person = {}, recipient = {}) {
  const haystack = digestPersonHaystack(person);
  const excluded = (recipient.exclude || []).some((value) => haystack.includes(digestNameKey(value)));
  if (!haystack || excluded) {
    return false;
  }
  if (recipient.email && normalizeImportCell(person.email).toLowerCase() === recipient.email.toLowerCase()) {
    return true;
  }
  return (recipient.aliases || [recipient.label]).some((alias) => haystack.includes(digestNameKey(alias)));
}

function digestFallbackPerson(recipient = {}) {
  return {
    id: recipient.email || recipient.label,
    name: recipient.label,
    email: recipient.email || ""
  };
}

function digestBasePeople() {
  return forcedDigestRecipients
    .map((recipient) =>
      (state.people || []).find((person) => digestPersonMatchesRecipient(person, recipient))
      || digestFallbackPerson(recipient)
    )
    .filter(Boolean);
}

function digestAdditionalPeople(automation = {}) {
  const ids = Array.isArray(automation.digestAdditionalRecipientIds) ? automation.digestAdditionalRecipientIds : [];
  return ids
    .map((id) => (state.people || []).find((person) =>
      String(person.id || "") === String(id)
      || String(person.email || "") === String(id)
      || String(person.name || "") === String(id)
    ))
    .filter(Boolean);
}

function digestRecipientPeople(automation = {}) {
  const seen = new Set();
  return [...digestBasePeople(), ...digestAdditionalPeople(automation)].filter((person) => {
    const key = personRecipientValue(person).toLowerCase();
    if (!key || seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function digestRecipientLabel(automation = {}) {
  const recipients = digestRecipientPeople(automation)
    .map((person) => personRecipientValue(person) || person.name)
    .filter(Boolean);
  return recipients.join(", ") || "Groupe pilotage force";
}

function digestRecipientSummaryHtml(automation = {}) {
  const people = digestRecipientPeople(automation);
  if (!people.length) {
    return '<span class="digest-recipient-chip">Groupe pilotage force</span>';
  }
  return people.map((person) => `
    <span class="digest-recipient-chip">
      <strong>${escapeHtml(person.name || "-")}</strong>
      ${person.email ? `<small>${escapeHtml(person.email)}</small>` : ""}
    </span>
  `).join("");
}

function renderDigestRecipientChoices(automation = {}) {
  const selectedIds = new Set(Array.isArray(automation.digestAdditionalRecipientIds) ? automation.digestAdditionalRecipientIds.map(String) : []);
  return (state.people || [])
    .filter((person) =>
      normalizeImportCell(person.name)
      && !forcedDigestRecipients.some((recipient) => digestPersonMatchesRecipient(person, recipient))
    )
    .sort((left, right) => normalizeImportCell(left.name).localeCompare(normalizeImportCell(right.name), "fr", { sensitivity: "base" }))
    .map((person) => {
      const id = String(person.id || person.email || person.name);
      const label = [person.name, person.email].filter(Boolean).join(" - ");
      return `
        <label class="digest-recipient-choice">
          <input type="checkbox" value="${escapeHtml(id)}" data-automation-id="${escapeHtml(automation.id)}" data-automation-field="digestAdditionalRecipientIds" ${selectedIds.has(id) ? "checked" : ""}>
          <span>${escapeHtml(label)}</span>
        </label>
      `;
    })
    .join("");
}

function nextMorningIso(hour = 9) {
  const date = new Date();
  date.setDate(date.getDate() + 1);
  date.setHours(hour, 0, 0, 0);
  return date.toISOString();
}

function emailDateLabel(value, language = "fr") {
  const date = normalizeDateOnly(value);
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    return "";
  }
  return new Intl.DateTimeFormat(normalizeLanguageCode(language) === "nl" ? "nl-BE" : "fr-BE", {
    weekday: "long",
    day: "2-digit",
    month: "long",
    year: "numeric"
  }).format(date);
}

