function buildInstallReminderEmail(store, automation = {}, options = {}) {
  const workflow = ensureStoreWorkflowData(store);
  const managerPerson = managerPersonForStore(store);
  const managerContact = managerContactForStore(store);
  const language = storeLanguageForPrint(store);
  const managerName = managerPerson?.name || managerContact?.name || store.manager || store.name || (language === "nl" ? "verantwoordelijke" : "responsable");
  const installDate = emailDateLabel(workflow.destinyInstallDate, language) || workflow.destinyInstallDate || "";
  const isKnownNotice = options.phase === "known";
  const subject = language === "nl"
    ? `${isKnownNotice ? "Installatie gepland" : "Herinnering installatie"} - ${store.name || store.code || "winkel"}`
    : `${isKnownNotice ? "Installation planifiee" : "Rappel installation"} - ${store.name || store.code || "magasin"}`;
  const body = language === "nl"
    ? [
        `Hallo ${managerName},`,
        "",
        `Wij bevestigen de komst van ons team voor de installatie van uw nieuwe telefooncentrale op ${installDate}.`,
        "",
        "Alles is gepland zodat de interventie in de best mogelijke omstandigheden kan verlopen.",
        "U kunt de opvolging raadplegen via de applicatie.",
        "",
        appAccessLink(),
        "",
        "Alvast bedankt voor uw ontvangst en samenwerking.",
        "",
        "Met vriendelijke groeten,"
      ].join("\n")
    : [
        `Bonjour ${managerName},`,
        "",
        `Nous vous confirmons le passage de notre equipe pour l'installation de votre nouvelle centrale telephonique a la date du ${installDate}.`,
        "",
        "Tout est planifie afin que l'intervention se deroule dans les meilleures conditions possibles.",
        "Vous pouvez suivre le dossier via l'application.",
        "",
        appAccessLink(),
        "",
        "Nous vous remercions d'avance pour votre accueil et votre collaboration.",
        "",
        "Bien a vous,"
      ].join("\n");
  const values = {
    managerName,
    contactName: managerName,
    installDate,
    storeName: store.name || "",
    storeCode: store.code || "",
    appLink: appAccessLink()
  };
  const templateBody = automation.emailBodyManual && automation.emailBody
    ? automation.emailBody
    : body;
  const recipient = normalizeImportCell(managerPerson?.email || managerContact?.email || store.email || "");

  return {
    subject: fillMailTemplate(automation.emailSubject || subject, values),
    body: fillMailTemplate(templateBody, values),
    recipient,
    language,
    status: recipient ? "" : "blocked",
    blockedReason: recipient ? "" : "Aucune adresse mail manager trouvee pour ce magasin."
  };
}

function buildNetworkConfigReminderEmail(store, automation = {}, context = {}) {
  const workflow = ensureStoreWorkflowData(store);
  const managerContact = managerContactForStore(store);
  const language = storeLanguageForPrint(store);
  const installDate = emailDateLabel(workflow.destinyInstallDate, language) || workflow.destinyInstallDate || "";
  const recipient = normalizeImportCell(managerContact?.email || store?.email || "");
  const subject = language === "nl"
    ? "Configuratie van uw telefonie - Actie vereist vóór de installatie"
    : "Configuration de votre téléphonie - Action requise avant l'installation";
  const body = language === "nl"
    ? [
        "Hallo,",
        "",
        `Met het oog op uw komende installatie voorzien op ${installDate} hebben wij vastgesteld dat de configuratie van uw telefonie nog niet werd ingevuld in de applicatie.`,
        "Om de installatie vlot te laten verlopen, willen wij u vriendelijk vragen deze configuratie zo snel mogelijk aan te vullen.",
        "",
        "Ondervindt u problemen bij het aanmelden of bij het invullen van de gevraagde gegevens? Aarzel dan niet om contact op te nemen met Valou.",
        "Zij helpt u graag verder.",
        "",
        "📧 backoffice@twem.be",
        "📞 0488 23 17 73",
        "",
        "Alvast hartelijk dank voor uw medewerking.",
        "",
        "Met vriendelijke groeten,",
        "Het TWEM-team"
      ].join("\n")
    : [
        "Bonjour,",
        "",
        `En vue de votre prochaine installation qui aura lieu le ${installDate}, nous avons constaté que la configuration de votre téléphonie n'a pas encore été préremplie dans l'application.`,
        "Afin de garantir le bon déroulement de l'installation, nous vous remercions de bien vouloir compléter cette configuration dès que possible.",
        "",
        "Si vous rencontrez la moindre difficulté, que ce soit pour vous connecter à l'application ou pour compléter les informations demandées, n'hésitez pas à contacter Valou.",
        "Elle se fera un plaisir de vous accompagner.",
        "",
        "📧 backoffice@twem.be",
        "📞 0488 23 17 73",
        "",
        "Nous vous remercions d'avance pour votre collaboration.",
        "",
        "Bien cordialement,",
        "L'équipe TWEM"
      ].join("\n");
  return {
    recipient,
    subject,
    body,
    language,
    status: recipient ? "" : "blocked",
    blockedReason: recipient ? "" : "Adresse mail du manager manquante.",
    reminderDays: Number(context.reminderDays) || 14
  };
}

