function previsitDateForStore(store, options = {}) {
  const workflow = ensureStoreWorkflowData(store);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const candidates = [
    workflow.previsitDate,
    workflow.vlan22Date,
    workflow.cablingDate,
    workflow.ltSwitchDate || workflow.transferDate
  ]
    .map((value) => ({
      raw: value,
      date: normalizeDateOnly(value)
    }))
    .filter((entry) =>
      entry.date instanceof Date
      && !Number.isNaN(entry.date.getTime())
      && (!options.futureOnly || entry.date >= today)
    );
  if (!candidates.length) {
    return "";
  }
  candidates.sort((left, right) => left.date - right.date);
  return candidates[0].raw;
}

function buildPrevisitReminderEmail(store, automation = {}) {
  const managerPerson = managerPersonForStore(store);
  const language = storeLanguageForPrint(store);
  const managerName = managerPerson?.name || store.manager || store.name || (language === "nl" ? "verantwoordelijke" : "responsable");
  const rawPrevisitDate = previsitDateForStore(store, { futureOnly: true }) || previsitDateForStore(store);
  const previsitDate = emailDateLabel(rawPrevisitDate, language) || rawPrevisitDate || "";
  const subject = language === "nl"
    ? `Aankondiging pre-visit - ${store.name || store.code || "winkel"}`
    : `Pre-visite planifiee - ${store.name || store.code || "magasin"}`;
  const body = language === "nl"
    ? [
        `Hallo ${managerName},`,
        "",
        `Wij bevestigen de komst van ons team op ${previsitDate} voor de pre-visit ter voorbereiding van de installatie van uw nieuwe telefooncentrale.`,
        "",
        "Tijdens deze passage controleren we de nodige voorbereidingspunten: VLAN, netwerk, bekabeling, switch en de elementen die nodig zijn voor een vlotte installatie.",
        "",
        "Deze controle helpt ons om de latere installatie in de best mogelijke omstandigheden te laten verlopen.",
        "",
        "Ons team blijft uiteraard beschikbaar als u intussen vragen heeft.",
        "",
        "Alvast bedankt voor uw ontvangst en samenwerking.",
        "",
        "Met vriendelijke groeten,"
      ].join("\n")
    : [
        `Bonjour ${managerName},`,
        "",
        `Nous vous confirmons le passage de notre equipe le ${previsitDate} pour effectuer la pre-visite en vue de l'installation de votre nouvelle centrale telephonique.`,
        "",
        "Lors de ce passage, nous verifierons les points de preparation necessaires: VLAN, reseau, cablage, switch et les elements utiles au bon deroulement de l'installation.",
        "",
        "Cette verification nous permettra de preparer l'intervention finale dans les meilleures conditions possibles.",
        "",
        "Notre equipe reste bien entendu a votre disposition si vous avez des questions d'ici la.",
        "",
        "Nous vous remercions d'avance pour votre accueil et votre collaboration.",
        "",
        "Bien a vous,"
      ].join("\n");
  const values = {
    managerName,
    previsitDate,
    storeName: store.name || "",
    storeCode: store.code || ""
  };

  return {
    subject: fillMailTemplate(automation.emailSubject || subject, values),
    body: automation.emailBodyManual && automation.emailBody && hasMailTemplateVariables(automation.emailBody)
      ? fillMailTemplate(automation.emailBody, values)
      : body,
    recipient: managerPerson?.email || "",
    language,
    status: managerPerson && !personHasFirstAppLogin(managerPerson) ? "blocked" : "",
    blockedReason: managerPerson && !personHasFirstAppLogin(managerPerson)
      ? firstLoginBlockLabel([managerPerson])
      : ""
  };
}

function appAccessLink() {
  return window.location.href.split("?")[0];
}

const bricoTelephonyAppUrl = "https://twem-brico-suivi.appwrite.network/";
const bricoMailReferencePrefix = "BRICO-TEL";
const bricoBackofficeReplyAlias = "Bricobackoffice@twem.be";

function publicAppAccessLink() {
  return bricoTelephonyAppUrl;
}

function appStoreUpdateLink(store, activity) {
  const params = new URLSearchParams();
  params.set("store", store?.code || store?.id || "");
  if (activity?.id) {
    params.set("focus", activity.id);
  }
  return `${appAccessLink()}?${params.toString()}`;
}

function bricoMailScopeCode(scope = "") {
  const value = normalizeImportCell(scope).toLowerCase();
  if (value.includes("sav")) return "SAV";
  if (value.includes("previsit") || value.includes("pre-visite") || value.includes("previsite")) return "PREVISITE";
  if (value.includes("appointment") || value.includes("rdv") || value.includes("rendez")) return "RDV";
  if (value.includes("install")) return "INSTALL";
  return "CONFIG";
}

function bricoMailScopeLabel(scope = "") {
  const code = bricoMailScopeCode(scope);
  if (code === "SAV") return "SAV";
  if (code === "PREVISITE") return "Previsite";
  if (code === "RDV") return "Rendez-vous";
  if (code === "INSTALL") return "Installation";
  return "Configuration";
}

function mailStoreCode(store = {}, email = {}) {
  return normalizeImportCell(store?.code || email.storeCode || "");
}

function mailStoreLabel(store = {}, email = {}) {
  return storeOptionLabel(store) || [email.storeCode, email.storeName].filter(Boolean).join(" - ") || "Magasin";
}

function bricoMailSubject(subject = "", store = {}, scope = "configuration", ticket = null) {
  const cleanSubject = normalizeImportCell(subject || "Suivi Brico Telephonie")
    .replace(/^\[BRICO-TEL\](\[[^\]]+\]){1,2}\s*/i, "")
    .trim();
  const storeCode = mailStoreCode(store);
  const scopeCode = ticket?.id || ticket?.mailObjectId || ticket?.appointmentId || bricoMailScopeCode(scope);
  const prefix = `[${bricoMailReferencePrefix}]${storeCode ? `[${storeCode}]` : ""}[${scopeCode}]`;
  return cleanSubject.startsWith(prefix) ? cleanSubject : `${prefix} ${cleanSubject}`;
}

function bricoMailReplyToken(store = {}, scope = "configuration", ticket = null) {
  const storeCode = mailStoreCode(store) || "MAGASIN";
  const scopeCode = ticket?.id || ticket?.mailObjectId || ticket?.appointmentId || bricoMailScopeCode(scope);
  const randomPart = Math.random().toString(36).slice(2, 8);
  return `${bricoMailReferencePrefix}:${storeCode}:${scopeCode}:${randomPart}`;
}

function bricoMailReplyLink(store = {}, scope = "configuration", ticket = null, replyToken = "") {
  const params = new URLSearchParams();
  params.set("mailReply", "1");
  params.set("store", store?.code || store?.id || "");
  params.set("scope", scope || "configuration");
  if (ticket?.id) {
    params.set("ticket", ticket.id);
  }
  if (ticket?.appointmentId) {
    params.set("appointment", ticket.appointmentId);
  }
  if (replyToken) {
    params.set("ref", replyToken);
  }
  return `${publicAppAccessLink()}?${params.toString()}`;
}

function appendBricoMailSignature(body = "", { store = {}, scope = "configuration", ticket = null, replyToken = "" } = {}) {
  const replyLink = bricoMailReplyLink(store, scope, ticket, replyToken);
  const reference = `[REF:${replyToken}]`;
  const cleanBody = String(body || "")
    .replace(/\n+Bouton repondre dans l'application :[\s\S]*?\[REF:BRICO-TEL:[^\]]+\]\s*$/i, "")
    .trimEnd();
  return [
    cleanBody,
    "",
    "Bouton repondre dans l'application :",
    replyLink,
    "",
    "---",
    "Ce mail vous est transmis par le biais de l'application Brico Telephonie.",
    `Lien vers l'application : ${publicAppAccessLink()}`,
    "Merci de conserver l'objet du mail si vous repondez, afin que votre reponse puisse etre rattachee au bon magasin ou dossier.",
    reference
  ].filter((line, index) => index !== 0 || line).join("\n");
}

function bricoMailHtmlFromText(text = "") {
  return String(text || "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replace(/\r?\n/g, "<br>");
}

