function prepareBricoOutgoingEmail(email, { store = {}, scope = "configuration", ticket = null } = {}) {
  if (!email) return email;
  const replyToken = email.replyToken || bricoMailReplyToken(store, scope, ticket);
  email.scope = scope || email.scope || "configuration";
  email.storeId = store?.id || email.storeId || ticket?.storeId || "";
  email.storeCode = store?.code || email.storeCode || ticket?.storeCode || "";
  email.storeName = store?.name || email.storeName || ticket?.storeName || "";
  email.ticketId = ticket?.id || email.ticketId || "";
  email.appointmentId = ticket?.appointmentId || email.appointmentId || "";
  email.replyToken = replyToken;
  email.replyLink = bricoMailReplyLink(store, email.scope, ticket, replyToken);
  email.replyTo = bricoBackofficeReplyAlias;
  email.subject = bricoMailSubject(email.subject, store, email.scope, ticket);
  email.body = appendBricoMailSignature(email.body, { store, scope: email.scope, ticket, replyToken });
  email.bodyHtml = appendBricoMailSignatureHtml(email.body, { store, scope: email.scope, ticket, replyToken });
  return email;
}

function outgoingMailActivitiesForStore(store, scope = "") {
  const storeCode = normalizeImportCell(store?.code || "");
  const storeName = normalizeImportCell(store?.name || "");
  const wantedScope = normalizeImportCell(scope).toLowerCase();
  return (state.activities || [])
    .filter((activity) => activity?.type === "outgoing_email")
    .filter((activity) =>
      (storeCode && normalizeImportCell(activity.storeCode) === storeCode)
      || (storeName && normalizeImportCell(activity.storeName) === storeName)
      || (store?.id && String(activity.storeId || "") === String(store.id))
    )
    .filter((activity) => !wantedScope || normalizeImportCell(activity.scope).toLowerCase() === wantedScope)
    .sort((left, right) => new Date(right.createdAt || right.sentAt || 0) - new Date(left.createdAt || left.sentAt || 0));
}

function outgoingMailActivitiesForTicket(ticket) {
  if (!ticket?.id) return [];
  return (state.activities || [])
    .filter((activity) => activity?.type === "outgoing_email" && activity.ticketId === ticket.id)
    .sort((left, right) => new Date(right.createdAt || right.sentAt || 0) - new Date(left.createdAt || left.sentAt || 0));
}

function outgoingMailActivitiesForAppointment(appointment) {
  if (!appointment?.id) return [];
  return (state.activities || [])
    .filter((activity) => activity?.type === "outgoing_email" && activity.appointmentId === appointment.id)
    .sort((left, right) => new Date(right.createdAt || right.sentAt || 0) - new Date(left.createdAt || left.sentAt || 0));
}

function renderOutgoingMailLog(activities = [], title = "Mails envoyes") {
  if (!activities.length) {
    return "";
  }
  return `
    <div class="outgoing-mail-log">
      <div class="sav-thread-label">${escapeUi(title)}</div>
      ${activities.map((activity) => `
        <div class="outgoing-mail-item">
          <div class="outgoing-mail-meta">
            <strong>${escapeHtml(activity.subject || "Mail envoye")}</strong>
            <span>${escapeHtml(formatDateTime(activity.sentAt || activity.createdAt))}</span>
          </div>
          <div class="cell-note">${escapeHtml(bricoMailScopeLabel(activity.scope))} - ${escapeHtml(activity.to || activity.recipient || "-")}</div>
          ${activity.replyLink ? `<a class="mini-button mail-reply-link" href="${escapeHtml(activity.replyLink)}">Repondre dans l'application</a>` : ""}
        </div>
      `).join("")}
    </div>
  `;
}

function recordOutgoingEmailActivity(email, sendResult = {}) {
  if (!email?.replyToken || !email?.storeCode) {
    return null;
  }
  const existing = (state.activities || []).find((activity) =>
    activity.type === "outgoing_email"
    && activity.replyToken === email.replyToken
  );
  if (existing) {
    existing.sentAt = existing.sentAt || email.sentAt || new Date().toISOString();
    existing.mailerResponse = sendResult;
    return existing;
  }
  const now = email.sentAt || new Date().toISOString();
  const activity = {
    id: `mail-out-${safeDocumentId("ref", email.replyToken)}-${Date.now()}`,
    type: "outgoing_email",
    scope: email.scope || "configuration",
    storeId: email.storeId || "",
    storeCode: email.storeCode || "",
    storeName: email.storeName || "",
    ticketId: email.ticketId || "",
    appointmentId: email.appointmentId || "",
    subject: email.subject || "",
    to: email.recipient || "",
    body: email.body || "",
    bodyHtml: email.bodyHtml || "",
    replyToken: email.replyToken,
    replyLink: email.replyLink || "",
    sentAt: now,
    sentBy: currentUser()?.name || state.activeUserName || "TWEM",
    result: "ok",
    comment: `Mail envoye - ${bricoMailScopeLabel(email.scope)} - ${email.subject || ""}`,
    confirmedBy: currentUser()?.name || state.activeUserName || "TWEM",
    createdAt: now,
    mailerResponse: sendResult
  };
  state.activities.unshift(activity);
  saveState();
  return activity;
}

function storeForActivity(activity) {
  return (state.stores || []).find((store) =>
    (activity?.storeCode && store.code === activity.storeCode)
    || (activity?.storeId && store.id === activity.storeId)
    || (activity?.storeName && store.name === activity.storeName)
  ) || null;
}

function buildStoreUpdateAlertEmail(activity, automation = {}) {
  const store = storeForActivity(activity);
  const language = store ? storeLanguageForPrint(store) : "fr";
  const appLink = store ? appStoreUpdateLink(store, activity) : appAccessLink();
  const storeName = store?.name || activity?.storeName || "magasin";
  const updateText = activity?.comment || "Nouvelle information a consulter";
  const linkedPeople = store ? linkedPeopleForStore(store) : [];
  const connectedPeople = linkedPeople.filter(personHasFirstAppLogin);
  const recipients = connectedPeople.map((person) => person.email);
  const subject = language === "nl"
    ? `Nieuwe update - ${storeName}`
    : `Nouvelle mise a jour - ${storeName}`;
  const body = language === "nl"
    ? [
        "Hallo,",
        "",
        `Er is een nieuwe update / informatie toegevoegd in de applicatie voor winkel ${storeName}.`,
        "",
        `Waarover gaat het: ${updateText}`,
        "",
        "Klik op onderstaande link om rechtstreeks naar de wijziging te gaan en de nieuwe elementen van het dossier te bekijken:",
        "",
        appLink,
        "",
        "Wij blijven uiteraard beschikbaar voor elke vraag of bijkomende informatie.",
        "",
        "Met vriendelijke groeten,"
      ].join("\n")
    : [
        "Bonjour,",
        "",
        `Une nouvelle mise a jour / information a ete ajoutee dans l'application pour le magasin ${storeName}.`,
        "",
        `Ce qui est nouveau: ${updateText}`,
        "",
        "Veuillez cliquer sur le lien ci-dessous afin d'acceder directement a la modification et consulter les nouveaux elements du dossier :",
        "",
        appLink,
        "",
        "Nous restons bien entendu a votre disposition pour toute question ou information complementaire.",
        "",
        "Bien a vous,"
      ].join("\n");
  const values = {
    storeName,
    appLink,
    updateText
  };
  return {
    subject: fillMailTemplate(automation.emailSubject || subject, values),
    body: automation.emailBodyManual && automation.emailBody && hasMailTemplateVariables(automation.emailBody)
      ? fillMailTemplate(automation.emailBody, values)
      : body,
    recipient: recipients.join(", "),
    language,
    status: recipients.length ? "" : "blocked",
    blockedReason: recipients.length ? "" : firstLoginBlockLabel(linkedPeople) || "Aucun contact connecte une premiere fois"
  };
}

function storesForPersonAccess(person = {}) {
  const codes = Array.isArray(person.allowedStoreCodes) && person.allowedStoreCodes.length
    ? person.allowedStoreCodes
    : person.storeCode
      ? [person.storeCode]
      : [];
  if (!codes.length || codes.includes("*")) {
    return person.storeCode
      ? (state.stores || []).filter((store) => store.code === person.storeCode)
      : [];
  }
  return (state.stores || []).filter((store) => codes.includes(store.code));
}

function accessMailStoreTypeGroup(person = {}) {
  const types = storesForPersonAccess(person)
    .map((store) => normalizeShopTypeValue(store.shopType))
    .filter(Boolean);
  if (types.some((type) => type === "FOS" || type === "FOSDOS")) {
    return "FOS-FOSDOS";
  }
  if (types.some((type) => type === "DOS")) {
    return "DOS";
  }
  return "DOS";
}

function accessMailStoreLabel(person = {}) {
  const stores = storesForPersonAccess(person);
  if (!stores.length) {
    return "";
  }
  return stores
    .map((store) => [store.code, store.name].filter(Boolean).join(" - "))
    .join(", ");
}

