function parseTechSupportExecutionBody(execution = {}) {
  const candidates = [
    execution.responseBody,
    execution.body,
    execution.response
  ];
  for (const candidate of candidates) {
    if (!candidate) {
      continue;
    }
    if (typeof candidate === "object") {
      return candidate;
    }
    const parsed = parseJsonField(candidate, null);
    if (parsed && typeof parsed === "object") {
      return parsed;
    }
  }
  return {};
}

function rememberOpenSupportRequest(payload, responseBody) {
  const requestId = normalizeImportCell(responseBody?.requestId || responseBody?.id || responseBody?.supportRequestId);
  if (!requestId) {
    throw new Error("Missing support requestId");
  }
  const now = new Date().toISOString();
  state.supportRequests = normalizedSupportRequests([
    ...(state.supportRequests || []).filter((request) =>
      !(request.requestId === requestId && request.appId === payload.appId)
    ),
    {
      requestId,
      appId: payload.appId,
      appName: payload.appName,
      clientName: payload.clientName,
      subject: payload.subject,
      priority: payload.priority,
      sourceUrl: payload.sourceUrl,
      status: "open",
      createdAt: now,
      updatedAt: now
    }
  ]);
  return requestId;
}

async function sendTechSupportRequest(payload) {
  const response = await fetch(techSupportGatewayUrl, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Appwrite-Project": appwriteProjectId || "69eb57e00020de70ed30",
      "X-Appwrite-Response-Format": "1.9.5"
    },
    body: JSON.stringify({
      async: false,
      body: JSON.stringify(payload)
    })
  });
  const execution = await response.json().catch(() => ({}));
  if (!response.ok || execution?.status === "failed" || Number(execution?.responseStatusCode || 200) >= 400) {
    throw new Error(execution?.message || execution?.stderr || "Tech support request failed");
  }
  const responseBody = parseTechSupportExecutionBody(execution);
  if (responseBody?.ok !== true) {
    throw new Error(responseBody?.message || "Tech support request not accepted");
  }
  const requestId = rememberOpenSupportRequest(payload, responseBody);
  saveState();
  if (hasRemoteData()) {
    syncSettingsToRemote().catch((error) => console.error("Tech support settings sync error", error));
  }
  return { execution, responseBody, requestId };
}

async function handleTechSupportSubmit(event) {
  event.preventDefault();
  if (!ENABLE_TECH_SUPPORT_BUTTON || !techSupportForm) {
    return;
  }
  const subject = normalizeImportCell(techSupportForm.querySelector('[name="subject"]')?.value).slice(0, 120);
  const message = String(techSupportForm.querySelector('[name="message"]')?.value || "").trim();
  const priority = techSupportForm.querySelector('[name="priority"]')?.value === "urgent" ? "urgent" : "normal";
  if (!subject || !message) {
    return;
  }
  if (techSupportFeedback) {
    techSupportFeedback.textContent = "Envoi en cours...";
    techSupportFeedback.className = "validation-text is-pending";
  }
  try {
    await sendTechSupportRequest({
      appId: techSupportAppId,
      appName: techSupportAppName,
      clientName: techSupportClientName,
      subject,
      message,
      priority,
      source: techSupportSource,
      sourceUrl: window.location.href
    });
    techSupportForm.reset();
    if (techSupportFeedback) {      techSupportFeedback.textContent = "Demande envoyee au service technique.";
      techSupportFeedback.className = "validation-text is-success";
    }
  } catch (error) {
    console.error("Tech support request error", error);
    if (techSupportFeedback) {      techSupportFeedback.textContent = "Impossible d envoyer la demande pour le moment. Reessayez plus tard.";
      techSupportFeedback.className = "validation-text is-error";
    }
  }
}

