function downloadTextFile(content, fileName, mimeType) {
  const blob = new Blob([content], { type: mimeType });
  downloadBlob(blob, fileName);
}

function downloadBlob(blob, fileName) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  document.body.append(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function dataUrlToBlob(dataUrl) {
  const [header, payload] = String(dataUrl || "").split(",");
  const mimeMatch = header?.match(/^data:([^;]+);base64$/i);
  if (!mimeMatch || !payload) {
    return null;
  }
  const binary = window.atob(payload);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return new Blob([bytes], { type: mimeMatch[1] || "application/pdf" });
}

function appwriteStorageFileUrl(fileId, mode = "download", bucketId = appwritePlansBucketId) {
  const storageEndpoint = appwriteEndpoint || (isSnapshotMode ? appConfig.snapshotStorageEndpoint : "");
  const storageProjectId = appwriteProjectId || (isSnapshotMode ? appConfig.snapshotStorageProjectId : "");
  if (!fileId || !bucketId || !storageEndpoint || !storageProjectId) {
    return "";
  }
  const action = mode === "view" ? "view" : "download";
  const base = storageEndpoint.replace(/\/$/, "");
  return `${base}/storage/buckets/${encodeURIComponent(bucketId)}/files/${encodeURIComponent(fileId)}/${action}?project=${encodeURIComponent(storageProjectId)}`;
}

async function createAppwriteStorageFile(bucketId, fileId, file, permissions = []) {
  if (!appwriteStorage) {
    throw new Error("Storage Appwrite indisponible.");
  }
  try {
    return await appwriteStorage.createFile({ bucketId, fileId, file, permissions });
  } catch (error) {
    return appwriteStorage.createFile(bucketId, fileId, file, permissions);
  }
}

function isAppwriteFileExtensionDenied(error) {
  const text = `${error?.message || ""} ${error?.response?.message || ""} ${error?.type || ""}`.toLowerCase();
  return text.includes("file extension not allowed")
    || text.includes("extension not allowed")
    || text.includes("allowed extension");
}

function appwriteCompatiblePrevisitUploadFile(file) {
  if (!file?.name) return file;
  const compatibleName = file.name.replace(/\.[^.]+$/i, ".jpeg");
  try {
    return new File([file], compatibleName, {
      type: file.type || "image/jpeg",
      lastModified: file.lastModified || Date.now()
    });
  } catch (error) {
    console.warn("Impossible de renommer la photo avant upload Appwrite", error);
    return file;
  }
}

function appwritePdfNamedPrevisitUploadFile(file) {
  if (!file?.name) return file;
  const compatibleName = file.name.replace(/\.[^.]+$/i, ".pdf");
  try {
    return new File([file], compatibleName, {
      type: file.type || "application/octet-stream",
      lastModified: file.lastModified || Date.now()
    });
  } catch (error) {
    console.warn("Impossible de renommer la photo en document avant upload Appwrite", error);
    return file;
  }
}

async function createAppwritePrevisitFile(bucketId, fileId, file) {
  const attempts = [file];
  if (/^image\//i.test(file.type) || /\.(jpe?g|png|webp|heic)$/i.test(file.name || "")) {
    attempts.push(appwriteCompatiblePrevisitUploadFile(file));
    attempts.push(appwritePdfNamedPrevisitUploadFile(file));
  }
  let lastError = null;
  const triedNames = new Set();
  for (const attempt of attempts) {
    const name = attempt?.name || "";
    if (triedNames.has(name)) continue;
    triedNames.add(name);
    try {
      return await createAppwriteStorageFile(bucketId, fileId, attempt);
    } catch (error) {
      lastError = error;
      if (!/extension/i.test(String(error?.message || error?.response?.message || ""))) {
        throw error;
      }
    }
  }
  throw lastError || new Error("Upload previsite impossible.");
}

async function deleteAppwriteStorageFile(bucketId, fileId) {
  if (!appwriteStorage || !bucketId || !fileId) {
    return;
  }
  try {
    await appwriteStorage.deleteFile({ bucketId, fileId });
  } catch (error) {
    await appwriteStorage.deleteFile(bucketId, fileId);
  }
}

function storeOptionLabel(store) {
  return [store?.code, store?.name].filter(Boolean).join(" - ") || "Magasin";
}

function storeSearchText(store) {
  return normalizeFileMatchText([
    store?.code,
    store?.shopNumber,
    store?.name,
    store?.city,
    store?.address
  ].filter(Boolean).join(" "));
}

function findStoreFromReportSearch(value = "") {
  const search = normalizeFileMatchText(value);
  if (!search) return null;
  const exact = state.stores.find((store) =>
    normalizeFileMatchText(storeOptionLabel(store)) === search
    || normalizeFileMatchText(store.code || "") === search
    || normalizeFileMatchText(store.shopNumber || "") === search
  );
  if (exact) return exact;
  const matches = state.stores.filter((store) => storeSearchText(store).includes(search));
  return matches.length === 1 ? matches[0] : null;
}

function findRoleScopedStoreFromGlobalSearch(value = "") {
  const search = normalizeFileMatchText(value);
  if (search.length < 3) return null;
  const scopedStores = getRoleScopedStores();
  const exact = scopedStores.find((store) =>
    normalizeFileMatchText(storeOptionLabel(store)) === search
    || normalizeFileMatchText(store.code || "") === search
    || normalizeFileMatchText(store.shopNumber || "") === search
  );
  if (exact) return exact;
  const matches = scopedStores.filter((store) => storeSearchText(store).includes(search));
  return matches.length === 1 ? matches[0] : null;
}

function openStoreByIdInTab(storeId, tab = "") {
  const store = state.stores.find((item) => Number(item.id) === Number(storeId));
  if (!store) return false;
  const targetTab = isMobileConsultationViewport() ? "stores" : (tab || storePrimaryListTab(store));
  if (!canAccessTab(targetTab)) {
    return false;
  }
  resetWorkspaceFilters();
  const focusedSearch = store.code || store.shopNumber || store.name || "";
  state.filters.search = normalizeImportCell(focusedSearch).toLowerCase();
  if (searchInput) {
    searchInput.value = focusedSearch;
  }
  state.activeAdminTab = targetTab;
  state.expandedStoreIds = new Set([store.id]);
  state.pendingStoreDetailFocusId = String(store.id);
  saveState();
  render();
  window.location.hash = `#section-${targetTab}`;
  return true;
}

async function handleSimHammerToolDownload() {
  if (!canDownloadSimHammerTool()) {
    if (simHammerToolDownloadStatus) {
      simHammerToolDownloadStatus.textContent = "Telechargement reserve a Emir et Valou.";
    }
    return;
  }
  if (simHammerToolDownloadButton) {
    simHammerToolDownloadButton.disabled = true;
  }
  if (simHammerToolDownloadStatus) {
    simHammerToolDownloadStatus.textContent = "Preparation du telechargement...";
  }
  try {
    const downloadUrl = appwriteStorageFileUrl(
      "sim-hammer-kit-cbo-ui-20",
      "download",
      "sim_hammer_tools"
    );
    const response = await fetch(downloadUrl, { cache: "no-store" });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    downloadBlob(await response.blob(), "Kit-SIM-Hammer-PC-CbO-UI-2.0.zip");
    if (simHammerToolDownloadStatus) {
      simHammerToolDownloadStatus.textContent = "Kit telecharge. Tu peux maintenant l'installer ou le transmettre.";
    }
  } catch (error) {
    console.error("SIM Hammer kit download failed", error);
    if (simHammerToolDownloadStatus) {
      simHammerToolDownloadStatus.textContent = "Le telechargement a echoue. Reessaie dans un instant.";
    }
  } finally {
    if (simHammerToolDownloadButton) {
      simHammerToolDownloadButton.disabled = false;
    }
  }
}

