function createSavTicketsFromFieldReport(store, text, report) {
  const actions = fieldReportSavActions(text);
  if (!actions.length) return [];
  const now = new Date().toISOString();
  const created = [];
  actions.forEach((action, index) => {
    const sourceKey = fieldReportSavSourceKey(store, report, action);
    const exists = (state.tickets || []).some((ticket) => ticket.fieldReportSourceKey === sourceKey);
    if (exists) return;
    const ticket = {
      id: `SAV-${store.code}-REPORT-${Date.now()}-${index + 1}`,
      storeId: store.id,
      storeCode: store.code,
      storeName: store.name,
      requesterName: "Installateur centrale",
      targetService: "Emir, Valou",
      targetPeople: ["Emir", "Valou"],
      concern: action.concern,
      initialNote: action.initialNote,
      requestKind: action.requestKind || "SAV",
      materialLabel: action.materialLabel || "",
      extensionLabel: "",
      quantityRequested: action.quantityRequested || "",
      orderWorkflowStatus: action.orderWorkflowStatus || "",
      status: "dispatch",
      dispatchStatus: "pending_twem",
      receivedByTwemAt: now,
      createdAt: now,
      updates: [],
      fieldReportId: report.id,
      fieldReportSourceKey: sourceKey
    };
    state.tickets.unshift(ticket);
    state.activities.unshift({
      id: `field-report-sav-${Date.now()}-${index + 1}`,
      storeId: store.id,
      storeCode: store.code,
      storeName: store.name,
      result: "issue",
      comment: `SAV cree depuis rapport installation - ${action.concern}`,
      confirmedBy: "Installateur centrale",
      createdAt: now
    });
    created.push(ticket);
  });
  return created;
}

