async function executeSavAlertMailFunction(email) {
  if (!appwriteEndpoint || !appwriteProjectId || !appwriteMailerFunctionId) {
    throw new Error("Configuration Appwrite mailer incomplete.");
  }
  if (!email?.recipient || !email?.body) {
    throw new Error("Mail rapport installation incomplet.");
  }
  const response = await fetch(`${appwriteEndpoint}/functions/${encodeURIComponent(appwriteMailerFunctionId)}/executions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Appwrite-Project": appwriteProjectId,
      "X-Appwrite-Response-Format": "1.9.5"
    },
    body: JSON.stringify({
      body: JSON.stringify({
        action: "send-field-report-direct",
        recipients: email.recipient,
        replyTo: email.replyTo || bricoBackofficeReplyAlias,
        subject: email.subject,
        body: email.body,
        bodyHtml: email.bodyHtml || "",
        attachments: JSON.stringify(email.attachments || [])
      }),
      async: false,
      path: "/?action=send-field-report-direct",
      method: "POST",
      headers: { "content-type": "application/json" }
    })
  });
  const execution = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(execution?.message || `Execution Appwrite refusee (${response.status}).`);
  }
  const body = parseJsonField(execution.responseBody, {});
  if (execution.status !== "completed" || execution.responseStatusCode >= 400 || body?.ok === false) {
    throw new Error(body?.error || execution.stderr || "La fonction mailer n'a pas confirme l'envoi.");
  }
  if (body?.dryRun) {
    throw new Error("La fonction Appwrite est encore en DRY_RUN=true, donc aucun mail reel n'est parti.");
  }
  recordOutgoingEmailActivity(email, body);
  return body;
}

const executeFieldReportSavMailFunction = executeSavAlertMailFunction;

function surveyZipVersion(name = "") {
  return Number(String(name).match(/-v(\d+)\.pdf$/i)?.[1] || 0);
}

function surveyZipTimestamp(name = "") {
  const match = String(name).match(/_(\d{4}-\d{2}-\d{2})_(\d{6})\.pdf$/i);
  return match ? `${match[1]}T${match[2].slice(0, 2)}:${match[2].slice(2, 4)}:${match[2].slice(4, 6)}` : "";
}

function surveyZipEntryType(path = "") {
  const name = installationZipBaseName(path);
  if (/^PV-.*\.pdf$/i.test(name)) return "previsit_report";
  if (/^SYNTHESE-.*\.pdf$/i.test(name)) return "summary";
  if (/^GO-BRICO-.*\.pdf$/i.test(name)) return "go_brico";
  if (/^GO-DESTINY-.*\.pdf$/i.test(name)) return "go_destiny";
  if (/^CL-.*\.pdf$/i.test(name)) return "closure";
  if (/Plan.*Technique.*\.pdf$/i.test(name) || /site-plan[\\/].*\.pdf$/i.test(path)) return "technical_plan";
  if (/^report-1\.pdf$/i.test(name) || /cover.mobile.*\.pdf$/i.test(path)) return "mobile_report_1";
  return "other";
}

function surveyZipLatest(entries = [], type) {
  return entries.filter((item) => item.type === type).sort((left, right) => {
    if (type === "technical_plan") return surveyZipTimestamp(right.name).localeCompare(surveyZipTimestamp(left.name));
    return surveyZipVersion(right.name) - surveyZipVersion(left.name) || right.name.localeCompare(left.name);
  })[0] || null;
}

function surveyZipSignature(manifest = {}, entries = []) {
  return [
    normalizeImportCell(manifest.clientRunId || manifest.visitId || manifest.siteId),
    ...entries.map((entry) => `${entry.path}:${entry.size || 0}`).sort()
  ].join("|");
}

function renderSurveyZipPreview(review = state.fieldSurveyZipReview) {
  if (!fieldSurveyZipPreview || !fieldSurveyZipApplyButton) return;
  fieldSurveyZipPreview.classList.remove("empty-state");
  if (!review) {
    fieldSurveyZipPreview.classList.add("empty-state");
    fieldSurveyZipPreview.innerHTML = "Aucun dossier Survey charge.";
    fieldSurveyZipApplyButton.disabled = true;
    return;
  }
  const ready = Boolean(review.store && review.previsitReport && review.technicalPlan && !review.errors.length && !review.duplicateImport);
  fieldSurveyZipApplyButton.disabled = !ready;
  fieldSurveyZipPreview.innerHTML = `
    <strong>${escapeHtml(review.store ? storeOptionLabel(review.store) : "Magasin non reconnu")}</strong>
    <p>${escapeHtml(review.file.name)} - ${review.entries.length} document(s) conserve(s).</p>
    <ul>
      <li><strong>Particularites magasin</strong> : ${escapeHtml(review.previsitReport?.name || "Aucun rapport PV disponible")}</li>
      <li><strong>Plan technique complet</strong> : ${escapeHtml(review.technicalPlan?.name || "Aucun plan technique disponible")}</li>
      <li><strong>Couverture mobile</strong> : ${escapeHtml(review.mobileReport?.name || "Aucun report-1 de previsite disponible")}</li>
    </ul>
    ${review.ignoredVersions.length ? `<div><strong>Versions anterieures conservees dans l'historique, mais non utilisees comme version courante</strong><ul>${review.ignoredVersions.map((item) => `<li>${escapeHtml(item.name)}</li>`).join("")}</ul></div>` : ""}
    ${review.duplicateFiles.length ? `<div><strong>Doublons identiques detectes</strong><ul>${review.duplicateFiles.map((item) => `<li>${escapeHtml(item.name)}</li>`).join("")}</ul></div>` : ""}
    ${review.warnings.length ? `<div><strong>A verifier</strong><ul>${review.warnings.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
    ${review.errors.length ? `<div><strong>Import bloque</strong><ul>${review.errors.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
    ${review.duplicateImport ? `<div class="empty-state"><strong>Ce dossier Survey a deja ete applique. Aucune seconde ecriture ne sera effectuee.</strong></div>` : ""}
    ${ready ? "<p><strong>Previsualisation terminee.</strong> Rien n'a encore ete ecrit. Clique sur Appliquer pour lancer la repartition.</p>" : ""}
  `;
}

async function surveyZipSha256(entry) {
  const bytes = await entry.async("arraybuffer");
  const hash = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(hash)].map((value) => value.toString(16).padStart(2, "0")).join("");
}

async function handleSurveyZipFileChange(event) {
  const input = event.currentTarget;
  const file = input?.files?.[0];
  if (!file) return;
  if (!window.JSZip) throw new Error("Bibliotheque ZIP indisponible.");
  if (!/\.zip$/i.test(file.name)) throw new Error("Choisis un dossier ZIP Survey / pre-visite.");
  fieldSurveyZipPreview.classList.remove("empty-state");
  fieldSurveyZipPreview.innerHTML = "<p>Analyse du dossier Survey en cours. Aucune donnee n'est ecrite.</p>";
  fieldSurveyZipApplyButton.disabled = true;
  const zip = await window.JSZip.loadAsync(file);
  const manifestEntry = zip.file("manifest.json");
  if (!manifestEntry) throw new Error("manifest.json manque dans le dossier Survey.");
  const manifest = JSON.parse(await manifestEntry.async("string"));
  if (manifest.format !== "TWEM_PREVISIT_REPORT_PACKAGE" || Number(manifest.version) !== 1) {
    throw new Error("Format de dossier Survey non reconnu.");
  }
  const store = state.stores.find((item) => normalizeImportCell(item.remoteSiteId) === normalizeImportCell(manifest.siteId))
    || state.stores.find((item) => normalizeImportCell(item.code).toLowerCase() === normalizeImportCell(manifest.siteCode).toLowerCase());
  const errors = [];
  const warnings = [];
  if (!store) errors.push(`Magasin ${manifest.siteCode || manifest.siteId || "inconnu"} introuvable.`);
  const paths = Array.isArray(manifest.files) ? manifest.files : [];
  const entries = [];
  for (const path of paths) {
    const source = zip.file(path);
    if (!source) {
      errors.push(`${path} est annonce dans le manifeste mais absent du ZIP.`);
      continue;
    }
    entries.push({ path, name: installationZipBaseName(path), type: surveyZipEntryType(path), size: Number(source?._data?.uncompressedSize || 0), source, sha256: await surveyZipSha256(source) });
  }
  const previsitReport = surveyZipLatest(entries, "previsit_report");
  const technicalPlan = surveyZipLatest(entries, "technical_plan");
  const mobileReport = surveyZipLatest(entries, "mobile_report_1");
  if (!previsitReport) errors.push("Aucun rapport de pre-visite PV n'est disponible.");
  if (!technicalPlan) errors.push("Aucun plan technique complet n'est disponible.");
  if (!mobileReport) warnings.push("Aucun report-1 de pre-visite disponible : la couverture mobile restera sans donnees.");
  if (!entries.some((item) => /manifest.*\.json$/i.test(item.name)) && !entries.some((item) => /^image\//i.test(installationZipMimeType(item.name)))) {
    warnings.push("Ce ZIP ne contient ni manifeste technique detaille ni photos d'equipement. Les cadres Rack, Algo Pager, Postes fixes et Buttons existants ne seront pas inventes ni modifies.");
  }
  const currentEntries = new Set([previsitReport?.path, technicalPlan?.path, mobileReport?.path].filter(Boolean));
  const ignoredVersions = entries.filter((item) => ["previsit_report", "technical_plan", "mobile_report_1"].includes(item.type) && !currentEntries.has(item.path));
  const seenHashes = new Set();
  const duplicateFiles = entries.filter((item) => seenHashes.has(item.sha256) ? true : (seenHashes.add(item.sha256), false));
  if (entries.filter((item) => item.type === "other").length) warnings.push("Les documents non classes seront conserves dans l'historique Survey sans etre distribues dans une section metier.");
  const signature = surveyZipSignature(manifest, entries);
  const duplicateImport = store && (ensureStoreWorkflowData(store).surveyZipImports || []).some((item) => item.signature === signature);
  state.fieldSurveyZipReview = { file, zip, manifest, store, entries, previsitReport, technicalPlan, mobileReport, ignoredVersions, duplicateFiles, warnings, errors, signature, duplicateImport };
  renderSurveyZipPreview();
  input.value = "";
}

async function saveSurveyZipDocument(store, item, documentType) {
  const blob = await item.source.async("blob");
  const file = new File([blob], item.name, { type: installationZipMimeType(item.name) });
  const fileId = safeDocumentId("survey", `${store.code}-${documentType}-${item.sha256.slice(0, 16)}`);
  if (hasRemoteData() && appwriteStorage && appwritePlansBucketId) {
    try { await createAppwriteStorageFile(appwritePlansBucketId, fileId, file); }
    catch (error) {
      if (Number(error?.code || error?.response?.code || 0) !== 409) throw error;
    }
  }
  return {
    id: `survey-doc-${item.sha256.slice(0, 24)}`,
    type: documentType,
    sourceKey: `manual-survey-zip-${item.sha256.slice(0, 16)}`,
    bucketId: appwritePlansBucketId,
    fileId,
    sha256: item.sha256,
    mimeType: file.type,
    byteSize: String(file.size || item.size || ""),
    fileName: item.name,
    generatedAt: new Date().toISOString(),
    version: surveyZipVersion(item.name) || 1,
    status: "IMPORTED",
    isCurrent: false,
    origin: "Import manuel ZIP Survey",
    downloadAvailable: true,
    createdAt: new Date().toISOString()
  };
}

async function handleSurveyZipApply() {
  const review = state.fieldSurveyZipReview;
  if (!review?.store || review.errors.length || review.duplicateImport) return;
  const store = state.stores.find((item) => String(item.id) === String(review.store.id));
  if (!store) throw new Error("Magasin introuvable au moment de l'application.");
  fieldSurveyZipApplyButton.disabled = true;
  fieldSurveyZipPreview.insertAdjacentHTML("afterbegin", "<p><strong>Sauvegarde et repartition Appwrite en cours...</strong></p>");
  const workflow = ensureStoreWorkflowData(store);
  const report = ensurePrevisitReport(workflow);
  workflow.surveyZipImports = Array.isArray(workflow.surveyZipImports) ? workflow.surveyZipImports : [];
  if (workflow.surveyZipImports.some((item) => item.signature === review.signature)) throw new Error("Ce dossier Survey a deja ete applique.");
  const uploaded = [];
  const existingHashes = new Set((workflow.previsitRuns || []).flatMap((run) => run.documents || []).map((item) => item.sha256).filter(Boolean));
  const selectedPaths = [review.previsitReport?.path, review.technicalPlan?.path, review.mobileReport?.path].filter(Boolean);
  const orderedEntries = [...selectedPaths.map((path) => review.entries.find((item) => item.path === path)).filter(Boolean), ...review.entries.filter((item) => !selectedPaths.includes(item.path))];
  for (const item of orderedEntries) {
    if (existingHashes.has(item.sha256)) continue;
    const typeMap = { previsit_report: "PREVISIT_REPORT_PDF", technical_plan: "PREVISIT_SUMMARY_PDF", summary: "PREVISIT_SUMMARY_PDF", go_brico: "GO_NO_GO_REPORT_PDF", go_destiny: "GO_NO_GO_REPORT_PDF", closure: "CLOSURE_REPORT_PDF", mobile_report_1: "MOBILE_COVERAGE_REPORT_PDF", other: "OTHER_DOCUMENT" };
    uploaded.push(await saveSurveyZipDocument(store, item, typeMap[item.type] || "OTHER_DOCUMENT"));
    existingHashes.add(item.sha256);
  }
  const selectedHashes = new Set([review.previsitReport?.sha256, review.technicalPlan?.sha256, review.mobileReport?.sha256].filter(Boolean));
  uploaded.forEach((document) => { document.isCurrent = selectedHashes.has(document.sha256); });
  const run = {
    id: `manual-survey-${safeDocumentId("run", review.manifest.clientRunId || review.manifest.visitId || Date.now())}`,
    clientRunId: normalizeImportCell(review.manifest.clientRunId),
    visitId: normalizeImportCell(review.manifest.visitId),
    status: "IMPORTED",
    portalVisible: true,
    publishedAt: new Date().toISOString(),
    technician: currentUser()?.name || state.activeUserName || "TWEM",
    receivedAt: new Date().toISOString(),
    completedAt: new Date().toISOString(),
    documents: uploaded
  };
  workflow.previsitRuns = [run, ...(Array.isArray(workflow.previsitRuns) ? workflow.previsitRuns : [])];
  const chosenReport = uploaded.find((item) => item.sha256 === review.previsitReport.sha256);
  if (chosenReport) {
    const photos = getPrevisitPhotosFromReport(report);
    const key = previsitPhotoMergeKey({ name: chosenReport.fileName, fileId: chosenReport.fileId, fileSize: chosenReport.byteSize });
    if (!photos.some((photo) => previsitPhotoMergeKey(photo) === key)) {
      report.photos = [...photos, normalizePrevisitPhoto({ id: chosenReport.id, name: chosenReport.fileName, category: "Autre", fileType: chosenReport.mimeType, fileSize: chosenReport.byteSize, fileId: chosenReport.fileId, bucketId: chosenReport.bucketId, updatedAt: chosenReport.createdAt }, photos.length)];
    }
  }
  const chosenPlan = uploaded.find((item) => item.sha256 === review.technicalPlan.sha256);
  if (chosenPlan) report.technicalPlan = { ...chosenPlan, name: chosenPlan.fileName };
  const chosenMobile = review.mobileReport && uploaded.find((item) => item.sha256 === review.mobileReport.sha256);
  if (chosenMobile) {
    report.mobileSurveyReports = Array.isArray(report.mobileSurveyReports) ? report.mobileSurveyReports : [];
    if (!report.mobileSurveyReports.some((item) => item.sha256 === chosenMobile.sha256)) report.mobileSurveyReports.unshift({ ...chosenMobile, name: chosenMobile.fileName, kind: "comparison", importedAt: chosenMobile.createdAt });
  }
  workflow.surveyZipImports.unshift({ id: `survey-zip-import-${Date.now()}`, signature: review.signature, fileName: review.file.name, clientRunId: review.manifest.clientRunId || "", visitId: review.manifest.visitId || "", reportFileName: review.previsitReport.name, technicalPlanFileName: review.technicalPlan.name, mobileReportFileName: review.mobileReport?.name || "", importedAt: new Date().toISOString(), importedBy: currentUser()?.name || state.activeUserName || "TWEM" });
  report.updatedAt = new Date().toISOString();
  report.updatedBy = currentUser()?.name || state.activeUserName || "TWEM";
  store.updatedAt = new Date().toISOString();
  saveState();
  if (hasRemoteData()) await syncStoreToRemote(store, `Import ZIP Survey controle - ${review.file.name}`);
  recordImportExportHistory("import", "ZIP Survey / pre-visite", `${storeOptionLabel(store)} - ${review.previsitReport.name} - ${review.technicalPlan.name}`);
  state.fieldSurveyZipReview = null;
  renderSurveyZipPreview();
  window.alert(`Dossier Survey reparti dans ${storeOptionLabel(store)}. Rapport de pre-visite et plan technique ajoutes sans remplacer les donnees existantes.${review.mobileReport ? " report-1 ajoute." : " Aucun report-1 de pre-visite disponible."}`);
  render();
}

function installationReportMergeKey(text = "") {
  return normalizeImportCell(text)
    .toLowerCase()
    .replace(/\s+/g, " ")
    .slice(0, 4000);
}

function installationZipMimeType(name = "") {
  const extension = String(name).toLowerCase().split(".").pop();
  return {
    zip: "application/zip",
    docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    pdf: "application/pdf",
    xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    xls: "application/vnd.ms-excel",
    csv: "text/csv",
    png: "image/png",
    jpg: "image/jpeg",
    jpeg: "image/jpeg",
    webp: "image/webp",
    txt: "text/plain",
    md: "text/markdown",
    html: "text/html",
    htm: "text/html"
  }[extension] || "application/octet-stream";
}

function installationZipBaseName(path = "") {
  return String(path).split(/[\\/]/).pop() || String(path);
}

function installationZipEntryKind(name = "") {
  const normalized = normalizeSearchText(installationZipBaseName(name));
  const extension = String(name).toLowerCase().split(".").pop();
  if (["docx", "pdf"].includes(extension) && /(verslag|rapport|report)/.test(normalized)) return "report";
  if (["xlsx", "xls"].includes(extension) && /(sim|simkaart|sim card)/.test(normalized)) return "sim";
  if (extension === "csv" && /(gebruiker|user|utilisateur)/.test(normalized)) return "users";
  if (["png", "jpg", "jpeg", "webp"].includes(extension) && /(callflow|call flow|appel|keuzemenu|menu.*visual)/.test(normalized)) return "callflow";
  if (["txt", "md", "html", "htm"].includes(extension) && /(callflow|call flow|appel|keuzemenu|retranscription|transcript)/.test(normalized)) return "callflow_text";
  return "document";
}

function normalizeAutomaticCallflowText(value = "") {
  return String(value || "")
    .replace(/\r/g, "")
    .split("\n")
    .map((line) => line.replace(/[ \t]+/g, " ").trim())
    .filter(Boolean)
    .join("\n")
    .trim();
}

async function buildCallflowOcrTiles(imageBlob) {
  const bitmap = await createImageBitmap(imageBlob);
  const sourceTileWidth = Math.min(bitmap.width, Math.max(1100, Math.round(bitmap.height * 3.2)));
  const overlap = Math.min(140, Math.round(sourceTileWidth * 0.1));
  const scale = Math.max(2, Math.min(3, 1200 / Math.max(1, bitmap.height)));
  const tiles = [];
  for (let left = 0; left < bitmap.width; left += Math.max(1, sourceTileWidth - overlap)) {
    const width = Math.min(sourceTileWidth, bitmap.width - left);
    const canvas = document.createElement("canvas");
    canvas.width = Math.round(width * scale);
    canvas.height = Math.round(bitmap.height * scale);
    const context = canvas.getContext("2d", { willReadFrequently: true });
    context.imageSmoothingEnabled = true;
    context.imageSmoothingQuality = "high";
    context.drawImage(bitmap, left, 0, width, bitmap.height, 0, 0, canvas.width, canvas.height);
    tiles.push(canvas);
    if (left + width >= bitmap.width) break;
  }
  bitmap.close?.();
  return tiles;
}

async function extractAutomaticCallflowText(imageBlob, onProgress = () => {}) {
  if (!window.Tesseract?.createWorker) throw new Error("Moteur de retranscription automatique indisponible.");
  let worker = null;
  try {
    worker = await window.Tesseract.createWorker(["nld", "fra"], 1, {
      workerPath: "https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js",
      corePath: "https://cdn.jsdelivr.net/npm/tesseract.js-core@v6.0.0",
      langPath: "https://tessdata.projectnaptha.com/4.0.0_fast",
      logger() {}
    });
    await worker.setParameters({
      tessedit_pageseg_mode: window.Tesseract.PSM?.SPARSE_TEXT || "11",
      preserve_interword_spaces: "1"
    });
    const tiles = await buildCallflowOcrTiles(imageBlob);
    const parts = [];
    for (let index = 0; index < tiles.length; index += 1) {
      const tileOffset = index / tiles.length;
      const tileWeight = 1 / tiles.length;
      const result = await worker.recognize(tiles[index], {}, {
        text: true
      });
      const text = normalizeAutomaticCallflowText(result?.data?.text || "");
      if (text) parts.push(text);
      onProgress(Math.round((tileOffset + tileWeight) * 100));
    }
    return normalizeAutomaticCallflowText(parts.join("\n"));
  } finally {
    if (worker) await worker.terminate().catch(() => {});
  }
}

async function extractDocxInstallationText(arrayBuffer) {
  const docxZip = await window.JSZip.loadAsync(arrayBuffer);
  const documentEntry = docxZip.file("word/document.xml");
  if (!documentEntry) return "";
  const xmlText = await documentEntry.async("string");
  const xml = new DOMParser().parseFromString(xmlText, "application/xml");
  return [...xml.getElementsByTagNameNS("*", "p")]
    .map((paragraph) => [...paragraph.getElementsByTagNameNS("*", "t")].map((node) => node.textContent || "").join(""))
    .map((line) => normalizeImportCell(line))
    .filter(Boolean)
    .join("\n");
}

function installationZipSignature(file, entries = []) {
  return [
    normalizeImportCell(file?.name).toLowerCase(),
    String(file?.size || ""),
    ...entries.map((entry) => `${String(entry.name).toLowerCase()}:${entry.size || 0}`).sort()
  ].join("|");
}

function installationZipUnmatchedUserRows(rows = []) {
  return (Array.isArray(rows) ? rows : []).map(normalizeImportRow).map((row) => {
    const label = normalizeImportCell(readImportValue(row, ["first_name", "first name", "name"], ""));
    const phone = normalizeImportCell(readImportValue(row, ["primary_number", "primary number", "number"], ""));
    const email = normalizeImportCell(readImportValue(row, ["e_mail", "e-mail", "email"], ""));
    const alias = normalizeImportCell(readImportValue(row, ["primary_short_alias", "primary short alias", "short_alias", "primary_aliases", "primary aliases"], ""));
    if (alias || (!label && !phone && !email)) return null;
    const normalizedLabel = normalizeSearchText(label);
    let category = "A verifier manuellement";
    let explanation = "Aucun alias court ne permet de retrouver l'extension.";
    if (/^pb\b/.test(normalizedLabel)) {
      category = "Bouton panique";
      explanation = "PB est interprete comme Panic Button; emplacement a confirmer dans la configuration.";
    } else if (/pager\s+(malaise|evacuation)/.test(normalizedLabel)) {
      category = "Bouton panique";
      explanation = "Libelle Pager inhabituel, mais correspond aux deux boutons panique du magasin.";
    } else if (/^flash/.test(normalizedLabel)) {
      category = "Flashlight";
      explanation = "Correspond a un Flashlight; emplacement a confirmer dans la configuration.";
    } else if (normalizedLabel === "pager") {
      category = "Algo Pager";
      explanation = "Correspond au Pager principal; extension absente du CSV.";
    } else if (/ehbo/.test(normalizedLabel)) {
      category = "Poste fixe EHBO - a verifier";
      explanation = "La destination EHBO est reconnue, mais aucune extension fiable n'est fournie.";
    }
    return { label: label || "Ligne sans nom", phone, email, category, explanation };
  }).filter(Boolean);
}

function reconcileInstallationZipSimRowsWithUsers(store, simRows = [], userEntries = []) {
  const users = Array.isArray(userEntries) ? userEntries : [];
  return (Array.isArray(simRows) ? simRows : []).map((row) => {
    const target = normalizeSearchText(row.firstName || "");
    const candidates = target ? users.filter((entry) => {
      const label = normalizeSearchText(entry.label || "");
      return label && (label === target || label.includes(target) || target.includes(label));
    }) : [];
    const user = candidates.length === 1 ? candidates[0] : null;
    if (user?.extension) row.extension = user.extension;
    if (user?.phone && !row.phoneNumber) row.phoneNumber = user.phone;
    const match = findNetworkRowForPostInstallImport(store, row.extension, row.firstName);
    if (["matched", "matched_by_name"].includes(match.status)) {
      row.status = "matched";
      row.rowId = match.row.id || match.row.slotLabel || "";
      row.slotLabel = match.row.slotLabel || "";
      row.extensionLabel = match.row.extensionLabel || "";
      row.reason = match.status === "matched_by_name" ? "Associee par le nom du service" : "";
    } else if (row.status !== "ignored") {
      row.status = "unmatched_service";
      row.reason = row.extension
        ? "Extension recue et conservee; aucune ligne reseau correspondante"
        : (row.reason || "Service recu dans le ZIP mais non rattache automatiquement");
    }
    return row;
  });
}

function renderInstallationZipPreview(review = state.fieldInstallationZipReview) {
  if (!fieldInstallationZipPreview || !fieldInstallationZipApplyButton) return;
  fieldInstallationZipPreview.classList.remove("empty-state");
  if (!review) {
    fieldInstallationZipPreview.classList.add("empty-state");
    fieldInstallationZipPreview.innerHTML = "Aucun dossier ZIP charge.";
    fieldInstallationZipApplyButton.disabled = true;
    return;
  }
  const storeLabel = review.store ? storeOptionLabel(review.store) : "Magasin non reconnu";
  const alreadyImported = Boolean(review.duplicateImport);
  const archiveRetryOnly = Boolean(review.archiveRetryOnly);
  const ready = Boolean(review.store && !review.errors.length && (
    (review.reportText && !alreadyImported)
    || (alreadyImported && archiveRetryOnly && review.file)
  ));
  fieldInstallationZipApplyButton.disabled = !ready;
  fieldInstallationZipApplyButton.textContent = archiveRetryOnly
    ? "Reessayer l'archivage du ZIP"
    : "Appliquer l'import controle";
  fieldInstallationZipPreview.innerHTML = `
    <strong>${escapeHtml(storeLabel)}</strong>
    <p>${escapeHtml(review.file.name)} - ${review.entries.length} fichier(s) detecte(s).</p>
    <ul>
      ${review.entries.map((entry) => `<li><strong>${escapeHtml(entry.label)}</strong> : ${escapeHtml(entry.name)}${entry.detail ? ` - ${escapeHtml(entry.detail)}` : ""}</li>`).join("")}
    </ul>
    ${review.warnings.length ? `<div><strong>A verifier avant application</strong><ul>${review.warnings.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
    ${review.userUnmatchedRows?.length ? `<div class="installation-zip-unmatched">
      <strong>Lignes non reprises automatiquement</strong>
      <p>Elles restent visibles pour controle et ne sont pas injectees sans extension fiable.</p>
      ${review.userUnmatchedRows.map((row) => `<article class="installation-report-item">
        <div class="installation-report-meta"><strong>${escapeHtml(row.label)}</strong><span>${escapeHtml(row.category)}</span></div>
        <p>${escapeHtml([row.phone, row.email].filter(Boolean).join(" - ") || "Aucun numero ni e-mail")}</p>
        <p class="cell-note">${escapeHtml(row.explanation)}</p>
      </article>`).join("")}
    </div>` : ""}
    ${review.errors.length ? `<div><strong>Import bloque</strong><ul>${review.errors.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
    ${alreadyImported && archiveRetryOnly ? `<div class="empty-state"><strong>Les donnees metier sont deja importees. Seul l'archivage du ZIP complet reste a reessayer.</strong></div>` : ""}
    ${alreadyImported && !archiveRetryOnly ? `<div class="empty-state"><strong>Ce ZIP a deja ete importe. Aucune seconde ecriture ne sera effectuee.</strong></div>` : ""}
    ${ready ? `<p><strong>Previsualisation terminee.</strong> ${archiveRetryOnly ? "Clique pour reessayer uniquement le transfert de l'archive ZIP." : "Clique sur Appliquer l'import controle pour ecrire dans Appwrite."}</p>` : ""}
  `;
}

async function handleInstallationZipFileChange(event) {
  const input = event.currentTarget;
  const file = input?.files?.[0];
  if (!file) return;
  if (!window.JSZip) throw new Error("Bibliotheque ZIP indisponible.");
  if (!/\.zip$/i.test(file.name)) throw new Error("Choisis un dossier ZIP d'installation.");
  fieldInstallationZipPreview.classList.remove("empty-state");
  fieldInstallationZipPreview.innerHTML = "<p>Analyse du ZIP en cours, aucune donnee n'est encore ecrite.</p>";
  fieldInstallationZipApplyButton.disabled = true;
  const zip = await window.JSZip.loadAsync(file);
  const sourceEntries = Object.values(zip.files).filter((entry) => !entry.dir && !/(^|[\\/])(__MACOSX|\.DS_Store)/i.test(entry.name));
  const candidates = [findStoreForImportedFileName(file.name), ...sourceEntries.map((entry) => findStoreForImportedFileName(entry.name))].filter(Boolean);
  const uniqueStores = [...new Map(candidates.map((store) => [String(store.id), store])).values()];
  const store = uniqueStores.length === 1 ? uniqueStores[0] : null;
  const entries = [];
  const warnings = [];
  const errors = [];
  let reportText = "";
  let reportEntryName = "";
  let simRows = [];
  let userEntries = [];
  let userIgnoredCount = 0;
  let userUnmatchedRows = [];
  let callflowEntryName = "";
  let callflowText = "";
  let callflowOcrSource = null;
  let callflowPreviewEntry = null;
  for (const entry of sourceEntries) {
    const name = installationZipBaseName(entry.name);
    const kind = installationZipEntryKind(name);
    const size = Number(entry?._data?.uncompressedSize || 0);
    const previewEntry = { name, kind, size, label: "Document conserve", detail: "" };
    try {
      if (kind === "report") {
        previewEntry.label = "Rapport d'installation";
        reportEntryName ||= entry.name;
        if (/\.docx$/i.test(name)) {
          reportText ||= await extractDocxInstallationText(await entry.async("arraybuffer"));
          previewEntry.detail = reportText ? `${reportText.split("\n").length} ligne(s) lue(s)` : "texte non lisible";
        } else {
          previewEntry.detail = "PDF original conserve; extraction manuelle du texte si necessaire";
        }
      } else if (kind === "sim") {
        previewEntry.label = "Sheet SIM";
        const blob = await entry.async("blob");
        const nestedFile = new File([blob], name, { type: installationZipMimeType(name) });
        simRows = parseSimImportRows(readWorkbookRows(nestedFile, await blob.arrayBuffer()), { store, allowNewRows: false });
        const readyCount = simRows.filter((row) => row.status === "matched").length;
        const conservedCount = simRows.filter((row) => row.status === "unmatched_service").length;
        previewEntry.detail = `${readyCount}/${simRows.length} rattachee(s), ${conservedCount} conservee(s) a rattacher`;
      } else if (kind === "users") {
        previewEntry.label = "Utilisateurs telephonie";
        const userCsvText = await entry.async("string");
        const userSourceRows = parseDelimitedText(userCsvText);
        const parsedUserEntries = fieldUsersCsvEntries(userCsvText);
        const parsedUnmatchedRows = installationZipUnmatchedUserRows(userSourceRows);
        const entryKeys = new Set(userEntries.map((item) => `${item.extension}|${normalizeSearchText(item.label)}|${normalizeSearchText(item.phone)}`));
        parsedUserEntries.forEach((item) => {
          const key = `${item.extension}|${normalizeSearchText(item.label)}|${normalizeSearchText(item.phone)}`;
          if (!entryKeys.has(key)) {
            entryKeys.add(key);
            userEntries.push(item);
          }
        });
        const unmatchedKeys = new Set(userUnmatchedRows.map((item) => `${normalizeSearchText(item.label)}|${normalizeSearchText(item.phone)}|${normalizeSearchText(item.email)}`));
        parsedUnmatchedRows.forEach((item) => {
          const key = `${normalizeSearchText(item.label)}|${normalizeSearchText(item.phone)}|${normalizeSearchText(item.email)}`;
          if (!unmatchedKeys.has(key)) {
            unmatchedKeys.add(key);
            userUnmatchedRows.push(item);
          }
        });
        userIgnoredCount = userUnmatchedRows.length;
        previewEntry.detail = `${parsedUserEntries.length} extension(s) reconnue(s) dans ce fichier${parsedUnmatchedRows.length ? `, ${parsedUnmatchedRows.length} ligne(s) sans alias` : ""}`;
      } else if (kind === "callflow") {
        previewEntry.label = "Call Flow";
        callflowEntryName ||= entry.name;
        if (!callflowOcrSource) {
          callflowOcrSource = entry;
          callflowPreviewEntry = previewEntry;
        }
        previewEntry.detail = "image reconnue; retranscription automatique prevue";
      } else if (kind === "callflow_text") {
        previewEntry.label = "Retranscription du Call Flow";
        let text = await entry.async("string");
        if (/\.html?$/i.test(name)) text = text.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
        callflowText ||= String(text || "").trim();
        previewEntry.detail = callflowText ? `${callflowText.split("\n").length} ligne(s) lue(s)` : "texte vide";
      }
    } catch (error) {
      errors.push(`${name} : ${error.message || "lecture impossible"}`);
    }
    entries.push(previewEntry);
  }
  if (callflowOcrSource && !normalizeImportCell(callflowText)) {
    try {
      if (callflowPreviewEntry) callflowPreviewEntry.detail = "retranscription automatique en cours (0 %)";
      renderInstallationZipPreview({ file, store, entries, warnings, errors, userUnmatchedRows, duplicateImport: false });
      const callflowBlob = await callflowOcrSource.async("blob");
      callflowText = await extractAutomaticCallflowText(callflowBlob, (progress) => {
        if (callflowPreviewEntry) callflowPreviewEntry.detail = `retranscription automatique en cours (${progress} %)`;
        renderInstallationZipPreview({ file, store, entries, warnings, errors, userUnmatchedRows, duplicateImport: false });
      });
      if (callflowPreviewEntry) callflowPreviewEntry.detail = callflowText
        ? `image et retranscription automatique (${callflowText.split("\n").length} ligne(s))`
        : "image conservee; aucun texte lisible detecte";
      if (!callflowText) warnings.push("Le Call Flow a ete conserve, mais aucun texte lisible n'a pu etre retranscrit automatiquement.");
    } catch (error) {
      if (callflowPreviewEntry) callflowPreviewEntry.detail = "image conservee; retranscription automatique impossible";
      warnings.push(`Retranscription automatique du Call Flow impossible : ${error.message || "erreur OCR"}`);
    }
  }
  if (uniqueStores.length > 1) errors.push("Plusieurs magasins sont detectes dans le meme ZIP.");
  if (!store) errors.push("Le magasin n'a pas pu etre reconnu de facon unique.");
  if (!reportText) errors.push("Aucun rapport DOCX lisible n'a ete trouve dans ce ZIP.");
  if (!simRows.length) warnings.push("Aucun sheet SIM reconnu.");
  if (!userEntries.length) warnings.push("Aucun CSV utilisateurs reconnu.");
  else if (userIgnoredCount) warnings.push(`${userIgnoredCount} ligne(s) du CSV utilisateurs n'ont pas d'alias court et ne seront pas injectees automatiquement.`);
  if (!callflowEntryName) warnings.push("Aucune image Call Flow reconnue.");
  const signature = installationZipSignature(file, entries);
  const priorImport = store
    ? (ensureStoreWorkflowData(store).installationZipImports || []).find((item) => item.signature === signature)
    : null;
  const duplicateImport = Boolean(priorImport);
  const archiveRetryOnly = Boolean(priorImport && priorImport.archiveStatus === "failed" && !priorImport.archivePlanId);
  state.fieldInstallationZipReview = { file, zip, store, entries, warnings, errors, reportText, reportEntryName, simRows, userEntries, userIgnoredCount, userUnmatchedRows, callflowEntryName, callflowText, signature, duplicateImport, archiveRetryOnly, priorImport };
  renderInstallationZipPreview();
  if (input) input.value = "";
}

function applyInstallationZipUsers(store, entries = [], unmatchedEntries = []) {
  const workflow = ensureStoreWorkflowData(store);
  const networkRows = getNetworkConfigRows(store);
  const byExtension = new Map(networkRows.map((row) => [normalizeExtensionNumber(String(row.extensionLabel || "").split(" - ")[0]), row]).filter(([key]) => key));
  let matched = 0;
  const unmatched = [];
  entries.forEach(({ extension, label, phone }) => {
    let targetRow = byExtension.get(extension);
    if (!targetRow) {
      const catalogRow = fieldUsersCatalogRowForExtension(extension);
      targetRow = fieldUsersEmptyNetworkRow(networkRows, catalogRow);
      if (!targetRow) {
        unmatched.push(`${extension} - ${label || "-"}`);
        return;
      }
      targetRow.extensionLabel = catalogRow ? extensionReferenceMultilingualText(catalogRow) : `${extension} - ${label || "Extension importee"}`;
      byExtension.set(extension, targetRow);
    }
    targetRow.note = appendFieldNote(targetRow.note, [label, phone].filter(Boolean).join(" - "));
    matched += 1;
  });
  workflow.networkRows = networkRows;
  workflow.networkConfigConfirmed = workflow.networkConfigConfirmed || matched > 0;
  const directory = Array.isArray(workflow.postInstallExtensionDirectory)
    ? workflow.postInstallExtensionDirectory.filter((entry) => entry && typeof entry === "object")
    : [];
  const directoryKeys = new Set(directory.map((entry) => `${normalizeSearchText(entry.serviceName)}|${normalizeSearchText(entry.phoneNumber)}`));
  entries.forEach(({ extension, label, phone }, index) => {
    if (!label && !phone) return;
    const key = `${normalizeSearchText(label)}|${normalizeSearchText(phone)}`;
    if (directoryKeys.has(key)) return;
    directory.push({
      id: `zip-user-${safeDocumentId("directory", `${store.code}-${extension || index}-${label || phone}`)}`,
      serviceName: label || `Extension ${extension}`,
      phoneNumber: phone,
      importedExtension: extension,
      source: "CSV utilisateurs du ZIP installation",
      updatedAt: new Date().toISOString(),
      updatedBy: currentUser()?.name || state.activeUserName || "TWEM"
    });
    directoryKeys.add(key);
  });
  unmatchedEntries.forEach(({ label, phone, email }, index) => {
    if (!label && !phone && !email) return;
    const key = `${normalizeSearchText(label)}|${normalizeSearchText(phone)}`;
    if (directoryKeys.has(key)) return;
    directory.push({
      id: `zip-user-unmatched-${safeDocumentId("directory", `${store.code}-${index}-${label || phone || email}`)}`,
      serviceName: label || email || `Ligne utilisateur ${index + 1}`,
      phoneNumber: phone || "",
      email: email || "",
      importedExtension: "",
      source: "CSV utilisateurs du ZIP installation - sans alias court",
      updatedAt: new Date().toISOString(),
      updatedBy: currentUser()?.name || state.activeUserName || "TWEM"
    });
    directoryKeys.add(key);
  });
  workflow.postInstallExtensionDirectory = directory;
  return { matched, unmatched };
}

function applyInstallationZipSimRows(store, rows = []) {
  const workflow = ensureStoreWorkflowData(store);
  let matched = 0;
  let preserved = 0;
  const storeRows = rows.filter((row) => String(row.storeId) === String(store.id) && row.status !== "ignored");
  workflow.postInstallSimInventory = storeRows.map((row) => ({
    id: `zip-sim-${safeDocumentId("inventory", `${store.code}-${row.rowNumber}-${row.firstName}-${row.simCard}`)}`,
    rowNumber: row.rowNumber,
    serviceName: row.firstName,
    importedExtension: row.extension,
    phoneNumber: row.phoneNumber,
    servicePhoneNumber: row.servicePhoneNumber,
    simCard: row.simCard,
    pin: row.pin || "1111",
    puk: row.puk,
    puk2: row.puk2,
    rowId: row.rowId,
    status: row.status,
    reason: row.reason,
    source: "Sheet SIM du ZIP installation",
    updatedAt: new Date().toISOString(),
    updatedBy: currentUser()?.name || state.activeUserName || "TWEM"
  }));
  storeRows.filter((row) => row.status === "matched").forEach((row) => {
    let networkRow = getNetworkConfigRows(store).find((entry) => String(entry.id || entry.slotLabel || "") === String(row.rowId));
    if (!networkRow) return;
    const info = simInfoForNetworkRow(store, networkRow);
    const fillEmpty = (key, value, replaceDefaultPin = false) => {
      const incoming = normalizeSimImportValue(value);
      if (!incoming) return;
      const current = normalizeSimImportValue(info[key]);
      const replacePin = replaceDefaultPin && key === "pin" && current === "1111" && !info.source;
      if (!current || replacePin) info[key] = incoming;
      else if (current !== incoming) preserved += 1;
    };
    fillEmpty("serviceName", row.firstName);
    fillEmpty("importedExtension", row.extension);
    fillEmpty("phoneNumber", row.phoneNumber);
    fillEmpty("fixedPhoneNumber", row.servicePhoneNumber);
    fillEmpty("mobileNumber", row.phoneNumber);
    fillEmpty("simCard", row.simCard);
    fillEmpty("pin", row.pin, true);
    fillEmpty("puk", row.puk);
    fillEmpty("puk2", row.puk2);
    info.status ||= "Active";
    info.source ||= "Import ZIP installation";
    info.updatedAt = new Date().toISOString();
    info.updatedBy = currentUser()?.name || state.activeUserName || "TWEM";
    matched += 1;
  });
  return { matched, preserved };
}

async function saveInstallationZipArtifact(store, file, kind) {
  const workflow = ensureStoreWorkflowData(store);
  workflow.installationDocuments = Array.isArray(workflow.installationDocuments) ? workflow.installationDocuments : [];
  const incomingKey = planFileMergeKey({ name: file.name, fileSize: String(file.size || "") });
  const existing = workflow.installationDocuments.find((document) => planFileMergeKey(document) === incomingKey && document.installationKind === kind);
  if (existing) return { ...existing, duplicateSkipped: true };
  const entry = {
    id: safeDocumentId("installation-doc", `${store.code}-${kind}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`),
    name: file.name,
    fileType: file.type || installationZipMimeType(file.name),
    fileSize: String(file.size || ""),
    fileId: "",
    bucketId: "",
    dataUrl: "",
    updatedAt: new Date().toISOString(),
    installationKind: kind
  };
  if (hasRemoteData() && appwriteStorage && appwritePlansBucketId) {
    const fileId = safeDocumentId("installation", `${store.code}-${kind}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
    if (/^image\//i.test(entry.fileType)) await createAppwritePrevisitFile(appwritePlansBucketId, fileId, file);
    else await createAppwriteStorageFile(appwritePlansBucketId, fileId, file);
    entry.fileId = fileId;
    entry.bucketId = appwritePlansBucketId;
  } else {
    entry.dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result || ""));
      reader.onerror = () => reject(reader.error || new Error("Lecture du document impossible"));
      reader.readAsDataURL(file);
    });
  }
  workflow.installationDocuments.push(entry);
  return entry;
}

function installationImportWithTimeout(promise, label, timeoutMs = 45000) {
  let timeoutId = null;
  const timeout = new Promise((_, reject) => {
    timeoutId = window.setTimeout(() => reject(new Error(`${label} n'a pas repondu apres ${Math.round(timeoutMs / 1000)} secondes.`)), timeoutMs);
  });
  return Promise.race([Promise.resolve(promise), timeout]).finally(() => window.clearTimeout(timeoutId));
}

function setInstallationImportProgress(message) {
  if (!fieldInstallationZipPreview) return;
  let status = fieldInstallationZipPreview.querySelector("[data-installation-import-progress]");
  if (!status) {
    fieldInstallationZipPreview.insertAdjacentHTML("afterbegin", '<p data-installation-import-progress><strong></strong></p>');
    status = fieldInstallationZipPreview.querySelector("[data-installation-import-progress]");
  }
  const strong = status?.querySelector("strong");
  if (strong) strong.textContent = message;
}

async function handleInstallationZipApply() {
  const review = state.fieldInstallationZipReview;
  if (!review?.store || review.errors.length || (review.duplicateImport && !review.archiveRetryOnly)) return;
  const store = state.stores.find((item) => String(item.id) === String(review.store.id));
  if (!store) throw new Error("Magasin introuvable au moment de l'application.");
  try {
  fieldInstallationZipApplyButton.disabled = true;
  if (review.archiveRetryOnly) {
    setInstallationImportProgress("Nouvelle tentative d'archivage du ZIP dans Appwrite...");
    const workflow = ensureStoreWorkflowData(store);
    const priorImport = (workflow.installationZipImports || []).find((item) => item.signature === review.signature);
    if (!priorImport) throw new Error("Trace de l'import initial introuvable.");
    const archive = await installationImportWithTimeout(saveInstallationZipArtifact(store, review.file, "installation_zip"), "Archivage du ZIP");
    priorImport.archivePlanId = archive.id;
    priorImport.archiveStatus = "archived";
    priorImport.archiveError = "";
    priorImport.archivedAt = new Date().toISOString();
    const report = (workflow.installationReports || []).find((item) => item.id === priorImport.reportId);
    if (report && !report.sourceArchivePlanId) report.sourceArchivePlanId = archive.id;
    store.updatedAt = new Date().toISOString();
    saveState();
    if (hasRemoteData()) {
      await installationImportWithTimeout(syncStoreToRemote(store, `Archivage differe ZIP installation - ${review.file.name}`), "Sauvegarde de l'archive ZIP");
    }
    recordImportExportHistory("import", "Archive ZIP installation", `${storeOptionLabel(store)} - archivage differe OK`);
    state.fieldInstallationZipReview = null;
    renderInstallationZipPreview();
    window.alert(`Archive ZIP ajoutee dans ${storeOptionLabel(store)}. Les donnees metier n'ont pas ete reimportees.`);
    render();
    return;
  }
  setInstallationImportProgress("Preparation de l'import...");
  const workflow = ensureStoreWorkflowData(store);
  workflow.installationReports ||= [];
  workflow.installationZipImports ||= [];
  if (workflow.installationZipImports.some((item) => item.signature === review.signature)) throw new Error("Ce ZIP a deja ete importe.");
  let callflow = null;
  if (review.callflowEntryName) {
    const source = review.zip.file(review.callflowEntryName);
    const blob = await source.async("blob");
    const name = installationZipBaseName(review.callflowEntryName);
    setInstallationImportProgress("Archivage du Call Flow...");
    callflow = await installationImportWithTimeout(saveInstallationZipArtifact(store, new File([blob], name, { type: installationZipMimeType(name) }), "callflow"), "Archivage du Call Flow");
  }
  if (normalizeImportCell(review.callflowText || "") && !appwriteCallflowsCollectionId) {
    if (!normalizeImportCell(workflow.callflowTranscription || "")) workflow.callflowTranscription = review.callflowText;
    else if (normalizeImportCell(workflow.callflowTranscription) !== normalizeImportCell(review.callflowText)) {
      review.warnings.push("Retranscription Call Flow existante conservee.");
    }
  }
  const reportKey = installationReportMergeKey(review.reportText);
  let report = workflow.installationReports.find((item) => installationReportMergeKey(item?.text || "") === reportKey);
  let createdSavTickets = [];
  let queuedEmail = null;
  if (!report) {
    const hasOpenActions = /(openstaande actiepunten|fnp|definitieve nummerportering|action(?:s)? restante)/i.test(review.reportText);
    report = {
      id: `installation-report-${Date.now()}`,
      text: review.reportText,
      author: currentUser()?.name || state.activeUserName || "TWEM",
      createdAt: new Date().toISOString(),
      status: hasOpenActions ? "partial" : "completed",
      completed: !hasOpenActions,
      sourceFileName: installationZipBaseName(review.reportEntryName),
      sourceArchivePlanId: "",
      callflowPlanId: callflow?.id || ""
    };
    workflow.installationReports.unshift(report);
    createdSavTickets = createSavTicketsFromFieldReport(store, review.reportText, report);
    queuedEmail = queueFieldReportSavEmail(store, createdSavTickets, report);
  }
  const usersResult = applyInstallationZipUsers(store, review.userEntries, review.userUnmatchedRows);
  review.simRows = reconcileInstallationZipSimRowsWithUsers(store, review.simRows, review.userEntries);
  const simResult = applyInstallationZipSimRows(store, review.simRows);
  const importRecord = {
    id: `installation-zip-import-${Date.now()}`,
    signature: review.signature,
    fileName: review.file.name,
    archivePlanId: "",
    archiveStatus: "pending",
    archiveError: "",
    reportId: report?.id || "",
    callflowPlanId: callflow?.id || "",
    userRows: usersResult.matched,
    simRows: simResult.matched,
    importedAt: new Date().toISOString(),
    importedBy: currentUser()?.name || state.activeUserName || "TWEM"
  };
  workflow.installationZipImports.unshift(importRecord);
  syncStoreDoneFromInstallationReports(store);
  store.updatedAt = new Date().toISOString();
  let archiveWarning = "";
  setInstallationImportProgress("Archivage du ZIP complet dans Appwrite...");
  try {
    const archive = await installationImportWithTimeout(saveInstallationZipArtifact(store, review.file, "installation_zip"), "Archivage du ZIP");
    importRecord.archivePlanId = archive.id;
    importRecord.archiveStatus = "archived";
    importRecord.archivedAt = new Date().toISOString();
    if (report && !report.sourceArchivePlanId) report.sourceArchivePlanId = archive.id;
  } catch (archiveError) {
    importRecord.archiveStatus = "failed";
    importRecord.archiveError = normalizeImportCell(archiveError?.message || "Echec du transfert de l'archive ZIP");
    archiveWarning = importRecord.archiveError;
    console.error("Archivage ZIP non bloquant", archiveError);
  }
  saveState();
  if (hasRemoteData()) {
    setInstallationImportProgress("Sauvegarde principale du magasin...");
    await installationImportWithTimeout(syncStoreToRemote(store, `Import ZIP installation complet - ${review.file.name}`), "Sauvegarde principale du magasin");
    if (callflow || normalizeImportCell(review.callflowText || "")) {
      setInstallationImportProgress("Indexation du Call Flow...");
      await installationImportWithTimeout(upsertCallflowToRemote(store, review.callflowText || "", callflow), "Indexation du Call Flow", 30000);
    }
    const secondaryTasks = [];
    if (createdSavTickets.length) secondaryTasks.push(installationImportWithTimeout(syncSavStateToRemote(), "Sauvegarde des SAV", 20000));
    if (queuedEmail) {
      secondaryTasks.push(installationImportWithTimeout(executeFieldReportSavMailFunction(queuedEmail), "Envoi de l'alerte SAV", 20000));
    }
    if (secondaryTasks.length) {
      const results = await Promise.allSettled(secondaryTasks);
      results.filter((result) => result.status === "rejected").forEach((result) => console.error("Tache secondaire import ZIP", result.reason));
    }
  }
  recordImportExportHistory("import", "ZIP installation complet", `${storeOptionLabel(store)} - rapport ${report ? "OK" : "absent"} / ${usersResult.matched} users / ${simResult.matched} SIM`);
  if (archiveWarning) {
    review.duplicateImport = true;
    review.archiveRetryOnly = true;
    review.priorImport = importRecord;
    renderInstallationZipPreview(review);
  } else {
    state.fieldInstallationZipReview = null;
    renderInstallationZipPreview();
  }
  window.alert(`ZIP importe dans ${storeOptionLabel(store)}. Rapport: OK. Users: ${usersResult.matched}. SIM: ${simResult.matched}.${usersResult.unmatched.length ? ` ${usersResult.unmatched.length} extension(s) a verifier.` : ""}${simResult.preserved ? ` ${simResult.preserved} valeur(s) existante(s) conservee(s).` : ""}${archiveWarning ? ` Les donnees sont sauvegardees; seule l'archive ZIP n'a pas ete transferee (${archiveWarning}). Tu peux reessayer l'archive sans reimporter les donnees.` : " Archive ZIP: OK."}`);
  render();
  } catch (error) {
    renderInstallationZipPreview(review);
    if (fieldInstallationZipApplyButton) fieldInstallationZipApplyButton.disabled = false;
    setInstallationImportProgress(`Import interrompu : ${error.message || "erreur inconnue"}`);
    throw error;
  }
}

async function handleFieldReportSave() {
  const searchedStore = findStoreFromReportSearch(fieldReportStoreSearchInput?.value || "");
  const store = searchedStore || state.stores.find((item) => String(item.id) === String(fieldReportStoreSelect?.value || ""));
  const text = fieldReportTextInput?.value.trim() || "";
  if (!store || !text) {
    window.alert("Choisis un magasin clair et colle le texte du rapport.");
    return;
  }
  if (fieldReportStoreSelect) {
    fieldReportStoreSelect.value = String(store.id);
  }
  const workflow = ensureStoreWorkflowData(store);
  workflow.installationReports ||= [];
  const reportKey = installationReportMergeKey(text);
  const alreadyExists = workflow.installationReports.some((report) => installationReportMergeKey(report?.text || "") === reportKey);
  if (alreadyExists) {
    window.alert("Ce rapport installation est deja present dans la fiche magasin.");
    return;
  }
  const report = {
    id: `installation-report-${Date.now()}`,
    text,
    author: currentUser()?.name || state.activeUserName || "TWEM",
    createdAt: new Date().toISOString(),
    status: installationReportHasOpenActions(text) ? "partial" : "completed",
    completed: !installationReportHasOpenActions(text)
  };
  workflow.installationReports.unshift(report);
  syncStoreDoneFromInstallationReports(store);
  const createdSavTickets = createSavTicketsFromFieldReport(store, text, report);
  const queuedEmail = queueFieldReportSavEmail(store, createdSavTickets, report);
  ensureAutomationEmailDrafts();
  let fieldReportMailStatus = queuedEmail ? "prepare" : "";
  store.updatedAt = new Date().toISOString();
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, "Rapport installation ajoute");
    if (createdSavTickets.length) {
      await syncSavStateToRemote();
    }
    if (queuedEmail) {
      try {
        await executeFieldReportSavMailFunction(queuedEmail);
        fieldReportMailStatus = "envoye";
      } catch (error) {
        console.error("Erreur envoi mail rapport installation", error);
        queuedEmail.error = error.message;
        queuedEmail.updatedAt = new Date().toISOString();
        saveState();
      }
    }
  }
  recordImportExportHistory("import", "Rapport installation", storeOptionLabel(store));
  if (fieldReportStoreSearchInput) {
    fieldReportStoreSearchInput.value = storeOptionLabel(store);
  }
  fieldReportTextInput.value = "";
  const savMessage = createdSavTickets.length
    ? ` ${createdSavTickets.length} SAV cree(s) avec demandeur Installateur centrale.${fieldReportMailStatus === "envoye" ? " Mail Emir/Valou envoye." : fieldReportMailStatus === "prepare" ? " Mail Emir/Valou prepare." : ""}`
    : "";
  window.alert(`Rapport enregistre dans la fiche magasin.${savMessage}`);
  render();
}

function renderFieldUsersPreview(result) {
  if (!fieldUsersPreview || !result) return;
  fieldUsersPreview.classList.remove("empty-state");
  fieldUsersPreview.innerHTML = `
    <strong>${escapeHtml(result.storeLabel)}</strong>
    <p>${result.matched.length} ligne(s) injectee(s), ${result.unmatched.length} a verifier.</p>
    ${result.matched.length ? `<div><strong>Injectees</strong><ul>${result.matched.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
    ${result.unmatched.length ? `<div><strong>A verifier</strong><ul>${result.unmatched.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
    ${result.unmatched.length && result.storeId ? `<button type="button" class="mini-button field-review-button" data-field-users-review-store="${escapeHtml(String(result.storeId))}">Ouvrir la fiche et verifier</button>` : ""}
  `;
  fieldUsersPreview.querySelector("[data-field-users-review-store]")?.addEventListener("click", openFieldUsersReviewStore);
}

function fieldUsersUnmatchedExtensions(lines = []) {
  return [...new Set(lines
    .map((line) => normalizeExtensionNumber(String(line || "").split(" - ")[0]))
    .filter(Boolean))];
}

function fieldUsersCatalogRowForExtension(extension = "") {
  const target = normalizeExtensionNumber(extension);
  if (!target) return null;
  return selectableExtensionCatalogRows().find((row) => normalizeExtensionNumber(row.number) === target) || null;
}

function fieldUsersEmptyNetworkRow(networkRows = [], catalogRow = null) {
  const targetCategory = catalogRow ? extensionDisplayCategoryKey(catalogRow) : "";
  const emptyRows = networkRows.filter((row) => !normalizeImportCell(row.extensionLabel));
  if (!emptyRows.length) return null;
  if (targetCategory) {
    const categoryMatch = emptyRows.find((row) => {
      const rowCategory = extensionCategoryKey(row.category);
      if (targetCategory === "fixed") return rowCategory === "fixed";
      if (targetCategory === "mobile") return rowCategory === "mobile";
      if (targetCategory === "call") return rowCategory === "call";
      if (targetCategory === "panic") return rowCategory === "panic";
      if (targetCategory === "flash") return rowCategory === "flash";
      return false;
    });
    if (categoryMatch) return categoryMatch;
  }
  return emptyRows[0];
}

function fieldUsersCsvEntries(text = "") {
  return parseDelimitedText(text)
    .map(normalizeImportRow)
    .map((row) => {
      const label = normalizeImportCell(readImportValue(row, ["first_name", "first name", "name"], ""));
      const phone = normalizeImportCell(readImportValue(row, ["primary_number", "primary number", "number"], ""));
      const alias = normalizeImportCell(readImportValue(row, ["primary_short_alias", "primary short alias", "short_alias", "primary_aliases", "primary aliases"], ""));
      const extension = normalizeExtensionNumber(alias.slice(-3));
      return {
        extension,
        label,
        phone,
        note: [label, phone].filter(Boolean).join(" - ")
      };
    })
    .filter((entry) => entry.extension);
}

function removeFieldNotePart(current = "", addition = "") {
  const cleanAddition = normalizeImportCell(addition);
  if (!cleanAddition) return current || "";
  return normalizeImportCell(current)
    .split("|")
    .map((part) => normalizeImportCell(part))
    .filter((part) => part && part !== cleanAddition)
    .join(" | ");
}

function openFieldUsersReviewStore(event) {
  const storeId = Number(event.currentTarget.getAttribute("data-field-users-review-store"));
  const store = state.stores.find((item) => item.id === storeId);
  if (!store) return;
  state.activeAdminTab = "configuration";
  state.filters.search = store.code || store.name || "";
  if (searchInput) {
    searchInput.value = state.filters.search;
  }
  state.expandedStoreIds = new Set([store.id]);
  saveState();
  render();
  window.setTimeout(() => {
    document.querySelector(`[data-store-editor="${store.id}"] .field-users-review-box`)?.scrollIntoView({ behavior: "smooth", block: "center" });
  }, 80);
}

async function handleFieldUsersFileChange(event) {
  const input = event.currentTarget;
  const file = input?.files?.[0];
  const searchedStore = findStoreFromReportSearch(fieldUsersStoreSearchInput?.value || "");
  const store = searchedStore || state.stores.find((item) => String(item.id) === String(fieldUsersStoreSelect?.value || ""));
  if (!file || !store) return;
  if (fieldUsersStoreSelect) {
    fieldUsersStoreSelect.value = String(store.id);
  }
  const text = await file.text();
  const entries = fieldUsersCsvEntries(text);
  const workflow = ensureStoreWorkflowData(store);
  const networkRows = getNetworkConfigRows(store);
  const byExtension = new Map(networkRows.map((row) => [normalizeExtensionNumber(String(row.extensionLabel || "").split(" - ")[0]), row]).filter(([key]) => key));
  const matched = [];
  const unmatched = [];

  entries.forEach(({ extension, label, phone }) => {
    const targetRow = byExtension.get(extension);
    if (!targetRow) {
      const catalogRow = fieldUsersCatalogRowForExtension(extension);
      const emptyRow = fieldUsersEmptyNetworkRow(networkRows, catalogRow);
      if (!emptyRow) {
        unmatched.push(`${extension} - ${label || "-"} - ${phone || "-"}`);
        return;
      }
      emptyRow.extensionLabel = catalogRow ? extensionReferenceMultilingualText(catalogRow) : `${extension} - ${label || "Extension importee"}`;
      emptyRow.note = appendFieldNote(emptyRow.note, [label, phone].filter(Boolean).join(" - "));
      byExtension.set(extension, emptyRow);
      matched.push(`${extension} - ${label || emptyRow.slotLabel || "-"} - ${phone || "-"} (ajoutee dans ${emptyRow.slotLabel || "ligne vide"})`);
      return;
    }
    targetRow.note = appendFieldNote(targetRow.note, [label, phone].filter(Boolean).join(" - "));
    matched.push(`${extension} - ${label || targetRow.slotLabel || "-"} - ${phone || "-"}`);
  });

  workflow.networkRows = networkRows;
  workflow.networkConfigConfirmed = workflow.networkConfigConfirmed || matched.length > 0;
  store.updatedAt = new Date().toISOString();
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, `Import users telephonie - ${matched.length} ligne(s)`);
  }
  state.fieldUsersReview = {
    storeId: store.id,
    storeLabel: storeOptionLabel(store),
    unmatched,
    extensions: fieldUsersUnmatchedExtensions(unmatched),
    createdAt: new Date().toISOString()
  };
  const result = { storeId: store.id, storeLabel: storeOptionLabel(store), matched, unmatched };
  renderFieldUsersPreview(result);
  recordImportExportHistory("import", "Import users telephonie", `${storeOptionLabel(store)} - ${matched.length} OK / ${unmatched.length} a verifier`);
  if (fieldUsersStoreSearchInput) {
    fieldUsersStoreSearchInput.value = storeOptionLabel(store);
  }
  if (input) {
    input.value = "";
  }
}

async function handleFieldUsersRemoveFileChange(event) {
  const input = event.currentTarget;
  const file = input?.files?.[0];
  const searchedStore = findStoreFromReportSearch(fieldUsersStoreSearchInput?.value || "");
  const store = searchedStore || state.stores.find((item) => String(item.id) === String(fieldUsersStoreSelect?.value || ""));
  if (!file || !store) return;
  if (fieldUsersStoreSelect) {
    fieldUsersStoreSelect.value = String(store.id);
  }
  const entries = fieldUsersCsvEntries(await file.text());
  if (!entries.length) {
    window.alert("Aucune extension reconnue dans ce CSV.");
    if (input) input.value = "";
    return;
  }
  const shouldClearLikelyAutoRows = window.confirm("Retirer aussi les extensions ajoutees automatiquement dans les lignes vides par ce CSV ?");
  const workflow = ensureStoreWorkflowData(store);
  const networkRows = getNetworkConfigRows(store);
  const byExtension = new Map(networkRows.map((row) => [normalizeExtensionNumber(String(row.extensionLabel || "").split(" - ")[0]), row]).filter(([key]) => key));
  const removedNotes = [];
  const clearedRows = [];
  const untouched = [];

  entries.forEach((entry) => {
    const row = byExtension.get(entry.extension);
    if (!row) {
      untouched.push(`${entry.extension} - deja absent`);
      return;
    }
    const beforeNote = normalizeImportCell(row.note);
    row.note = removeFieldNotePart(row.note, entry.note);
    if (beforeNote !== normalizeImportCell(row.note)) {
      removedNotes.push(`${entry.extension} - ${entry.label || row.slotLabel || "-"} - ${entry.phone || "-"}`);
    }
    const defaultExtension = normalizeImportCell(defaultNetworkExtensionForRow(row));
    const canClearExtension = shouldClearLikelyAutoRows
      && !defaultExtension
      && normalizeExtensionNumber(String(row.extensionLabel || "").split(" - ")[0]) === entry.extension
      && !normalizeImportCell(row.note);
    if (canClearExtension) {
      row.extensionLabel = "";
      clearedRows.push(`${entry.extension} - ${row.slotLabel || "ligne vide"}`);
      byExtension.delete(entry.extension);
    }
  });

  workflow.networkRows = networkRows;
  store.updatedAt = new Date().toISOString();
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, `Retrait import users telephonie - ${removedNotes.length + clearedRows.length} ligne(s)`);
  }
  state.fieldUsersReview = null;
  renderFieldUsersPreview({
    storeId: store.id,
    storeLabel: storeOptionLabel(store),
    matched: [
      ...removedNotes.map((line) => `${line} (note retiree)`),
      ...clearedRows.map((line) => `${line} (ligne videe)`)
    ],
    unmatched: untouched
  });
  recordImportExportHistory("import", "Retrait users telephonie", `${storeOptionLabel(store)} - ${removedNotes.length} note(s) / ${clearedRows.length} ligne(s) videe(s)`);
  if (fieldUsersStoreSearchInput) {
    fieldUsersStoreSearchInput.value = storeOptionLabel(store);
  }
  if (input) {
    input.value = "";
  }
}

async function savePlanFileForStore(store, planFile) {
  const workflow = ensureStoreWorkflowData(store);
  const isZip = /\.zip$/i.test(planFile.name) || planFile.type === "application/zip" || planFile.type === "application/x-zip-compressed";
  const isImage = /^image\//i.test(planFile.type) || /\.(png|jpe?g|webp|heic)$/i.test(planFile.name);
  const updatedAt = new Date().toISOString();
  const existingPlans = getStorePlanFilesFromWorkflow(workflow);
  const incomingKey = planFileMergeKey({
    name: planFile.name,
    fileSize: String(planFile.size || "")
  });
  const existingPlan = existingPlans.find((plan) => planFileMergeKey(plan) === incomingKey);
  if (existingPlan) {
    return { ...existingPlan, duplicateSkipped: true };
  }
  const planEntry = {
    id: safeDocumentId("plan-doc", `${store.code || store.id}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`),
    name: planFile.name,
    fileType: isZip ? "application/zip" : isImage ? (planFile.type || "image/*") : (planFile.type || "application/pdf"),
    fileSize: String(planFile.size || ""),
    fileId: "",
    bucketId: "",
    dataUrl: "",
    updatedAt
  };
  if (hasRemoteData() && appwriteStorage && appwritePlansBucketId) {
    const fileId = safeDocumentId("plan", `${store.code || store.id}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
    if (isImage) {
      await createAppwritePrevisitFile(appwritePlansBucketId, fileId, planFile);
    } else {
      await createAppwriteStorageFile(appwritePlansBucketId, fileId, planFile);
    }
    planEntry.fileId = fileId;
    planEntry.bucketId = appwritePlansBucketId;
  } else {
    planEntry.dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result || ""));
      reader.onerror = () => reject(reader.error || new Error("Lecture plan impossible"));
      reader.readAsDataURL(planFile);
    });
  }
  workflow.planFiles = [...existingPlans, normalizeStorePlanFile(planEntry)];
  syncLegacyPlanFieldsFromList(workflow);
  store.updatedAt = updatedAt;
  if (hasRemoteData()) {
    await syncStoreToRemote(store, `Import plan magasin - ${planFile.name}`);
  }
  return planEntry;
}

async function handleFieldPlansFileChange(event) {
  const input = event.currentTarget;
  const file = input?.files?.[0];
  if (!file) return;
  if (fieldPlansPreview) {
    fieldPlansPreview.classList.remove("empty-state");
    fieldPlansPreview.innerHTML = "<p>Import des plans en cours...</p>";
  }
  if (!window.JSZip) {
    window.alert("Bibliotheque ZIP indisponible.");
    return;
  }
  const zip = await window.JSZip.loadAsync(file);
  const files = Object.values(zip.files).filter((entry) => !entry.dir && /\.(pdf|zip)$/i.test(entry.name));
  const matched = [];
  const unmatched = [];
  const errors = [];
  for (const entry of files) {
    const store = findStoreForImportedFileName(entry.name);
    if (!store) {
      unmatched.push(entry.name);
      continue;
    }
    try {
      const blob = await entry.async("blob");
      const planFile = new File([blob], entry.name.split(/[\\/]/).pop(), { type: /\.zip$/i.test(entry.name) ? "application/zip" : "application/pdf" });
      await savePlanFileForStore(store, planFile);
      matched.push(`${storeOptionLabel(store)} -> ${planFile.name}`);
    } catch (error) {
      console.error("Import plan ZIP error", entry.name, error);
      errors.push(`${entry.name} - ${error.message || "erreur inconnue"}`);
    }
  }
  if (!matched.length) {
    const storeFromZipName = findStoreForImportedFileName(file.name);
    if (storeFromZipName) {
      try {
        const planFile = new File([file], file.name, { type: "application/zip" });
        await savePlanFileForStore(storeFromZipName, planFile);
        matched.push(`${storeOptionLabel(storeFromZipName)} -> ${planFile.name}`);
      } catch (error) {
        console.error("Import ZIP complet error", file.name, error);
        errors.push(`${file.name} - ${error.message || "erreur inconnue"}`);
      }
    }
  }
  if (!files.length && !matched.length) {
    unmatched.push(`${file.name} - aucun PDF ou ZIP reconnu dans l'archive`);
  }
  saveState();
  if (fieldPlansPreview) {
    fieldPlansPreview.classList.remove("empty-state");
    fieldPlansPreview.innerHTML = `
      <p>${matched.length} plan(s) associe(s), ${unmatched.length} fichier(s) non reconnu(s), ${errors.length} erreur(s).</p>
      ${matched.length ? `<div><strong>Associes</strong><ul>${matched.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
      ${unmatched.length ? `<div><strong>A verifier</strong><ul>${unmatched.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
      ${errors.length ? `<div><strong>Erreurs</strong><ul>${errors.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul></div>` : ""}
    `;
  }
  recordImportExportHistory("import", "Import plans ZIP", `${matched.length} associe(s) / ${unmatched.length} non reconnu(s) / ${errors.length} erreur(s)`);
  if (input) {
    input.value = "";
  }
  render();
}

function csvEscape(value) {
  const stringValue = String(value ?? "");
  if (/[",;\n]/.test(stringValue)) {
    return `"${stringValue.replaceAll('"', '""')}"`;
  }
  return stringValue;
}

function buildCsv(rows) {
  return rows.map((row) => row.map(csvEscape).join(";")).join("\n");
}

function xlsxAvailable() {
  return typeof window.XLSX !== "undefined";
}

function pdfAvailable() {
  return Boolean(window.jspdf?.jsPDF);
}
document.documentElement.dataset.pdfEngine = pdfAvailable() ? "ready" : "missing";

function zipAvailable() {
  return typeof window.JSZip !== "undefined";
}

function sanitizeFileNamePart(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9-_]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 80) || "fiche";
}

function exportRowsToXlsx(rows, fileName, sheetName) {
  if (!xlsxAvailable()) {
    throw new Error("Bibliotheque XLSX indisponible.");
  }
  const worksheet = window.XLSX.utils.aoa_to_sheet(rows);
  const workbook = window.XLSX.utils.book_new();
  window.XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);
  window.XLSX.writeFile(workbook, fileName);
}

function exportRowsToPdf(title, headers, bodyRows, fileName) {
  if (!pdfAvailable()) {
    throw new Error("Bibliotheque PDF indisponible.");
  }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });
  doc.setFont("helvetica", "bold");
  doc.setFontSize(18);
  doc.text(title, 14, 16);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text(`Genere le ${formatDateTime(new Date().toISOString())}`, 14, 23);
  doc.autoTable({
    head: [headers],
    body: bodyRows,
    startY: 28,
    styles: { fontSize: 8, cellPadding: 2 },
    headStyles: { fillColor: [255, 243, 174], textColor: [50, 50, 50] },
    margin: { left: 10, right: 10 }
  });
  doc.save(fileName);
}

function readWorkbookRows(file, arrayBuffer) {
  if (!xlsxAvailable()) {
    throw new Error("Bibliotheque XLSX indisponible.");
  }
  const workbook = window.XLSX.read(arrayBuffer, { type: "array", cellDates: true });
  const sheetName = workbook.SheetNames[0];
  const worksheet = workbook.Sheets[sheetName];
  return window.XLSX.utils.sheet_to_json(worksheet, { defval: "" });
}

function readExtensionWorkbookRows(arrayBuffer) {
  if (!xlsxAvailable()) {
    throw new Error("Bibliotheque XLSX indisponible.");
  }
  const workbook = window.XLSX.read(arrayBuffer, { type: "array" });
  const sheetName = workbook.SheetNames[0];
  const worksheet = workbook.Sheets[sheetName];
  const matrix = window.XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: "" });
  if (!Array.isArray(matrix) || matrix.length < 2) {
    return [];
  }

  const normalizeHeaderKey = (value) => normalizeImportCell(value)
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
  const looksLikeExtensionHeader = (row) => {
    const keys = (row || []).map(normalizeHeaderKey);
    return keys.includes("categorie")
      && keys.includes("modele")
      && keys.includes("numero")
      && (keys.includes("libelle fr") || keys.includes("libelle") || keys.includes("last name*"));
  };

  const headerIndex = looksLikeExtensionHeader(matrix[0])
    ? 0
    : (looksLikeExtensionHeader(matrix[1]) ? 1 : 0);
  const headerRow = (matrix[headerIndex] || []).map((value) => normalizeImportCell(value));

  return matrix
    .slice(headerIndex + 1)
    .filter((row) => Array.isArray(row) && row.some((cell) => normalizeImportCell(cell) !== ""))
    .map((row) => {
      const entry = {};
      headerRow.forEach((header, index) => {
        if (header) {
          entry[header] = row[index] ?? "";
        }
      });
      return entry;
    });
}

