async function safeRunImport(action, label = "Import") {
  try {
    await action();
    renderImportExportHistory();
  } catch (error) {
    console.error(`${label} error`, error);
    window.alert(`${label} impossible: ${error.message || "erreur inconnue"}`);
  }
}

