function handleStorePlanOpen(event) {
  const storeId = Number(event.currentTarget.getAttribute("data-plan-open"));
  const planDocId = event.currentTarget.getAttribute("data-plan-doc-id") || "";
  const store = state.stores.find((item) => item.id === storeId);
  const workflow = store ? ensureStoreWorkflowData(store) : null;
  const planFiles = workflow ? getStorePlanFilesFromWorkflow(workflow) : [];
  const plan = planFiles.find((item) => item.id === planDocId) || planFiles[planFiles.length - 1];
  if (!plan?.dataUrl && !plan?.fileId) {
    window.alert("Aucun document n'est enregistre pour ce magasin.");
    return;
  }
  const isZipPlan = planFileIsZip(plan);
  if (plan.fileId) {
    const url = appwriteStorageFileUrl(plan.fileId, isZipPlan ? "download" : "view");
    if (!url) {
      window.alert("Impossible de construire le lien Appwrite Storage.");
      return;
    }
    const openedWindow = window.open(url, "_blank");
    if (!openedWindow) {
      window.location.href = url;
    }
    return;
  }
  const blob = dataUrlToBlob(plan.dataUrl);
  if (isZipPlan) {
    if (blob) {
      downloadBlob(blob, plan.name || `plans-${store?.code || storeId}.zip`);
      return;
    }
    window.alert("Impossible de telecharger ce ZIP.");
    return;
  }
  const pdfWindow = window.open(plan.dataUrl, "_blank");
  if (!pdfWindow && blob) {
    downloadBlob(blob, plan.name || `plan-${store?.code || storeId}.pdf`);
  } else if (!pdfWindow) {
    window.alert("Impossible d'ouvrir ou de telecharger ce document.");
  }
}

async function handleStorePlanDelete(event) {
  const storeId = Number(event.currentTarget.getAttribute("data-plan-delete"));
  const planDocId = event.currentTarget.getAttribute("data-plan-doc-id") || "";
  const store = state.stores.find((item) => item.id === storeId);
  if (!store) {
    return;
  }
  const workflow = ensureStoreWorkflowData(store);
  const planFiles = getStorePlanFilesFromWorkflow(workflow);
  const targetPlan = planFiles.find((plan) => plan.id === planDocId) || planFiles[planFiles.length - 1];
  if (!targetPlan) {
    window.alert("Aucun document n'est enregistre pour ce magasin.");
    return;
  }
  workflow.planFiles = planFiles.filter((plan) => plan.id !== targetPlan.id);
  syncLegacyPlanFieldsFromList(workflow);
  store.updatedAt = new Date().toISOString();
  setStoreSaveFeedback(storeId, "Document supprime localement, synchronisation en cours...", "pending");
  saveState();
  renderPreservingScroll();
  if (hasRemoteData()) {
    try {
      if (targetPlan.fileId) {
        await deleteAppwriteStorageFile(targetPlan.bucketId || appwritePlansBucketId, targetPlan.fileId).catch((error) => {
          console.warn("Document Storage non supprime, reference retiree de la fiche", error);
        });
      }
      await syncStoreToRemote(store, `Suppression document magasin - ${targetPlan.name || "document"}`);
      setStoreSaveFeedback(storeId, "Document supprime et synchronise.", "success");
    } catch (error) {
      console.error("Erreur suppression document magasin", error);
      setStoreSaveFeedback(storeId, "Document supprime localement, mais Appwrite n'a pas confirme la synchro.", "error");
    }
  }
  saveState();
  renderPreservingScroll();
}

async function savePrevisitPhotoForStore(store, file, category, scope = "previsit") {
  const workflow = ensureStoreWorkflowData(store);
  const report = ensurePrevisitReport(workflow);
  const updatedAt = new Date().toISOString();
  const entry = normalizePrevisitPhoto({
    id: safeDocumentId("previsit-doc", `${store.code || store.id}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`),
    name: file.name,
    category: category || "Autre",
    fileType: file.type || (/\.pdf$/i.test(file.name) ? "application/pdf" : "image/jpeg"),
    fileSize: String(file.size || ""),
    updatedAt
  });
  if (hasRemoteData() && appwriteStorage && appwritePlansBucketId) {
    const fileId = safeDocumentId("previsit", `${store.code || store.id}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
    await createAppwritePrevisitFile(appwritePlansBucketId, fileId, file);
    entry.fileId = fileId;
    entry.bucketId = appwritePlansBucketId;
  } else {
    entry.dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result || ""));
      reader.onerror = () => reject(reader.error || new Error("Lecture photo impossible"));
      reader.readAsDataURL(file);
    });
  }
  if (scope === "mobile-coverage") {
    report.mobileCoverageScreenshots = [...getMobileCoverageScreenshotsFromReport(report), entry];
  } else {
    report.photos = [...getPrevisitPhotosFromReport(report), entry];
  }
  workflow.previsitReport = report;
  store.updatedAt = updatedAt;
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, `Import photo previsite - ${file.name}`);
  }
  return entry;
}

