async function handleSignedFnpFileChange(event) {
  const input = event.currentTarget;
  const storeId = Number(input.getAttribute("data-signed-fnp-file"));
  const file = input.files?.[0];
  input.value = "";
  if (!file) return;
  if (!/\.pdf$/i.test(file.name || "") && file.type !== "application/pdf") {
    window.alert("Le FNP signe doit etre un fichier PDF.");
    return;
  }
  if (file.size > 12 * 1024 * 1024) {
    window.alert("Le FNP signe depasse 12 Mo.");
    return;
  }
  if (!hasRemoteData() || !appwriteStorage || !appwritePlansBucketId) {
    window.alert("Connexion Appwrite requise pour archiver le FNP signe. Aucun enregistrement local n'a ete effectue.");
    return;
  }
  const store = state.stores.find((item) => Number(item.id) === storeId);
  if (!store) return;
  const workflow = ensureStoreWorkflowData(store);
  const fileId = safeDocumentId("signed-fnp", `${store.code || store.id}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
  setStoreSaveFeedback(storeId, "Archivage du FNP signe dans Appwrite...", "pending");
  renderPreservingScroll();
  try {
    await createAppwritePrevisitFile(appwritePlansBucketId, fileId, file);
    const createdAt = new Date().toISOString();
    workflow.signedFnpDocuments = [...(Array.isArray(workflow.signedFnpDocuments) ? workflow.signedFnpDocuments : []), {
      id: fileId,
      fileId,
      bucketId: appwritePlansBucketId,
      name: file.name,
      fileType: file.type || "application/pdf",
      fileSize: String(file.size || ""),
      createdAt,
      createdBy: currentUser()?.name || state.activeUserName || "TWEM"
    }];
    syncStoreFinishItems(store);
    store.updatedAt = createdAt;
    await syncStoreToRemote(store, `FNP signe archive - ${file.name}`);
    setStoreSaveFeedback(storeId, "FNP signe archive dans Appwrite. Le suivi FNP est valide.", "success");
  } catch (error) {
    console.error("Erreur archivage FNP signe", error);
    setStoreSaveFeedback(storeId, `Le FNP signe n'a pas pu etre archive : ${error?.message || "erreur Appwrite"}`, "error");
  }
  saveState();
  renderPreservingScroll();
}

