async function handlePrevisitPhotoDelete(event) {
  const storeId = Number(event.currentTarget.getAttribute("data-previsit-photo-delete"));
  const photoId = event.currentTarget.getAttribute("data-previsit-photo-id") || "";
  const store = state.stores.find((item) => item.id === storeId);
  if (!store) return;
  const workflow = ensureStoreWorkflowData(store);
  const report = ensurePrevisitReport(workflow);
  const photos = getPrevisitPhotosFromReport(report);
  const coverageScreenshots = getMobileCoverageScreenshotsFromReport(report);
  const photo = [...photos, ...coverageScreenshots].find((item) => item.id === photoId);
  if (!photo) return;
  report.photos = photos.filter((item) => item.id !== photo.id);
  report.mobileCoverageScreenshots = coverageScreenshots.filter((item) => item.id !== photo.id);
  store.updatedAt = new Date().toISOString();
  setStoreSaveFeedback(storeId, "Photo previsite supprimee, synchronisation en cours...", "pending");
  saveState();
  renderPreservingScroll();
  if (hasRemoteData()) {
    try {
      if (photo.fileId) {
        await deleteAppwriteStorageFile(photo.bucketId || appwritePlansBucketId, photo.fileId).catch((error) => {
          console.warn("Photo Storage non supprimee, reference retiree de la fiche", error);
        });
      }
      await syncStoreToRemote(store, `Suppression photo previsite - ${photo.name || "photo"}`);
      setStoreSaveFeedback(storeId, "Photo previsite supprimee et synchronisee.", "success");
    } catch (error) {
      console.error("Erreur suppression photo previsite", error);
      setStoreSaveFeedback(storeId, "Photo retiree localement, mais Appwrite n'a pas confirme la synchro.", "error");
    }
  }
  saveState();
  renderPreservingScroll();
}

async function handlePrevisitPhotoFileChange(event) {
  const input = event.currentTarget;
  const files = [...(input.files || [])];
  if (!files.length) return;
  const storeId = Number(input.getAttribute("data-previsit-photo-file"));
  const store = state.stores.find((item) => item.id === storeId);
  if (!store) {
    window.alert("Magasin introuvable pour ces photos. Ferme et rouvre la fiche.");
    input.value = "";
    delete input.dataset.previsitPhotoCategory;
    delete input.dataset.previsitPhotoScope;
    return;
  }
  const invalid = files.find((file) => {
    const isImage = /^image\//i.test(file.type) || /\.(jpe?g|png|webp|heic)$/i.test(file.name);
    const isPdf = /\.pdf$/i.test(file.name) || file.type === "application/pdf";
    return !isImage && !isPdf;
  });
  if (invalid) {
    window.alert("Utilise uniquement des photos/images ou PDF pour le rapport previsite.");
    input.value = "";
    delete input.dataset.previsitPhotoCategory;
    delete input.dataset.previsitPhotoScope;
    return;
  }
  const tooLarge = files.find((file) => file.size > 12 * 1024 * 1024);
  if (tooLarge) {
    window.alert("Un fichier est trop lourd. Garde des fichiers inferieurs a 12 Mo.");
    input.value = "";
    delete input.dataset.previsitPhotoCategory;
    delete input.dataset.previsitPhotoScope;
    return;
  }
  const form = input.closest("form");
  const category = input.dataset.previsitPhotoCategory
    || form?.querySelector('[name="previsit_photo_category"]')?.value
    || "Autre";
  const scope = input.dataset.previsitPhotoScope || "previsit";
  previsitPhotoUploadInProgress = true;
  setStoreSaveFeedback(storeId, `Import de ${files.length} photo(s) previsite en cours...`, "pending");
  renderPreservingScroll();
  const imported = [];
  const errors = [];
  try {
    for (const file of files) {
      try {
        await savePrevisitPhotoForStore(store, file, category, scope);
        imported.push(file.name);
      } catch (error) {
        console.error("Erreur sync photo previsite", error);
        errors.push(`${file.name}: ${syncErrorLabel(error)}`);
      }
    }
  } finally {
    previsitPhotoUploadInProgress = false;
  }
  saveState();
  setStoreSaveFeedback(
    storeId,
    errors.length ? `${imported.length} photo(s) importee(s), ${errors.length} en erreur.` : `${imported.length} photo(s) importee(s) et synchronisee(s).`,
    errors.length ? "error" : "success"
  );
  if (errors.length) {
    window.alert(`Certaines photos n'ont pas ete importees:\n\n${errors.join("\n")}`);
  }
  renderPreservingScroll();
  input.value = "";
  delete input.dataset.previsitPhotoCategory;
  delete input.dataset.previsitPhotoScope;
}

