function readJsonFile(file) {
  return file.text().then((text) => JSON.parse(text));
}

function reportFromPrevisitImportPayload(payload = {}) {
  if (payload.type !== "twem_previsit_report" && !payload.report) {
    throw new Error("Fichier previsite non reconnu.");
  }
  return payload.report && typeof payload.report === "object" ? payload.report : {};
}

function isMobileSurveyCampaignPayload(payload = {}) {
  return payload?.format === "TWEM_NETWORK_SURVEY_CAMPAIGN"
    && Number(payload?.version) === 1
    && Array.isArray(payload?.measurements);
}

function mobileSurveyRunFromPayload(payload = {}, store) {
  const measurements = Array.isArray(payload.measurements) ? payload.measurements : [];
  const operators = [...new Set(measurements.map((row) => normalizeImportCell(row.operator)).filter(Boolean))];
  const realCallCount = measurements.filter((row) => normalizeImportCell(row.voiceCallResult)).length;
  const measurementsPerOperator = Object.fromEntries(operators.map((operator) => [
    operator,
    measurements.filter((row) => normalizeImportCell(row.operator) === operator).length
  ]));
  const enoughMeasurements = operators.length > 0 && operators.every((operator) => measurementsPerOperator[operator] >= 5);
  const enoughRealCalls = realCallCount >= 2;
  const clientRunId = normalizeImportCell(payload.clientRunId)
    || `android-${normalizeImportCell(payload.siteCode || store.code)}-${normalizeImportCell(payload.exportedAt || new Date().toISOString())}`;
  return {
    surveyRunId: normalizeImportCell(payload.surveyRunId) || clientRunId,
    clientRunId,
    siteId: normalizeImportCell(payload.siteId || store.remoteSiteId || ""),
    siteCode: normalizeImportCell(payload.siteCode || store.code),
    siteName: normalizeImportCell(payload.siteName || store.name),
    status: enoughMeasurements && enoughRealCalls ? "COMPLETE" : "RECEIVED_INCOMPLETE",
    measurementCount: measurements.length,
    realCallCount,
    operators,
    measurementsPerOperator,
    technicianUserId: normalizeImportCell(payload.technicianUserId),
    technicianName: normalizeImportCell(payload.technicianName),
    deviceId: normalizeImportCell(payload.deviceId),
    deviceModel: normalizeImportCell(payload.deviceModel || measurements[0]?.deviceModel),
    androidVersion: normalizeImportCell(payload.androidVersion || measurements[0]?.androidVersion),
    appVersion: normalizeImportCell(payload.appVersion),
    methodologyVersion: normalizeImportCell(payload.methodologyVersion || "android-v1"),
    exportedAt: normalizeImportCell(payload.exportedAt),
    completedAt: normalizeImportCell(payload.completedAt),
    receivedAt: new Date().toISOString(),
    artifact: {
      kind: "CAMPAIGN_JSON",
      schemaVersion: 1,
      payload
    },
    reports: []
  };
}

async function applyMobileSurveyCampaignPayload(payload, fallbackStoreId = null) {
  const siteCode = normalizeImportCell(payload.siteCode);
  const siteId = normalizeImportCell(payload.siteId);
  const store = state.stores.find((item) => siteId && normalizeImportCell(item.remoteSiteId) === siteId)
    || state.stores.find((item) => normalizeImportCell(item.code).toLowerCase() === siteCode.toLowerCase())
    || state.stores.find((item) => Number(item.id) === Number(fallbackStoreId));
  if (!store) {
    throw new Error(`Magasin introuvable pour ${siteCode || siteId || "cette campagne"}.`);
  }
  const workflow = ensureStoreWorkflowData(store);
  const report = ensurePrevisitReport(workflow);
  const run = mobileSurveyRunFromPayload(payload, store);
  const runs = Array.isArray(report.mobileSurveyRuns) ? report.mobileSurveyRuns : [];
  if (!runs.some((item) => item.clientRunId === run.clientRunId)) {
    report.mobileSurveyRuns = [run, ...runs];
  }
  report.mobileTestNetworks = [...new Set([...(report.mobileTestNetworks || []), ...run.operators])];
  report.mobileTestNetwork = report.mobileTestNetworks.join(", ");
  report.updatedAt = new Date().toISOString();
  report.updatedBy = currentUser()?.name || state.activeUserName || "TWEM";
  workflow.mobileCoverageTestNetwork = report.mobileTestNetwork;
  workflow.mobileCoverageResult = run.status === "COMPLETE" ? "Rapport mobile complet recu" : "Rapport mobile recu - incomplet";
  workflow.mobileCoverage = run.status === "COMPLETE" ? "Rapport mobile valide" : "A verifier";
  store.updatedAt = new Date().toISOString();
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, `Campagne couverture mobile recue - ${run.clientRunId}`);
  }
  return store;
}

function previsitPhotoMergeKey(photo = {}) {
  return [
    String(photo.fileId || ""),
    String(photo.name || "").toLowerCase(),
    String(photo.category || "").toLowerCase(),
    String(photo.fileSize || "")
  ].join("|");
}

async function storeImportedPrevisitPhoto(store, photo) {
  const normalized = normalizePrevisitPhoto(photo, Date.now());
  if (normalized.dataUrl && !normalized.fileId && hasRemoteData() && appwriteStorage && appwritePlansBucketId) {
    const blob = dataUrlToBlob(normalized.dataUrl);
    if (blob) {
      const fileId = safeDocumentId("previsit", `${store.code || store.id}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
      const fileName = normalized.name || `previsite-${store.code || store.id}`;
      const file = new File([blob], fileName, { type: normalized.fileType || blob.type || "application/octet-stream" });
      await createAppwriteStorageFile(appwritePlansBucketId, fileId, file);
      normalized.fileId = fileId;
      normalized.bucketId = appwritePlansBucketId;
      delete normalized.dataUrl;
    }
  }
  normalized.pending = false;
  return normalized;
}

async function applyPrevisitImportPayload(payload, fallbackStoreId = null) {
  if (isMobileSurveyCampaignPayload(payload)) {
    return applyMobileSurveyCampaignPayload(payload, fallbackStoreId);
  }
  const reportInput = reportFromPrevisitImportPayload(payload);
  const storeCode = String(payload.storeCode || reportInput.storeCode || "").trim();
  const store = state.stores.find((item) => String(item.code || "").toLowerCase() === storeCode.toLowerCase())
    || state.stores.find((item) => item.id === fallbackStoreId);
  if (!store) {
    throw new Error(`Magasin introuvable pour ${storeCode || "ce fichier"}.`);
  }
  const workflow = ensureStoreWorkflowData(store);
  const currentReport = ensurePrevisitReport(workflow);
  const importedPhotosRaw = Array.isArray(reportInput.photos) ? reportInput.photos : [];
  const importedCoverageRaw = Array.isArray(reportInput.mobileCoverageScreenshots) ? reportInput.mobileCoverageScreenshots : [];
  const importedPhotos = [];
  for (const [index, photo] of importedPhotosRaw.entries()) {
    const normalized = normalizePrevisitPhoto(photo, index);
    if (!normalized.name && !normalized.fileId && !normalized.dataUrl) continue;
    importedPhotos.push(await storeImportedPrevisitPhoto(store, normalized));
  }
  const existingPhotos = getPrevisitPhotosFromReport(currentReport);
  const mergedPhotos = [...existingPhotos];
  const photoKeys = new Set(mergedPhotos.map((photo) => previsitPhotoMergeKey(photo)));
  importedPhotos.forEach((photo) => {
    const key = previsitPhotoMergeKey(photo);
    if (!photoKeys.has(key)) {
      photoKeys.add(key);
      mergedPhotos.push(photo);
    }
  });
  const importedCoverage = [];
  for (const [index, photo] of importedCoverageRaw.entries()) {
    const normalized = normalizePrevisitPhoto(photo, index);
    if (!normalized.name && !normalized.fileId && !normalized.dataUrl) continue;
    importedCoverage.push(await storeImportedPrevisitPhoto(store, normalized));
  }
  const mergedCoverage = [...getMobileCoverageScreenshotsFromReport(currentReport)];
  const coverageKeys = new Set(mergedCoverage.map((photo) => previsitPhotoMergeKey(photo)));
  importedCoverage.forEach((photo) => {
    const key = previsitPhotoMergeKey(photo);
    if (!coverageKeys.has(key)) {
      coverageKeys.add(key);
      mergedCoverage.push(photo);
    }
  });
  const report = {
    ...currentReport,
    ...reportInput,
    photos: mergedPhotos,
    mobileCoverageScreenshots: mergedCoverage,
    importedAt: new Date().toISOString(),
    importedFrom: payload.source || "fiche terrain"
  };
  workflow.previsitReport = report;
  ensurePrevisitReport(workflow);
  const importedTechnicalSwitches = (Array.isArray(reportInput.rackRows) ? reportInput.rackRows : [])
    .flatMap((rack) => Array.isArray(rack?.switches) ? rack.switches : [])
    .filter(Boolean);
  if (importedTechnicalSwitches.length) {
    workflow.ltSwitchStatus = "A valider par le service technique";
    workflow.switchNote = `Plan technique importé : ${importedTechnicalSwitches.length} switch(s) à contrôler et valider.`;
    workflow.switchUpdatedBy = payload.source || "Import plan technique";
  }
  if (report.date) {
    workflow.previsitDate = report.date;
    workflow.previsitAppointment = {
      ...(workflow.previsitAppointment || {}),
      id: workflow.previsitAppointment?.id || `previsit-${store.code || store.id}-${report.date}`,
      datetime: `${report.date}T09:00`,
      previsitDate: report.date,
      previsitTime: "",
      timeProvided: false,
      people: [],
      status: "",
      mailReplies: Array.isArray(workflow.previsitAppointment?.mailReplies) ? workflow.previsitAppointment.mailReplies : []
    };
  }
  if (report.fixedCablingStatus && report.fixedCablingStatus !== "A verifier") {
    workflow.cablingStatus = report.fixedCablingStatus;
  }
  workflow.mobileCoverageTestNetwork = report.mobileTestNetwork || workflow.mobileCoverageTestNetwork || "";
  workflow.mobileCoverageResult = report.mobileSignal || workflow.mobileCoverageResult || "";
  if (["Mauvais", "Aucun signal"].includes(report.mobileSignal)) workflow.mobileCoverage = "Bloque";
  else if (report.mobileTestNetwork) workflow.mobileCoverage = report.mobileTestNetwork;
  store.updatedAt = new Date().toISOString();
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, `Import fiche pre-visite terrain - ${payload.storeCode || store.code || store.name}`);
  }
  return store;
}

async function handlePrevisitImportFileChange(event) {
  const input = event.currentTarget;
  const files = [...(input.files || [])];
  if (!files.length) return;
  const fallbackStoreId = Number(input.getAttribute("data-previsit-import-file"));
  const fallbackStore = state.stores.find((item) => item.id === fallbackStoreId);
  if (fallbackStore) setStoreSaveFeedback(fallbackStoreId, `Import de ${files.length} fiche(s) previsite en cours...`, "pending");
  renderPreservingScroll();
  const importedStores = [];
  const errors = [];
  for (const file of files) {
    try {
      const payload = await readJsonFile(file);
      const store = await applyPrevisitImportPayload(payload, fallbackStoreId);
      importedStores.push(store);
    } catch (error) {
      console.error("Erreur import fiche previsite", error);
      errors.push(`${file.name}: ${error.message || "erreur inconnue"}`);
    }
  }
  saveState();
  const targetStore = importedStores[0] || fallbackStore;
  if (targetStore) {
    setStoreSaveFeedback(
      targetStore.id,
      errors.length
        ? `${importedStores.length} fiche(s) importee(s), ${errors.length} en erreur.`
        : `${importedStores.length} fiche(s) previsite importee(s) et synchronisee(s).`,
      errors.length ? "error" : "success"
    );
  }
  if (errors.length) window.alert(`Certaines fiches n'ont pas ete importees:\n\n${errors.join("\n")}`);
  input.value = "";
  renderPreservingScroll();
}
async function handleStorePlanFileChange(event) {
  const input = event.currentTarget;
  const files = [...(input.files || [])];
  if (!files.length) {
    return;
  }
  const storeId = Number(input.getAttribute("data-plan-file"));
  const store = state.stores.find((item) => item.id === storeId);
  if (!store) {
    return;
  }
  const invalid = files.find((file) => {
    const isPdf = /\.pdf$/i.test(file.name) || file.type === "application/pdf";
    const isZip = /\.zip$/i.test(file.name) || file.type === "application/zip" || file.type === "application/x-zip-compressed";
    const isImage = /^image\//i.test(file.type) || /\.(png|jpe?g|webp|heic)$/i.test(file.name);
    return !isPdf && !isZip && !isImage;
  });
  if (invalid) {
    window.alert("Utilise uniquement des fichiers PDF, ZIP ou images PNG/JPG/WEBP pour les documents magasin.");
    input.value = "";
    return;
  }
  const tooLarge = files.find((file) => file.size > 10 * 1024 * 1024);
  if (tooLarge) {
    window.alert("Un document est trop lourd. Garde des fichiers inferieurs a 10 Mo.");
    input.value = "";
    return;
  }

  setStoreSaveFeedback(storeId, `Import de ${files.length} document(s) en cours...`, "pending");
  renderPreservingScroll();
  const imported = [];
  const skipped = [];
  const errors = [];
  for (const file of files) {
    try {
      const result = await savePlanFileForStore(store, file);
      if (result?.duplicateSkipped) {
        skipped.push(file.name);
      } else {
        imported.push(file.name);
      }
    } catch (error) {
      console.error("Erreur sync document magasin", error);
      errors.push(file.name);
    }
  }
  saveState();
  setStoreSaveFeedback(
    storeId,
    errors.length
      ? `${imported.length} document(s) importe(s), ${skipped.length} deja present(s), ${errors.length} en erreur.`
      : `${imported.length} document(s) importe(s), ${skipped.length} deja present(s).`,
    errors.length ? "error" : "success"
  );
  renderPreservingScroll();
  input.value = "";
}

