function handleStorePrint(event) {
  const storeId = Number(event.currentTarget.getAttribute("data-store-print"));
  const store = state.stores.find((item) => item.id === storeId);
  if (!store) {
    return;
  }
  const openForm = projectTableBody.querySelector(`[data-store-editor="${storeId}"]`);
  if (openForm) {
    const workflow = ensureStoreWorkflowData(store);
    if (openForm.querySelector('[name^="network_extension_"]')) {
      workflow.networkRows = readNetworkRows(openForm, store);
    }
    if (openForm.querySelector('[name^="gsm_model_"]')) {
      workflow.gsmRows = readGsmRows(openForm, store);
    }
    workflow.callGroupsNote = openForm.querySelector('[name="call_groups_note"]')?.value.trim() || workflow.callGroupsNote || "";
    workflow.cascadeNote = openForm.querySelector('[name="cascade_note"]')?.value.trim() || workflow.cascadeNote || "";
    workflow.menuChoiceNote = openForm.querySelector('[name="menu_choice_note"]')?.value.trim() || workflow.menuChoiceNote || "";
    store.ipRange = openForm.querySelector('[name="ip_range"]')?.value.trim() || store.ipRange || "";
    workflow.currentContractClientNumber = openForm.querySelector('[name="current_contract_client_number"]')?.value.trim() || workflow.currentContractClientNumber || "";
    workflow.currentContractMainNumber = openForm.querySelector('[name="current_contract_main_number"]')?.value.trim() || workflow.currentContractMainNumber || "";
    workflow.currentContractOtherNumbers = openForm.querySelector('[name="current_contract_other_numbers"]')?.value.trim() || workflow.currentContractOtherNumbers || "";
  }
  const printWindow = window.open("", "_blank");
  if (!printWindow) {
    window.alert(t("reportWindowError"));
    return;
  }
  const printContent = document.createElement("div");
  printContent.innerHTML = buildStoreDetailForm(store, "stores");
  printContent.querySelectorAll("details").forEach((details) => {
    details.setAttribute("open", "");
  });
  printContent.querySelectorAll(".store-quick-actions, .editor-actions, .floating-store-save, button, input[type='file']").forEach((element) => {
    element.remove();
  });
  printWindow.document.open();
  printWindow.document.write(`
    <!doctype html>
    <html lang="${escapeHtml(state.language || store.language || "fr")}">
    <head>
      <meta charset="UTF-8">
      <title>${escapeHtml(store.code)} - ${escapeHtml(store.name)}</title>
      <link rel="stylesheet" href="styles.css?v=20260730-refonte2-final4">
      <style>
        @page { margin: 10mm; }
        body { margin: 0; padding: 0; background: #fff; }
        .details-panel { border: 0; box-shadow: none; padding: 0; }
        details, article, .editor-card, .installation-report-item { break-inside: avoid; }
        details > summary { break-after: avoid; }
        details[open] > .store-config-archive-body,
        details[open] > .store-config-subsection-body { display: block !important; }
        textarea, input, select { border: 0 !important; background: transparent !important; box-shadow: none !important; }
        textarea { overflow: visible; resize: none; min-height: 80px; }
        .section-anchor { scroll-margin: 0; }
      </style>
    </head>
    <body class="store-full-print">
      ${printContent.innerHTML}
    </body>
    </html>
  `);
  printWindow.document.close();
  printWindow.addEventListener("load", () => {
    printWindow.focus();
    printWindow.print();
  }, { once: true });
}

