function persistClosureDraftFromForm(form) {
  if (!form) return;
  const storeId = Number(form.getAttribute("data-store-editor"));
  const store = state.stores.find((item) => item.id === storeId);
  if (!store) return;
  const workflow = ensureStoreWorkflowData(store);
  const value = (name, fallback = "", { trim = false } = {}) => {
    const field = form.querySelector(`[name="${name}"]`);
    if (!field) return fallback;
    return trim ? field.value.trim() : field.value;
  };
  workflow.destinyInstallDone = value("destiny_install_done", workflow.destinyInstallDone);
  workflow.destinyInstallRemark = value("destiny_install_remark", workflow.destinyInstallRemark, { trim: true });
  workflow.bricoFinalMailStatus = value("brico_final_mail_status", workflow.bricoFinalMailStatus);
  workflow.bricoFinalRemark = value("brico_final_remark", workflow.bricoFinalRemark, { trim: true });
  workflow.ltSwitchStatus = value("lt_switch_status", workflow.ltSwitchStatus);
  applyCompletionStatusFromClosure(store);
  store.updatedAt = new Date().toISOString();
  saveState();
}

async function handleRemoveAppointment(event) {
  const storeId = Number(event.currentTarget.getAttribute("data-remove-appointment"));
  const index = Number(event.currentTarget.getAttribute("data-index"));
  const store = state.stores.find((item) => item.id === storeId);
  if (!store) {
    return;
  }

  store.appointments.splice(index, 1);
  store.updatedAt = new Date().toISOString();
  if (hasRemoteData()) {
    await syncStoreToRemote(store);
    await loadRemoteState();
  }
  saveState();
  render();
}

async function handleAppointmentMail(event) {
  const button = event.currentTarget;
  const storeId = Number(button.getAttribute("data-appointment-store"));
  const appointmentId = button.getAttribute("data-appointment-mail");
  const store = state.stores.find((item) => item.id === storeId);
  const appointment = store?.appointments?.find((item) => item.id === appointmentId);
  if (!store || !appointment) return;
  button.disabled = true;
  const result = await sendAppointmentEmail(store, appointment, "appointment");
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, "");
  }
  window.alert(result.status === "envoye"
    ? "Mail rendez-vous envoye."
    : result.status === "aucun_email"
      ? "Aucun destinataire mail trouve pour ce rendez-vous."
      : `Mail rendez-vous non envoye: ${result.error?.message || "erreur inconnue"}`);
  renderPreservingScroll();
}

async function handlePrevisitMail(event) {
  const button = event.currentTarget;
  const storeId = Number(button.getAttribute("data-previsit-mail"));
  const store = state.stores.find((item) => item.id === storeId);
  const form = button.closest("[data-store-editor]");
  if (!store || !form) return;
  const workflow = ensureStoreWorkflowData(store);
  const previsit = readPrevisitAppointment(form, workflow);
  if (!previsit.previsitDate) {
    window.alert("Indique une date de pre-visite avant d'envoyer.");
    return;
  }
  button.disabled = true;
  const feedback = form.querySelector(`[data-previsit-mail-feedback="${storeId}"]`);
  if (feedback) {
    feedback.textContent = "Envoi du mail pre-visite...";
  }
  const result = await sendAppointmentEmail(store, previsit, "previsit");
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, "");
  }
  if (feedback) {
    feedback.textContent = result.status === "envoye"
      ? "Mail pre-visite envoye."
      : result.status === "aucun_email"
        ? "Aucun destinataire mail trouve."
        : `Mail pre-visite non envoye: ${result.error?.message || "erreur inconnue"}`;
  }
  renderPreservingScroll();
}

async function handleAppointmentReply(event) {
  const button = event.currentTarget;
  const storeId = Number(button.getAttribute("data-appointment-store"));
  const appointmentId = button.getAttribute("data-appointment-reply");
  const store = state.stores.find((item) => item.id === storeId);
  const appointment = store?.appointments?.find((item) => item.id === appointmentId);
  const field = button.closest(".mail-reply-box")?.querySelector(`[name="appointment_reply_${CSS.escape(appointmentId)}"]`);
  const text = normalizeImportCell(field?.value || "");
  if (!store || !appointment || !text) return;
  appointment.mailReplies = Array.isArray(appointment.mailReplies) ? appointment.mailReplies : [];
  appointment.mailReplies.push({
    id: `mail-reply-${Date.now()}`,
    text,
    author: currentUser()?.name || state.activeUserName || "TWEM",
    createdAt: new Date().toISOString()
  });
  field.value = "";
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, "");
  }
  renderPreservingScroll();
}

function normalizeSimImportStoreName(value = "") {
  return normalizeSearchText(value)
    .replace(/\b(brico|plan it|planit|pi)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function findStoreBySimImportName(name = "") {
  const normalizedName = normalizeSimImportStoreName(name);
  if (!normalizedName) {
    return null;
  }
  const matches = state.stores.filter((store) => {
    const candidates = [
      store.name,
      store.city
    ].map(normalizeSimImportStoreName).filter(Boolean);
    return candidates.includes(normalizedName);
  });
  return matches.length === 1 ? matches[0] : null;
}

function simCsvAscii(value = "") {
  return normalizeImportCell(value)
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^A-Za-z0-9 +./&-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function simCsvPhone(value = "") {
  const text = normalizeImportCell(value);
  if (!text) return "";
  const digits = text.replace(/\D/g, "");
  return text.startsWith("+") ? `+${digits}` : digits;
}

function simCsvField(value = "") {
  const text = String(value ?? "");
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function buildStoreSimContacts(store) {
  const workflow = ensureStoreWorkflowData(store);
  const simInfo = workflow.postInstallSimInfo && typeof workflow.postInstallSimInfo === "object"
    ? workflow.postInstallSimInfo
    : {};
  const rows = getNetworkConfigRows(store);
  const contacts = [];
  let missingPhoneCount = 0;
  rows.forEach((row) => {
    const key = row.id || row.slotLabel || "";
    const info = simInfo[key] || {};
    const phone = simCsvPhone(info.phoneNumber);
    const extensionSource = normalizeImportCell(info.importedExtension || row.extensionLabel);
    const extension = extensionSource.match(/^\s*([A-Za-z]{1,3}|\d{2,6})\b/)?.[1] || "";
    const configured = Boolean(extensionSource || info.serviceName || row.note);
    if (!phone) {
      if (configured) missingPhoneCount += 1;
      return;
    }
    const extensionDescription = extensionSource.replace(/^\s*(?:[A-Za-z]{1,3}|\d{2,6})\s*[-–—]?\s*/, "");
    const service = normalizeImportCell(info.serviceName || extensionDescription || row.note || row.slotLabel);
    const fullName = simCsvAscii([extension, service].filter(Boolean).join(" ")) || simCsvAscii(row.slotLabel || "Contact");
    contacts.push({
      slot: contacts.length + 1,
      simName: fullName.slice(0, 20).trim(),
      phone
    });
  });
  return { contacts, missingPhoneCount };
}

function handleStoreSimCsvDownload(event) {
  if (!canDownloadStoreSimCsv()) {
    window.alert("Telechargement non autorise pour ce profil.");
    return;
  }
  const storeId = Number(event.currentTarget.getAttribute("data-store-sim-csv"));
  const store = state.stores.find((item) => Number(item.id) === storeId);
  if (!store) {
    window.alert("Magasin introuvable.");
    return;
  }
  const storeLabel = normalizeImportCell(store.code || store.shopNumber || store.name || "MAGASIN").toUpperCase();
  const safeStoreLabel = storeLabel.replace(/[^A-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "") || "MAGASIN";
  const simExport = buildStoreSimContacts(store);
  if (!simExport.contacts.length) {
    window.alert("Aucun numero de telephone reel n est disponible pour ce magasin. Importe d abord le sheet SIM dans Appwrite.");
    return;
  }
  const csv = [
    "slot,sim_name,phone",
    ...simExport.contacts.map((contact) => [contact.slot, contact.simName, contact.phone].map(simCsvField).join(",")),
  ].join("\r\n");
  downloadBlob(new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" }), `contacts-hammer-sim-${safeStoreLabel}.csv`);
}

async function handleAppointmentStandaloneSave(event) {
  const button = event.currentTarget;
  const form = button.closest("[data-appointment-standalone-form]");
  const storeId = Number(form?.getAttribute("data-store-editor") || 0);
  const store = state.stores.find((item) => Number(item.id) === storeId);
  if (!form || !store) return;
  const feedback = form.querySelector(`[data-appointment-save-feedback="${store.id}"]`);
  const previousAppointmentIds = new Set(ensureAppointmentIds(store.appointments || []).map((appointment) => appointment.id));
  button.disabled = true;
  if (feedback) {
    feedback.textContent = "Sauvegarde des rendez-vous...";
  }

  store.appointments = readAppointments(form, store);
  const appointmentMailJobs = store.appointments.filter((appointment) =>
    appointment.shouldSendAppointmentMail
    || !previousAppointmentIds.has(appointment.id)
  );
  appointmentMailJobs.forEach((appointment) => {
    delete appointment.shouldSendAppointmentMail;
  });
  store.updatedAt = new Date().toISOString();
  saveState();

  if (hasRemoteData()) {
    await syncStoreToRemote(store, "");
  }

  for (const appointment of appointmentMailJobs) {
    await sendAppointmentEmail(store, appointment, "appointment");
  }

  if (appointmentMailJobs.length && hasRemoteData()) {
    await syncStoreToRemote(store, "");
  }

  if (feedback) {
    feedback.textContent = appointmentMailJobs.length
      ? "Rendez-vous sauvegarde et mail envoye si destinataire disponible."
      : "Rendez-vous sauvegardes.";
  }
  button.disabled = false;
  saveState();
  renderPreservingScroll();
}

async function handlePrevisitReply(event) {
  const button = event.currentTarget;
  const storeId = Number(button.getAttribute("data-previsit-reply"));
  const store = state.stores.find((item) => item.id === storeId);
  const form = button.closest("[data-store-editor]");
  if (!store || !form) return;
  const workflow = ensureStoreWorkflowData(store);
  const previsit = readPrevisitAppointment(form, workflow);
  const field = form.querySelector('[name="previsit_reply_text"]');
  const text = normalizeImportCell(field?.value || "");
  if (!text) return;
  previsit.mailReplies = Array.isArray(previsit.mailReplies) ? previsit.mailReplies : [];
  previsit.mailReplies.push({
    id: `mail-reply-${Date.now()}`,
    text,
    author: currentUser()?.name || state.activeUserName || "TWEM",
    createdAt: new Date().toISOString()
  });
  field.value = "";
  saveState();
  if (hasRemoteData()) {
    await syncStoreToRemote(store, "");
  }
  renderPreservingScroll();
}

function readAppointments(form, store) {
  const currentAppointments = ensureAppointmentIds(store.appointments || []).map((appointment, index) => ({
    ...appointment,
    datetime: form.querySelector(`[name="appointment_datetime_${index}"]`)?.value || appointment.datetime,
    status: form.querySelector(`[name="appointment_status_${index}"]`)?.value || appointment.status,
    note: form.querySelector(`[name="appointment_note_${index}"]`)?.value.trim() ?? appointment.note,
    people: form.querySelector(`[name="appointment_people_${index}"]`)
      ? [...form.querySelector(`[name="appointment_people_${index}"]`).selectedOptions].map((option) => option.value)
      : appointment.people
  })).filter((appointment) => appointment.datetime);

  const newDatetime = form.querySelector('[name="new_appointment_datetime"]')?.value || "";
  const newPeopleField = form.querySelector('[name="new_appointment_people"]');
  const newPeople = newPeopleField ? [...newPeopleField.selectedOptions].map((option) => option.value) : [];
  const newStatus = form.querySelector('[name="new_appointment_status"]')?.value || "Propose";
  const newNote = form.querySelector('[name="new_appointment_note"]')?.value.trim() || "";

  if (newDatetime) {
    currentAppointments.push({
      id: `appt-${Date.now()}`,
      datetime: newDatetime,
      status: newStatus,
      people: newPeople,
      note: newNote,
      mailReplies: [],
      shouldSendAppointmentMail: true
    });
  }

  return currentAppointments;
}

function readPrevisitAppointment(form, workflow) {
  const previsit = ensurePrevisitAppointment(workflow);
  if (!form.querySelector('[name="previsit_date"]') && !form.querySelector('[name="previsit_datetime"]')) {
    return previsit;
  }
  const legacyDateTime = form.querySelector('[name="previsit_datetime"]')?.value || "";
  const previsitDate = form.querySelector('[name="previsit_date"]')?.value || legacyDateTime.slice(0, 10) || "";
  const previsitTime = form.querySelector('[name="previsit_time"]')?.value || "";
  previsit.previsitDate = previsitDate;
  previsit.previsitTime = previsitTime;
  previsit.timeProvided = Boolean(previsitTime);
  previsit.datetime = previsitDate ? `${previsitDate}T${previsitTime || "09:00"}` : "";
  previsit.status = "";
  previsit.people = [];
  previsit.note = form.querySelector('[name="previsit_note"]')?.value.trim() || defaultPrevisitNote();
  workflow.previsitDate = previsitDate;
  return previsit;
}

function readPrevisitReport(form, workflow, store) {
  if (!form.querySelector('[name="previsit_report_marker"]')) {
    return ensurePrevisitReport(workflow);
  }
  const report = ensurePrevisitReport(workflow);
  const value = (name, fallback = "") => form.querySelector(`[name="${name}"]`)?.value?.trim() || fallback;
  const fieldValue = (name, fallback = "") => form.elements.namedItem(name)?.value?.trim() || fallback;
  report.fixedCablingRows = ensurePrevisitFixedCablingRows(store, report).map((row) => ({
    ...row,
    status: fieldValue(`previsit_fixed_status_${row.id}`, row.status),
    note: fieldValue(`previsit_fixed_note_${row.id}`, "")
  }));
  const fixedStatuses = report.fixedCablingRows.map((row) => row.status);
  report.fixedCablingStatus = fixedStatuses.length && fixedStatuses.every((status) => status === "OK")
    ? "OK"
    : fixedStatuses.includes("Bloque")
      ? "Bloque"
      : fixedStatuses.includes("A prevoir")
        ? "A prevoir"
        : "A verifier";
  report.fixedCablingNote = report.fixedCablingRows
    .filter((row) => row.note)
    .map((row) => `${row.label}: ${row.note}`)
    .join("\n");
  report.callButtonRows = ensurePrevisitCallButtonRows(store, report).map((row) => ({
    ...row,
    status: fieldValue(`previsit_button_status_${row.id}`, row.status),
    location: fieldValue(`previsit_button_location_${row.id}`, ""),
    note: fieldValue(`previsit_button_note_${row.id}`, "")
  }));
  const buttonStatuses = report.callButtonRows.map((row) => row.status);
  report.callButtonsStatus = buttonStatuses.length && buttonStatuses.every((status) => ["Défini", "Pas concerné"].includes(status))
    ? "Definis"
    : buttonStatuses.includes("Impossible")
      ? "Impossible"
      : "A confirmer";
  report.callButtonLocations = report.callButtonRows
    .filter((row) => row.location || row.note)
    .map((row) => `${row.label}: ${row.location || "-"}${row.note ? ` - ${row.note}` : ""}`)
    .join("\n");
  report.vocovoStatus = fieldValue("previsit_vocovo_status", report.vocovoStatus || "A venir");
  report.vocovoHeadsets = report.vocovoStatus;
  const mobileBlock8Field = form.elements.namedItem("previsit_mobile_charger_block_8");
  const mobileBlock10Field = form.elements.namedItem("previsit_mobile_charger_block_10");
  if (mobileBlock8Field) {
    report.mobileChargerBlock8Count = normalizeImportCell(mobileBlock8Field.value);
  }
  if (mobileBlock10Field) {
    report.mobileChargerBlock10Count = normalizeImportCell(mobileBlock10Field.value);
  }
  if (report.mobileChargerBlock8Count !== "" || report.mobileChargerBlock10Count !== "") {
    workflow.mobileChargerCount = String(
      Math.max(0, Number(report.mobileChargerBlock8Count) || 0)
      + Math.max(0, Number(report.mobileChargerBlock10Count) || 0)
    );
  }
  report.rackRows = ensurePrevisitRackRows(report).map((rack) => ({
    ...rack,
    access: fieldValue(`previsit_rack_access_${rack.id}`, rack.access),
    height: fieldValue(`previsit_rack_height_${rack.id}`, rack.height),
    location: fieldValue(`previsit_rack_location_${rack.id}`, ""),
    note: fieldValue(`previsit_rack_note_${rack.id}`, "")
  }));
  report.rackAccess = report.rackRows[0]?.access || report.rackAccess;
  report.rackHeight = report.rackRows[0]?.height || report.rackHeight;
  report.rackNote = report.rackRows
    .filter((rack) => rack.location || rack.note)
    .map((rack) => `${rack.label}${rack.location ? ` - ${rack.location}` : ""}${rack.note ? ` : ${rack.note}` : ""}`)
    .join("\n");
  report.mobileTestNetworks = [...form.querySelectorAll('[name="previsit_mobile_network"]:checked')]
    .map((input) => normalizeImportCell(input.value))
    .filter(Boolean);
  report.mobileTestNetwork = report.mobileTestNetworks.join(", ");
  report.mobileCoveragePoints = ensureMobileCoveragePoints(report).map((point) => ({
    ...point,
    checked: Boolean(
      form.elements.namedItem(`previsit_mobile_point_checked_${point.id}`)?.checked
      || form.elements.namedItem(`previsit_mobile_point_checked_card_${point.id}`)?.checked
    ),
    comment: fieldValue(`previsit_mobile_point_comment_${point.id}`, "")
  }));
  report.mobileTester = value("previsit_mobile_tester", "");
  report.mobileSignal = value("previsit_mobile_signal", report.mobileSignal);
  report.mobileNote = value("previsit_mobile_note", "");
  report.particularities = value("previsit_particularities", "");
  report.questions = value("previsit_questions", "");
  report.updatedAt = new Date().toISOString();
  report.updatedBy = currentUser()?.name || state.activeUserName || "TWEM";
  workflow.previsitReport = report;
  if (report.fixedCablingStatus && report.fixedCablingStatus !== "A verifier") {
    workflow.cablingStatus = report.fixedCablingStatus;
  }
  workflow.mobileCoverageTestNetwork = report.mobileTestNetwork || workflow.mobileCoverageTestNetwork || "";
  workflow.mobileCoverageResult = report.mobileSignal || workflow.mobileCoverageResult || "";
  if (["Mauvais", "Aucun signal"].includes(report.mobileSignal)) {
    workflow.mobileCoverage = "Bloque";
  } else if (report.mobileTestNetwork) {
    workflow.mobileCoverage = report.mobileTestNetwork;
  }
  return report;
}
function readNetworkRows(form, store) {
  return getNetworkConfigRows(store).map((row) => {
    const extensionField = form.querySelector(`[name="network_extension_${row.id}"]`);
    const noteField = form.querySelector(`[name="network_note_${row.id}"]`);
    const extensionValue = extensionField ? normalizeImportCell(extensionField.value) : "";
    const noteValue = noteField ? noteField.value.trim() : null;
    return {
      ...row,
      extensionLabel: row.lockedExtension
        ? "920 - Pager"
        : (extensionValue || row.extensionLabel || defaultNetworkExtensionForRow(row) || ""),
      note: noteValue !== null ? noteValue : (row.note || ""),
      bigFixKeys: networkConfigurationGuideStage(row.category) === "big-fixed"
        ? proposedBigFixKeys(row, store).map((keyRow) => ({
            ...keyRow,
            extensionLabel: (() => {
              const field = form.querySelector(`[name="big_fix_key_${row.id}_${keyRow.key}"]`);
              return normalizeImportCell(field ? field.value : (keyRow.extensionLabel || ""));
            })()
          }))
        : row.bigFixKeys
    };
  });
}

