function handleAdminTabClick(event) {
  const button = event.target.closest("[data-admin-tab]");
  if (button) {
    const requestedTab = button.getAttribute("data-admin-tab");
    const nextTab = openUnifiedStoresFromLegacyTab(requestedTab);
    if (!canAccessTab(nextTab)) {
      return;
    }
    state.activeAdminTab = nextTab;
    if (nextTab === "dashboard") {
      resetWorkspaceFilters();
    }
    if (requestedTab === "stores") {
      state.storeCategoryFilter = "all";
      resetWorkspaceFilters();
    }
    if (nextTab === "configuration") {
      state.expandedStoreIds = new Set();
    }
    saveState();
    render();
    return;
  }
}

