function reloadWithBuildVersion(version) {
  const url = new URL(window.location.href);
  url.searchParams.set("build", version);
  console.info("Nouvelle version disponible, rechargement manuel attendu.", version, url.toString());
}

async function checkForAppUpdate() {
  if (isUserActivelyWorking()) {
    return;
  }
  try {
    const response = await fetch(`${appVersionCheckUrl}?t=${Date.now()}`, {
      cache: "no-store"
    });
    if (!response.ok) return;
    const payload = await response.json();
    const remoteVersion = String(payload?.version || "").trim();
    if (!remoteVersion || remoteVersion === appBuildVersion) return;
    window.localStorage.setItem(appVersionStorageKey, remoteVersion);
    reloadWithBuildVersion(remoteVersion);
  } catch (error) {
    console.warn("Version check skipped", error);
  }
}

function setupUserActivityGuard() {
  const activityEvents = ["input", "change", "focusin", "keydown", "pointerdown"];
  activityEvents.forEach((eventName) => {
    document.addEventListener(eventName, (event) => {
      if (isEditableElement(event.target) || event.target?.closest?.("form, [data-store-editor], [data-sav-create], [data-sav-update], [data-sav-dispatch]")) {
        markUserActivity();
      }
    }, true);
  });
}

function setupAppUpdateCheck() {
  try {
    const storedVersion = window.localStorage.getItem(appVersionStorageKey);
    if (storedVersion && storedVersion !== appBuildVersion) {
      window.localStorage.setItem(appVersionStorageKey, appBuildVersion);
    } else if (!storedVersion) {
      window.localStorage.setItem(appVersionStorageKey, appBuildVersion);
    }
  } catch (error) {
    console.warn("Version storage skipped", error);
  }
  window.setInterval(checkForAppUpdate, appVersionCheckIntervalMs);
}

async function init() {
  setupUserActivityGuard();
  setupAppUpdateCheck();
  const stored = await loadSnapshotState(loadState());
  state.stores = stored.stores;
  state.activities = stored.activities;
  state.people = normalizeSpecialPeople(stored.people);
  state.activeUserName = stored.activeUserName;
  state.language = stored.language || "fr";
  state.languageLocked = Boolean(stored.languageLocked);
  state.activeAdminTab = stored.activeAdminTab || "dashboard";
  state.activeAutomationSubtab = stored.activeAutomationSubtab || "rules";
  state.pinValidated = false;
  state.pinSession = stored.pinSession || null;
  state.launchMailDraft = stored.launchMailDraft || {};
  state.toolItems = (stored.toolItems || []).filter((item) =>
    item?.id !== tutorialVideosSettingsItemId
    && item?.kind !== "tutorial_videos"
    && item?.id !== technicalSheetsSettingsItemId
    && item?.kind !== "technical_sheets"
  );
  state.accessOverrides = stored.accessOverrides || [];
  state.roleOptions = normalizedRoleOptions(stored.roleOptions);
  state.tutorialVideos = normalizedTutorialVideos(stored.tutorialVideos || []);
  state.technicalSheets = normalizedTechnicalSheets(stored.technicalSheets || []);
  state.automations = normalizedAutomations(stored.automations);
  state.roleVisibilityConfig = stored.roleVisibilityConfig || {};
  state.visibilityEditorRole = stored.visibilityEditorRole || "supadmin_twem";
  state.roleViewUnlocked = Boolean(stored.roleViewUnlocked);
  state.contactSearch = stored.contactSearch || "";
  state.importExportHistory = cleanImportHistory(stored.importExportHistory || []);
  state.automationEmails = Array.isArray(stored.automationEmails) ? stored.automationEmails : [];
  state.supportRequests = normalizedSupportRequests(stored.supportRequests || []);
  state.supportAccessLog = normalizedSupportAccessLog(stored.supportAccessLog || []);
  state.supportSession = stored.supportSession || null;
  if (!hasRemoteData() && Array.isArray(stored.extensionCatalogRows) && stored.extensionCatalogRows.length) {
    extensionCatalogRows.splice(0, extensionCatalogRows.length, ...stored.extensionCatalogRows.map((row, index) => normalizeExtensionCatalogRow(row, index)));
  }
  state.people = normalizeSpecialPeople(stripKnownTestPeople(state.people));
  state.tickets = mergeSavTicketDuplicates(stripKnownTestTickets(state.tickets));
  ensureAutomationEmailDrafts();
  document.documentElement.lang = state.language;

  if (!isSnapshotMode && hasImportedStoreSet(state.stores)) {
    state.stores = resetImportedStoresForKickoff(state.stores);
    state.people = cleanPeopleForImportedStores(state.people, state.stores);
  }

  if (!isSnapshotMode && !hasRemoteData() && applyCompletionStatusCorrections().length) {
    saveState();
  }

  const supportQuery = supportAccessParamsFromQuery();
  if (!hasRemoteData()) {
    applySupportAccessFromQuery();
  } else {
    clearSupportSessionIfClosed();
  }

  const queryUserName = preferredUserFromQuery();
  if (!supportQuery && queryUserName) {
    state.activeUserName = queryUserName;
    state.pinValidated = presentationBypassUsers.includes(queryUserName);
    state.activeAdminTab = "dashboard";
  } else if (!supportQuery && state.activeUserName && presentationBypassUsers.includes(state.activeUserName)) {
    state.activeUserName = state.people.find((person) => person.name === state.activeUserName)?.name || state.activeUserName;
    state.pinValidated = true;
    state.activeAdminTab = "dashboard";
  }

  if (isSupabaseMode && supabaseClient) {
    try {
      await loadRemoteState();
      await setupRealtime();
      supabaseClient.auth.onAuthStateChange(async (_event, session) => {
        const sessionPerson = roleValueFromSession(session);
        if (sessionPerson) {
          state.activeUserName = sessionPerson.name;
        }
        await loadRemoteState();
        render();
      });
    } catch (error) {
      connectionBadge.textContent = "Erreur";
      console.error("Supabase init error", error);
      window.alert(`Connexion Supabase incomplete: ${error.message}`);
    }
  }

  if (isAppwriteMode && appwriteAccount) {
    try {
      await completeAppwriteMagicSession();
      await loadAppwriteSessionUser();
      if (hasAppwriteDataConfig) {
        await loadRemoteState();
        // Ne plus fusionner un ancien catalogue local avec la nomenclature officielle.
        const cancelledInstallStores = applyCancelledInstallCorrections();
        if (cancelledInstallStores.length) {
          saveState();
          for (const store of cancelledInstallStores) {
            await syncStoreToRemote(store);
          }
          refreshRemoteSyncShadow();
        }
        const completedStores = applyCompletionStatusCorrections();
        if (completedStores.length) {
          saveState();
          for (const store of completedStores) {
            await syncStoreToRemote(store);
          }
          refreshRemoteSyncShadow();
        }
        const dstnyAppointmentStores = reconcileDstnyInstallationAppointments();
        if (dstnyAppointmentStores.length) {
          saveState();
          for (const store of dstnyAppointmentStores) {
            await syncStoreToRemote(store, "Correction rendez-vous Dstny selon date installation");
          }
          refreshRemoteSyncShadow();
        }
        await setupRealtime();
        setupAppwritePolling();
      }
    } catch (error) {
      state.connectionState = "fallback";
      console.error("Appwrite init error", error);
    }
  }

  if (hasRemoteData()) {
    applySupportAccessFromQuery();
  }

  if (!state.pinValidated) {
    restoreRememberedPinSession();
  }
  ensureValidActiveTab();
  const closureReviewStoreCode = state.pinValidated ? applyClosureReviewDeepLink() : "";
  if (state.pinValidated) {
    updateFocusFromQuery();
  }
  render();
  // Les fonctions de rendu complètent certains anciens objets avec des valeurs
  // par défaut. Ces normalisations d'affichage deviennent la référence locale
  // initiale et ne doivent pas être envoyées comme des modifications utilisateur.
  if (hasRemoteData()) {
    refreshRemoteSyncShadow();
  }
  scrollToFocusedUpdate();
  if (closureReviewStoreCode) window.setTimeout(() => scrollToClosureReviewStore(closureReviewStoreCode), 60);
}

init();




























